// JSString is an immutable JavaScript string with UTF-16 semantics.
// Flat strings are either ASCII (stored in s) or wide (stored in u).
// Ropes have left/right set and are flattened lazily.
type JSString struct {
	s           string
	u           []uint16
	left, right *JSString
	n           int
	wide        bool
}

var emptyStr = &JSString{}

var asciiCharStrs [128]*JSString

func init() {
	for i := 0; i < 128; i++ {
		asciiCharStrs[i] = &JSString{s: string(rune(i)), n: 1}
	}
}

func newStrASCII(s string) *JSString {
	if len(s) == 0 {
		return emptyStr
	}
	if len(s) == 1 {
		return asciiCharStrs[s[0]]
	}
	return &JSString{s: s, n: len(s)}
}

func isASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] >= 0x80 {
			return false
		}
	}
	return true
}

// newStr creates a JSString from a Go (UTF-8 / WTF-8) string.
func newStr(s string) *JSString {
	if isASCII(s) {
		return newStrASCII(s)
	}
	return newStrUTF16(wtf8ToUTF16(s))
}

func newStrUTF16(u []uint16) *JSString {
	if len(u) == 0 {
		return emptyStr
	}
	for _, c := range u {
		if c >= 0x80 {
			return &JSString{u: u, n: len(u), wide: true}
		}
	}
	b := make([]byte, len(u))
	for i, c := range u {
		b[i] = byte(c)
	}
	return newStrASCII(string(b))
}

func strFromUnit(c uint16) *JSString {
	if c < 128 {
		return asciiCharStrs[c]
	}
	return &JSString{u: []uint16{c}, n: 1, wide: true}
}

func strFromCodePoint(cp rune) *JSString {
	if cp < 0x10000 {
		return strFromUnit(uint16(cp))
	}
	r1, r2 := utf16.EncodeRune(cp)
	return &JSString{u: []uint16{uint16(r1), uint16(r2)}, n: 2, wide: true}
}

func wtf8ToUTF16(s string) []uint16 {
	u := make([]uint16, 0, len(s))
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			u = append(u, uint16(c))
			i++
			continue
		}
		// decode manually to allow surrogates (WTF-8)
		if c&0xE0 == 0xC0 && i+1 < len(s) {
			r := rune(c&0x1F)<<6 | rune(s[i+1]&0x3F)
			u = append(u, uint16(r))
			i += 2
			continue
		}
		if c&0xF0 == 0xE0 && i+2 < len(s) {
			r := rune(c&0x0F)<<12 | rune(s[i+1]&0x3F)<<6 | rune(s[i+2]&0x3F)
			u = append(u, uint16(r))
			i += 3
			continue
		}
		if c&0xF8 == 0xF0 && i+3 < len(s) {
			r := rune(c&0x07)<<18 | rune(s[i+1]&0x3F)<<12 | rune(s[i+2]&0x3F)<<6 | rune(s[i+3]&0x3F)
			r1, r2 := utf16.EncodeRune(r)
			u = append(u, uint16(r1), uint16(r2))
			i += 4
			continue
		}
		u = append(u, 0xFFFD)
		i++
	}
	return u
}

func (s *JSString) Len() int { return s.n }

func (s *JSString) flatten() {
	if s.left == nil {
		return
	}
	// iterative flatten
	if s.wide {
		buf := make([]uint16, 0, s.n)
		buf = appendRopeUTF16(buf, s)
		s.u = buf
	} else {
		var sb strings.Builder
		sb.Grow(s.n)
		appendRopeASCII(&sb, s)
		s.s = sb.String()
	}
	s.left = nil
	s.right = nil
