func appendRopeASCII(sb *strings.Builder, s *JSString) {
	stack := []*JSString{s}
	for len(stack) > 0 {
		x := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if x.left != nil {
			stack = append(stack, x.right, x.left)
			continue
		}
		sb.WriteString(x.s)
	}
}

func appendRopeUTF16(buf []uint16, s *JSString) []uint16 {
	stack := []*JSString{s}
	for len(stack) > 0 {
		x := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if x.left != nil {
			stack = append(stack, x.right, x.left)
			continue
		}
		if x.wide {
			buf = append(buf, x.u...)
		} else {
			for i := 0; i < len(x.s); i++ {
				buf = append(buf, uint16(x.s[i]))
			}
		}
	}
	return buf
}

func (s *JSString) At(i int) uint16 {
	if s.left != nil {
		s.flatten()
	}
	if s.wide {
		return s.u[i]
	}
	return uint16(s.s[i])
}

// UTF16 returns the code units (may allocate for ASCII strings)
func (s *JSString) UTF16() []uint16 {
	if s.left != nil {
		s.flatten()
	}
	if s.wide {
		return s.u
	}
	u := make([]uint16, len(s.s))
	for i := 0; i < len(s.s); i++ {
		u[i] = uint16(s.s[i])
	}
	return u
}

func (s *JSString) IsASCII() bool {
	return !s.wide
}

// ASCII returns the ascii content; only valid when !wide
func (s *JSString) ASCII() string {
	if s.left != nil {
		s.flatten()
	}
	return s.s
}

// String converts to Go UTF-8 string (lone surrogates encoded WTF-8 style)
func (s *JSString) String() string {
	if s.left != nil {
		s.flatten()
	}
	if !s.wide {
		return s.s
	}
	return utf16ToWTF8(s.u)
}

// ToUTF8 converts to valid UTF-8 replacing lone surrogates with U+FFFD
func (s *JSString) ToUTF8() string {
	if s.left != nil {
		s.flatten()
	}
	if !s.wide {
		return s.s
	}
	var b []byte
	u := s.u
	for i := 0; i < len(u); i++ {
		c := rune(u[i])
		if c >= 0xD800 && c < 0xDC00 && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] < 0xE000 {
			c = 0x10000 + (c-0xD800)<<10 + rune(u[i+1]-0xDC00)
			i++
		} else if c >= 0xD800 && c < 0xE000 {
			c = 0xFFFD
		}
		b = utf8.AppendRune(b, c)
	}
	return string(b)
