func utf16ToWTF8(u []uint16) string {
	b := make([]byte, 0, len(u)+8)
	for i := 0; i < len(u); i++ {
		c := rune(u[i])
		if c < 0x80 {
			b = append(b, byte(c))
			continue
		}
		if c >= 0xD800 && c < 0xDC00 && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] < 0xE000 {
			c = 0x10000 + (c-0xD800)<<10 + rune(u[i+1]-0xDC00)
			i++
			b = utf8.AppendRune(b, c)
			continue
		}
		if c >= 0xD800 && c < 0xE000 {
			// encode surrogate directly (WTF-8)
			b = append(b, byte(0xE0|(c>>12)), byte(0x80|((c>>6)&0x3F)), byte(0x80|(c&0x3F)))
			continue
		}
		b = utf8.AppendRune(b, c)
	}
	return string(b)
