const ropeThreshold = 256

func concatStr(a, b *JSString) *JSString {
	if a.n == 0 {
		return b
	}
	if b.n == 0 {
		return a
	}
	n := a.n + b.n
	if n < ropeThreshold {
		if !a.wide && !b.wide {
			return &JSString{s: a.ASCII() + b.ASCII(), n: n}
		}
		u := make([]uint16, 0, n)
		u = appendUnits(u, a)
		u = appendUnits(u, b)
		return &JSString{u: u, n: n, wide: true}
	}
	return &JSString{left: a, right: b, n: n, wide: a.wide || b.wide}
}

func appendUnits(u []uint16, s *JSString) []uint16 {
	if s.left != nil {
		s.flatten()
	}
	if s.wide {
		return append(u, s.u...)
	}
	for i := 0; i < len(s.s); i++ {
		u = append(u, uint16(s.s[i]))
	}
	return u
}

func (s *JSString) Substring(start, end int) *JSString {
	if start >= end {
		return emptyStr
	}
	if start == 0 && end == s.n {
		return s
	}
	if s.left != nil {
		s.flatten()
	}
	if !s.wide {
		return newStrASCII(s.s[start:end])
	}
	sub := s.u[start:end]
	for _, c := range sub {
		if c >= 0x80 {
			cp := make([]uint16, len(sub))
			copy(cp, sub)
			return &JSString{u: cp, n: len(cp), wide: true}
		}
	}
	return newStrUTF16(sub)
}

func strEquals(a, b *JSString) bool {
	if a == b {
		return true
	}
	if a.n != b.n {
		return false
	}
	if a.wide != b.wide {
		return false // normalized: wide strings always contain non-ascii
	}
	if !a.wide {
		return a.ASCII() == b.ASCII()
	}
	au := a.UTF16()
	bu := b.UTF16()
	for i := range au {
		if au[i] != bu[i] {
			return false
		}
	}
	return true
}

func strCompare(a, b *JSString) int {
	if !a.wide && !b.wide {
		return strings.Compare(a.ASCII(), b.ASCII())
	}
	n := a.n
	if b.n < n {
		n = b.n
	}
	for i := 0; i < n; i++ {
		x, y := a.At(i), b.At(i)
		if x != y {
			if x < y {
				return -1
			}
			return 1
		}
	}
	if a.n < b.n {
		return -1
	}
	if a.n > b.n {
		return 1
	}
	return 0
}

func (s *JSString) IndexOf(sub *JSString, from int) int {
	if from < 0 {
		from = 0
	}
	if sub.n == 0 {
		if from > s.n {
			return s.n
		}
		return from
	}
	if from >= s.n {
		return -1
	}
	if !s.wide && !sub.wide {
		i := strings.Index(s.ASCII()[from:], sub.ASCII())
		if i < 0 {
			return -1
		}
		return i + from
	}
	if !s.wide && sub.wide {
		return -1
	}
	a := s.UTF16()
	b := sub.UTF16()
	for i := from; i+len(b) <= len(a); i++ {
		if a[i] == b[0] {
			match := true
			for j := 1; j < len(b); j++ {
				if a[i+j] != b[j] {
					match = false
					break
				}
			}
			if match {
				return i
			}
		}
	}
	return -1
}

func (s *JSString) LastIndexOf(sub *JSString, from int) int {
	if from > s.n-sub.n {
		from = s.n - sub.n
	}
	for i := from; i >= 0; i-- {
		match := true
		for j := 0; j < sub.n; j++ {
			if s.At(i+j) != sub.At(j) {
				match = false
				break
			}
		}
		if match {
			return i
		}
	}
	return -1
}

// strBuilder builds JS strings
type strBuilder struct {
	a    []byte
	u    []uint16
	wide bool
}

func (b *strBuilder) WriteASCII(s string) {
	if b.wide {
		for i := 0; i < len(s); i++ {
			b.u = append(b.u, uint16(s[i]))
		}
	} else {
		b.a = append(b.a, s...)
	}
}

func (b *strBuilder) WriteGo(s string) {
	if isASCII(s) {
		b.WriteASCII(s)
		return
	}
	b.WriteUnits(wtf8ToUTF16(s))
}

func (b *strBuilder) toWide() {
	if !b.wide {
		b.wide = true
		u := make([]uint16, len(b.a), len(b.a)+16)
		for i, c := range b.a {
			u[i] = uint16(c)
		}
		b.u = u
		b.a = nil
	}
}

func (b *strBuilder) WriteUnit(c uint16) {
	if c >= 0x80 && !b.wide {
		b.toWide()
	}
	if b.wide {
		b.u = append(b.u, c)
	} else {
		b.a = append(b.a, byte(c))
	}
}

func (b *strBuilder) WriteCodePoint(cp rune) {
	if cp < 0x10000 {
		b.WriteUnit(uint16(cp))
		return
	}
	r1, r2 := utf16.EncodeRune(cp)
	b.WriteUnit(uint16(r1))
	b.WriteUnit(uint16(r2))
}

func (b *strBuilder) WriteUnits(u []uint16) {
	for _, c := range u {
		b.WriteUnit(c)
	}
}

func (b *strBuilder) WriteStr(s *JSString) {
	if s.left != nil {
		s.flatten()
	}
	if !s.wide {
		b.WriteASCII(s.s)
		return
	}
	b.toWide()
	b.u = append(b.u, s.u...)
}

func (b *strBuilder) Len() int {
	if b.wide {
		return len(b.u)
	}
	return len(b.a)
}

func (b *strBuilder) String() *JSString {
	if b.wide {
		return newStrUTF16(b.u)
	}
	return newStrASCII(string(b.a))
}

// codePointAt returns code point at index i and its length in units
func (s *JSString) CodePointAt(i int) (rune, int) {
	c := s.At(i)
	if c >= 0xD800 && c < 0xDC00 && i+1 < s.n {
		d := s.At(i + 1)
		if d >= 0xDC00 && d < 0xE000 {
			return 0x10000 + (rune(c)-0xD800)<<10 + rune(d-0xDC00), 2
		}
	}
	return rune(c), 1
}
