		return b
	}
	if b.n == 0 {
		return a
	}
	n := a.n + b.n
	if n < ropeThreshold {
		if !a.wide && !b.wide {
			return &JSString{s: a.ASCII() + b.ASCII(), n: n}
		}
		u := make([]uint16, 0, n)
		u = appendUnits(u, a)
		u = appendUnits(u, b)
		return &JSString{u: u, n: n, wide: true}
	}
	return &JSString{left: a, right: b, n: n, wide: a.wide || b.wide}
}

func appendUnits(u []uint16, s *JSString) []uint16 {
	if s.left != nil {
		s.flatten()
	}
	if s.wide {
		return append(u, s.u...)
	}
	for i := 0; i < len(s.s); i++ {
