	}
	return newStrUTF16(sub)
}

func strEquals(a, b *JSString) bool {
	if a == b {
		return true
	}
	if a.n != b.n {
		return false
	}
	if a.wide != b.wide {
		return false // normalized: wide strings always contain non-ascii
	}
	if !a.wide {
		return a.ASCII() == b.ASCII()
	}
	au := a.UTF16()
	bu := b.UTF16()
	for i := range au {
		if au[i] != bu[i] {
			return false
		}
	}
	return true
}

func strCompare(a, b *JSString) int {
	if !a.wide && !b.wide {
		return strings.Compare(a.ASCII(), b.ASCII())
	}
	n := a.n
	if b.n < n {
		n = b.n
	}
	for i := 0; i < n; i++ {
		x, y := a.At(i), b.At(i)
		if x != y {
			if x < y {
				return -1
			}
			return 1
		}
	}
	if a.n < b.n {
		return -1
	}
	if a.n > b.n {
		return 1
	}
	return 0
}

func (s *JSString) IndexOf(sub *JSString, from int) int {
	if from < 0 {
		from = 0
