			return true
		}
	}
	lx.pos++
	return true
}

// scanTemplate scans from after ` or } up to ${ or `
func (lx *Lexer) scanTemplate(t *Token) {
	start := lx.pos
	var b strBuilder
	invalid := false
	var raw strings.Builder
	for {
		if lx.pos >= len(lx.src) {
			lx.errAt(start-1, "unexpected end of template")
		}
		c := lx.src[lx.pos]
		if c == '`' {
			lx.pos++
			t.tail = true
			break
		}
		if c == '$' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '{' {
			lx.pos += 2
			break
		}
		if c == '\\' {
			escStart := lx.pos
			lx.pos++
			if lx.pos >= len(lx.src) {
				lx.errAt(start, "unexpected end of template")
			}
			var tmp Token
			save := lx.pos
			if !lx.scanEscape(&b, &tmp, true) {
				invalid = true
				// skip the char
				lx.pos = save
				_, sz := lx.peekRune(lx.pos)
				lx.pos += sz
			}
			rawPart := lx.src[escStart:lx.pos]
			rawPart = strings.ReplaceAll(rawPart, "\r\n", "\n")
			rawPart = strings.ReplaceAll(rawPart, "\r", "\n")
			raw.WriteString(rawPart)
			continue
		}
		if c == '\r' {
			lx.pos++
			if lx.pos < len(lx.src) && lx.src[lx.pos] == '\n' {
				lx.pos++
			}
			b.WriteUnit('\n')
			raw.WriteByte('\n')
			continue
		}
		if c < 0x80 {
			b.WriteUnit(uint16(c))
			raw.WriteByte(c)
			lx.pos++
			continue
		}
		r, sz := utf8.DecodeRuneInString(lx.src[lx.pos:])
		b.WriteCodePoint(r)
		raw.WriteString(lx.src[lx.pos : lx.pos+sz])
		lx.pos += sz
	}
	t.kind = tTemplate
	if invalid {
		t.sval = nil
		t.invalidEsc = true
	} else {
		t.sval = b.String()
	}
	t.raw = raw.String()
}

// rescanTemplateContinuation: called when parser sees '}' closing a substitution
func (lx *Lexer) rescanTemplate() {
	// current token is '}' ; restart from its end
	lx.pos = lx.tok.pos + 1
	t := Token{pos: lx.tok.pos}
	lx.scanTemplate(&t)
	t.end = lx.pos
	lx.tok = t
}

func (lx *Lexer) rescanRegExp() {
	start := lx.tok.pos
	lx.pos = start + 1
	inClass := false
	for {
		if lx.pos >= len(lx.src) {
			lx.errAt(start, "unexpected end of regexp")
		}
		r, sz := lx.peekRune(lx.pos)
		if isLineTerm(r) {
			lx.errAt(start, "unexpected line terminator in regexp")
		}
		if r == '\\' {
			lx.pos++
			r2, sz2 := lx.peekRune(lx.pos)
			if r2 < 0 || isLineTerm(r2) {
				lx.errAt(start, "unexpected line terminator in regexp")
			}
			lx.pos += sz2
			continue
		}
		if r == '[' {
			inClass = true
		} else if r == ']' {
			inClass = false
		} else if r == '/' && !inClass {
			break
		}
		lx.pos += sz
	}
	pattern := lx.src[start+1 : lx.pos]
	lx.pos++
	fstart := lx.pos
	for lx.pos < len(lx.src) {
		r, sz := lx.peekRune(lx.pos)
		if !isIDPart(r) {
			break
		}
		lx.pos += sz
	}
	t := Token{kind: tRegExp, pos: start, str: pattern, flags: lx.src[fstart:lx.pos], nlBefore: lx.tok.nlBefore}
	t.end = lx.pos
	lx.tok = t
}

func (lx *Lexer) scanNumber(t *Token) {
	start := lx.pos
	src := lx.src
	t.kind = tNum
	isDigitSep := func(c byte, base int) bool {
		if c == '_' {
			return true
		}
		return hexVal(c) >= 0 && hexVal(c) < base
	}
	readDigits := func(base int) string {
		s := lx.pos
		lastSep := false
		for lx.pos < len(src) && isDigitSep(src[lx.pos], base) {
			if src[lx.pos] == '_' {
				if lastSep || lx.pos == s {
					lx.errAt(lx.pos, "invalid number literal")
				}
				lastSep = true
			} else {
				lastSep = false
			}
			lx.pos++
		}
		if lastSep {
			lx.errAt(lx.pos-1, "invalid number literal")
		}
		return strings.ReplaceAll(src[s:lx.pos], "_", "")
	}
	if src[lx.pos] == '0' && lx.pos+1 < len(src) {
		c2 := src[lx.pos+1] | 0x20
		base := 0
		switch c2 {
		case 'x':
			base = 16
		case 'o':
			base = 8
		case 'b':
			base = 2
		}
		if base != 0 {
			lx.pos += 2
			digits := readDigits(base)
			if digits == "" {
				lx.errAt(start, "invalid number literal")
			}
			if lx.pos < len(src) && src[lx.pos] == 'n' {
				lx.pos++
				bi := new(big.Int)
				bi.SetString(digits, base)
				t.kind = tBigInt
				t.str = bi.String()
			} else {
				t.num = parseIntDigits(digits, base)
			}
			lx.checkAfterNumber()
			return
		}
		if src[lx.pos+1] >= '0' && src[lx.pos+1] <= '9' || src[lx.pos+1] == '_' {
			// legacy octal or decimal with leading zero
			if src[lx.pos+1] == '_' {
				lx.errAt(lx.pos+1, "invalid number literal")
			}
			t.legacyOctal = true
			s := lx.pos
			octal := true
			for lx.pos < len(src) && src[lx.pos] >= '0' && src[lx.pos] <= '9' {
				if src[lx.pos] >= '8' {
					octal = false
				}
				lx.pos++
			}
			if octal {
				t.num = parseIntDigits(src[s:lx.pos], 8)
				lx.checkAfterNumber()
				return
			}
			// decimal with leading zero: may have fraction
			if lx.pos < len(src) && src[lx.pos] == '.' {
				lx.pos++
				for lx.pos < len(src) && src[lx.pos] >= '0' && src[lx.pos] <= '9' {
					lx.pos++
				}
			}
			if lx.pos < len(src) && (src[lx.pos]|0x20) == 'e' {
				lx.scanExponent()
			}
			f, _ := strconv.ParseFloat(src[s:lx.pos], 64)
			t.num = f
			lx.checkAfterNumber()
			return
		}
	}
	intPart := ""
	if src[lx.pos] != '.' {
		intPart = readDigits(10)
	}
	isInt := true
	frac := ""
	if lx.pos < len(src) && src[lx.pos] == '.' {
		isInt = false
		lx.pos++
		if lx.pos < len(src) && src[lx.pos] == '_' {
			lx.errAt(lx.pos, "invalid number literal")
		}
		frac = readDigits(10)
	}
	exp := ""
	if lx.pos < len(src) && (src[lx.pos]|0x20) == 'e' {
		isInt = false
		es := lx.pos
		lx.pos++
		if lx.pos < len(src) && (src[lx.pos] == '+' || src[lx.pos] == '-') {
			lx.pos++
		}
		if lx.pos >= len(src) || src[lx.pos] < '0' || src[lx.pos] > '9' {
			lx.errAt(es, "invalid number literal")
		}
		readDigits(10)
		exp = strings.ReplaceAll(src[es:lx.pos], "_", "")
	}
	if isInt && lx.pos < len(src) && src[lx.pos] == 'n' {
		lx.pos++
		t.kind = tBigInt
		bi := new(big.Int)
		bi.SetString(intPart, 10)
		t.str = bi.String()
		lx.checkAfterNumber()
		return
	}
	s := intPart
	if s == "" {
		s = "0"
	}
	if frac != "" {
		s += "." + frac
	}
	s += exp
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		// ParseFloat returns inf with err for overflow
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			// f is +-Inf or 0
		} else {
			lx.errAt(start, "invalid number literal")
		}
	}
	t.num = f
	lx.checkAfterNumber()
}

func (lx *Lexer) scanExponent() {
	lx.pos++
	if lx.pos < len(lx.src) && (lx.src[lx.pos] == '+' || lx.src[lx.pos] == '-') {
		lx.pos++
	}
	for lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '9' {
		lx.pos++
	}
}

func (lx *Lexer) checkAfterNumber() {
	r, _ := lx.peekRune(lx.pos)
	if r >= 0 && (isIDStart(r) || r == '\\' || (r >= '0' && r <= '9')) {
		lx.errAt(lx.pos, "invalid number literal")
	}
}

func parseIntDigits(digits string, base int) float64 {
	if len(digits) <= 12 || base == 10 && len(digits) <= 15 {
		v, err := strconv.ParseUint(digits, base, 64)
		if err == nil {
			return float64(v)
		}
	}
	if base == 10 {
		f, _ := strconv.ParseFloat(digits, 64)
		return f
	}
	bi := new(big.Int)
	bi.SetString(digits, base)
	f, _ := new(big.Float).SetInt(bi).Float64()
	if math.IsInf(f, 0) {
		return math.Inf(1)
	}
	return f
}
EOF
echo ok"}

