cd /workspace && cat > lexer.go <<'EOF'
package main

import (
	"math"
	"math/big"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type TokKind int

const (
	tEOF TokKind = iota
	tIdent
	tPrivate
	tNum
	tBigInt
	tStr
	tTemplate
	tRegExp
	tPunct
)

type Token struct {
	kind        TokKind
	str         string // ident name / punct / bigint digits / regexp pattern
	num         float64
	sval        *JSString
	raw         string
	pos         int
	end         int
	nlBefore    bool
	escaped     bool
	tail        bool
	flags       string
	legacyOctal bool
	invalidEsc  bool
}

type SyntaxErr struct {
	msg string
	pos int
}

type Lexer struct {
	src  string
	pos  int
	tok  Token
	prev Token
	file *SourceFile
	// for error reporting
}

type SourceFile struct {
	name       string
	src        string
	lineStarts []int
}

func newSourceFile(name, src string) *SourceFile {
	sf := &SourceFile{name: name, src: src}
	sf.lineStarts = append(sf.lineStarts, 0)
	for i := 0; i < len(src); i++ {
		c := src[i]
		if c == '\n' {
			sf.lineStarts = append(sf.lineStarts, i+1)
		} else if c == '\r' {
			if i+1 < len(src) && src[i+1] == '\n' {
				i++
			}
			sf.lineStarts = append(sf.lineStarts, i+1)
		} else if c == 0xE2 && i+2 < len(src) && src[i+1] == 0x80 && (src[i+2] == 0xA8 || src[i+2] == 0xA9) {
			sf.lineStarts = append(sf.lineStarts, i+3)
			i += 2
		}
	}
	return sf
}

// lineCol returns 1-based line and column (in code points)
func (sf *SourceFile) lineCol(pos int) (int, int) {
	if pos > len(sf.src) {
		pos = len(sf.src)
	}
	lo, hi := 0, len(sf.lineStarts)-1
	for lo < hi {
		mid := (lo + hi + 1) / 2
		if sf.lineStarts[mid] <= pos {
			lo = mid
		} else {
			hi = mid - 1
		}
	}
	ls := sf.lineStarts[lo]
	col := utf8.RuneCountInString(sf.src[ls:pos]) + 1
	return lo + 1, col
}

func (lx *Lexer) errAt(pos int, msg string) {
	panic(&SyntaxErr{msg: msg, pos: pos})
}

func isIDStart(r rune) bool {
	if r < 128 {
		return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r == '$' || r == '_'
	}
	return unicode.IsLetter(r) || unicode.Is(unicode.Nl, r) || unicode.Is(unicode.Other_ID_Start, r)
}

func isIDPart(r rune) bool {
	if r < 128 {
		return r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r == '$' || r == '_' || r >= '0' && r <= '9'
	}
	return isIDStart(r) || unicode.In(r, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc, unicode.Other_ID_Continue) || r == 0x200C || r == 0x200D
}

func isLineTerm(r rune) bool {
	return r == '\n' || r == '\r' || r == 0x2028 || r == 0x2029
}

func isWS(r rune) bool {
	switch r {
	case '\t', '\v', '\f', ' ', 0xA0, 0xFEFF:
		return true
	}
	if r >= 128 && unicode.Is(unicode.Zs, r) {
		return true
	}
	return false
}

func (lx *Lexer) peekRune(p int) (rune, int) {
	if p >= len(lx.src) {
		return -1, 0
	}
	c := lx.src[p]
	if c < 0x80 {
		return rune(c), 1
	}
	r, sz := utf8.DecodeRuneInString(lx.src[p:])
	return r, sz
}

// skip whitespace & comments, returns whether newline seen
func (lx *Lexer) skipSpace() bool {
	nl := false
	for lx.pos < len(lx.src) {
		c := lx.src[lx.pos]
		if c == ' ' || c == '\t' {
			lx.pos++
			continue
		}
		if c == '\n' || c == '\r' {
			nl = true
			lx.pos++
			continue
		}
		if c == '/' && lx.pos+1 < len(lx.src) {
			c2 := lx.src[lx.pos+1]
			if c2 == '/' {
				lx.pos += 2
				for lx.pos < len(lx.src) {
					r, sz := lx.peekRune(lx.pos)
					if isLineTerm(r) {
						break
					}
					lx.pos += sz
				}
				continue
			}
			if c2 == '*' {
				start := lx.pos
				lx.pos += 2
				closed := false
				for lx.pos < len(lx.src) {
					if lx.src[lx.pos] == '*' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '/' {
						lx.pos += 2
						closed = true
						break
					}
					r, sz := lx.peekRune(lx.pos)
					if isLineTerm(r) {
						nl = true
					}
					lx.pos += sz
				}
				if !closed {
					_ = start
					lx.errAt(lx.pos, "unexpected end of comment")
				}
				continue
			}
		}
		if c == '<' && strings.HasPrefix(lx.src[lx.pos:], "<!--") && !lx.isModule() {
			for lx.pos < len(lx.src) {
				r, sz := lx.peekRune(lx.pos)
				if isLineTerm(r) {
					break
				}
				lx.pos += sz
			}
			continue
		}
		if c == '-' && (nl || lx.pos == 0) && strings.HasPrefix(lx.src[lx.pos:], "-->") && !lx.isModule() {
			for lx.pos < len(lx.src) {
				r, sz := lx.peekRune(lx.pos)
				if isLineTerm(r) {
					break
				}
				lx.pos += sz
			}
			continue
		}
		if c >= 0x80 || c == '\v' || c == '\f' {
			r, sz := lx.peekRune(lx.pos)
			if isLineTerm(r) {
				nl = true
				lx.pos += sz
				continue
			}
			if isWS(r) {
				lx.pos += sz
				continue
			}
		}
		break
	}
	return nl
}

var moduleLexFlag bool

func (lx *Lexer) isModule() bool { return moduleLexFlag }

var puncts3 = []string{">>>=", "...", "===", "!==", "**=", "<<=", ">>=", ">>>", "&&=", "||=", "??="}
var puncts2 = []string{"=>", "==", "!=", "<=", ">=", "&&", "||", "??", "?.", "++", "--", "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<", ">>", "**"}

func (lx *Lexer) next() {
	lx.prev = lx.tok
	nl := lx.skipSpace()
	t := Token{pos: lx.pos, nlBefore: nl}
	if lx.pos >= len(lx.src) {
		t.kind = tEOF
		t.end = lx.pos
		lx.tok = t
		return
	}
	c := lx.src[lx.pos]
	switch {
	case c == '"' || c == '\'':
		lx.scanString(&t, c)
	case c == '`':
		lx.pos++
		lx.scanTemplate(&t)
	case c >= '0' && c <= '9' || (c == '.' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] >= '0' && lx.src[lx.pos+1] <= '9'):
		lx.scanNumber(&t)
	case c == '#':
		lx.pos++
		r, _ := lx.peekRune(lx.pos)
		if r == '\\' || isIDStart(r) {
			name, esc := lx.scanIdentName()
			t.kind = tPrivate
			t.str = "#" + name
			t.escaped = esc
		} else {
			lx.errAt(t.pos, "invalid character")
		}
	default:
		r, sz := lx.peekRune(lx.pos)
		if r == '\\' || isIDStart(r) {
			name, esc := lx.scanIdentName()
			t.kind = tIdent
			t.str = name
			t.escaped = esc
		} else if c < 0x80 && strings.IndexByte("{}()[];,<>+-*/%&|^!~?:=.@", c) >= 0 {
			t.kind = tPunct
			rest := lx.src[lx.pos:]
			found := ""
			if strings.HasPrefix(rest, ">>>=") {
				found = ">>>="
			} else {
				for _, p := range puncts3 {
					if strings.HasPrefix(rest, p) {
						found = p
						break
					}
				}
				if found == "" {
					for _, p := range puncts2 {
						if strings.HasPrefix(rest, p) {
							found = p
							break
						}
					}
				}
			}
			if found == "?." && len(rest) > 2 && rest[2] >= '0' && rest[2] <= '9' {
				found = ""
			}
			if found == "" {
				found = rest[:1]
			}
			lx.pos += len(found)
			t.str = found
		} else {
			_ = sz
			lx.errAt(t.pos, "unexpected character")
		}
	}
	t.end = lx.pos
	lx.tok = t
}

func hexVal(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

// parse \uXXXX or \u{...} at lx.pos (pointing after 'u'); returns -1 on error
func (lx *Lexer) scanUnicodeEscape() rune {
	if lx.pos < len(lx.src) && lx.src[lx.pos] == '{' {
		lx.pos++
		var v rune
		n := 0
		for lx.pos < len(lx.src) && lx.src[lx.pos] != '}' {
			h := hexVal(lx.src[lx.pos])
			if h < 0 {
				return -1
			}
			v = v*16 + rune(h)
			if v > 0x10FFFF {
				return -1
			}
			lx.pos++
			n++
		}
		if lx.pos >= len(lx.src) || n == 0 {
			return -1
		}
		lx.pos++
		return v
	}
	if lx.pos+4 > len(lx.src) {
		return -1
	}
	var v rune
	for i := 0; i < 4; i++ {
		h := hexVal(lx.src[lx.pos+i])
		if h < 0 {
			return -1
		}
		v = v*16 + rune(h)
	}
	lx.pos += 4
	return v
}

func (lx *Lexer) scanIdentName() (string, bool) {
	var sb strings.Builder
	esc := false
	first := true
	for lx.pos < len(lx.src) {
		r, sz := lx.peekRune(lx.pos)
		if r == '\\' {
			p0 := lx.pos
			lx.pos++
			if lx.pos >= len(lx.src) || lx.src[lx.pos] != 'u' {
				lx.errAt(p0, "invalid escape sequence")
			}
			lx.pos++
			cp := lx.scanUnicodeEscape()
			if cp < 0 || (first && !isIDStart(cp)) || (!first && !isIDPart(cp)) {
				lx.errAt(p0, "invalid escape sequence")
			}
			esc = true
			sb.WriteRune(cp)
			first = false
			continue
		}
		if first {
			if !isIDStart(r) {
				break
			}
		} else if !isIDPart(r) {
			break
		}
		sb.WriteString(lx.src[lx.pos : lx.pos+sz])
		lx.pos += sz
		first = false
	}
	return sb.String(), esc
}

func (lx *Lexer) scanString(t *Token, q byte) {
	start := lx.pos
	lx.pos++
	var b strBuilder
	for {
		if lx.pos >= len(lx.src) {
			lx.errAt(start, "unexpected end of string")
		}
		c := lx.src[lx.pos]
		if c == q {
			lx.pos++
			break
		}
		if c == '\\' {
			lx.pos++
			if lx.pos >= len(lx.src) {
				lx.errAt(start, "unexpected end of string")
			}
			if !lx.scanEscape(&b, t, false) {
				lx.errAt(lx.pos, "invalid escape sequence")
			}
			continue
		}
		if c == '\n' || c == '\r' {
			lx.errAt(start, "unexpected end of string")
		}
		if c < 0x80 {
			b.WriteUnit(uint16(c))
			lx.pos++
			continue
		}
		r, sz := utf8.DecodeRuneInString(lx.src[lx.pos:])
		b.WriteCodePoint(r)
		lx.pos += sz
	}
	t.kind = tStr
	t.sval = b.String()
	t.raw = lx.src[start:lx.pos]
}

// scanEscape handles escape after backslash. returns false on invalid escape.
func (lx *Lexer) scanEscape(b *strBuilder, t *Token, template bool) bool {
	c := lx.src[lx.pos]
	switch c {
	case 'n':
		b.WriteUnit('\n')
	case 't':
		b.WriteUnit('\t')
	case 'r':
		b.WriteUnit('\r')
	case 'b':
		b.WriteUnit('\b')
	case 'f':
		b.WriteUnit('\f')
	case 'v':
		b.WriteUnit('\v')
	case '\r':
		lx.pos++
		if lx.pos < len(lx.src) && lx.src[lx.pos] == '\n' {
			lx.pos++
		}
		return true
	case '\n':
		lx.pos++
		return true
	case 'x':
		if lx.pos+2 < len(lx.src)+0 && lx.pos+2 <= len(lx.src)-1+1 {
			if lx.pos+2 < len(lx.src)+1 && lx.pos+2 <= len(lx.src) {
				h1 := -1
				h2 := -1
				if lx.pos+1 < len(lx.src) {
					h1 = hexVal(lx.src[lx.pos+1])
				}
				if lx.pos+2 < len(lx.src) {
					h2 = hexVal(lx.src[lx.pos+2])
				}
				if h1 >= 0 && h2 >= 0 {
					b.WriteUnit(uint16(h1*16 + h2))
					lx.pos += 3
					return true
				}
			}
		}
		return false
	case 'u':
		lx.pos++
		cp := lx.scanUnicodeEscape()
		if cp < 0 {
			return false
		}
		b.WriteCodePoint(cp)
		return true
	case '0', '1', '2', '3', '4', '5', '6', '7':
		if c == '0' && (lx.pos+1 >= len(lx.src) || lx.src[lx.pos+1] < '0' || lx.src[lx.pos+1] > '9') {
			b.WriteUnit(0)
			lx.pos++
			return true
		}
		if template {
			return false
		}
		// legacy octal
		t.legacyOctal = true
		v := int(c - '0')
		lx.pos++
		if lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '7' {
			v = v*8 + int(lx.src[lx.pos]-'0')
			lx.pos++
			if c <= '3' && lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '7' {
				v = v*8 + int(lx.src[lx.pos]-'0')
				lx.pos++
			}
		}
		b.WriteUnit(uint16(v))
		return true
	case '8', '9':
		if template {
			return false
		}
		t.legacyOctal = true
		b.WriteUnit(uint16(c))
	default:
		if c < 0x80 {
			b.WriteUnit(uint16(c))
		} else {
			r, sz := utf8.DecodeRuneInString(lx.src[lx.pos:])
			if r == 0x2028 || r == 0x2029 {
				lx.pos += sz
				return true
			}
			b.WriteCodePoint(r)
			lx.pos += sz
			return true
		}
	}
	lx.pos++
	return true
}

// scanTemplate scans from after ` or } up to ${ or `
func (lx *Lexer) scanTemplate(t *Token) {
	start := lx.pos
	var b strBuilder
	invalid := false
	var raw strings.Builder
	for {
		if lx.pos >= len(lx.src) {
			lx.errAt(start-1, "unexpected end of template")
		}
		c := lx.src[lx.pos]
		if c == '`' {
			lx.pos++
			t.tail = true
			break
		}
		if c == '$' && lx.pos+1 < len(lx.src) && lx.src[lx.pos+1] == '{' {
			lx.pos += 2
			break
		}
		if c == '\\' {
			escStart := lx.pos
			lx.pos++
			if lx.pos >= len(lx.src) {
				lx.errAt(start, "unexpected end of template")
			}
			var tmp Token
			save := lx.pos
			if !lx.scanEscape(&b, &tmp, true) {
				invalid = true
				// skip the char
				lx.pos = save
				_, sz := lx.peekRune(lx.pos)
				lx.pos += sz
			}
			rawPart := lx.src[escStart:lx.pos]
			rawPart = strings.ReplaceAll(rawPart, "\r\n", "\n")
			rawPart = strings.ReplaceAll(rawPart, "\r", "\n")
			raw.WriteString(rawPart)
			continue
		}
		if c == '\r' {
			lx.pos++
			if lx.pos < len(lx.src) && lx.src[lx.pos] == '\n' {
				lx.pos++
			}
			b.WriteUnit('\n')
			raw.WriteByte('\n')
			continue
		}
		if c < 0x80 {
			b.WriteUnit(uint16(c))
			raw.WriteByte(c)
			lx.pos++
			continue
		}
		r, sz := utf8.DecodeRuneInString(lx.src[lx.pos:])
		b.WriteCodePoint(r)
		raw.WriteString(lx.src[lx.pos : lx.pos+sz])
		lx.pos += sz
	}
	t.kind = tTemplate
	if invalid {
		t.sval = nil
		t.invalidEsc = true
	} else {
		t.sval = b.String()
	}
	t.raw = raw.String()
}

// rescanTemplateContinuation: called when parser sees '}' closing a substitution
func (lx *Lexer) rescanTemplate() {
	// current token is '}' ; restart from its end
	lx.pos = lx.tok.pos + 1
	t := Token{pos: lx.tok.pos}
	lx.scanTemplate(&t)
	t.end = lx.pos
	lx.tok = t
}

func (lx *Lexer) rescanRegExp() {
	start := lx.tok.pos
	lx.pos = start + 1
	inClass := false
	for {
		if lx.pos >= len(lx.src) {
			lx.errAt(start, "unexpected end of regexp")
		}
		r, sz := lx.peekRune(lx.pos)
		if isLineTerm(r) {
			lx.errAt(start, "unexpected line terminator in regexp")
		}
		if r == '\\' {
			lx.pos++
			r2, sz2 := lx.peekRune(lx.pos)
			if r2 < 0 || isLineTerm(r2) {
				lx.errAt(start, "unexpected line terminator in regexp")
			}
			lx.pos += sz2
			continue
		}
		if r == '[' {
			inClass = true
		} else if r == ']' {
			inClass = false
		} else if r == '/' && !inClass {
			break
		}
		lx.pos += sz
	}
	pattern := lx.src[start+1 : lx.pos]
	lx.pos++
	fstart := lx.pos
	for lx.pos < len(lx.src) {
		r, sz := lx.peekRune(lx.pos)
		if !isIDPart(r) {
			break
		}
		lx.pos += sz
	}
	t := Token{kind: tRegExp, pos: start, str: pattern, flags: lx.src[fstart:lx.pos], nlBefore: lx.tok.nlBefore}
	t.end = lx.pos
	lx.tok = t
}

func (lx *Lexer) scanNumber(t *Token) {
	start := lx.pos
	src := lx.src
	t.kind = tNum
	isDigitSep := func(c byte, base int) bool {
		if c == '_' {
			return true
		}
		return hexVal(c) >= 0 && hexVal(c) < base
	}
	readDigits := func(base int) string {
		s := lx.pos
		lastSep := false
		for lx.pos < len(src) && isDigitSep(src[lx.pos], base) {
			if src[lx.pos] == '_' {
				if lastSep || lx.pos == s {
					lx.errAt(lx.pos, "invalid number literal")
				}
				lastSep = true
			} else {
				lastSep = false
			}
			lx.pos++
		}
		if lastSep {
			lx.errAt(lx.pos-1, "invalid number literal")
		}
		return strings.ReplaceAll(src[s:lx.pos], "_", "")
	}
	if src[lx.pos] == '0' && lx.pos+1 < len(src) {
		c2 := src[lx.pos+1] | 0x20
		base := 0
		switch c2 {
		case 'x':
			base = 16
		case 'o':
			base = 8
		case 'b':
			base = 2
		}
		if base != 0 {
			lx.pos += 2
			digits := readDigits(base)
			if digits == "" {
				lx.errAt(start, "invalid number literal")
			}
			if lx.pos < len(src) && src[lx.pos] == 'n' {
				lx.pos++
				bi := new(big.Int)
				bi.SetString(digits, base)
				t.kind = tBigInt
				t.str = bi.String()
			} else {
				t.num = parseIntDigits(digits, base)
			}
			lx.checkAfterNumber()
			return
		}
		if src[lx.pos+1] >= '0' && src[lx.pos+1] <= '9' || src[lx.pos+1] == '_' {
			// legacy octal or decimal with leading zero
			if src[lx.pos+1] == '_' {
				lx.errAt(lx.pos+1, "invalid number literal")
			}
			t.legacyOctal = true
			s := lx.pos
			octal := true
			for lx.pos < len(src) && src[lx.pos] >= '0' && src[lx.pos] <= '9' {
				if src[lx.pos] >= '8' {
					octal = false
				}
				lx.pos++
			}
			if octal {
				t.num = parseIntDigits(src[s:lx.pos], 8)
				lx.checkAfterNumber()
				return
			}
			// decimal with leading zero: may have fraction
			if lx.pos < len(src) && src[lx.pos] == '.' {
				lx.pos++
				for lx.pos < len(src) && src[lx.pos] >= '0' && src[lx.pos] <= '9' {
					lx.pos++
				}
			}
			if lx.pos < len(src) && (src[lx.pos]|0x20) == 'e' {
				lx.scanExponent()
			}
			f, _ := strconv.ParseFloat(src[s:lx.pos], 64)
			t.num = f
			lx.checkAfterNumber()
			return
		}
	}
	intPart := ""
	if src[lx.pos] != '.' {
		intPart = readDigits(10)
	}
	isInt := true
	frac := ""
	if lx.pos < len(src) && src[lx.pos] == '.' {
		isInt = false
		lx.pos++
		if lx.pos < len(src) && src[lx.pos] == '_' {
			lx.errAt(lx.pos, "invalid number literal")
		}
		frac = readDigits(10)
	}
	exp := ""
	if lx.pos < len(src) && (src[lx.pos]|0x20) == 'e' {
		isInt = false
		es := lx.pos
		lx.pos++
		if lx.pos < len(src) && (src[lx.pos] == '+' || src[lx.pos] == '-') {
			lx.pos++
		}
		if lx.pos >= len(src) || src[lx.pos] < '0' || src[lx.pos] > '9' {
			lx.errAt(es, "invalid number literal")
		}
		readDigits(10)
		exp = strings.ReplaceAll(src[es:lx.pos], "_", "")
	}
	if isInt && lx.pos < len(src) && src[lx.pos] == 'n' {
		lx.pos++
		t.kind = tBigInt
		bi := new(big.Int)
		bi.SetString(intPart, 10)
		t.str = bi.String()
		lx.checkAfterNumber()
		return
	}
	s := intPart
	if s == "" {
		s = "0"
	}
	if frac != "" {
		s += "." + frac
	}
	s += exp
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		// ParseFloat returns inf with err for overflow
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			// f is +-Inf or 0
		} else {
			lx.errAt(start, "invalid number literal")
		}
	}
	t.num = f
	lx.checkAfterNumber()
}

func (lx *Lexer) scanExponent() {
	lx.pos++
	if lx.pos < len(lx.src) && (lx.src[lx.pos] == '+' || lx.src[lx.pos] == '-') {
		lx.pos++
	}
	for lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '9' {
		lx.pos++
	}
}

func (lx *Lexer) checkAfterNumber() {
	r, _ := lx.peekRune(lx.pos)
	if r >= 0 && (isIDStart(r) || r == '\\' || (r >= '0' && r <= '9')) {
		lx.errAt(lx.pos, "invalid number literal")
	}
}

func parseIntDigits(digits string, base int) float64 {
	if len(digits) <= 12 || base == 10 && len(digits) <= 15 {
		v, err := strconv.ParseUint(digits, base, 64)
		if err == nil {
			return float64(v)
		}
	}
	if base == 10 {
		f, _ := strconv.ParseFloat(digits, 64)
		return f
	}
	bi := new(big.Int)
	bi.SetString(digits, base)
	f, _ := new(big.Float).SetInt(bi).Float64()
	if math.IsInf(f, 0) {
		return math.Inf(1)
	}
	return f
}
EOF
echo ok

