{"command":"cd /workspace && cat > parser.go <<'EOF'
package main

import (
	"fmt"
)

type fnCtx struct {
	f          *FuncNode
	parent     *fnCtx
	strict     bool
	isAsync    bool
	isGen      bool
	isArrow    bool
	breakables []breakable
	labels     []string
	allowSuperProp bool
	allowSuperCall bool
	allowNewTarget bool
	inClassField bool
	inStaticBlock bool
}

type breakable struct {
	labels []string
	isLoop bool
	isSwitch bool
}

type Parser struct {
	lx       Lexer
	sf       *SourceFile
	fc       *fnCtx
	noIn     bool
	isModule bool
	pendingLabels []string
	evalCtx  *evalContext
}

type evalContext struct {
	allowSuperProp bool
	allowSuperCall bool
	allowNewTarget bool
	allowArguments bool
	inFunction bool
	strict bool
}

func (p *Parser) tok() *Token { return &p.lx.tok }

func (p *Parser) next() { p.lx.next() }

func (p *Parser) errAt(pos int, format string, args ...interface{}) {
	panic(&SyntaxErr{msg: fmt.Sprintf(format, args...), pos: pos})
}

func (p *Parser) err(format string, args ...interface{}) {
	p.errAt(p.lx.tok.pos, format, args...)
}

func (p *Parser) is(s string) bool {
	t := &p.lx.tok
	return t.kind == tPunct && t.str == s
}

func (p *Parser) isKw(s string) bool {
	t := &p.lx.tok
	return t.kind == tIdent && t.str == s && !t.escaped
}

func (p *Parser) eat(s string) bool {
	if p.is(s) {
		p.next()
		return true
	}
	return false
}

func tokDesc(t *Token) string {
	switch t.kind {
	case tEOF:
		return ""
	case tStr:
		return "string"
	case tNum:
		return "number"
	case tBigInt:
		return "bigint"
	case tTemplate:
		return "template"
	case tRegExp:
		return "regexp"
	}
	return t.str
}

func (p *Parser) expect(s string) {
	if !p.is(s) {
		p.err("expecting '%s'", s)
	}
	p.next()
}

func (p *Parser) expectKw(s string) {
	if !p.isKw(s) {
		p.err("expecting '%s'", s)
	}
	p.next()
}

// automatic semicolon insertion
func (p *Parser) semicolon() {
	t := &p.lx.tok
	if t.kind == tPunct && t.str == ";" {
		p.next()
		return
	}
	if t.kind == tEOF || (t.kind == tPunct && t.str == "}") || t.nlBefore {
		return
	}
	p.err("expecting ';'")
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true, "continue": true,
	"debugger": true, "default": true, "delete": true, "do": true, "else": true, "enum": true,
	"export": true, "extends": true, "false": true, "finally": true, "for": true, "function": true,
	"if": true, "import": true, "in": true, "instanceof": true, "new": true, "null": true,
	"return": true, "super": true, "switch": true, "this": true, "throw": true, "true": true,
	"try": true, "typeof": true, "var": true, "void": true, "while": true, "with": true,
}

var strictReserved = map[string]bool{
	"implements": true, "interface": true, "let": true, "package": true, "private": true,
	"protected": true, "public": true, "static": true, "yield": true,
}

func (p *Parser) strict() bool { return p.fc.strict }

// is current token an identifier usable as binding/reference
func (p *Parser) isIdentRef() bool {
	t := &p.lx.tok
	if t.kind != tIdent {
		return false
	}
	if reservedWords[t.str] {
		return false
	}
	if t.str == "yield" && (p.fc.isGen || p.strict()) {
		return false
	}
	if t.str == "await" && (p.fc.isAsync || p.isModule) {
		return false
	}
	if p.strict() && strictReserved[t.str] {
		return false
	}
	return true
}

func (p *Parser) parseIdentRef() *Ident {
	t := &p.lx.tok
	if !p.isIdentRef() {
		if t.kind == tIdent && (t.str == "yield" || t.str == "await" || reservedWords[t.str] || strictReserved[t.str]) {
			if t.kind == tIdent && !reservedWords[t.str] && p.strict() && strictReserved[t.str] {
				p.err("invalid keyword: %s", t.str)
			}
			p.err("unexpected token in expression: '%s'", tokDesc(t))
		}
		p.err("identifier expected")
	}
	id := &Ident{pos: t.pos, Name: t.str}
	p.next()
	return id
}

func (p *Parser) parseBindingIdent() *Ident {
	t := &p.lx.tok
	if t.kind != tIdent {
		p.err("variable name expected")
	}
	if !p.isIdentRef() {
		if p.strict() && strictReserved[t.str] && !reservedWords[t.str] {
			p.err("invalid variable name in strict mode")
		}
		if reservedWords[t.str] && !(t.escaped == false && false) {
			p.err("variable name expected")
		}
		p.err("variable name expected")
	}
	if p.strict() && (t.str == "eval" || t.str == "arguments") {
		p.err("invalid variable name in strict mode")
	}
	id := &Ident{pos: t.pos, Name: t.str}
	p.next()
	return id
}

// ---------------- Program ----------------

func parseProgram(sf *SourceFile, isModule bool, strict bool, ec *evalContext) (prog *Program, err *SyntaxErr) {
	p := &Parser{sf: sf, isModule: isModule, evalCtx: ec}
	p.lx.src = sf.src
	p.lx.file = sf
	moduleLexFlag = isModule
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*SyntaxErr); ok {
				err = se
				prog = nil
				return
			}
			panic(r)
		}
	}()
	f := &FuncNode{pos: 0, end: len(sf.src), src: sf, isScript: !isModule, isModule: isModule}
	f.Strict = strict || isModule
	p.fc = &fnCtx{f: f, strict: f.Strict}
	if isModule {
		p.fc.isAsync = true // top-level await
	}
	if ec != nil {
		f.isEvalCode = true
		p.fc.allowSuperProp = ec.allowSuperProp
		p.fc.allowSuperCall = ec.allowSuperCall
		p.fc.allowNewTarget = ec.allowNewTarget
	}
	// skip hashbang
	if len(sf.src) >= 2 && sf.src[0] == '#' && sf.src[1] == '!' {
		i := 0
		for i < len(sf.src) && sf.src[i] != '\n' && sf.src[i] != '\r' {
			i++
		}
		p.lx.pos = i
	}
	p.next()
	prog = &Program{F: f, IsModule: isModule}
	body := p.parseDirectivesAndBody(true)
	f.Body = body
	f.Strict = p.fc.strict
	prog.Body = body
	return prog, nil
}

func (p *Parser) parseDirectivesAndBody(top bool) []Node {
	var body []Node
	directives := true
	for {
		t := &p.lx.tok
		if t.kind == tEOF {
			if !top {
				p.err("unexpected token in expression: ''")
			}
			break
		}
		if !top && t.kind == tPunct && t.str == "}" {
			break
		}
		if directives {
			if t.kind == tStr {
				raw := t.raw
				// check if this is a complete expression statement
				save := p.lx
				p.next()
				nt := &p.lx.tok
				isDirective := nt.kind == tEOF || (nt.kind == tPunct && (nt.str == ";" || nt.str == "}")) || nt.nlBefore && !(nt.kind == tPunct && isContinuationPunct(nt.str))
				p.lx = save
				if isDirective {
					if raw == "'use strict'" || raw == "\"use strict\"" {
						if !p.fc.f.SimpleParams && !p.fc.f.isScript && !p.fc.f.isModule && p.fc.f.Params != nil && !p.fc.f.isEvalCode {
							p.err("\"use strict\" not allowed in function with default or destructuring parameter")
						}
						p.fc.strict = true
						p.fc.f.Strict = true
					}
				} else {
					directives = false
				}
			} else {
				directives = false
			}
		}
		body = append(body, p.parseStatementListItem())
	}
	return body
}

func isContinuationPunct(s string) bool {
	switch s {
	case "(", "[", ".", "+", "-", "*", "/", "%", "=", "==", "===", "!=", "!==", "<", ">", "<=", ">=", "&&", "||", "??", "?", ",", "?.", "`", "&", "|", "^", "**", "in", "instanceof", "+=", "-=":
		return true
	}
	return false
}

// ---------------- Statements ----------------

func (p *Parser) isLetDecl() bool {
	if !p.isKw("let") {
		return false
	}
	// let followed by identifier, [ or {
	save := p.lx
	p.next()
	t := &p.lx.tok
	r := false
	if t.kind == tIdent && !(t.str == "in" || t.str == "instanceof") {
		if !t.nlBefore || !(reservedWords[t.str]) {
			r = true
		}
		if t.str == "of" {
			r = !t.nlBefore || true
		}
	} else if t.kind == tPunct && (t.str == "[" || t.str == "{") {
		r = true
	}
	p.lx = save
	return r
}

func (p *Parser) isAsyncFunction() bool {
	if !p.isKw("async") {
		return false
	}
	save := p.lx
	p.next()
	r := p.isKw("function") && !p.lx.tok.nlBefore
	p.lx = save
	return r
}

func (p *Parser) parseStatementListItem() Node {
	t := &p.lx.tok
	if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "function":
			return p.parseFunctionDecl(false, t.pos)
		case "class":
			return p.parseClassDecl()
		case "const":
			return p.parseVarStatement("const")
		case "let":
			if p.isLetDecl() {
				return p.parseVarStatement("let")
			}
		case "async":
			if p.isAsyncFunction() {
				pos := t.pos
				p.next()
				return p.parseFunctionDecl(true, pos)
			}
		case "import":
			if p.isModule && p.fc.parent == nil && !p.fc.f.isEvalCode {
				save := p.lx
				p.next()
				if !p.is("(") && !p.is(".") {
					p.lx = save
					return p.parseImportDecl()
				}
				p.lx = save
			}
		case "export":
			if p.isModule && p.fc.parent == nil && !p.fc.f.isEvalCode {
				return p.parseExportDecl()
			}
		}
	}
	return p.parseStatement()
}

func (p *Parser) parseStatement() Node {
	t := &p.lx.tok
	pos := t.pos
	if t.kind == tPunct {
		switch t.str {
		case "{":
			return p.parseBlock()
		case ";":
			p.next()
			return &EmptyStmt{pos: pos}
		}
	}
	if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "var":
			return p.parseVarStatement("var")
		case "if":
			return p.parseIf()
		case "for":
			return p.parseFor()
		case "while":
			p.next()
			p.expect("(")
			test := p.parseExpression()
			p.expect(")")
			w := &WhileStmt{pos: pos, Test: test, labels: p.takeLabels()}
			w.Body = p.parseLoopBody(w.labels)
			return w
		case "do":
			p.next()
			d := &DoWhileStmt{pos: pos, labels: p.takeLabels()}
			d.Body = p.parseLoopBody(d.labels)
			p.expectKw("while")
			p.expect("(")
			d.Test = p.parseExpression()
			p.expect(")")
			if p.is(";") {
				p.next()
			}
			return d
		case "continue", "break":
			isBreak := t.str == "break"
			p.next()
			label := ""
			if p.lx.tok.kind == tIdent && !p.lx.tok.nlBefore && !reservedWords[p.lx.tok.str] {
				label = p.lx.tok.str
				p.next()
			}
			p.checkBreak(isBreak, label, pos)
			p.semicolon()
			if isBreak {
				return &BreakStmt{pos: pos, Label: label}
			}
			return &ContinueStmt{pos: pos, Label: label}
		case "return":
			if p.fc.parent == nil && (p.fc.f.isScript || p.fc.f.isModule || p.fc.f.isEvalCode) {
				p.err("return not in a function")
			}
			p.next()
			var x Node
			nt := &p.lx.tok
			if !(nt.kind == tEOF || nt.kind == tPunct && (nt.str == ";" || nt.str == "}") || nt.nlBefore) {
				x = p.parseExpression()
				if c, ok := x.(*CallExpr); ok {
					c.tail = true
					c.retPos = pos
				}
			}
			p.semicolon()
			return &ReturnStmt{pos: pos, X: x}
		case "throw":
			p.next()
			if p.lx.tok.nlBefore {
				p.err("line terminator not allowed after throw")
			}
			x := p.parseExpression()
			p.semicolon()
			return &ThrowStmt{pos: pos, X: x}
		case "try":
			return p.parseTry()
		case "switch":
			return p.parseSwitch()
		case "debugger":
			p.next()
			p.semicolon()
			return &DebuggerStmt{pos: pos}
		case "with":
			if p.strict() {
				p.err("invalid keyword: with")
			}
			p.next()
			p.expect("(")
			obj := p.parseExpression()
			p.expect(")")
			body := p.parseStatement()
			return &WithStmt{pos: pos, Obj: obj, Body: body}
		case "function":
			// function declaration in statement position (sloppy annex B: if body)
			if p.strict() {
				p.err("function declarations can't appear in single-statement context")
			}
			return p.parseFunctionDecl(false, pos)
		case "class":
			p.err("unexpected token in expression: 'class'")
		case "const":
			p.err("lexical declarations can't appear in single-statement context")
		case "let":
			save := p.lx
			p.next()
			if p.is("[") {
				p.err("lexical declarations can't appear in single-statement context")
			}
			p.lx = save
		case "import":
			save := p.lx
			p.next()
			if !p.is("(") && !p.is(".") {
				p.lx = save
				if !p.isModule {
					p.err("unexpected token in expression: 'import'")
				}
				p.err("unexpected token in expression: 'import'")
			}
			p.lx = save
		case "export":
			p.err("unexpected token in expression: 'export'")
		}
		// labeled statement
		if p.isIdentRef() || t.str == "yield" || t.str == "await" {
			save := p.lx
			name := t.str
			p.next()
			if p.is(":") {
				if !p.isIdentRefName(name) {
					p.lx = save
				} else {
					p.next()
					for _, l := range p.fc.labels {
						if l == name {
							p.errAt(p.lx.prev.pos, "duplicate label name")
						}
					}
					for _, l := range p.pendingLabels {
						if l == name {
							p.errAt(p.lx.prev.pos, "duplicate label name")
						}
					}
					p.pendingLabels = append(p.pendingLabels, name)
					p.fc.labels = append(p.fc.labels, name)
					var body Node
					nt := &p.lx.tok
					if nt.kind == tIdent && !nt.escaped && (nt.str == "for" || nt.str == "while" || nt.str == "do") {
						body = p.parseStatement()
					} else if nt.kind == tIdent && nt.str == "function" && !nt.escaped {
						if p.strict() {
							p.err("function declarations can't appear in single-statement context")
						}
						p.pendingLabels = nil
						body = p.parseFunctionDecl(false, nt.pos)
					} else {
						labels := p.takeLabels()
						p.fc.breakables = append(p.fc.breakables, breakable{labels: labels})
						body = p.parseStatement()
						p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
					}
					p.fc.labels = p.fc.labels[:len(p.fc.labels)-1]
					return &LabeledStmt{pos: pos, Label: name, Body: body}
				}
			} else {
				p.lx = save
			}
		}
	}
	p.pendingLabels = nil
	x := p.parseExpression()
	p.semicolon()
	return &ExprStmt{pos: pos, X: x}
}

func (p *Parser) isIdentRefName(name string) bool {
	if reservedWords[name] {
		return false
	}
	if name == "yield" && (p.fc.isGen || p.strict()) {
		return false
	}
	if name == "await" && (p.fc.isAsync || p.isModule) {
		return false
	}
	return true
}

func (p *Parser) takeLabels() []string {
	l := p.pendingLabels
	p.pendingLabels = nil
	return l
}

func (p *Parser) parseLoopBody(labels []string) Node {
	p.fc.breakables = append(p.fc.breakables, breakable{labels: labels, isLoop: true})
	body := p.parseStatement()
	p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
	return body
}

func (p *Parser) checkBreak(isBreak bool, label string, pos int) {
	bs := p.fc.breakables
	if label == "" {
		for i := len(bs) - 1; i >= 0; i-- {
			if bs[i].isLoop || (isBreak && bs[i].isSwitch) {
				return
			}
		}
		if isBreak {
			p.err("break must be inside loop or switch")
		}
		p.err("continue must be inside loop")
	}
	for i := len(bs) - 1; i >= 0; i-- {
		for _, l := range bs[i].labels {
			if l == label {
				if !isBreak && !bs[i].isLoop {
					p.errAt(p.lx.tok.pos, "break/continue label not found")
				}
				return
			}
		}
	}
	p.errAt(p.lx.tok.pos, "break/continue label not found")
}

func (p *Parser) parseBlock() *BlockStmt {
	pos := p.lx.tok.pos
	p.expect("{")
	p.pendingLabels = nil
	b := &BlockStmt{pos: pos}
	for !p.is("}") {
		if p.lx.tok.kind == tEOF {
			p.err("expecting '}'")
		}
		b.Body = append(b.Body, p.parseStatementListItem())
	}
	p.next()
	return b
}

func (p *Parser) parseVarStatement(kind string) Node {
	pos := p.lx.tok.pos
	p.next()
	d := p.parseVarDecls(kind, pos, false)
	p.semicolon()
	return d
}

func (p *Parser) parseVarDecls(kind string, pos int, inFor bool) *VarDecl {
	d := &VarDecl{pos: pos, Kind: kind}
	for {
		dpos := p.lx.tok.pos
		var target Node
		if p.is("[") || p.is("{") {
			target = p.parseBindingPattern()
		} else {
			t := &p.lx.tok
			if kind != "var" && t.kind == tIdent && t.str == "let" {
				p.err("'let' is not a valid lexical identifier")
			}
			target = p.parseBindingIdent()
		}
		var init Node
		if p.is("=") {
			p.next()
			init = p.parseAssign()
		} else if !inFor || !(p.isKw("in") || p.isKw("of")) {
			if kind == "const" {
				p.err("missing initializer for const variable")
			}
			if _, ok := target.(*Ident); !ok {
				p.errAt(dpos, "variable name expected")
			}
		}
		d.Decls = append(d.Decls, &VarDeclarator{pos: dpos, Target: target, Init: init})
		if !p.is(",") {
			break
		}
		p.next()
	}
	return d
}

func (p *Parser) parseIf() Node {
	pos := p.lx.tok.pos
	p.next()
	p.expect("(")
	test := p.parseExpression()
	p.expect(")")
	p.pendingLabels = nil
	cons := p.parseSubStatement()
	var alt Node
	if p.isKw("else") {
		p.next()
		alt = p.parseSubStatement()
	}
	return &IfStmt{pos: pos, Test: test, Cons: cons, Alt: alt}
}

func (p *Parser) parseSubStatement() Node {
	if p.isKw("function") && !p.strict() {
		// annex B: function declaration in if statement - wrap in block
		pos := p.lx.tok.pos
		fd := p.parseFunctionDecl(false, pos)
		return &BlockStmt{pos: pos, Body: []Node{fd}}
	}
	return p.parseStatement()
}

func (p *Parser) parseFor() Node {
	pos := p.lx.tok.pos
	p.next()
	labels := p.takeLabels()
	isAwait := false
	if p.isKw("await") && (p.fc.isAsync) {
		isAwait = true
		p.next()
	}
	p.expect("(")
	var init Node
	initPos := p.lx.tok.pos
	if p.is(";") {
		// no init
	} else {
		saveNoIn := p.noIn
		p.noIn = true
		if p.isKw("var") || p.isKw("const") || (p.isKw("let") && p.isLetDeclFor()) {
			kind := p.lx.tok.str
			p.next()
			init = p.parseVarDecls(kind, initPos, true)
		} else {
			startTok := p.lx.tok
			init = p.parseExpressionCover()
			if (p.isKw("of") && !(startTok.kind == tIdent && startTok.str == "async" && !startTok.escaped && isIdentNode(init, "async"))) || p.isKw("in") {
				// convert to pattern
				init = p.toAssignTarget(init, true)
			} else {
				p.checkCoverInit(init)
			}
			_ = startTok
		}
		p.noIn = saveNoIn
	}
	if p.isKw("of") || p.isKw("in") {
		isOf := p.lx.tok.str == "of"
		if vd, ok := init.(*VarDecl); ok {
			if len(vd.Decls) != 1 {
				p.err("a declaration in the head of a for-%s loop can't have more than one binding", map[bool]string{true: "of", false: "in"}[isOf])
			}
			if vd.Decls[0].Init != nil {
				if isOf || p.strict() || vd.Kind != "var" {
					p.errAt(p.lx.tok.pos, "a declaration in the head of a for-%s loop can't have an initializer", map[bool]string{true: "of", false: "in"}[isOf])
				}
			}
		}
		p.next()
		var right Node
		if isOf {
			right = p.parseAssign()
		} else {
			right = p.parseExpression()
		}
		p.expect(")")
		fs := &ForInStmt{pos: pos, Left: init, Right: right, Of: isOf, Await: isAwait, labels: labels}
		fs.Body = p.parseLoopBody(labels)
		return fs
	}
	if isAwait {
		p.err("expecting 'of'")
	}
	if vd, ok := init.(*VarDecl); ok {
		for _, d := range vd.Decls {
			if d.Init == nil {
				if vd.Kind == "const" {
					p.err("missing initializer for const variable")
				}
				if _, ok := d.Target.(*Ident); !ok {
					p.err("variable name expected")
				}
			}
		}
	}
	p.expect(";")
	var test, update Node
	if !p.is(";") {
		test = p.parseExpression()
	}
	p.expect(";")
	if !p.is(")") {
		update = p.parseExpression()
	}
	p.expect(")")
	fs := &ForStmt{pos: pos, Init: init, Test: test, Update: update, labels: labels}
	fs.Body = p.parseLoopBody(labels)
	return fs
}

func isIdentNode(n Node, name string) bool {
	id, ok := n.(*Ident)
	return ok && id.Name == name
}

func (p *Parser) isLetDeclFor() bool {
	save := p.lx
	p.next()
	t := &p.lx.tok
	r := false
	if t.kind == tIdent && !(t.str == "in" || t.str == "of") {
		r = true
	} else if t.kind == tIdent && t.str == "of" {
		// for (let of ...) is ambiguous; treat 'let' as identifier unless followed by...
		r = false
	} else if t.kind == tPunct && (t.str == "[" || t.str == "{") {
		r = true
	}
	p.lx = save
	return r
}

func (p *Parser) parseTry() Node {
	pos := p.lx.tok.pos
	p.next()
	ts := &TryStmt{pos: pos}
	p.pendingLabels = nil
	ts.Block = p.parseBlock()
	if p.isKw("catch") {
		p.next()
		if p.is("(") {
			p.next()
			if p.is("[") || p.is("{") {
				ts.Param = p.parseBindingPattern()
			} else {
				ts.Param = p.parseBindingIdent()
			}
			p.expect(")")
		}
		ts.Handler = p.parseBlock()
	}
	if p.isKw("finally") {
		p.next()
		ts.Finalizer = p.parseBlock()
	}
	if ts.Handler == nil && ts.Finalizer == nil {
		p.err("expecting catch or finally")
	}
	return ts
}

func (p *Parser) parseSwitch() Node {
	pos := p.lx.tok.pos
	p.next()
	labels := p.takeLabels()
	p.expect("(")
	disc := p.parseExpression()
	p.expect(")")
	p.expect("{")
	ss := &SwitchStmt{pos: pos, Disc: disc, labels: labels}
	p.fc.breakables = append(p.fc.breakables, breakable{labels: labels, isSwitch: true})
	hasDefault := false
	for !p.is("}") {
		cpos := p.lx.tok.pos
		c := &SwitchCase{pos: cpos}
		if p.isKw("case") {
			p.next()
			c.Test = p.parseExpression()
		} else if p.isKw("default") {
			if hasDefault {
				p.err("duplicate default")
			}
			hasDefault = true
			p.next()
		} else {
			p.err("invalid switch statement")
		}
		p.expect(":")
		for !p.is("}") && !p.isKw("case") && !p.isKw("default") {
			if p.lx.tok.kind == tEOF {
				p.err("expecting '}'")
			}
			c.Body = append(c.Body, p.parseStatementListItem())
		}
		ss.Cases = append(ss.Cases, c)
	}
	p.next()
	p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
	return ss
}

// ---------------- Functions ----------------

func (p *Parser) parseFunctionDecl(isAsync bool, pos int) Node {
	p.expectKw("function")
	isGen := false
	if p.is("*") {
		isGen = true
		p.next()
	}
	t := &p.lx.tok
	if t.kind != tIdent {
		p.err("function name expected")
	}
	var nameId *Ident
	if p.isIdentRef() || (t.str == "yield" && !p.strict() && !isGen && !p.fc.isGen) || (t.str == "await" && !p.isModule && !p.fc.isAsync) {
		nameId = &Ident{pos: t.pos, Name: t.str}
		if p.strict() && (t.str == "eval" || t.str == "arguments") {
			p.err("invalid function name in strict code")
		}
		p.next()
	} else {
		p.err("function name expected")
	}
	f := p.parseFunctionRest(pos, nameId.Name, nameId.pos, isAsync, isGen, FKNormal, false)
	f.IsDecl = true
	p.pendingLabels = nil
	return &FuncDecl{pos: pos, F: f}
}

func (p *Parser) parseFunctionExpr(isAsync bool, pos int) Node {
	p.expectKw("function")
	isGen := false
	if p.is("*") {
		isGen = true
		p.next()
	}
	name := ""
	namePos := 0
	t := &p.lx.tok
	if t.kind == tIdent && !p.is("(") {
		ok := p.isIdentRef()
		if !ok {
			if t.str == "yield" && !p.strict() && !isGen {
				ok = true
			} else if t.str == "await" && !p.isModule && !isAsync {
				ok = true
			}
		}
		if t.str == "yield" && isGen || t.str == "await" && isAsync {
			ok = false
		}
		if !ok {
			p.err("function name expected")
		}
		if p.strict() && (t.str == "eval" || t.str == "arguments") {
			p.err("invalid function name in strict code")
		}
		name = t.str
		namePos = t.pos
		p.next()
	}
	f := p.parseFunctionRest(pos, name, namePos, isAsync, isGen, FKNormal, false)
	f.IsExpr = name != ""
	return &FuncExpr{pos: pos, F: f}
}

func (p *Parser) enterFunc(f *FuncNode, isAsync, isGen, isArrow bool) *fnCtx {
	fc := &fnCtx{f: f, parent: p.fc, strict: p.fc.strict, isAsync: isAsync, isGen: isGen, isArrow: isArrow}
	if isArrow {
		fc.allowSuperProp = p.fc.allowSuperProp
		fc.allowSuperCall = p.fc.allowSuperCall
		fc.allowNewTarget = p.fc.allowNewTarget
		fc.inClassField = p.fc.inClassField
	} else {
		fc.allowNewTarget = true
	}
	f.Strict = fc.strict
	old := p.fc
	p.fc = fc
	return old
}

// parse params and body; current token is '('
func (p *Parser) parseFunctionRest(pos int, name string, namePos int, isAsync, isGen bool, kind FuncKind, isMethod bool) *FuncNode {
	f := &FuncNode{pos: pos, Name: name, NamePos: namePos, IsAsync: isAsync, IsGen: isGen, Kind: kind, src: p.sf}
	old := p.enterFunc(f, isAsync, isGen, false)
	if kind == FKMethod || kind == FKGetter || kind == FKSetter || kind == FKClassConstructor || kind == FKDerivedConstructor {
		p.fc.allowSuperProp = true
	}
	if kind == FKDerivedConstructor {
		p.fc.allowSuperCall = true
	}
	saveLabels := p.pendingLabels
	p.pendingLabels = nil
	saveNoIn := p.noIn
	p.noIn = false
	p.parseParams(f)
	if kind == FKGetter && len(f.Params) != 0 {
		p.errAt(p.lx.prev.pos, "invalid number of arguments for getter or setter")
	}
	if kind == FKSetter && (len(f.Params) != 1 || isRest(f.Params[0])) {
		p.errAt(p.lx.prev.pos, "invalid number of arguments for getter or setter")
	}
	p.parseFunctionBody(f)
	p.noIn = saveNoIn
	p.pendingLabels = saveLabels
	p.fc = old
	return f
}

func isRest(n Node) bool {
	_, ok := n.(*Spread)
	return ok
}

func (p *Parser) parseParams(f *FuncNode) {
	p.expect("(")
	f.SimpleParams = true
	f.Params = []Node{}
	length := 0
	sawDefault := false
	for !p.is(")") {
		if p.is("...") {
			rpos := p.lx.tok.pos
			p.next()
			var target Node
			if p.is("[") || p.is("{") {
				target = p.parseBindingPattern()
			} else {
				target = p.parseBindingIdent()
			}
			f.Params = append(f.Params, &Spread{pos: rpos, X: target})
			f.SimpleParams = false
			if !p.is(")") {
				p.err("expecting ')'")
			}
			break
		}
		var target Node
		if p.is("[") || p.is("{") {
			target = p.parseBindingPattern()
			f.SimpleParams = false
		} else {
			target = p.parseBindingIdent()
		}
		if p.is("=") {
			apos := p.lx.tok.pos
			p.next()
			def := p.parseAssign()
			target = &AssignPat{pos: apos, Target: target, Default: def}
			f.SimpleParams = false
			sawDefault = true
		} else if !sawDefault {
			length++
		}
		f.Params = append(f.Params, target)
		if !p.is(")") {
			p.expect(",")
		}
	}
	f.length = length
	p.next()
}

func (p *Parser) parseFunctionBody(f *FuncNode) {
	if !p.is("{") {
		p.err("expecting '{'")
	}
	p.next()
	f.Body = p.parseDirectivesAndBody(false)
	f.Strict = p.fc.strict
	if f.Strict {
		p.checkStrictParams(f)
	}
	f.end = p.lx.tok.end
	p.next()
}

func (p *Parser) checkStrictParams(f *FuncNode) {
	var names []string
	var collect func(n Node)
	collect = func(n Node) {
		switch x := n.(type) {
		case *Ident:
			names = append(names, x.Name)
			if x.Name == "eval" || x.Name == "arguments" {
				p.errAt(x.pos, "invalid argument name in strict code")
			}
		case *AssignPat:
			collect(x.Target)
		case *Spread:
			collect(x.X)
		case *ObjPattern:
			for _, pp := range x.Props {
				collect(pp.Value)
			}
			if x.Rest != nil {
				collect(x.Rest)
			}
		case *ArrPattern:
			for _, e := range x.Elems {
				if e != nil {
					collect(e)
				}
			}
			if x.Rest != nil {
				collect(x.Rest)
			}
		}
	}
	for _, prm := range f.Params {
		collect(prm)
	}
	if f.Name == "eval" || f.Name == "arguments" {
		p.errAt(f.NamePos, "invalid function name in strict code")
	}
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			p.errAt(f.pos, "duplicate argument names not allowed in this context")
		}
		seen[n] = true
	}
}

// ---------------- Classes ----------------

func (p *Parser) parseClassDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.lx.tok.kind != tIdent || p.isKw("extends") {
		p.err("class statement requires a name")
	}
	c := p.parseClassRest(pos, true)
	p.pendingLabels = nil
	return &ClassDecl{pos: pos, C: c}
}

func (p *Parser) parseClassRest(pos int, needName bool) *ClassNode {
	c := &ClassNode{pos: pos, src: p.sf}
	saveStrict := p.fc.strict
	p.fc.strict = true
	if p.lx.tok.kind == tIdent && !p.isKw("extends") {
		t := &p.lx.tok
		if !p.isIdentRef() || t.str == "yield" || t.str == "let" || t.str == "static" || t.str == "implements" {
			if t.str == "await" && !p.isModule && !p.fc.isAsync {
			} else {
				p.err("class name expected")
			}
		}
		c.Name = t.str
		c.NamePos = t.pos
		p.next()
	}
	if p.isKw("extends") {
		p.next()
		c.HasSuper = true
		c.Super = p.parseLHS()
	}
	p.expect("{")
	for !p.is("}") {
		if p.is(";") {
			p.next()
			continue
		}
		if p.lx.tok.kind == tEOF {
			p.err("expecting '}'")
		}
		m := p.parseClassMember(c)
		if m != nil {
			c.Members = append(c.Members, m)
		}
	}
	c.end = p.lx.tok.end
	p.next()
	p.fc.strict = saveStrict
	return c
}

func (p *Parser) parsePropertyName() (key Node, name string, computed bool, private bool) {
	t := &p.lx.tok
	pos := t.pos
	switch t.kind {
	case tIdent:
		name = t.str
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tStr:
		name = t.sval.String()
		key = &StrLit{pos: pos, Val: t.sval}
		p.next()
	case tNum:
		key = &NumLit{pos: pos, Val: t.num}
		name = numberToGoString(t.num)
		p.next()
	case tBigInt:
		name = t.str
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tPrivate:
		name = t.str
		private = true
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tPunct:
		if t.str == "[" {
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			key = p.parseAssign()
			p.noIn = saveNoIn
			p.expect("]")
			computed = true
			return
		}
		fallthrough
	default:
		p.err("invalid property name")
	}
	return
}

func (p *Parser) parseClassMember(c *ClassNode) *ClassMember {
	pos := p.lx.tok.pos
	isStatic := false
	if p.isKw("static") {
		save := p.lx
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") {
			p.lx = save
		} else {
			isStatic = true
			if p.is("{") {
				// static block
				f := &FuncNode{pos: p.lx.tok.pos, Kind: FKClassStaticBlock, src: p.sf, Name: "<static_initializer>"}
				old := p.enterFunc(f, false, false, false)
				p.fc.allowSuperProp = true
				p.fc.inStaticBlock = true
				p.next()
				f.Params = []Node{}
				f.SimpleParams = true
				for !p.is("}") {
					if p.lx.tok.kind == tEOF {
						p.err("expecting '}'")
					}
					f.Body = append(f.Body, p.parseStatementListItem())
				}
				f.end = p.lx.tok.end
				p.next()
				p.fc = old
				return &ClassMember{pos: pos, Kind: "static-block", Static: true, Value: f}
			}
		}
	}
	kind := "method"
	isAsync := false
	isGen := false
	if p.isKw("async") {
		save := p.lx
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") || p.lx.tok.nlBefore {
			p.lx = save
		} else {
			isAsync = true
		}
	}
	if p.is("*") {
		isGen = true
		p.next()
	}
	if !isAsync && !isGen && (p.isKw("get") || p.isKw("set")) {
		save := p.lx
		which := p.lx.tok.str
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") {
			p.lx = save
		} else {
			kind = which
		}
	}
	keyPos := p.lx.tok.pos
	key, name, computed, private := p.parsePropertyName()
	m := &ClassMember{pos: pos, Static: isStatic, Key: key, KeyName: name, Computed: computed, Private: private}
	if private && name == "#constructor" {
		p.errAt(keyPos, "invalid method name")
	}
	if p.is("(") {
		fk := FKMethod
		if kind == "get" {
			fk = FKGetter
		} else if kind == "set" {
			fk = FKSetter
		}
		isCtor := !isStatic && !computed && !private && name == "constructor"
		if isCtor {
			if kind != "method" || isAsync || isGen {
				p.errAt(keyPos, "invalid constructor")
			}
			if c.Ctor != nil {
				p.errAt(p.lx.tok.pos, "property constructor appears more than once")
			}
			fk = FKClassConstructor
			if c.HasSuper {
				fk = FKDerivedConstructor
			}
		}
		f := p.parseFunctionRest(pos, name, keyPos, isAsync, isGen, fk, true)
		f.classNode = c
		if isCtor {
			c.Ctor = f
			f.Name = c.Name
			return nil
		}
		m.Kind = kind
		m.Value = f
		return m
	}
	if kind != "method" || isAsync || isGen {
		p.err("expecting '('")
	}
	if !computed && !private && (name == "constructor") {
		p.errAt(keyPos, "invalid field name")
	}
	if isStatic && !computed && name == "prototype" {
		p.errAt(keyPos, "invalid field name")
	}
	// field
	m.Kind = "field"
	f := &FuncNode{pos: p.lx.tok.pos, Kind: FKFieldInit, src: p.sf}
	if p.is("=") {
		p.next()
		old := p.enterFunc(f, false, false, false)
		p.fc.allowSuperProp = true
		p.fc.inClassField = true
		f.Params = []Node{}
		f.SimpleParams = true
		startPos := p.lx.tok.pos
		f.ExprBody = p.parseAssign()
		_ = startPos
		f.end = p.lx.prev.end
		p.fc = old
		m.Value = f
	}
	p.semicolon()
	return m
}

// ---------------- Patterns ----------------

func (p *Parser) parseBindingPattern() Node {
	pos := p.lx.tok.pos
	if p.is("[") {
		p.next()
		ap := &ArrPattern{pos: pos}
		for !p.is("]") {
			if p.is(",") {
				p.next()
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if p.is("...") {
				p.next()
				ap.Rest = p.parseBindingTarget()
				if !p.is("]") {
					p.err("expecting ']'")
				}
				break
			}
			el := p.parseBindingElement()
			ap.Elems = append(ap.Elems, el)
			if !p.is("]") {
				p.expect(",")
			}
		}
		p.next()
		return ap
	}
	p.expect("{")
	op := &ObjPattern{pos: pos}
	for !p.is("}") {
		if p.is("...") {
			p.next()
			op.Rest = p.parseBindingIdent()
			if !p.is("}") {
				p.err("expecting '}'")
			}
			break
		}
		ppos := p.lx.tok.pos
		t := &p.lx.tok
		var pp *PatProp
		if t.kind == tIdent {
			save := p.lx
			nameTok := *t
			p.next()
			if !p.is(":") {
				// shorthand
				p.lx = save
				id := p.parseBindingIdent()
				pp = &PatProp{pos: ppos, Key: &StrLit{pos: ppos, Val: newStr(nameTok.str)}, KeyName: nameTok.str, Value: id}
				if p.is("=") {
					apos := p.lx.tok.pos
					p.next()
					pp.Value = &AssignPat{pos: apos, Target: id, Default: p.parseAssign()}
				}
			} else {
				p.lx = save
			}
		}
		if pp == nil {
			key, name, computed, private := p.parsePropertyName()
			if private {
				p.errAt(ppos, "unexpected private name")
			}
			p.expect(":")
			pp = &PatProp{pos: ppos, Key: key, KeyName: name, Computed: computed}
			pp.Value = p.parseBindingElement()
		}
		op.Props = append(op.Props, pp)
		if !p.is("}") {
			p.expect(",")
		}
	}
	p.next()
	return op
}

func (p *Parser) parseBindingTarget() Node {
	if p.is("[") || p.is("{") {
		return p.parseBindingPattern()
	}
	return p.parseBindingIdent()
}

func (p *Parser) parseBindingElement() Node {
	target := p.parseBindingTarget()
	if p.is("=") {
		apos := p.lx.tok.pos
		p.next()
		return &AssignPat{pos: apos, Target: target, Default: p.parseAssign()}
	}
	return target
}

// convert expression (cover grammar) to assignment target
func (p *Parser) toAssignTarget(n Node, isDestructuring bool) Node {
	switch x := n.(type) {
	case *Ident:
		if p.strict() && (x.Name == "eval" || x.Name == "arguments") {
			p.errAt(x.pos, "invalid assignment left-hand side")
		}
		return x
	case *MemberExpr:
		if x.Optional {
			p.errAt(x.pos, "invalid assignment left-hand side")
		}
		return x
	case *OptChain:
		p.errAt(x.pos, "invalid assignment left-hand side")
	case *ParenExpr:
		inner := x.X
		switch inner.(type) {
		case *Ident, *MemberExpr, *ParenExpr:
			return p.toAssignTarget(inner, false)
		}
		if isDestructuring {
			p.errAt(x.pos, "invalid destructuring target")
		}
		p.errAt(x.pos, "invalid assignment left-hand side")
	case *ArrayLit:
		ap := &ArrPattern{pos: x.pos}
		for i, e := range x.Elems {
			if e == nil {
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if sp, ok := e.(*Spread); ok {
				if i != len(x.Elems)-1 || x.trailingHole {
					p.errAt(sp.pos, "invalid destructuring target")
				}
				ap.Rest = p.toAssignTarget(sp.X, true)
				if _, ok := ap.Rest.(*AssignPat); ok {
					p.errAt(sp.pos, "invalid destructuring target")
				}
				continue
			}
			ap.Elems = append(ap.Elems, p.toAssignElem(e))
		}
		return ap
	case *ObjectLit:
		op := &ObjPattern{pos: x.pos}
		for i, pr := range x.Props {
			switch pr.Kind {
			case PSpread:
				if i != len(x.Props)-1 {
					p.errAt(pr.pos, "invalid destructuring target")
				}
				op.Rest = p.toAssignTarget(pr.Value, true)
			case PInit, PProto:
				pp := &PatProp{pos: pr.pos, Key: pr.Key, KeyName: pr.KeyName, Computed: pr.Computed}
				if pr.Shorthand {
					id := pr.Value.(*Ident)
					p.checkBindingName(id)
					if pr.CoverInit != nil {
						pp.Value = &AssignPat{pos: pr.pos, Target: id, Default: pr.CoverInit}
					} else {
						pp.Value = id
					}
				} else {
					pp.Value = p.toAssignElem(pr.Value)
				}
				op.Props = append(op.Props, pp)
			default:
				p.errAt(pr.pos, "invalid destructuring target")
			}
		}
		return op
	case *AssignExpr:
		if x.Op == "=" {
			return &AssignPat{pos: x.pos, Target: x.L, Default: x.R}
		}
	case *AssignPat, *ObjPattern, *ArrPattern:
		return n
	}
	if isDestructuring {
		p.errAt(nodePos(n), "invalid destructuring target")
	}
	p.errAt(nodePos(n), "invalid assignment left-hand side")
	return nil
}

func (p *Parser) checkBindingName(id *Ident) {
	if reservedWords[id.Name] || (p.strict() && (strictReserved[id.Name] || id.Name == "eval" || id.Name == "arguments")) {
		p.errAt(id.pos, "invalid destructuring target")
	}
}

func (p *Parser) toAssignElem(e Node) Node {
	if a, ok := e.(*AssignExpr); ok && a.Op == "=" {
		return &AssignPat{pos: a.pos, Target: p.toAssignTarget(a.L, true), Default: a.R}
	}
	return p.toAssignTarget(e, true)
}

// convert arrow params from cover expressions
func (p *Parser) toParam(n Node) Node {
	switch x := n.(type) {
	case *Ident:
		if reservedWords[x.Name] {
			p.errAt(x.pos, "invalid parameter")
		}
		return x
	case *AssignExpr:
		if x.Op == "=" {
			return &AssignPat{pos: x.pos, Target: p.toParam(x.L), Default: x.R}
		}
	case *AssignPat:
		return x
	case *ArrayLit, *ObjectLit:
		return p.toBindingPattern(p.toAssignTarget(n, true))
	case *Spread:
		return &Spread{pos: x.pos, X: p.toParam(x.X)}
	case *ArrPattern, *ObjPattern:
		return p.toBindingPattern(x)
	}
	p.errAt(nodePos(n), "invalid parameter")
	return nil
}

func (p *Parser) toBindingPattern(n Node) Node {
	switch x := n.(type) {
	case *Ident:
		return x
	case *AssignPat:
		x.Target = p.toBindingPattern(x.Target)
		return x
	case *ArrPattern:
		for i, e := range x.Elems {
			if e != nil {
				x.Elems[i] = p.toBindingPattern(e)
			}
		}
		if x.Rest != nil {
			x.Rest = p.toBindingPattern(x.Rest)
		}
		return x
	case *ObjPattern:
		for _, pp := range x.Props {
			pp.Value = p.toBindingPattern(pp.Value)
		}
		if x.Rest != nil {
			x.Rest = p.toBindingPattern(x.Rest)
		}
		return x
	}
	p.errAt(nodePos(n), "invalid destructuring target")
	return nil
}

func (p *Parser) checkCoverInit(n Node) {
	// error if object literal contains shorthand initializer that wasn't converted
	switch x := n.(type) {
	case *ObjectLit:
		for _, pr := range x.Props {
			if pr.CoverInit != nil {
				p.errAt(pr.pos, "invalid property name")
			}
		}
	}
}

// ---------------- Expressions ----------------

func (p *Parser) parseExpression() Node {
	x := p.parseExpressionCover()
	p.checkCoverInit(x)
	return x
}

func (p *Parser) parseExpressionCover() Node {
	pos := p.lx.tok.pos
	x := p.parseAssign()
	if p.is(",") {
		seq := &SeqExpr{pos: pos, List: []Node{x}}
		for p.is(",") {
			p.next()
			seq.List = append(seq.List, p.parseAssign())
		}
		return seq
	}
	return x
}

func isAssignOp(s string) bool {
	switch s {
	case "=", "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=":
		return true
	}
	return false
}

func (p *Parser) parseAssign() Node {
	t := &p.lx.tok
	pos := t.pos
	// yield
	if t.kind == tIdent && t.str == "yield" && p.fc.isGen && !t.escaped {
		return p.parseYield()
	}
	// async arrow: async x => ...
	if t.kind == tIdent && t.str == "async" && !t.escaped {
		save := p.lx
		p.next()
		nt := &p.lx.tok
		if !nt.nlBefore && nt.kind == tIdent && !reservedWords[nt.str] {
			// async ident =>
			save2 := p.lx
			id := &Ident{pos: nt.pos, Name: nt.str}
			p.next()
			if p.is("=>") && !p.lx.tok.nlBefore {
				return p.parseArrowFrom(pos, []Node{id}, true)
			}
			p.lx = save2
		}
		p.lx = save
	}
	if t.kind == tIdent && p.isIdentRef() {
		// simple arrow: x => ...
		save := p.lx
		id := &Ident{pos: t.pos, Name: t.str}
		p.next()
		if p.is("=>") && !p.lx.tok.nlBefore {
			return p.parseArrowFrom(pos, []Node{id}, false)
		}
		p.lx = save
	}
	startTok := p.lx.tok
	left := p.parseConditional()
	if arrow, ok := left.(*ArrowFunc); ok {
		_ = arrow
		return left
	}
	t = &p.lx.tok
	if t.kind == tPunct && isAssignOp(t.str) {
		op := t.str
		opPos := t.pos
		var target Node
		if op == "=" {
			switch left.(type) {
			case *ObjectLit, *ArrayLit:
				target = p.toAssignTarget(left, true)
			default:
				target = p.toSimpleTarget(left, opPos)
			}
		} else {
			target = p.toSimpleTarget(left, opPos)
		}
		p.next()
		right := p.parseAssign()
		_ = startTok
		return &AssignExpr{pos: opPos, Op: op, L: target, R: right}
	}
	return left
}

func (p *Parser) toSimpleTarget(n Node, opPos int) Node {
	switch x := n.(type) {
	case *Ident:
		if p.strict() && (x.Name == "eval" || x.Name == "arguments") {
			p.errAt(opPos, "invalid assignment left-hand side")
		}
		return x
	case *MemberExpr:
		return x
	case *ParenExpr:
		switch x.X.(type) {
		case *Ident, *MemberExpr, *ParenExpr:
			return p.toSimpleTarget(x.X, opPos)
		}
	case *CallExpr:
		if !p.strict() {
			return x // runtime ReferenceError
		}
	}
	p.errAt(opPos, "invalid assignment left-hand side")
	return nil
}

func (p *Parser) parseYield() Node {
	pos := p.lx.tok.pos
	if p.fc.inClassField {
		p.err("yield not allowed here")
	}
	p.next()
	y := &YieldExpr{pos: pos}
	t := &p.lx.tok
	if t.nlBefore {
		return y
	}
	if p.is("*") {
		p.next()
		y.Delegate = true
		y.X = p.parseAssign()
		return y
	}
	if t.kind == tEOF || t.kind == tPunct && (t.str == ")" || t.str == "]" || t.str == "}" || t.str == "," || t.str == ";" || t.str == ":" || (t.str == "?" ) ) || (t.kind == tIdent && t.str == "in" && !t.escaped) {
		return y
	}
	y.X = p.parseAssign()
	return y
}

func (p *Parser) parseConditional() Node {
	pos := p.lx.tok.pos
	test := p.parseBinary(0)
	if _, ok := test.(*ArrowFunc); ok {
		return test
	}
	if p.is("?") {
		p.checkCoverInit(test)
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		cons := p.parseAssign()
		p.noIn = saveNoIn
		p.expect(":")
		alt := p.parseAssign()
		return &CondExpr{pos: pos, Test: test, Cons: cons, Alt: alt}
	}
	return test
}

func binPrec(t *Token, noIn bool) int {
	if t.kind == tPunct {
		switch t.str {
		case "??":
			return 1
		case "||":
			return 2
		case "&&":
			return 3
		case "|":
			return 4
		case "^":
			return 5
		case "&":
			return 6
		case "==", "!=", "===", "!==":
			return 7
		case "<", ">", "<=", ">=":
			return 8
		case "<<", ">>", ">>>":
			return 9
		case "+", "-":
			return 10
		case "*", "/", "%":
			return 11
		case "**":
			return 12
		}
	} else if t.kind == tIdent && !t.escaped {
		if t.str == "instanceof" {
			return 8
		}
		if t.str == "in" && !noIn {
			return 8
		}
	}
	return 0
}

func (p *Parser) parseBinary(minPrec int) Node {
	var left Node
	// private name 'in'
	if p.lx.tok.kind == tPrivate {
		t := p.lx.tok
		p.next()
		if !p.isKw("in") || p.noIn {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		if minPrec > 8 {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		opPos := p.lx.tok.pos
		p.next()
		right := p.parseBinary(9)
		left = &PrivateIn{pos: opPos, Name: t.str, R: right}
	} else {
		left = p.parseUnary()
	}
	if _, ok := left.(*ArrowFunc); ok {
		return left
	}
	for {
		t := &p.lx.tok
		prec := binPrec(t, p.noIn)
		if prec == 0 || prec <= minPrec && !(prec == 12 && minPrec == 12) {
			break
		}
		if prec < minPrec || (prec == minPrec && prec != 12) {
			break
		}
		op := t.str
		opPos := t.pos
		if op == "**" {
			if u, ok := left.(*UnaryExpr); ok {
				_ = u
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
			if _, ok := left.(*AwaitExpr); ok {
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
		}
		p.checkCoverInit(left)
		p.next()
		var right Node
		if op == "**" {
			right = p.parseBinary(11) // right assoc
		} else {
			right = p.parseBinary(prec)
		}
		if op == "??" || op == "||" || op == "&&" {
			// mixing ?? with || && without parens is error
			if op == "??" {
				if l, ok := left.(*LogicalExpr); ok && l.Op != "??" {
					p.errAt(opPos, "unexpected token in expression: '??'")
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op != "??" {
					p.errAt(opPos, "unexpected token in expression: '??'")
				}
			} else {
				if l, ok := left.(*LogicalExpr); ok && l.Op == "??" {
					p.errAt(opPos, "unexpected token in expression: '%s'", op)
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op == "??" {
					p.errAt(opPos, "unexpected token in expression: '%s'", op)
				}
			}
			left = &LogicalExpr{pos: opPos, Op: op, L: left, R: right}
		} else {
			left = &BinaryExpr{pos: opPos, Op: op, L: left, R: right}
		}
	}
	return left
}

func (p *Parser) parseUnary() Node {
	t := &p.lx.tok
	pos := t.pos
	if t.kind == tPunct {
		switch t.str {
		case "!", "~", "+", "-":
			op := t.str
			p.next()
			x := p.parseUnary()
			return &UnaryExpr{pos: pos, Op: op, X: x}
		case "++", "--":
			op := t.str
			p.next()
			x := p.parseUnary()
			x = p.checkUpdateTarget(x, pos)
			return &UpdateExpr{pos: pos, Op: op, Prefix: true, X: x}
		}
	} else if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "delete", "void", "typeof":
			op := t.str
			p.next()
			x := p.parseUnary()
			if op == "delete" && p.strict() {
				if _, ok := x.(*Ident); ok {
					p.errAt(pos, "cannot delete a direct reference in strict mode")
				}
			}
			if op == "delete" {
				if m, ok := x.(*MemberExpr); ok && m.Private {
					p.errAt(pos, "cannot delete a private class field")
				}
			}
			return &UnaryExpr{pos: pos, Op: op, X: x}
		case "await":
			if p.fc.isAsync && !p.fc.inClassField {
				if p.fc.inStaticBlock {
					p.err("await not allowed here")
				}
				p.next()
				x := p.parseUnary()
				return &AwaitExpr{pos: pos, X: x}
			}
		}
	}
	return p.parsePostfix()
}

func (p *Parser) checkUpdateTarget(x Node, pos int) Node {
	switch y := x.(type) {
	case *Ident:
		if p.strict() && (y.Name == "eval" || y.Name == "arguments") {
			p.errAt(pos, "invalid increment/decrement operand")
		}
		return x
	case *MemberExpr:
		return x
	case *ParenExpr:
		return p.checkUpdateTarget(y.X, pos)
	case *CallExpr:
		if !p.strict() {
			return x
		}
	}
	p.err("invalid increment/decrement operand")
	return nil
}

func (p *Parser) parsePostfix() Node {
	x := p.parseLHS()
	if _, ok := x.(*ArrowFunc); ok {
		return x
	}
	t := &p.lx.tok
	if t.kind == tPunct && (t.str == "++" || t.str == "--") && !t.nlBefore {
		op := t.str
		pos := t.pos
		x = p.checkUpdateTarget(x, pos)
		p.next()
		return &UpdateExpr{pos: pos, Op: op, Prefix: false, X: x}
	}
	return x
}

func (p *Parser) parseArgs() []Node {
	p.expect("(")
	args := []Node{}
	saveNoIn := p.noIn
	p.noIn = false
	for !p.is(")") {
		if p.is("...") {
			spos := p.lx.tok.pos
			p.next()
			args = append(args, &Spread{pos: spos, X: p.parseAssign()})
		} else {
			args = append(args, p.parseAssign())
		}
		if !p.is(")") {
			p.expect(",")
		}
	}
	p.noIn = saveNoIn
	p.next()
	return args
}

// parse call/member/new expression
func (p *Parser) parseLHS() Node {
	t := &p.lx.tok
	pos := t.pos
	var x Node
	if t.kind == tIdent && t.str == "new" && !t.escaped {
		x = p.parseNew()
	} else if t.kind == tIdent && t.str == "super" && !t.escaped {
		p.next()
		if p.is("(") {
			if !p.fc.allowSuperCall {
				p.errAt(pos, "super() is only valid in a derived class constructor")
			}
			argPos := p.lx.tok.pos
			args := p.parseArgs()
			x = &CallExpr{pos: argPos, Callee: &SuperExpr{pos: pos}, Args: args}
		} else if p.is(".") || p.is("[") {
			if !p.fc.allowSuperProp {
				p.errAt(p.lx.tok.pos, "'super' is only valid in a method")
			}
			x = &SuperExpr{pos: pos}
			x = p.parseMemberTail(x, true)
		} else {
			p.err("invalid use of 'super'")
		}
	} else if t.kind == tIdent && t.str == "import" && !t.escaped {
		p.next()
		if p.is(".") {
			p.next()
			if !p.isKw("meta") {
				p.err("invalid use of 'import'")
			}
			if !p.isModule {
				p.err("import.meta only valid in module code")
			}
			p.next()
			x = &ImportMetaExpr{pos: pos}
		} else {
			p.expect("(")
			saveNoIn := p.noIn
			p.noIn = false
			arg := p.parseAssign()
			var opt Node
			if p.is(",") {
				p.next()
				if !p.is(")") {
					opt = p.parseAssign()
					if p.is(",") {
						p.next()
					}
				}
			}
			p.noIn = saveNoIn
			p.expect(")")
			x = &ImportCall{pos: pos, X: arg, Opt: opt}
		}
	} else {
		x = p.parsePrimary()
		if _, ok := x.(*ArrowFunc); ok {
			return x
		}
	}
	return p.parseCallTail(x)
}

func (p *Parser) parseNew() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.is(".") {
		p.next()
		if !p.isKw("target") {
			p.err("expecting target")
		}
		if !p.fc.allowNewTarget && !p.inFunctionForNewTarget() {
			p.err("new.target only allowed within functions")
		}
		p.next()
		return &NewTargetExpr{pos: pos}
	}
	var callee Node
	if p.isKw("new") {
		callee = p.parseNew()
	} else if p.isKw("super") {
		p.err("invalid use of 'super'")
	} else if p.isKw("import") {
		p.err("invalid use of 'import'")
	} else {
		callee = p.parsePrimary()
	}
	callee = p.parseMemberTail(callee, false)
	if p.is("(") {
		argPos := p.lx.tok.pos
		args := p.parseArgs()
		return &NewExpr{pos: argPos, Callee: callee, Args: args}
	}
	return &NewExpr{pos: pos, Callee: callee, Args: nil}
}

func (p *Parser) inFunctionForNewTarget() bool {
	for fc := p.fc; fc != nil; fc = fc.parent {
		if !fc.isArrow {
			if fc.parent == nil {
				return fc.allowNewTarget
			}
			return true
		}
	}
	return false
}

// member accesses only (no calls) - used for new callee
func (p *Parser) parseMemberTail(x Node, superOnly bool) Node {
	for {
		t := &p.lx.tok
		if t.kind == tPunct && t.str == "." {
			pos := t.pos
			p.next()
			nt := &p.lx.tok
			if nt.kind == tPrivate {
				if _, ok := x.(*SuperExpr); ok {
					p.err("unexpected private name")
				}
				x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Private: true}
				p.next()
			} else if nt.kind == tIdent {
				x = &MemberExpr{pos: pos, Obj: x, Name: nt.str}
				p.next()
			} else {
				p.err("expecting field name")
			}
		} else if t.kind == tPunct && t.str == "[" {
			pos := t.pos
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			prop := p.parseExpression()
			p.noIn = saveNoIn
			p.expect("]")
			x = &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true}
		} else if t.kind == tTemplate && !superOnly {
			if _, ok := x.(*SuperExpr); ok {
				p.err("invalid use of 'super'")
			}
			tpl := p.parseTemplate(true)
			x = &TaggedTemplate{pos: tpl.pos, Tag: x, Tpl: tpl}
		} else {
			break
		}
		if superOnly {
			superOnly = false
		}
	}
	return x
}

func (p *Parser) parseCallTail(x Node) Node {
	inChain := false
	for {
		t := &p.lx.tok
		if t.kind == tPunct {
			switch t.str {
			case ".", "[":
				x = p.parseMemberTail1(x)
				continue
			case "(":
				pos := t.pos
				args := p.parseArgs()
				c := &CallExpr{pos: pos, Callee: x, Args: args}
				if id, ok := x.(*Ident); ok && id.Name == "eval" {
					c.isEval = true
				}
				x = c
				continue
			case "?.":
				pos := t.pos
				inChain = true
				p.next()
				nt := &p.lx.tok
				if nt.kind == tPunct && nt.str == "(" {
					cpos := nt.pos
					args := p.parseArgs()
					x = &CallExpr{pos: cpos, Callee: x, Args: args, Optional: true}
				} else if nt.kind == tPunct && nt.str == "[" {
					p.next()
					saveNoIn := p.noIn
					p.noIn = false
					prop := p.parseExpression()
					p.noIn = saveNoIn
					p.expect("]")
					x = &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true, Optional: true}
				} else if nt.kind == tIdent {
					x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Optional: true}
					p.next()
				} else if nt.kind == tPrivate {
					x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Optional: true, Private: true}
					p.next()
				} else if nt.kind == tTemplate {
					p.err("invalid tagged template in optional chain")
				} else {
					p.err("expecting field name")
				}
				continue
			}
		} else if t.kind == tTemplate {
			if inChain {
				p.err("invalid tagged template in optional chain")
			}
			tpl := p.parseTemplate(true)
			x = &TaggedTemplate{pos: tpl.pos, Tag: x, Tpl: tpl}
			continue
		}
		break
	}
	if inChain {
		return &OptChain{pos: nodePos(x), X: x}
	}
	return x
}

func (p *Parser) parseMemberTail1(x Node) Node {
	t := &p.lx.tok
	pos := t.pos
	if t.str == "." {
		p.next()
		nt := &p.lx.tok
		if nt.kind == tPrivate {
			x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Private: true}
			p.next()
		} else if nt.kind == tIdent {
			x = &MemberExpr{pos: pos, Obj: x, Name: nt.str}
			p.next()
		} else {
			p.err("expecting field name")
		}
		return x
	}
	p.next()
	saveNoIn := p.noIn
	p.noIn = false
	prop := p.parseExpression()
	p.noIn = saveNoIn
	p.expect("]")
	return &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true}
}

func (p *Parser) parseTemplate(tagged bool) *TemplateLit {
	t := &p.lx.tok
	tpl := &TemplateLit{pos: t.pos}
	for {
		t = &p.lx.tok
		if t.kind != tTemplate {
			p.err("unexpected token in expression: '%s'", tokDesc(t))
		}
		if t.sval == nil && !tagged {
			p.errAt(t.pos, "malformed escape sequence in string literal")
		}
		tpl.Cooked = append(tpl.Cooked, t.sval)
		tpl.Raws = append(tpl.Raws, t.raw)
		if t.tail {
			p.next()
			break
		}
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		e := p.parseExpression()
		p.noIn = saveNoIn
		tpl.Exprs = append(tpl.Exprs, e)
		if !p.is("}") {
			p.err("expecting '}'")
		}
		p.lx.rescanTemplate()
	}
	return tpl
}

func (p *Parser) parsePrimary() Node {
	t := &p.lx.tok
	pos := t.pos
	switch t.kind {
	case tNum:
		if t.legacyOctal && p.strict() {
			p.err("octal literals are deprecated in strict mode")
		}
		v := t.num
		p.next()
		return &NumLit{pos: pos, Val: v}
	case tBigInt:
		d := t.str
		p.next()
		return &BigIntLit{pos: pos, Digits: d}
	case tStr:
		if t.legacyOctal && p.strict() {
			p.err("octal escape sequences are not allowed in strict mode")
		}
		s := &StrLit{pos: pos, Val: t.sval, Raw: t.raw}
		p.next()
		return s
	case tTemplate:
		return p.parseTemplate(false)
	case tPrivate:
		p.err("unexpected token in expression: '%s'", t.str)
	case tEOF:
		p.err("unexpected token in expression: ''")
	case tPunct:
		switch t.str {
		case "(":
			return p.parseParenOrArrow()
		case "[":
			return p.parseArrayLit()
		case "{":
			return p.parseObjectLit()
		case "/", "/=":
			p.lx.rescanRegExp()
			rt := &p.lx.tok
			r := &RegExpLit{pos: pos, Pattern: rt.str, Flags: rt.flags}
			p.next()
			return r
		}
		p.err("unexpected token in expression: '%s'", t.str)
	case tIdent:
		if !t.escaped {
			switch t.str {
			case "function":
				return p.parseFunctionExpr(false, pos)
			case "async":
				if p.isAsyncFunction() {
					p.next()
					return p.parseFunctionExpr(true, pos)
				}
				// async ( ... ) =>
				save := p.lx
				p.next()
				if p.is("(") && !p.lx.tok.nlBefore {
					argPos := p.lx.tok.pos
					args := p.parseArgs()
					if p.is("=>") && !p.lx.tok.nlBefore {
						params := make([]Node, len(args))
						for i, a := range args {
							params[i] = p.toParam(a)
						}
						return p.parseArrowFrom(pos, params, true)
					}
					return &CallExpr{pos: argPos, Callee: &Ident{pos: pos, Name: "async"}, Args: args}
				}
				p.lx = save
			case "class":
				p.next()
				c := p.parseClassRest(pos, false)
				return &ClassExpr{pos: pos, C: c}
			case "this":
				p.next()
				return &ThisExpr{pos: pos}
			case "null":
				p.next()
				return &NullLit{pos: pos}
			case "true":
				p.next()
				return &BoolLit{pos: pos, Val: true}
			case "false":
				p.next()
				return &BoolLit{pos: pos, Val: false}
			case "new":
				return p.parseNew()
			}
		}
		if t.escaped && reservedWords[t.str] {
			p.err("unexpected token in expression: '%s'", t.str)
		}
		return p.parseIdentRef()
	}
	p.err("unexpected token in expression: '%s'", tokDesc(t))
	return nil
}

func (p *Parser) parseParenOrArrow() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.is(")") {
		p.next()
		if !p.is("=>") || p.lx.tok.nlBefore {
			p.errAt(p.lx.prev.pos, "unexpected token in expression: ')'")
		}
		return p.parseArrowFrom(pos, []Node{}, false)
	}
	saveNoIn := p.noIn
	p.noIn = false
	var items []Node
	hasRest := false
	trailingComma := false
	restPos := 0
	for {
		if p.is("...") {
			restPos = p.lx.tok.pos
			p.next()
			var target Node
			if p.is("[") || p.is("{") {
				target = p.parseBindingPattern()
			} else {
				target = p.parseBindingIdent()
			}
			items = append(items, &Spread{pos: restPos, X: target})
			hasRest = true
			if !p.is(")") {
				p.err("expecting ')'")
			}
			break
		}
		items = append(items, p.parseAssign())
		if p.is(",") {
			p.next()
			if p.is(")") {
				trailingComma = true
				break
			}
			continue
		}
		break
	}
	p.noIn = saveNoIn
	p.expect(")")
	if p.is("=>") && !p.lx.tok.nlBefore {
		params := make([]Node, len(items))
		for i, a := range items {
			params[i] = p.toParam(a)
		}
		return p.parseArrowFrom(pos, params, false)
	}
	if hasRest {
		p.errAt(restPos, "unexpected token in expression: '...'")
	}
	if trailingComma {
		p.errAt(p.lx.prev.pos, "unexpected token in expression: ')'")
	}
	for _, it := range items {
		p.checkCoverInit(it)
	}
	if len(items) == 1 {
		return &ParenExpr{pos: pos, X: items[0]}
	}
	return &ParenExpr{pos: pos, X: &SeqExpr{pos: nodePos(items[0]), List: items}}
}

func (p *Parser) parseArrowFrom(pos int, params []Node, isAsync bool) Node {
	// current token is '=>'
	f := &FuncNode{pos: pos, IsArrow: true, IsAsync: isAsync, Kind: FKArrow, src: p.sf}
	f.Params = params
	f.SimpleParams = true
	length := 0
	sawDefault := false
	for _, prm := range params {
		switch prm.(type) {
		case *Ident:
			if !sawDefault {
				length++
			}
		case *AssignPat:
			sawDefault = true
			f.SimpleParams = false
		default:
			sawDefault = true
			f.SimpleParams = false
		}
	}
	f.length = length
	p.next() // skip =>
	old := p.enterFunc(f, isAsync, false, true)
	saveLabels := p.pendingLabels
	p.pendingLabels = nil
	if p.is("{") {
		saveBreak := p.fc.breakables
		p.fc.breakables = nil
		p.parseFunctionBody(f)
		p.fc.breakables = saveBreak
	} else {
		saveNoIn := p.noIn
		f.ExprBody = p.parseAssign()
		p.noIn = saveNoIn
		f.end = p.lx.prev.end
	}
	p.pendingLabels = saveLabels
	if f.Strict {
		p.checkStrictParams(f)
	}
	p.fc = old
	return &ArrowFunc{pos: pos, F: f}
}

func (p *Parser) parseArrayLit() Node {
	pos := p.lx.tok.pos
	p.next()
	a := &ArrayLit{pos: pos, Elems: []Node{}}
	saveNoIn := p.noIn
	p.noIn = false
	for !p.is("]") {
		if p.is(",") {
			p.next()
			a.Elems = append(a.Elems, nil)
			continue
		}
		var e Node
		if p.is("...") {
			spos := p.lx.tok.pos
			p.next()
			e = &Spread{pos: spos, X: p.parseAssign()}
		} else {
			e = p.parseAssign()
		}
		a.Elems = append(a.Elems, e)
		if !p.is("]") {
			if !p.is(",") {
				p.err("expecting ']'")
			}
			p.next()
			if p.is("]") {
				// trailing comma, not a hole
			}
		}
	}
	p.noIn = saveNoIn
	p.next()
	return a
}

func (p *Parser) parseObjectLit() Node {
	pos := p.lx.tok.pos
	p.next()
	o := &ObjectLit{pos: pos}
	saveNoIn := p.noIn
	p.noIn = false
	hasProto := false
	for !p.is("}") {
		ppos := p.lx.tok.pos
		if p.is("...") {
			p.next()
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: PSpread, Value: p.parseAssign()})
			if !p.is("}") {
				p.expect(",")
			}
			continue
		}
		t := &p.lx.tok
		isAsync := false
		isGen := false
		kind := ""
		if t.kind == tIdent && !t.escaped && (t.str == "get" || t.str == "set" || t.str == "async") {
			save := p.lx
			which := t.str
			p.next()
			nt := &p.lx.tok
			if nt.kind == tPunct && (nt.str == "(" || nt.str == ":" || nt.str == "," || nt.str == "}" || nt.str == "=") {
				p.lx = save
			} else if which == "async" && nt.nlBefore {
				p.lx = save
			} else {
				kind = which
				if which == "async" {
					isAsync = true
					kind = ""
					if p.is("*") {
						isGen = true
						p.next()
					}
				}
			}
		}
		if kind == "" && !isAsync && p.is("*") {
			isGen = true
			p.next()
		}
		keyTok := p.lx.tok
		key, name, computed, private := p.parsePropertyName()
		if private {
			p.errAt(keyTok.pos, "unexpected private name")
		}
		if kind == "get" || kind == "set" {
			fk := FKGetter
			pk := PGet
			if kind == "set" {
				fk = FKSetter
				pk = PSet
			}
			f := p.parseFunctionRest(ppos, name, keyTok.pos, false, false, fk, true)
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: pk, Key: key, KeyName: name, Computed: computed, Value: &FuncExpr{pos: ppos, F: f}})
		} else if p.is("(") || isAsync || isGen {
			f := p.parseFunctionRest(ppos, name, keyTok.pos, isAsync, isGen, FKMethod, true)
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: PMethod, Key: key, KeyName: name, Computed: computed, Value: &FuncExpr{pos: ppos, F: f}})
		} else if p.is(":") {
			p.next()
			v := p.parseAssign()
			pk := PInit
			if !computed && name == "__proto__" && keyTok.kind != tNum {
				if hasProto {
					p.errAt(ppos, "duplicate __proto__ property name")
				}
				hasProto = true
				pk = PProto
			}
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: pk, Key: key, KeyName: name, Computed: computed, Value: v})
		} else {
			// shorthand
			if keyTok.kind != tIdent || computed {
				p.err("expecting ':'")
			}
			if reservedWords[name] || (name == "yield" && (p.fc.isGen || p.strict())) || (name == "await" && (p.fc.isAsync || p.isModule)) || (p.strict() && strictReserved[name]) {
				p.errAt(keyTok.pos, "unexpected token in expression: '%s'", name)
			}
			id := &Ident{pos: keyTok.pos, Name: name}
			pn := &PropNode{pos: ppos, Kind: PInit, Key: key, KeyName: name, Value: id, Shorthand: true}
			if p.is("=") {
				p.next()
				pn.CoverInit = p.parseAssign()
			}
			o.Props = append(o.Props, pn)
		}
		if !p.is("}") {
			if !p.is(",") {
				p.err("expecting '}'")
			}
			p.next()
		}
	}
	p.noIn = saveNoIn
	p.next()
	return o
}

// ---------------- Modules ----------------

func (p *Parser) parseModuleSpecifier() string {
	t := &p.lx.tok
	if t.kind != tStr {
		p.err("expecting string")
	}
	s := t.sval.String()
	p.next()
	// import attributes: with { type: "json" }
	if (p.isKw("with") || p.isKw("assert")) && !p.lx.tok.nlBefore {
		p.next()
		p.expect("{")
		for !p.is("}") {
			p.next()
		}
		p.next()
	}
	return s
}

func (p *Parser) parseModuleExportName() string {
	t := &p.lx.tok
	if t.kind == tStr {
		s := t.sval.String()
		p.next()
		return s
	}
	if t.kind != tIdent {
		p.err("identifier expected")
	}
	s := t.str
	p.next()
	return s
}

func (p *Parser) parseImportDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	d := &ImportDecl{pos: pos}
	if p.lx.tok.kind == tStr {
		d.From = p.parseModuleSpecifier()
		p.semicolon()
		return d
	}
	if p.lx.tok.kind == tIdent && !p.is("{") {
		id := p.parseBindingIdent()
		d.Specs = append(d.Specs, &ImportSpec{Imported: "default", Local: id.Name})
		if p.is(",") {
			p.next()
		}
	}
	if p.is("*") {
		p.next()
		if !p.isKw("as") {
			p.err("expecting 'as'")
		}
		p.next()
		id := p.parseBindingIdent()
		d.Specs = append(d.Specs, &ImportSpec{Imported: "*", Local: id.Name})
	} else if p.is("{") {
		p.next()
		for !p.is("}") {
			t := p.lx.tok
			imported := p.parseModuleExportName()
			local := imported
			if p.isKw("as") {
				p.next()
				id := p.parseBindingIdent()
				local = id.Name
			} else {
				if t.kind != tIdent || reservedWords[imported] {
					p.errAt(t.pos, "identifier expected")
				}
			}
			d.Specs = append(d.Specs, &ImportSpec{Imported: imported, Local: local})
			if !p.is("}") {
				p.expect(",")
			}
		}
		p.next()
	}
	if !p.isKw("from") {
		p.err("expecting 'from'")
	}
	p.next()
	d.From = p.parseModuleSpecifier()
	p.semicolon()
	return d
}

func (p *Parser) parseExportDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	d := &ExportDecl{pos: pos}
	t := &p.lx.tok
	if p.is("*") {
		p.next()
		d.Star = true
		if p.isKw("as") {
			p.next()
			d.StarAs = p.parseModuleExportName()
		}
		if !p.isKw("from") {
			p.err("expecting 'from'")
		}
		p.next()
		d.From = p.parseModuleSpecifier()
		d.hasFrom = true
		p.semicolon()
		return d
	}
	if p.is("{") {
		p.next()
		for !p.is("}") {
			local := p.parseModuleExportName()
			exported := local
			if p.isKw("as") {
				p.next()
				exported = p.parseModuleExportName()
			}
			d.Specs = append(d.Specs, &ExportSpec{Local: local, Exported: exported})
			if !p.is("}") {
				p.expect(",")
			}
		}
		p.next()
		if p.isKw("from") {
			p.next()
			d.From = p.parseModuleSpecifier()
			d.hasFrom = true
		}
		p.semicolon()
		return d
	}
	if p.isKw("default") {
		p.next()
		dpos := p.lx.tok.pos
		if p.isKw("function") || p.isAsyncFunction() {
			isAsync := false
			if p.isKw("async") {
				isAsync = true
				p.next()
			}
			// function declaration, name optional
			save := p.lx
			p.next()
			if p.is("*") {
				p.next()
			}
			hasName := p.lx.tok.kind == tIdent
			p.lx = save
			if hasName {
				d.Decl = p.parseFunctionDecl(isAsync, dpos)
				d.Specs = []*ExportSpec{{Local: d.Decl.(*FuncDecl).F.Name, Exported: "default"}}
				return d
			}
			fe := p.parseFunctionExpr(isAsync, dpos).(*FuncExpr)
			fe.F.Name = "default"
			fd := &FuncDecl{pos: dpos, F: fe.F}
			fe.F.IsDecl = true
			fe.F.Name = "default"
			d.Decl = fd
			d.Specs = []*ExportSpec{{Local: "*default*", Exported: "default"}}
			return d
		}
		if p.isKw("class") {
			cpos := p.lx.tok.pos
			p.next()
			c := p.parseClassRest(cpos, false)
			if c.Name != "" {
				d.Decl = &ClassDecl{pos: cpos, C: c}
				d.Specs = []*ExportSpec{{Local: c.Name, Exported: "default"}}
				return d
			}
			d.Default = &ClassExpr{pos: cpos, C: c}
			return d
		}
		d.Default = p.parseAssign()
		p.semicolon()
		return d
	}
	if t.kind == tIdent {
		switch t.str {
		case "var", "let", "const":
			kind := t.str
			vpos := t.pos
			p.next()
			vd := p.parseVarDecls(kind, vpos, false)
			p.semicolon()
			d.Decl = vd
			return d
		case "function":
			d.Decl = p.parseFunctionDecl(false, t.pos)
			return d
		case "async":
			if p.isAsyncFunction() {
				apos := t.pos
				p.next()
				d.Decl = p.parseFunctionDecl(true, apos)
				return d
			}
		case "class":
			d.Decl = p.parseClassDecl()
			return d
		}
	}
	p.err("unexpected token in expression: '%s'", tokDesc(t))
	return nil
}

func nodePos(n Node) int {
	switch x := n.(type) {
	case *Ident:
		return x.pos
	case *NumLit:
		return x.pos
	case *StrLit:
		return x.pos
	case *BigIntLit:
		return x.pos
	case *TemplateLit:
		return x.pos
	case *TaggedTemplate:
		return x.pos
	case *RegExpLit:
		return x.pos
	case *BoolLit:
		return x.pos
	case *NullLit:
		return x.pos
	case *ThisExpr:
		return x.pos
	case *SuperExpr:
		return x.pos
	case *ArrayLit:
		return x.pos
	case *ObjectLit:
		return x.pos
	case *FuncExpr:
		return x.pos
	case *ArrowFunc:
		return x.pos
	case *ClassExpr:
		return x.pos
	case *UnaryExpr:
		return x.pos
	case *UpdateExpr:
		return x.pos
	case *BinaryExpr:
		return x.pos
	case *LogicalExpr:
		return x.pos
	case *AssignExpr:
		return x.pos
	case *CondExpr:
		return x.pos
	case *CallExpr:
		return x.pos
	case *NewExpr:
		return x.pos
	case *MemberExpr:
		return x.pos
	case *OptChain:
		return x.pos
	case *SeqExpr:
		return x.pos
	case *Spread:
		return x.pos
	case *YieldExpr:
		return x.pos
	case *AwaitExpr:
		return x.pos
	case *ParenExpr:
		return x.pos
	case *ObjPattern:
		return x.pos
	case *ArrPattern:
		return x.pos
	case *AssignPat:
		return x.pos
	case *NewTargetExpr:
		return x.pos
	case *ImportMetaExpr:
		return x.pos
	case *ImportCall:
		return x.pos
	case *PrivateIn:
		return x.pos
	}
	return 0
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > parser.go <<'EOF'
package main

import (
	"fmt"
)

type fnCtx struct {
	f          *FuncNode
	parent     *fnCtx
	strict     bool
	isAsync    bool
	isGen      bool
	isArrow    bool
	breakables []breakable
	labels     []string
	allowSuperProp bool
	allowSuperCall bool
	allowNewTarget bool
	inClassField bool
	inStaticBlock bool
}

type breakable struct {
	labels []string
	isLoop bool
	isSwitch bool
}

type Parser struct {
	lx       Lexer
	sf       *SourceFile
	fc       *fnCtx
	noIn     bool
	isModule bool
	pendingLabels []string
	evalCtx  *evalContext
}

type evalContext struct {
	allowSuperProp bool
	allowSuperCall bool
	allowNewTarget bool
	allowArguments bool
	inFunction bool
	strict bool
}

func (p *Parser) tok() *Token { return &p.lx.tok }

func (p *Parser) next() { p.lx.next() }

func (p *Parser) errAt(pos int, format string, args ...interface{}) {
	panic(&SyntaxErr{msg: fmt.Sprintf(format, args...), pos: pos})
}

func (p *Parser) err(format string, args ...interface{}) {
	p.errAt(p.lx.tok.pos, format, args...)
}

func (p *Parser) is(s string) bool {
	t := &p.lx.tok
	return t.kind == tPunct && t.str == s
}

func (p *Parser) isKw(s string) bool {
	t := &p.lx.tok
	return t.kind == tIdent && t.str == s && !t.escaped
}

func (p *Parser) eat(s string) bool {
	if p.is(s) {
		p.next()
		return true
	}
	return false
}

func tokDesc(t *Token) string {
	switch t.kind {
	case tEOF:
		return ""
	case tStr:
		return "string"
	case tNum:
		return "number"
	case tBigInt:
		return "bigint"
	case tTemplate:
		return "template"
	case tRegExp:
		return "regexp"
	}
	return t.str
}

func (p *Parser) expect(s string) {
	if !p.is(s) {
		p.err("expecting '%s'", s)
	}
	p.next()
}

func (p *Parser) expectKw(s string) {
	if !p.isKw(s) {
		p.err("expecting '%s'", s)
	}
	p.next()
}

// automatic semicolon insertion
func (p *Parser) semicolon() {
	t := &p.lx.tok
	if t.kind == tPunct && t.str == ";" {
		p.next()
		return
	}
	if t.kind == tEOF || (t.kind == tPunct && t.str == "}") || t.nlBefore {
		return
	}
	p.err("expecting ';'")
}

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true, "continue": true,
	"debugger": true, "default": true, "delete": true, "do": true, "else": true, "enum": true,
	"export": true, "extends": true, "false": true, "finally": true, "for": true, "function": true,
	"if": true, "import": true, "in": true, "instanceof": true, "new": true, "null": true,
	"return": true, "super": true, "switch": true, "this": true, "throw": true, "true": true,
	"try": true, "typeof": true, "var": true, "void": true, "while": true, "with": true,
}

var strictReserved = map[string]bool{
	"implements": true, "interface": true, "let": true, "package": true, "private": true,
	"protected": true, "public": true, "static": true, "yield": true,
}

func (p *Parser) strict() bool { return p.fc.strict }

// is current token an identifier usable as binding/reference
func (p *Parser) isIdentRef() bool {
	t := &p.lx.tok
	if t.kind != tIdent {
		return false
	}
	if reservedWords[t.str] {
		return false
	}
	if t.str == "yield" && (p.fc.isGen || p.strict()) {
		return false
	}
	if t.str == "await" && (p.fc.isAsync || p.isModule) {
		return false
	}
	if p.strict() && strictReserved[t.str] {
		return false
	}
	return true
}

func (p *Parser) parseIdentRef() *Ident {
	t := &p.lx.tok
	if !p.isIdentRef() {
		if t.kind == tIdent && (t.str == "yield" || t.str == "await" || reservedWords[t.str] || strictReserved[t.str]) {
			if t.kind == tIdent && !reservedWords[t.str] && p.strict() && strictReserved[t.str] {
				p.err("invalid keyword: %s", t.str)
			}
			p.err("unexpected token in expression: '%s'", tokDesc(t))
		}
		p.err("identifier expected")
	}
	id := &Ident{pos: t.pos, Name: t.str}
	p.next()
	return id
}

func (p *Parser) parseBindingIdent() *Ident {
	t := &p.lx.tok
	if t.kind != tIdent {
		p.err("variable name expected")
	}
	if !p.isIdentRef() {
		if p.strict() && strictReserved[t.str] && !reservedWords[t.str] {
			p.err("invalid variable name in strict mode")
		}
		if reservedWords[t.str] && !(t.escaped == false && false) {
			p.err("variable name expected")
		}
		p.err("variable name expected")
	}
	if p.strict() && (t.str == "eval" || t.str == "arguments") {
		p.err("invalid variable name in strict mode")
	}
	id := &Ident{pos: t.pos, Name: t.str}
	p.next()
	return id
}

// ---------------- Program ----------------

func parseProgram(sf *SourceFile, isModule bool, strict bool, ec *evalContext) (prog *Program, err *SyntaxErr) {
	p := &Parser{sf: sf, isModule: isModule, evalCtx: ec}
	p.lx.src = sf.src
	p.lx.file = sf
	moduleLexFlag = isModule
	defer func() {
		if r := recover(); r != nil {
			if se, ok := r.(*SyntaxErr); ok {
				err = se
				prog = nil
				return
			}
			panic(r)
		}
	}()
	f := &FuncNode{pos: 0, end: len(sf.src), src: sf, isScript: !isModule, isModule: isModule}
	f.Strict = strict || isModule
	p.fc = &fnCtx{f: f, strict: f.Strict}
	if isModule {
		p.fc.isAsync = true // top-level await
	}
	if ec != nil {
		f.isEvalCode = true
		p.fc.allowSuperProp = ec.allowSuperProp
		p.fc.allowSuperCall = ec.allowSuperCall
		p.fc.allowNewTarget = ec.allowNewTarget
	}
	// skip hashbang
	if len(sf.src) >= 2 && sf.src[0] == '#' && sf.src[1] == '!' {
		i := 0
		for i < len(sf.src) && sf.src[i] != '\n' && sf.src[i] != '\r' {
			i++
		}
		p.lx.pos = i
	}
	p.next()
	prog = &Program{F: f, IsModule: isModule}
	body := p.parseDirectivesAndBody(true)
	f.Body = body
	f.Strict = p.fc.strict
	prog.Body = body
	return prog, nil
}

func (p *Parser) parseDirectivesAndBody(top bool) []Node {
	var body []Node
	directives := true
	for {
		t := &p.lx.tok
		if t.kind == tEOF {
			if !top {
				p.err("unexpected token in expression: ''")
			}
			break
		}
		if !top && t.kind == tPunct && t.str == "}" {
			break
		}
		if directives {
			if t.kind == tStr {
				raw := t.raw
				// check if this is a complete expression statement
				save := p.lx
				p.next()
				nt := &p.lx.tok
				isDirective := nt.kind == tEOF || (nt.kind == tPunct && (nt.str == ";" || nt.str == "}")) || nt.nlBefore && !(nt.kind == tPunct && isContinuationPunct(nt.str))
				p.lx = save
				if isDirective {
					if raw == "'use strict'" || raw == "\"use strict\"" {
						if !p.fc.f.SimpleParams && !p.fc.f.isScript && !p.fc.f.isModule && p.fc.f.Params != nil && !p.fc.f.isEvalCode {
							p.err("\"use strict\" not allowed in function with default or destructuring parameter")
						}
						p.fc.strict = true
						p.fc.f.Strict = true
					}
				} else {
					directives = false
				}
			} else {
				directives = false
			}
		}
		body = append(body, p.parseStatementListItem())
	}
	return body
}

func isContinuationPunct(s string) bool {
	switch s {
	case "(", "[", ".", "+", "-", "*", "/", "%", "=", "==", "===", "!=", "!==", "<", ">", "<=", ">=", "&&", "||", "??", "?", ",", "?.", "`", "&", "|", "^", "**", "in", "instanceof", "+=", "-=":
		return true
	}
	return false
}

// ---------------- Statements ----------------

func (p *Parser) isLetDecl() bool {
	if !p.isKw("let") {
		return false
	}
	// let followed by identifier, [ or {
	save := p.lx
	p.next()
	t := &p.lx.tok
	r := false
	if t.kind == tIdent && !(t.str == "in" || t.str == "instanceof") {
		if !t.nlBefore || !(reservedWords[t.str]) {
			r = true
		}
		if t.str == "of" {
			r = !t.nlBefore || true
		}
	} else if t.kind == tPunct && (t.str == "[" || t.str == "{") {
		r = true
	}
	p.lx = save
	return r
}

func (p *Parser) isAsyncFunction() bool {
	if !p.isKw("async") {
		return false
	}
	save := p.lx
	p.next()
	r := p.isKw("function") && !p.lx.tok.nlBefore
	p.lx = save
	return r
}

func (p *Parser) parseStatementListItem() Node {
	t := &p.lx.tok
	if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "function":
			return p.parseFunctionDecl(false, t.pos)
		case "class":
			return p.parseClassDecl()
		case "const":
			return p.parseVarStatement("const")
		case "let":
			if p.isLetDecl() {
				return p.parseVarStatement("let")
			}
		case "async":
			if p.isAsyncFunction() {
				pos := t.pos
				p.next()
				return p.parseFunctionDecl(true, pos)
			}
		case "import":
			if p.isModule && p.fc.parent == nil && !p.fc.f.isEvalCode {
				save := p.lx
				p.next()
				if !p.is("(") && !p.is(".") {
					p.lx = save
					return p.parseImportDecl()
				}
				p.lx = save
			}
		case "export":
			if p.isModule && p.fc.parent == nil && !p.fc.f.isEvalCode {
				return p.parseExportDecl()
			}
		}
	}
	return p.parseStatement()
}

func (p *Parser) parseStatement() Node {
	t := &p.lx.tok
	pos := t.pos
	if t.kind == tPunct {
		switch t.str {
		case "{":
			return p.parseBlock()
		case ";":
			p.next()
			return &EmptyStmt{pos: pos}
		}
	}
	if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "var":
			return p.parseVarStatement("var")
		case "if":
			return p.parseIf()
		case "for":
			return p.parseFor()
		case "while":
			p.next()
			p.expect("(")
			test := p.parseExpression()
			p.expect(")")
			w := &WhileStmt{pos: pos, Test: test, labels: p.takeLabels()}
			w.Body = p.parseLoopBody(w.labels)
			return w
		case "do":
			p.next()
			d := &DoWhileStmt{pos: pos, labels: p.takeLabels()}
			d.Body = p.parseLoopBody(d.labels)
			p.expectKw("while")
			p.expect("(")
			d.Test = p.parseExpression()
			p.expect(")")
			if p.is(";") {
				p.next()
			}
			return d
		case "continue", "break":
			isBreak := t.str == "break"
			p.next()
			label := ""
			if p.lx.tok.kind == tIdent && !p.lx.tok.nlBefore && !reservedWords[p.lx.tok.str] {
				label = p.lx.tok.str
				p.next()
			}
			p.checkBreak(isBreak, label, pos)
			p.semicolon()
			if isBreak {
				return &BreakStmt{pos: pos, Label: label}
			}
			return &ContinueStmt{pos: pos, Label: label}
		case "return":
			if p.fc.parent == nil && (p.fc.f.isScript || p.fc.f.isModule || p.fc.f.isEvalCode) {
				p.err("return not in a function")
			}
			p.next()
			var x Node
			nt := &p.lx.tok
			if !(nt.kind == tEOF || nt.kind == tPunct && (nt.str == ";" || nt.str == "}") || nt.nlBefore) {
				x = p.parseExpression()
				if c, ok := x.(*CallExpr); ok {
					c.tail = true
					c.retPos = pos
				}
			}
			p.semicolon()
			return &ReturnStmt{pos: pos, X: x}
		case "throw":
			p.next()
			if p.lx.tok.nlBefore {
				p.err("line terminator not allowed after throw")
			}
			x := p.parseExpression()
			p.semicolon()
			return &ThrowStmt{pos: pos, X: x}
		case "try":
			return p.parseTry()
		case "switch":
			return p.parseSwitch()
		case "debugger":
			p.next()
			p.semicolon()
			return &DebuggerStmt{pos: pos}
		case "with":
			if p.strict() {
				p.err("invalid keyword: with")
			}
			p.next()
			p.expect("(")
			obj := p.parseExpression()
			p.expect(")")
			body := p.parseStatement()
			return &WithStmt{pos: pos, Obj: obj, Body: body}
		case "function":
			// function declaration in statement position (sloppy annex B: if body)
			if p.strict() {
				p.err("function declarations can't appear in single-statement context")
			}
			return p.parseFunctionDecl(false, pos)
		case "class":
			p.err("unexpected token in expression: 'class'")
		case "const":
			p.err("lexical declarations can't appear in single-statement context")
		case "let":
			save := p.lx
			p.next()
			if p.is("[") {
				p.err("lexical declarations can't appear in single-statement context")
			}
			p.lx = save
		case "import":
			save := p.lx
			p.next()
			if !p.is("(") && !p.is(".") {
				p.lx = save
				if !p.isModule {
					p.err("unexpected token in expression: 'import'")
				}
				p.err("unexpected token in expression: 'import'")
			}
			p.lx = save
		case "export":
			p.err("unexpected token in expression: 'export'")
		}
		// labeled statement
		if p.isIdentRef() || t.str == "yield" || t.str == "await" {
			save := p.lx
			name := t.str
			p.next()
			if p.is(":") {
				if !p.isIdentRefName(name) {
					p.lx = save
				} else {
					p.next()
					for _, l := range p.fc.labels {
						if l == name {
							p.errAt(p.lx.prev.pos, "duplicate label name")
						}
					}
					for _, l := range p.pendingLabels {
						if l == name {
							p.errAt(p.lx.prev.pos, "duplicate label name")
						}
					}
					p.pendingLabels = append(p.pendingLabels, name)
					p.fc.labels = append(p.fc.labels, name)
					var body Node
					nt := &p.lx.tok
					if nt.kind == tIdent && !nt.escaped && (nt.str == "for" || nt.str == "while" || nt.str == "do") {
						body = p.parseStatement()
					} else if nt.kind == tIdent && nt.str == "function" && !nt.escaped {
						if p.strict() {
							p.err("function declarations can't appear in single-statement context")
						}
						p.pendingLabels = nil
						body = p.parseFunctionDecl(false, nt.pos)
					} else {
						labels := p.takeLabels()
						p.fc.breakables = append(p.fc.breakables, breakable{labels: labels})
						body = p.parseStatement()
						p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
					}
					p.fc.labels = p.fc.labels[:len(p.fc.labels)-1]
					return &LabeledStmt{pos: pos, Label: name, Body: body}
				}
			} else {
				p.lx = save
			}
		}
	}
	p.pendingLabels = nil
	x := p.parseExpression()
	p.semicolon()
	return &ExprStmt{pos: pos, X: x}
}

func (p *Parser) isIdentRefName(name string) bool {
	if reservedWords[name] {
		return false
	}
	if name == "yield" && (p.fc.isGen || p.strict()) {
		return false
	}
	if name == "await" && (p.fc.isAsync || p.isModule) {
		return false
	}
	return true
}

func (p *Parser) takeLabels() []string {
	l := p.pendingLabels
	p.pendingLabels = nil
	return l
}

func (p *Parser) parseLoopBody(labels []string) Node {
	p.fc.breakables = append(p.fc.breakables, breakable{labels: labels, isLoop: true})
	body := p.parseStatement()
	p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
	return body
}

func (p *Parser) checkBreak(isBreak bool, label string, pos int) {
	bs := p.fc.breakables
	if label == "" {
		for i := len(bs) - 1; i >= 0; i-- {
			if bs[i].isLoop || (isBreak && bs[i].isSwitch) {
				return
			}
		}
		if isBreak {
			p.err("break must be inside loop or switch")
		}
		p.err("continue must be inside loop")
	}
	for i := len(bs) - 1; i >= 0; i-- {
		for _, l := range bs[i].labels {
			if l == label {
				if !isBreak && !bs[i].isLoop {
					p.errAt(p.lx.tok.pos, "break/continue label not found")
				}
				return
			}
		}
	}
	p.errAt(p.lx.tok.pos, "break/continue label not found")
}

func (p *Parser) parseBlock() *BlockStmt {
	pos := p.lx.tok.pos
	p.expect("{")
	p.pendingLabels = nil
	b := &BlockStmt{pos: pos}
	for !p.is("}") {
		if p.lx.tok.kind == tEOF {
			p.err("expecting '}'")
		}
		b.Body = append(b.Body, p.parseStatementListItem())
	}
	p.next()
	return b
}

func (p *Parser) parseVarStatement(kind string) Node {
	pos := p.lx.tok.pos
	p.next()
	d := p.parseVarDecls(kind, pos, false)
	p.semicolon()
	return d
}

func (p *Parser) parseVarDecls(kind string, pos int, inFor bool) *VarDecl {
	d := &VarDecl{pos: pos, Kind: kind}
	for {
		dpos := p.lx.tok.pos
		var target Node
		if p.is("[") || p.is("{") {
			target = p.parseBindingPattern()
		} else {
			t := &p.lx.tok
			if kind != "var" && t.kind == tIdent && t.str == "let" {
				p.err("'let' is not a valid lexical identifier")
			}
			target = p.parseBindingIdent()
		}
		var init Node
		if p.is("=") {
			p.next()
			init = p.parseAssign()
		} else if !inFor || !(p.isKw("in") || p.isKw("of")) {
			if kind == "const" {
				p.err("missing initializer for const variable")
			}
			if _, ok := target.(*Ident); !ok {
				p.errAt(dpos, "variable name expected")
			}
		}
		d.Decls = append(d.Decls, &VarDeclarator{pos: dpos, Target: target, Init: init})
		if !p.is(",") {
			break
		}
		p.next()
	}
	return d
}

func (p *Parser) parseIf() Node {
	pos := p.lx.tok.pos
	p.next()
	p.expect("(")
	test := p.parseExpression()
	p.expect(")")
	p.pendingLabels = nil
	cons := p.parseSubStatement()
	var alt Node
	if p.isKw("else") {
		p.next()
		alt = p.parseSubStatement()
	}
	return &IfStmt{pos: pos, Test: test, Cons: cons, Alt: alt}
}

func (p *Parser) parseSubStatement() Node {
	if p.isKw("function") && !p.strict() {
		// annex B: function declaration in if statement - wrap in block
		pos := p.lx.tok.pos
		fd := p.parseFunctionDecl(false, pos)
		return &BlockStmt{pos: pos, Body: []Node{fd}}
	}
	return p.parseStatement()
}

func (p *Parser) parseFor() Node {
	pos := p.lx.tok.pos
	p.next()
	labels := p.takeLabels()
	isAwait := false
	if p.isKw("await") && (p.fc.isAsync) {
		isAwait = true
		p.next()
	}
	p.expect("(")
	var init Node
	initPos := p.lx.tok.pos
	if p.is(";") {
		// no init
	} else {
		saveNoIn := p.noIn
		p.noIn = true
		if p.isKw("var") || p.isKw("const") || (p.isKw("let") && p.isLetDeclFor()) {
			kind := p.lx.tok.str
			p.next()
			init = p.parseVarDecls(kind, initPos, true)
		} else {
			startTok := p.lx.tok
			init = p.parseExpressionCover()
			if (p.isKw("of") && !(startTok.kind == tIdent && startTok.str == "async" && !startTok.escaped && isIdentNode(init, "async"))) || p.isKw("in") {
				// convert to pattern
				init = p.toAssignTarget(init, true)
			} else {
				p.checkCoverInit(init)
			}
			_ = startTok
		}
		p.noIn = saveNoIn
	}
	if p.isKw("of") || p.isKw("in") {
		isOf := p.lx.tok.str == "of"
		if vd, ok := init.(*VarDecl); ok {
			if len(vd.Decls) != 1 {
				p.err("a declaration in the head of a for-%s loop can't have more than one binding", map[bool]string{true: "of", false: "in"}[isOf])
			}
			if vd.Decls[0].Init != nil {
				if isOf || p.strict() || vd.Kind != "var" {
					p.errAt(p.lx.tok.pos, "a declaration in the head of a for-%s loop can't have an initializer", map[bool]string{true: "of", false: "in"}[isOf])
				}
			}
		}
		p.next()
		var right Node
		if isOf {
			right = p.parseAssign()
		} else {
			right = p.parseExpression()
		}
		p.expect(")")
		fs := &ForInStmt{pos: pos, Left: init, Right: right, Of: isOf, Await: isAwait, labels: labels}
		fs.Body = p.parseLoopBody(labels)
		return fs
	}
	if isAwait {
		p.err("expecting 'of'")
	}
	if vd, ok := init.(*VarDecl); ok {
		for _, d := range vd.Decls {
			if d.Init == nil {
				if vd.Kind == "const" {
					p.err("missing initializer for const variable")
				}
				if _, ok := d.Target.(*Ident); !ok {
					p.err("variable name expected")
				}
			}
		}
	}
	p.expect(";")
	var test, update Node
	if !p.is(";") {
		test = p.parseExpression()
	}
	p.expect(";")
	if !p.is(")") {
		update = p.parseExpression()
	}
	p.expect(")")
	fs := &ForStmt{pos: pos, Init: init, Test: test, Update: update, labels: labels}
	fs.Body = p.parseLoopBody(labels)
	return fs
}

func isIdentNode(n Node, name string) bool {
	id, ok := n.(*Ident)
	return ok && id.Name == name
}

func (p *Parser) isLetDeclFor() bool {
	save := p.lx
	p.next()
	t := &p.lx.tok
	r := false
	if t.kind == tIdent && !(t.str == "in" || t.str == "of") {
		r = true
	} else if t.kind == tIdent && t.str == "of" {
		// for (let of ...) is ambiguous; treat 'let' as identifier unless followed by...
		r = false
	} else if t.kind == tPunct && (t.str == "[" || t.str == "{") {
		r = true
	}
	p.lx = save
	return r
}

func (p *Parser) parseTry() Node {
	pos := p.lx.tok.pos
	p.next()
	ts := &TryStmt{pos: pos}
	p.pendingLabels = nil
	ts.Block = p.parseBlock()
	if p.isKw("catch") {
		p.next()
		if p.is("(") {
			p.next()
			if p.is("[") || p.is("{") {
				ts.Param = p.parseBindingPattern()
			} else {
				ts.Param = p.parseBindingIdent()
			}
			p.expect(")")
		}
		ts.Handler = p.parseBlock()
	}
	if p.isKw("finally") {
		p.next()
		ts.Finalizer = p.parseBlock()
	}
	if ts.Handler == nil && ts.Finalizer == nil {
		p.err("expecting catch or finally")
	}
	return ts
}

func (p *Parser) parseSwitch() Node {
	pos := p.lx.tok.pos
	p.next()
	labels := p.takeLabels()
	p.expect("(")
	disc := p.parseExpression()
	p.expect(")")
	p.expect("{")
	ss := &SwitchStmt{pos: pos, Disc: disc, labels: labels}
	p.fc.breakables = append(p.fc.breakables, breakable{labels: labels, isSwitch: true})
	hasDefault := false
	for !p.is("}") {
		cpos := p.lx.tok.pos
		c := &SwitchCase{pos: cpos}
		if p.isKw("case") {
			p.next()
			c.Test = p.parseExpression()
		} else if p.isKw("default") {
			if hasDefault {
				p.err("duplicate default")
			}
			hasDefault = true
			p.next()
		} else {
			p.err("invalid switch statement")
		}
		p.expect(":")
		for !p.is("}") && !p.isKw("case") && !p.isKw("default") {
			if p.lx.tok.kind == tEOF {
				p.err("expecting '}'")
			}
			c.Body = append(c.Body, p.parseStatementListItem())
		}
		ss.Cases = append(ss.Cases, c)
	}
	p.next()
	p.fc.breakables = p.fc.breakables[:len(p.fc.breakables)-1]
	return ss
}

// ---------------- Functions ----------------

func (p *Parser) parseFunctionDecl(isAsync bool, pos int) Node {
	p.expectKw("function")
	isGen := false
	if p.is("*") {
		isGen = true
		p.next()
	}
	t := &p.lx.tok
	if t.kind != tIdent {
		p.err("function name expected")
	}
	var nameId *Ident
	if p.isIdentRef() || (t.str == "yield" && !p.strict() && !isGen && !p.fc.isGen) || (t.str == "await" && !p.isModule && !p.fc.isAsync) {
		nameId = &Ident{pos: t.pos, Name: t.str}
		if p.strict() && (t.str == "eval" || t.str == "arguments") {
			p.err("invalid function name in strict code")
		}
		p.next()
	} else {
		p.err("function name expected")
	}
	f := p.parseFunctionRest(pos, nameId.Name, nameId.pos, isAsync, isGen, FKNormal, false)
	f.IsDecl = true
	p.pendingLabels = nil
	return &FuncDecl{pos: pos, F: f}
}

func (p *Parser) parseFunctionExpr(isAsync bool, pos int) Node {
	p.expectKw("function")
	isGen := false
	if p.is("*") {
		isGen = true
		p.next()
	}
	name := ""
	namePos := 0
	t := &p.lx.tok
	if t.kind == tIdent && !p.is("(") {
		ok := p.isIdentRef()
		if !ok {
			if t.str == "yield" && !p.strict() && !isGen {
				ok = true
			} else if t.str == "await" && !p.isModule && !isAsync {
				ok = true
			}
		}
		if t.str == "yield" && isGen || t.str == "await" && isAsync {
			ok = false
		}
		if !ok {
			p.err("function name expected")
		}
		if p.strict() && (t.str == "eval" || t.str == "arguments") {
			p.err("invalid function name in strict code")
		}
		name = t.str
		namePos = t.pos
		p.next()
	}
	f := p.parseFunctionRest(pos, name, namePos, isAsync, isGen, FKNormal, false)
	f.IsExpr = name != ""
	return &FuncExpr{pos: pos, F: f}
}

func (p *Parser) enterFunc(f *FuncNode, isAsync, isGen, isArrow bool) *fnCtx {
	fc := &fnCtx{f: f, parent: p.fc, strict: p.fc.strict, isAsync: isAsync, isGen: isGen, isArrow: isArrow}
	if isArrow {
		fc.allowSuperProp = p.fc.allowSuperProp
		fc.allowSuperCall = p.fc.allowSuperCall
		fc.allowNewTarget = p.fc.allowNewTarget
		fc.inClassField = p.fc.inClassField
	} else {
		fc.allowNewTarget = true
	}
	f.Strict = fc.strict
	old := p.fc
	p.fc = fc
	return old
}

// parse params and body; current token is '('
func (p *Parser) parseFunctionRest(pos int, name string, namePos int, isAsync, isGen bool, kind FuncKind, isMethod bool) *FuncNode {
	f := &FuncNode{pos: pos, Name: name, NamePos: namePos, IsAsync: isAsync, IsGen: isGen, Kind: kind, src: p.sf}
	old := p.enterFunc(f, isAsync, isGen, false)
	if kind == FKMethod || kind == FKGetter || kind == FKSetter || kind == FKClassConstructor || kind == FKDerivedConstructor {
		p.fc.allowSuperProp = true
	}
	if kind == FKDerivedConstructor {
		p.fc.allowSuperCall = true
	}
	saveLabels := p.pendingLabels
	p.pendingLabels = nil
	saveNoIn := p.noIn
	p.noIn = false
	p.parseParams(f)
	if kind == FKGetter && len(f.Params) != 0 {
		p.errAt(p.lx.prev.pos, "invalid number of arguments for getter or setter")
	}
	if kind == FKSetter && (len(f.Params) != 1 || isRest(f.Params[0])) {
		p.errAt(p.lx.prev.pos, "invalid number of arguments for getter or setter")
	}
	p.parseFunctionBody(f)
	p.noIn = saveNoIn
	p.pendingLabels = saveLabels
	p.fc = old
	return f
}

func isRest(n Node) bool {
	_, ok := n.(*Spread)
	return ok
}

func (p *Parser) parseParams(f *FuncNode) {
	p.expect("(")
	f.SimpleParams = true
	f.Params = []Node{}
	length := 0
	sawDefault := false
	for !p.is(")") {
		if p.is("...") {
			rpos := p.lx.tok.pos
			p.next()
			var target Node
			if p.is("[") || p.is("{") {
				target = p.parseBindingPattern()
			} else {
				target = p.parseBindingIdent()
			}
			f.Params = append(f.Params, &Spread{pos: rpos, X: target})
			f.SimpleParams = false
			if !p.is(")") {
				p.err("expecting ')'")
			}
			break
		}
		var target Node
		if p.is("[") || p.is("{") {
			target = p.parseBindingPattern()
			f.SimpleParams = false
		} else {
			target = p.parseBindingIdent()
		}
		if p.is("=") {
			apos := p.lx.tok.pos
			p.next()
			def := p.parseAssign()
			target = &AssignPat{pos: apos, Target: target, Default: def}
			f.SimpleParams = false
			sawDefault = true
		} else if !sawDefault {
			length++
		}
		f.Params = append(f.Params, target)
		if !p.is(")") {
			p.expect(",")
		}
	}
	f.length = length
	p.next()
}

func (p *Parser) parseFunctionBody(f *FuncNode) {
	if !p.is("{") {
		p.err("expecting '{'")
	}
	p.next()
	f.Body = p.parseDirectivesAndBody(false)
	f.Strict = p.fc.strict
	if f.Strict {
		p.checkStrictParams(f)
	}
	f.end = p.lx.tok.end
	p.next()
}

func (p *Parser) checkStrictParams(f *FuncNode) {
	var names []string
	var collect func(n Node)
	collect = func(n Node) {
		switch x := n.(type) {
		case *Ident:
			names = append(names, x.Name)
			if x.Name == "eval" || x.Name == "arguments" {
				p.errAt(x.pos, "invalid argument name in strict code")
			}
		case *AssignPat:
			collect(x.Target)
		case *Spread:
			collect(x.X)
		case *ObjPattern:
			for _, pp := range x.Props {
				collect(pp.Value)
			}
			if x.Rest != nil {
				collect(x.Rest)
			}
		case *ArrPattern:
			for _, e := range x.Elems {
				if e != nil {
					collect(e)
				}
			}
			if x.Rest != nil {
				collect(x.Rest)
			}
		}
	}
	for _, prm := range f.Params {
		collect(prm)
	}
	if f.Name == "eval" || f.Name == "arguments" {
		p.errAt(f.NamePos, "invalid function name in strict code")
	}
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			p.errAt(f.pos, "duplicate argument names not allowed in this context")
		}
		seen[n] = true
	}
}

// ---------------- Classes ----------------

func (p *Parser) parseClassDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.lx.tok.kind != tIdent || p.isKw("extends") {
		p.err("class statement requires a name")
	}
	c := p.parseClassRest(pos, true)
	p.pendingLabels = nil
	return &ClassDecl{pos: pos, C: c}
}

func (p *Parser) parseClassRest(pos int, needName bool) *ClassNode {
	c := &ClassNode{pos: pos, src: p.sf}
	saveStrict := p.fc.strict
	p.fc.strict = true
	if p.lx.tok.kind == tIdent && !p.isKw("extends") {
		t := &p.lx.tok
		if !p.isIdentRef() || t.str == "yield" || t.str == "let" || t.str == "static" || t.str == "implements" {
			if t.str == "await" && !p.isModule && !p.fc.isAsync {
			} else {
				p.err("class name expected")
			}
		}
		c.Name = t.str
		c.NamePos = t.pos
		p.next()
	}
	if p.isKw("extends") {
		p.next()
		c.HasSuper = true
		c.Super = p.parseLHS()
	}
	p.expect("{")
	for !p.is("}") {
		if p.is(";") {
			p.next()
			continue
		}
		if p.lx.tok.kind == tEOF {
			p.err("expecting '}'")
		}
		m := p.parseClassMember(c)
		if m != nil {
			c.Members = append(c.Members, m)
		}
	}
	c.end = p.lx.tok.end
	p.next()
	p.fc.strict = saveStrict
	return c
}

func (p *Parser) parsePropertyName() (key Node, name string, computed bool, private bool) {
	t := &p.lx.tok
	pos := t.pos
	switch t.kind {
	case tIdent:
		name = t.str
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tStr:
		name = t.sval.String()
		key = &StrLit{pos: pos, Val: t.sval}
		p.next()
	case tNum:
		key = &NumLit{pos: pos, Val: t.num}
		name = numberToGoString(t.num)
		p.next()
	case tBigInt:
		name = t.str
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tPrivate:
		name = t.str
		private = true
		key = &StrLit{pos: pos, Val: newStr(name)}
		p.next()
	case tPunct:
		if t.str == "[" {
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			key = p.parseAssign()
			p.noIn = saveNoIn
			p.expect("]")
			computed = true
			return
		}
		fallthrough
	default:
		p.err("invalid property name")
	}
	return
}

func (p *Parser) parseClassMember(c *ClassNode) *ClassMember {
	pos := p.lx.tok.pos
	isStatic := false
	if p.isKw("static") {
		save := p.lx
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") {
			p.lx = save
		} else {
			isStatic = true
			if p.is("{") {
				// static block
				f := &FuncNode{pos: p.lx.tok.pos, Kind: FKClassStaticBlock, src: p.sf, Name: "<static_initializer>"}
				old := p.enterFunc(f, false, false, false)
				p.fc.allowSuperProp = true
				p.fc.inStaticBlock = true
				p.next()
				f.Params = []Node{}
				f.SimpleParams = true
				for !p.is("}") {
					if p.lx.tok.kind == tEOF {
						p.err("expecting '}'")
					}
					f.Body = append(f.Body, p.parseStatementListItem())
				}
				f.end = p.lx.tok.end
				p.next()
				p.fc = old
				return &ClassMember{pos: pos, Kind: "static-block", Static: true, Value: f}
			}
		}
	}
	kind := "method"
	isAsync := false
	isGen := false
	if p.isKw("async") {
		save := p.lx
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") || p.lx.tok.nlBefore {
			p.lx = save
		} else {
			isAsync = true
		}
	}
	if p.is("*") {
		isGen = true
		p.next()
	}
	if !isAsync && !isGen && (p.isKw("get") || p.isKw("set")) {
		save := p.lx
		which := p.lx.tok.str
		p.next()
		if p.is("(") || p.is("=") || p.is(";") || p.is("}") {
			p.lx = save
		} else {
			kind = which
		}
	}
	keyPos := p.lx.tok.pos
	key, name, computed, private := p.parsePropertyName()
	m := &ClassMember{pos: pos, Static: isStatic, Key: key, KeyName: name, Computed: computed, Private: private}
	if private && name == "#constructor" {
		p.errAt(keyPos, "invalid method name")
	}
	if p.is("(") {
		fk := FKMethod
		if kind == "get" {
			fk = FKGetter
		} else if kind == "set" {
			fk = FKSetter
		}
		isCtor := !isStatic && !computed && !private && name == "constructor"
		if isCtor {
			if kind != "method" || isAsync || isGen {
				p.errAt(keyPos, "invalid constructor")
			}
			if c.Ctor != nil {
				p.errAt(p.lx.tok.pos, "property constructor appears more than once")
			}
			fk = FKClassConstructor
			if c.HasSuper {
				fk = FKDerivedConstructor
			}
		}
		f := p.parseFunctionRest(pos, name, keyPos, isAsync, isGen, fk, true)
		f.classNode = c
		if isCtor {
			c.Ctor = f
			f.Name = c.Name
			return nil
		}
		m.Kind = kind
		m.Value = f
		return m
	}
	if kind != "method" || isAsync || isGen {
		p.err("expecting '('")
	}
	if !computed && !private && (name == "constructor") {
		p.errAt(keyPos, "invalid field name")
	}
	if isStatic && !computed && name == "prototype" {
		p.errAt(keyPos, "invalid field name")
	}
	// field
	m.Kind = "field"
	f := &FuncNode{pos: p.lx.tok.pos, Kind: FKFieldInit, src: p.sf}
	if p.is("=") {
		p.next()
		old := p.enterFunc(f, false, false, false)
		p.fc.allowSuperProp = true
		p.fc.inClassField = true
		f.Params = []Node{}
		f.SimpleParams = true
		startPos := p.lx.tok.pos
		f.ExprBody = p.parseAssign()
		_ = startPos
		f.end = p.lx.prev.end
		p.fc = old
		m.Value = f
	}
	p.semicolon()
	return m
}

// ---------------- Patterns ----------------

func (p *Parser) parseBindingPattern() Node {
	pos := p.lx.tok.pos
	if p.is("[") {
		p.next()
		ap := &ArrPattern{pos: pos}
		for !p.is("]") {
			if p.is(",") {
				p.next()
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if p.is("...") {
				p.next()
				ap.Rest = p.parseBindingTarget()
				if !p.is("]") {
					p.err("expecting ']'")
				}
				break
			}
			el := p.parseBindingElement()
			ap.Elems = append(ap.Elems, el)
			if !p.is("]") {
				p.expect(",")
			}
		}
		p.next()
		return ap
	}
	p.expect("{")
	op := &ObjPattern{pos: pos}
	for !p.is("}") {
		if p.is("...") {
			p.next()
			op.Rest = p.parseBindingIdent()
			if !p.is("}") {
				p.err("expecting '}'")
			}
			break
		}
		ppos := p.lx.tok.pos
		t := &p.lx.tok
		var pp *PatProp
		if t.kind == tIdent {
			save := p.lx
			nameTok := *t
			p.next()
			if !p.is(":") {
				// shorthand
				p.lx = save
				id := p.parseBindingIdent()
				pp = &PatProp{pos: ppos, Key: &StrLit{pos: ppos, Val: newStr(nameTok.str)}, KeyName: nameTok.str, Value: id}
				if p.is("=") {
					apos := p.lx.tok.pos
					p.next()
					pp.Value = &AssignPat{pos: apos, Target: id, Default: p.parseAssign()}
				}
			} else {
				p.lx = save
			}
		}
		if pp == nil {
			key, name, computed, private := p.parsePropertyName()
			if private {
				p.errAt(ppos, "unexpected private name")
			}
			p.expect(":")
			pp = &PatProp{pos: ppos, Key: key, KeyName: name, Computed: computed}
			pp.Value = p.parseBindingElement()
		}
		op.Props = append(op.Props, pp)
		if !p.is("}") {
			p.expect(",")
		}
	}
	p.next()
	return op
}

func (p *Parser) parseBindingTarget() Node {
	if p.is("[") || p.is("{") {
		return p.parseBindingPattern()
	}
	return p.parseBindingIdent()
}

func (p *Parser) parseBindingElement() Node {
	target := p.parseBindingTarget()
	if p.is("=") {
		apos := p.lx.tok.pos
		p.next()
		return &AssignPat{pos: apos, Target: target, Default: p.parseAssign()}
	}
	return target
}

// convert expression (cover grammar) to assignment target
func (p *Parser) toAssignTarget(n Node, isDestructuring bool) Node {
	switch x := n.(type) {
	case *Ident:
		if p.strict() && (x.Name == "eval" || x.Name == "arguments") {
			p.errAt(x.pos, "invalid assignment left-hand side")
		}
		return x
	case *MemberExpr:
		if x.Optional {
			p.errAt(x.pos, "invalid assignment left-hand side")
		}
		return x
	case *OptChain:
		p.errAt(x.pos, "invalid assignment left-hand side")
	case *ParenExpr:
		inner := x.X
		switch inner.(type) {
		case *Ident, *MemberExpr, *ParenExpr:
			return p.toAssignTarget(inner, false)
		}
		if isDestructuring {
			p.errAt(x.pos, "invalid destructuring target")
		}
		p.errAt(x.pos, "invalid assignment left-hand side")
	case *ArrayLit:
		ap := &ArrPattern{pos: x.pos}
		for i, e := range x.Elems {
			if e == nil {
				ap.Elems = append(ap.Elems, nil)
				continue
			}
			if sp, ok := e.(*Spread); ok {
				if i != len(x.Elems)-1 || x.trailingHole {
					p.errAt(sp.pos, "invalid destructuring target")
				}
				ap.Rest = p.toAssignTarget(sp.X, true)
				if _, ok := ap.Rest.(*AssignPat); ok {
					p.errAt(sp.pos, "invalid destructuring target")
				}
				continue
			}
			ap.Elems = append(ap.Elems, p.toAssignElem(e))
		}
		return ap
	case *ObjectLit:
		op := &ObjPattern{pos: x.pos}
		for i, pr := range x.Props {
			switch pr.Kind {
			case PSpread:
				if i != len(x.Props)-1 {
					p.errAt(pr.pos, "invalid destructuring target")
				}
				op.Rest = p.toAssignTarget(pr.Value, true)
			case PInit, PProto:
				pp := &PatProp{pos: pr.pos, Key: pr.Key, KeyName: pr.KeyName, Computed: pr.Computed}
				if pr.Shorthand {
					id := pr.Value.(*Ident)
					p.checkBindingName(id)
					if pr.CoverInit != nil {
						pp.Value = &AssignPat{pos: pr.pos, Target: id, Default: pr.CoverInit}
					} else {
						pp.Value = id
					}
				} else {
					pp.Value = p.toAssignElem(pr.Value)
				}
				op.Props = append(op.Props, pp)
			default:
				p.errAt(pr.pos, "invalid destructuring target")
			}
		}
		return op
	case *AssignExpr:
		if x.Op == "=" {
			return &AssignPat{pos: x.pos, Target: x.L, Default: x.R}
		}
	case *AssignPat, *ObjPattern, *ArrPattern:
		return n
	}
	if isDestructuring {
		p.errAt(nodePos(n), "invalid destructuring target")
	}
	p.errAt(nodePos(n), "invalid assignment left-hand side")
	return nil
}

func (p *Parser) checkBindingName(id *Ident) {
	if reservedWords[id.Name] || (p.strict() && (strictReserved[id.Name] || id.Name == "eval" || id.Name == "arguments")) {
		p.errAt(id.pos, "invalid destructuring target")
	}
}

func (p *Parser) toAssignElem(e Node) Node {
	if a, ok := e.(*AssignExpr); ok && a.Op == "=" {
		return &AssignPat{pos: a.pos, Target: p.toAssignTarget(a.L, true), Default: a.R}
	}
	return p.toAssignTarget(e, true)
}

// convert arrow params from cover expressions
func (p *Parser) toParam(n Node) Node {
	switch x := n.(type) {
	case *Ident:
		if reservedWords[x.Name] {
			p.errAt(x.pos, "invalid parameter")
		}
		return x
	case *AssignExpr:
		if x.Op == "=" {
			return &AssignPat{pos: x.pos, Target: p.toParam(x.L), Default: x.R}
		}
	case *AssignPat:
		return x
	case *ArrayLit, *ObjectLit:
		return p.toBindingPattern(p.toAssignTarget(n, true))
	case *Spread:
		return &Spread{pos: x.pos, X: p.toParam(x.X)}
	case *ArrPattern, *ObjPattern:
		return p.toBindingPattern(x)
	}
	p.errAt(nodePos(n), "invalid parameter")
	return nil
}

func (p *Parser) toBindingPattern(n Node) Node {
	switch x := n.(type) {
	case *Ident:
		return x
	case *AssignPat:
		x.Target = p.toBindingPattern(x.Target)
		return x
	case *ArrPattern:
		for i, e := range x.Elems {
			if e != nil {
				x.Elems[i] = p.toBindingPattern(e)
			}
		}
		if x.Rest != nil {
			x.Rest = p.toBindingPattern(x.Rest)
		}
		return x
	case *ObjPattern:
		for _, pp := range x.Props {
			pp.Value = p.toBindingPattern(pp.Value)
		}
		if x.Rest != nil {
			x.Rest = p.toBindingPattern(x.Rest)
		}
		return x
	}
	p.errAt(nodePos(n), "invalid destructuring target")
	return nil
}

func (p *Parser) checkCoverInit(n Node) {
	// error if object literal contains shorthand initializer that wasn't converted
	switch x := n.(type) {
	case *ObjectLit:
		for _, pr := range x.Props {
			if pr.CoverInit != nil {
				p.errAt(pr.pos, "invalid property name")
			}
		}
	}
}

// ---------------- Expressions ----------------

func (p *Parser) parseExpression() Node {
	x := p.parseExpressionCover()
	p.checkCoverInit(x)
	return x
}

func (p *Parser) parseExpressionCover() Node {
	pos := p.lx.tok.pos
	x := p.parseAssign()
	if p.is(",") {
		seq := &SeqExpr{pos: pos, List: []Node{x}}
		for p.is(",") {
			p.next()
			seq.List = append(seq.List, p.parseAssign())
		}
		return seq
	}
	return x
}

func isAssignOp(s string) bool {
	switch s {
	case "=", "+=", "-=", "*=", "/=", "%=", "**=", "<<=", ">>=", ">>>=", "&=", "|=", "^=", "&&=", "||=", "??=":
		return true
	}
	return false
}

func (p *Parser) parseAssign() Node {
	t := &p.lx.tok
	pos := t.pos
	// yield
	if t.kind == tIdent && t.str == "yield" && p.fc.isGen && !t.escaped {
		return p.parseYield()
	}
	// async arrow: async x => ...
	if t.kind == tIdent && t.str == "async" && !t.escaped {
		save := p.lx
		p.next()
		nt := &p.lx.tok
		if !nt.nlBefore && nt.kind == tIdent && !reservedWords[nt.str] {
			// async ident =>
			save2 := p.lx
			id := &Ident{pos: nt.pos, Name: nt.str}
			p.next()
			if p.is("=>") && !p.lx.tok.nlBefore {
				return p.parseArrowFrom(pos, []Node{id}, true)
			}
			p.lx = save2
		}
		p.lx = save
	}
	if t.kind == tIdent && p.isIdentRef() {
		// simple arrow: x => ...
		save := p.lx
		id := &Ident{pos: t.pos, Name: t.str}
		p.next()
		if p.is("=>") && !p.lx.tok.nlBefore {
			return p.parseArrowFrom(pos, []Node{id}, false)
		}
		p.lx = save
	}
	startTok := p.lx.tok
	left := p.parseConditional()
	if arrow, ok := left.(*ArrowFunc); ok {
		_ = arrow
		return left
	}
	t = &p.lx.tok
	if t.kind == tPunct && isAssignOp(t.str) {
		op := t.str
		opPos := t.pos
		var target Node
		if op == "=" {
			switch left.(type) {
			case *ObjectLit, *ArrayLit:
				target = p.toAssignTarget(left, true)
			default:
				target = p.toSimpleTarget(left, opPos)
			}
		} else {
			target = p.toSimpleTarget(left, opPos)
		}
		p.next()
		right := p.parseAssign()
		_ = startTok
		return &AssignExpr{pos: opPos, Op: op, L: target, R: right}
	}
	return left
}

func (p *Parser) toSimpleTarget(n Node, opPos int) Node {
	switch x := n.(type) {
	case *Ident:
		if p.strict() && (x.Name == "eval" || x.Name == "arguments") {
			p.errAt(opPos, "invalid assignment left-hand side")
		}
		return x
	case *MemberExpr:
		return x
	case *ParenExpr:
		switch x.X.(type) {
		case *Ident, *MemberExpr, *ParenExpr:
			return p.toSimpleTarget(x.X, opPos)
		}
	case *CallExpr:
		if !p.strict() {
			return x // runtime ReferenceError
		}
	}
	p.errAt(opPos, "invalid assignment left-hand side")
	return nil
}

func (p *Parser) parseYield() Node {
	pos := p.lx.tok.pos
	if p.fc.inClassField {
		p.err("yield not allowed here")
	}
	p.next()
	y := &YieldExpr{pos: pos}
	t := &p.lx.tok
	if t.nlBefore {
		return y
	}
	if p.is("*") {
		p.next()
		y.Delegate = true
		y.X = p.parseAssign()
		return y
	}
	if t.kind == tEOF || t.kind == tPunct && (t.str == ")" || t.str == "]" || t.str == "}" || t.str == "," || t.str == ";" || t.str == ":" || (t.str == "?" ) ) || (t.kind == tIdent && t.str == "in" && !t.escaped) {
		return y
	}
	y.X = p.parseAssign()
	return y
}

func (p *Parser) parseConditional() Node {
	pos := p.lx.tok.pos
	test := p.parseBinary(0)
	if _, ok := test.(*ArrowFunc); ok {
		return test
	}
	if p.is("?") {
		p.checkCoverInit(test)
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		cons := p.parseAssign()
		p.noIn = saveNoIn
		p.expect(":")
		alt := p.parseAssign()
		return &CondExpr{pos: pos, Test: test, Cons: cons, Alt: alt}
	}
	return test
}

func binPrec(t *Token, noIn bool) int {
	if t.kind == tPunct {
		switch t.str {
		case "??":
			return 1
		case "||":
			return 2
		case "&&":
			return 3
		case "|":
			return 4
		case "^":
			return 5
		case "&":
			return 6
		case "==", "!=", "===", "!==":
			return 7
		case "<", ">", "<=", ">=":
			return 8
		case "<<", ">>", ">>>":
			return 9
		case "+", "-":
			return 10
		case "*", "/", "%":
			return 11
		case "**":
			return 12
		}
	} else if t.kind == tIdent && !t.escaped {
		if t.str == "instanceof" {
			return 8
		}
		if t.str == "in" && !noIn {
			return 8
		}
	}
	return 0
}

func (p *Parser) parseBinary(minPrec int) Node {
	var left Node
	// private name 'in'
	if p.lx.tok.kind == tPrivate {
		t := p.lx.tok
		p.next()
		if !p.isKw("in") || p.noIn {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		if minPrec > 8 {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		opPos := p.lx.tok.pos
		p.next()
		right := p.parseBinary(9)
		left = &PrivateIn{pos: opPos, Name: t.str, R: right}
	} else {
		left = p.parseUnary()
	}
	if _, ok := left.(*ArrowFunc); ok {
		return left
	}
	for {
		t := &p.lx.tok
		prec := binPrec(t, p.noIn)
		if prec == 0 || prec <= minPrec && !(prec == 12 && minPrec == 12) {
			break
		}
		if prec < minPrec || (prec == minPrec && prec != 12) {
			break
		}
		op := t.str
		opPos := t.pos
		if op == "**" {
			if u, ok := left.(*UnaryExpr); ok {
				_ = u
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
			if _, ok := left.(*AwaitExpr); ok {
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
		}
		p.checkCoverInit(left)
		p.next()
		var right Node
		if op == "**" {
			right = p.parseBinary(11) // right assoc
		} else {
			right = p.parseBinary(prec)
		}
		if op == "??" || op == "||" || op == "&&" {
			// mixing ?? with || && without parens is error
			if op == "??" {
				if l, ok := left.(*LogicalExpr); ok && l.Op != "??" {
					p.errAt(opPos, "unexpected token in expression: '??'")
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op != "??" {
					p.errAt(opPos, "unexpected token in expression: '??'")
				}
			} else {
				if l, ok := left.(*LogicalExpr); ok && l.Op == "??" {
					p.errAt(opPos, "unexpected token in expression: '%s'", op)
				}
				if r, ok := right.(*LogicalExpr); ok && r.Op == "??" {
					p.errAt(opPos, "unexpected token in expression: '%s'", op)
				}
			}
			left = &LogicalExpr{pos: opPos, Op: op, L: left, R: right}
		} else {
			left = &BinaryExpr{pos: opPos, Op: op, L: left, R: right}
		}
	}
	return left
}

func (p *Parser) parseUnary() Node {
	t := &p.lx.tok
	pos := t.pos
	if t.kind == tPunct {
		switch t.str {
		case "!", "~", "+", "-":
			op := t.str
			p.next()
			x := p.parseUnary()
			return &UnaryExpr{pos: pos, Op: op, X: x}
		case "++", "--":
			op := t.str
			p.next()
			x := p.parseUnary()
			x = p.checkUpdateTarget(x, pos)
			return &UpdateExpr{pos: pos, Op: op, Prefix: true, X: x}
		}
	} else if t.kind == tIdent && !t.escaped {
		switch t.str {
		case "delete", "void", "typeof":
			op := t.str
			p.next()
			x := p.parseUnary()
			if op == "delete" && p.strict() {
				if _, ok := x.(*Ident); ok {
					p.errAt(pos, "cannot delete a direct reference in strict mode")
				}
			}
			if op == "delete" {
				if m, ok := x.(*MemberExpr); ok && m.Private {
					p.errAt(pos, "cannot delete a private class field")
				}
			}
			return &UnaryExpr{pos: pos, Op: op, X: x}
		case "await":
			if p.fc.isAsync && !p.fc.inClassField {
				if p.fc.inStaticBlock {
					p.err("await not allowed here")
				}
				p.next()
				x := p.parseUnary()
				return &AwaitExpr{pos: pos, X: x}
			}
		}
	}
	return p.parsePostfix()
}

func (p *Parser) checkUpdateTarget(x Node, pos int) Node {
	switch y := x.(type) {
	case *Ident:
		if p.strict() && (y.Name == "eval" || y.Name == "arguments") {
			p.errAt(pos, "invalid increment/decrement operand")
		}
		return x
	case *MemberExpr:
		return x
	case *ParenExpr:
		return p.checkUpdateTarget(y.X, pos)
	case *CallExpr:
		if !p.strict() {
			return x
		}
	}
	p.err("invalid increment/decrement operand")
	return nil
}

func (p *Parser) parsePostfix() Node {
	x := p.parseLHS()
	if _, ok := x.(*ArrowFunc); ok {
		return x
	}
	t := &p.lx.tok
	if t.kind == tPunct && (t.str == "++" || t.str == "--") && !t.nlBefore {
		op := t.str
		pos := t.pos
		x = p.checkUpdateTarget(x, pos)
		p.next()
		return &UpdateExpr{pos: pos, Op: op, Prefix: false, X: x}
	}
	return x
}

func (p *Parser) parseArgs() []Node {
	p.expect("(")
	args := []Node{}
	saveNoIn := p.noIn
	p.noIn = false
	for !p.is(")") {
		if p.is("...") {
			spos := p.lx.tok.pos
			p.next()
			args = append(args, &Spread{pos: spos, X: p.parseAssign()})
		} else {
			args = append(args, p.parseAssign())
		}
		if !p.is(")") {
			p.expect(",")
		}
	}
	p.noIn = saveNoIn
	p.next()
	return args
}

// parse call/member/new expression
func (p *Parser) parseLHS() Node {
	t := &p.lx.tok
	pos := t.pos
	var x Node
	if t.kind == tIdent && t.str == "new" && !t.escaped {
		x = p.parseNew()
	} else if t.kind == tIdent && t.str == "super" && !t.escaped {
		p.next()
		if p.is("(") {
			if !p.fc.allowSuperCall {
				p.errAt(pos, "super() is only valid in a derived class constructor")
			}
			argPos := p.lx.tok.pos
			args := p.parseArgs()
			x = &CallExpr{pos: argPos, Callee: &SuperExpr{pos: pos}, Args: args}
		} else if p.is(".") || p.is("[") {
			if !p.fc.allowSuperProp {
				p.errAt(p.lx.tok.pos, "'super' is only valid in a method")
			}
			x = &SuperExpr{pos: pos}
			x = p.parseMemberTail(x, true)
		} else {
			p.err("invalid use of 'super'")
		}
	} else if t.kind == tIdent && t.str == "import" && !t.escaped {
		p.next()
		if p.is(".") {
			p.next()
			if !p.isKw("meta") {
				p.err("invalid use of 'import'")
			}
			if !p.isModule {
				p.err("import.meta only valid in module code")
			}
			p.next()
			x = &ImportMetaExpr{pos: pos}
		} else {
			p.expect("(")
			saveNoIn := p.noIn
			p.noIn = false
			arg := p.parseAssign()
			var opt Node
			if p.is(",") {
				p.next()
				if !p.is(")") {
					opt = p.parseAssign()
					if p.is(",") {
						p.next()
					}
				}
			}
			p.noIn = saveNoIn
			p.expect(")")
			x = &ImportCall{pos: pos, X: arg, Opt: opt}
		}
	} else {
		x = p.parsePrimary()
		if _, ok := x.(*ArrowFunc); ok {
			return x
		}
	}
	return p.parseCallTail(x)
}

func (p *Parser) parseNew() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.is(".") {
		p.next()
		if !p.isKw("target") {
			p.err("expecting target")
		}
		if !p.fc.allowNewTarget && !p.inFunctionForNewTarget() {
			p.err("new.target only allowed within functions")
		}
		p.next()
		return &NewTargetExpr{pos: pos}
	}
	var callee Node
	if p.isKw("new") {
		callee = p.parseNew()
	} else if p.isKw("super") {
		p.err("invalid use of 'super'")
	} else if p.isKw("import") {
		p.err("invalid use of 'import'")
	} else {
		callee = p.parsePrimary()
	}
	callee = p.parseMemberTail(callee, false)
	if p.is("(") {
		argPos := p.lx.tok.pos
		args := p.parseArgs()
		return &NewExpr{pos: argPos, Callee: callee, Args: args}
	}
	return &NewExpr{pos: pos, Callee: callee, Args: nil}
}

func (p *Parser) inFunctionForNewTarget() bool {
	for fc := p.fc; fc != nil; fc = fc.parent {
		if !fc.isArrow {
			if fc.parent == nil {
				return fc.allowNewTarget
			}
			return true
		}
	}
	return false
}

// member accesses only (no calls) - used for new callee
func (p *Parser) parseMemberTail(x Node, superOnly bool) Node {
	for {
		t := &p.lx.tok
		if t.kind == tPunct && t.str == "." {
			pos := t.pos
			p.next()
			nt := &p.lx.tok
			if nt.kind == tPrivate {
				if _, ok := x.(*SuperExpr); ok {
					p.err("unexpected private name")
				}
				x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Private: true}
				p.next()
			} else if nt.kind == tIdent {
				x = &MemberExpr{pos: pos, Obj: x, Name: nt.str}
				p.next()
			} else {
				p.err("expecting field name")
			}
		} else if t.kind == tPunct && t.str == "[" {
			pos := t.pos
			p.next()
			saveNoIn := p.noIn
			p.noIn = false
			prop := p.parseExpression()
			p.noIn = saveNoIn
			p.expect("]")
			x = &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true}
		} else if t.kind == tTemplate && !superOnly {
			if _, ok := x.(*SuperExpr); ok {
				p.err("invalid use of 'super'")
			}
			tpl := p.parseTemplate(true)
			x = &TaggedTemplate{pos: tpl.pos, Tag: x, Tpl: tpl}
		} else {
			break
		}
		if superOnly {
			superOnly = false
		}
	}
	return x
}

func (p *Parser) parseCallTail(x Node) Node {
	inChain := false
	for {
		t := &p.lx.tok
		if t.kind == tPunct {
			switch t.str {
			case ".", "[":
				x = p.parseMemberTail1(x)
				continue
			case "(":
				pos := t.pos
				args := p.parseArgs()
				c := &CallExpr{pos: pos, Callee: x, Args: args}
				if id, ok := x.(*Ident); ok && id.Name == "eval" {
					c.isEval = true
				}
				x = c
				continue
			case "?.":
				pos := t.pos
				inChain = true
				p.next()
				nt := &p.lx.tok
				if nt.kind == tPunct && nt.str == "(" {
					cpos := nt.pos
					args := p.parseArgs()
					x = &CallExpr{pos: cpos, Callee: x, Args: args, Optional: true}
				} else if nt.kind == tPunct && nt.str == "[" {
					p.next()
					saveNoIn := p.noIn
					p.noIn = false
					prop := p.parseExpression()
					p.noIn = saveNoIn
					p.expect("]")
					x = &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true, Optional: true}
				} else if nt.kind == tIdent {
					x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Optional: true}
					p.next()
				} else if nt.kind == tPrivate {
					x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Optional: true, Private: true}
					p.next()
				} else if nt.kind == tTemplate {
					p.err("invalid tagged template in optional chain")
				} else {
					p.err("expecting field name")
				}
				continue
			}
		} else if t.kind == tTemplate {
			if inChain {
				p.err("invalid tagged template in optional chain")
			}
			tpl := p.parseTemplate(true)
			x = &TaggedTemplate{pos: tpl.pos, Tag: x, Tpl: tpl}
			continue
		}
		break
	}
	if inChain {
		return &OptChain{pos: nodePos(x), X: x}
	}
	return x
}

func (p *Parser) parseMemberTail1(x Node) Node {
	t := &p.lx.tok
	pos := t.pos
	if t.str == "." {
		p.next()
		nt := &p.lx.tok
		if nt.kind == tPrivate {
			x = &MemberExpr{pos: pos, Obj: x, Name: nt.str, Private: true}
			p.next()
		} else if nt.kind == tIdent {
			x = &MemberExpr{pos: pos, Obj: x, Name: nt.str}
			p.next()
		} else {
			p.err("expecting field name")
		}
		return x
	}
	p.next()
	saveNoIn := p.noIn
	p.noIn = false
	prop := p.parseExpression()
	p.noIn = saveNoIn
	p.expect("]")
	return &MemberExpr{pos: pos, Obj: x, Prop: prop, Computed: true}
}

func (p *Parser) parseTemplate(tagged bool) *TemplateLit {
	t := &p.lx.tok
	tpl := &TemplateLit{pos: t.pos}
	for {
		t = &p.lx.tok
		if t.kind != tTemplate {
			p.err("unexpected token in expression: '%s'", tokDesc(t))
		}
		if t.sval == nil && !tagged {
			p.errAt(t.pos, "malformed escape sequence in string literal")
		}
		tpl.Cooked = append(tpl.Cooked, t.sval)
		tpl.Raws = append(tpl.Raws, t.raw)
		if t.tail {
			p.next()
			break
		}
		p.next()
		saveNoIn := p.noIn
		p.noIn = false
		e := p.parseExpression()
		p.noIn = saveNoIn
		tpl.Exprs = append(tpl.Exprs, e)
		if !p.is("}") {
			p.err("expecting '}'")
		}
		p.lx.rescanTemplate()
	}
	return tpl
}

func (p *Parser) parsePrimary() Node {
	t := &p.lx.tok
	pos := t.pos
	switch t.kind {
	case tNum:
		if t.legacyOctal && p.strict() {
			p.err("octal literals are deprecated in strict mode")
		}
		v := t.num
		p.next()
		return &NumLit{pos: pos, Val: v}
	case tBigInt:
		d := t.str
		p.next()
		return &BigIntLit{pos: pos, Digits: d}
	case tStr:
		if t.legacyOctal && p.strict() {
			p.err("octal escape sequences are not allowed in strict mode")
		}
		s := &StrLit{pos: pos, Val: t.sval, Raw: t.raw}
		p.next()
		return s
	case tTemplate:
		return p.parseTemplate(false)
	case tPrivate:
		p.err("unexpected token in expression: '%s'", t.str)
	case tEOF:
		p.err("unexpected token in expression: ''")
	case tPunct:
		switch t.str {
		case "(":
			return p.parseParenOrArrow()
		case "[":
			return p.parseArrayLit()
		case "{":
			return p.parseObjectLit()
		case "/", "/=":
			p.lx.rescanRegExp()
			rt := &p.lx.tok
			r := &RegExpLit{pos: pos, Pattern: rt.str, Flags: rt.flags}
			p.next()
			return r
		}
		p.err("unexpected token in expression: '%s'", t.str)
	case tIdent:
		if !t.escaped {
			switch t.str {
			case "function":
				return p.parseFunctionExpr(false, pos)
			case "async":
				if p.isAsyncFunction() {
					p.next()
					return p.parseFunctionExpr(true, pos)
				}
				// async ( ... ) =>
				save := p.lx
				p.next()
				if p.is("(") && !p.lx.tok.nlBefore {
					argPos := p.lx.tok.pos
					args := p.parseArgs()
					if p.is("=>") && !p.lx.tok.nlBefore {
						params := make([]Node, len(args))
						for i, a := range args {
							params[i] = p.toParam(a)
						}
						return p.parseArrowFrom(pos, params, true)
					}
					return &CallExpr{pos: argPos, Callee: &Ident{pos: pos, Name: "async"}, Args: args}
				}
				p.lx = save
			case "class":
				p.next()
				c := p.parseClassRest(pos, false)
				return &ClassExpr{pos: pos, C: c}
			case "this":
				p.next()
				return &ThisExpr{pos: pos}
			case "null":
				p.next()
				return &NullLit{pos: pos}
			case "true":
				p.next()
				return &BoolLit{pos: pos, Val: true}
			case "false":
				p.next()
				return &BoolLit{pos: pos, Val: false}
			case "new":
				return p.parseNew()
			}
		}
		if t.escaped && reservedWords[t.str] {
			p.err("unexpected token in expression: '%s'", t.str)
		}
		return p.parseIdentRef()
	}
	p.err("unexpected token in expression: '%s'", tokDesc(t))
	return nil
}

func (p *Parser) parseParenOrArrow() Node {
	pos := p.lx.tok.pos
	p.next()
	if p.is(")") {
		p.next()
		if !p.is("=>") || p.lx.tok.nlBefore {
			p.errAt(p.lx.prev.pos, "unexpected token in expression: ')'")
		}
		return p.parseArrowFrom(pos, []Node{}, false)
	}
	saveNoIn := p.noIn
	p.noIn = false
	var items []Node
	hasRest := false
	trailingComma := false
	restPos := 0
	for {
		if p.is("...") {
			restPos = p.lx.tok.pos
			p.next()
			var target Node
			if p.is("[") || p.is("{") {
				target = p.parseBindingPattern()
			} else {
				target = p.parseBindingIdent()
			}
			items = append(items, &Spread{pos: restPos, X: target})
			hasRest = true
			if !p.is(")") {
				p.err("expecting ')'")
			}
			break
		}
		items = append(items, p.parseAssign())
		if p.is(",") {
			p.next()
			if p.is(")") {
				trailingComma = true
				break
			}
			continue
		}
		break
	}
	p.noIn = saveNoIn
	p.expect(")")
	if p.is("=>") && !p.lx.tok.nlBefore {
		params := make([]Node, len(items))
		for i, a := range items {
			params[i] = p.toParam(a)
		}
		return p.parseArrowFrom(pos, params, false)
	}
	if hasRest {
		p.errAt(restPos, "unexpected token in expression: '...'")
	}
	if trailingComma {
		p.errAt(p.lx.prev.pos, "unexpected token in expression: ')'")
	}
	for _, it := range items {
		p.checkCoverInit(it)
	}
	if len(items) == 1 {
		return &ParenExpr{pos: pos, X: items[0]}
	}
	return &ParenExpr{pos: pos, X: &SeqExpr{pos: nodePos(items[0]), List: items}}
}

func (p *Parser) parseArrowFrom(pos int, params []Node, isAsync bool) Node {
	// current token is '=>'
	f := &FuncNode{pos: pos, IsArrow: true, IsAsync: isAsync, Kind: FKArrow, src: p.sf}
	f.Params = params
	f.SimpleParams = true
	length := 0
	sawDefault := false
	for _, prm := range params {
		switch prm.(type) {
		case *Ident:
			if !sawDefault {
				length++
			}
		case *AssignPat:
			sawDefault = true
			f.SimpleParams = false
		default:
			sawDefault = true
			f.SimpleParams = false
		}
	}
	f.length = length
	p.next() // skip =>
	old := p.enterFunc(f, isAsync, false, true)
	saveLabels := p.pendingLabels
	p.pendingLabels = nil
	if p.is("{") {
		saveBreak := p.fc.breakables
		p.fc.breakables = nil
		p.parseFunctionBody(f)
		p.fc.breakables = saveBreak
	} else {
		saveNoIn := p.noIn
		f.ExprBody = p.parseAssign()
		p.noIn = saveNoIn
		f.end = p.lx.prev.end
	}
	p.pendingLabels = saveLabels
	if f.Strict {
		p.checkStrictParams(f)
	}
	p.fc = old
	return &ArrowFunc{pos: pos, F: f}
}

func (p *Parser) parseArrayLit() Node {
	pos := p.lx.tok.pos
	p.next()
	a := &ArrayLit{pos: pos, Elems: []Node{}}
	saveNoIn := p.noIn
	p.noIn = false
	for !p.is("]") {
		if p.is(",") {
			p.next()
			a.Elems = append(a.Elems, nil)
			continue
		}
		var e Node
		if p.is("...") {
			spos := p.lx.tok.pos
			p.next()
			e = &Spread{pos: spos, X: p.parseAssign()}
		} else {
			e = p.parseAssign()
		}
		a.Elems = append(a.Elems, e)
		if !p.is("]") {
			if !p.is(",") {
				p.err("expecting ']'")
			}
			p.next()
			if p.is("]") {
				// trailing comma, not a hole
			}
		}
	}
	p.noIn = saveNoIn
	p.next()
	return a
}

func (p *Parser) parseObjectLit() Node {
	pos := p.lx.tok.pos
	p.next()
	o := &ObjectLit{pos: pos}
	saveNoIn := p.noIn
	p.noIn = false
	hasProto := false
	for !p.is("}") {
		ppos := p.lx.tok.pos
		if p.is("...") {
			p.next()
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: PSpread, Value: p.parseAssign()})
			if !p.is("}") {
				p.expect(",")
			}
			continue
		}
		t := &p.lx.tok
		isAsync := false
		isGen := false
		kind := ""
		if t.kind == tIdent && !t.escaped && (t.str == "get" || t.str == "set" || t.str == "async") {
			save := p.lx
			which := t.str
			p.next()
			nt := &p.lx.tok
			if nt.kind == tPunct && (nt.str == "(" || nt.str == ":" || nt.str == "," || nt.str == "}" || nt.str == "=") {
				p.lx = save
			} else if which == "async" && nt.nlBefore {
				p.lx = save
			} else {
				kind = which
				if which == "async" {
					isAsync = true
					kind = ""
					if p.is("*") {
						isGen = true
						p.next()
					}
				}
			}
		}
		if kind == "" && !isAsync && p.is("*") {
			isGen = true
			p.next()
		}
		keyTok := p.lx.tok
		key, name, computed, private := p.parsePropertyName()
		if private {
			p.errAt(keyTok.pos, "unexpected private name")
		}
		if kind == "get" || kind == "set" {
			fk := FKGetter
			pk := PGet
			if kind == "set" {
				fk = FKSetter
				pk = PSet
			}
			f := p.parseFunctionRest(ppos, name, keyTok.pos, false, false, fk, true)
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: pk, Key: key, KeyName: name, Computed: computed, Value: &FuncExpr{pos: ppos, F: f}})
		} else if p.is("(") || isAsync || isGen {
			f := p.parseFunctionRest(ppos, name, keyTok.pos, isAsync, isGen, FKMethod, true)
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: PMethod, Key: key, KeyName: name, Computed: computed, Value: &FuncExpr{pos: ppos, F: f}})
		} else if p.is(":") {
			p.next()
			v := p.parseAssign()
			pk := PInit
			if !computed && name == "__proto__" && keyTok.kind != tNum {
				if hasProto {
					p.errAt(ppos, "duplicate __proto__ property name")
				}
				hasProto = true
				pk = PProto
			}
			o.Props = append(o.Props, &PropNode{pos: ppos, Kind: pk, Key: key, KeyName: name, Computed: computed, Value: v})
		} else {
			// shorthand
			if keyTok.kind != tIdent || computed {
				p.err("expecting ':'")
			}
			if reservedWords[name] || (name == "yield" && (p.fc.isGen || p.strict())) || (name == "await" && (p.fc.isAsync || p.isModule)) || (p.strict() && strictReserved[name]) {
				p.errAt(keyTok.pos, "unexpected token in expression: '%s'", name)
			}
			id := &Ident{pos: keyTok.pos, Name: name}
			pn := &PropNode{pos: ppos, Kind: PInit, Key: key, KeyName: name, Value: id, Shorthand: true}
			if p.is("=") {
				p.next()
				pn.CoverInit = p.parseAssign()
			}
			o.Props = append(o.Props, pn)
		}
		if !p.is("}") {
			if !p.is(",") {
				p.err("expecting '}'")
			}
			p.next()
		}
	}
	p.noIn = saveNoIn
	p.next()
	return o
}

// ---------------- Modules ----------------

func (p *Parser) parseModuleSpecifier() string {
	t := &p.lx.tok
	if t.kind != tStr {
		p.err("expecting string")
	}
	s := t.sval.String()
	p.next()
	// import attributes: with { type: "json" }
	if (p.isKw("with") || p.isKw("assert")) && !p.lx.tok.nlBefore {
		p.next()
		p.expect("{")
		for !p.is("}") {
			p.next()
		}
		p.next()
	}
	return s
}

func (p *Parser) parseModuleExportName() string {
	t := &p.lx.tok
	if t.kind == tStr {
		s := t.sval.String()
		p.next()
		return s
	}
	if t.kind != tIdent {
		p.err("identifier expected")
	}
	s := t.str
	p.next()
	return s
}

func (p *Parser) parseImportDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	d := &ImportDecl{pos: pos}
	if p.lx.tok.kind == tStr {
		d.From = p.parseModuleSpecifier()
		p.semicolon()
		return d
	}
	if p.lx.tok.kind == tIdent && !p.is("{") {
		id := p.parseBindingIdent()
		d.Specs = append(d.Specs, &ImportSpec{Imported: "default", Local: id.Name})
		if p.is(",") {
			p.next()
		}
	}
	if p.is("*") {
		p.next()
		if !p.isKw("as") {
			p.err("expecting 'as'")
		}
		p.next()
		id := p.parseBindingIdent()
		d.Specs = append(d.Specs, &ImportSpec{Imported: "*", Local: id.Name})
	} else if p.is("{") {
		p.next()
		for !p.is("}") {
			t := p.lx.tok
			imported := p.parseModuleExportName()
			local := imported
			if p.isKw("as") {
				p.next()
				id := p.parseBindingIdent()
				local = id.Name
			} else {
				if t.kind != tIdent || reservedWords[imported] {
					p.errAt(t.pos, "identifier expected")
				}
			}
			d.Specs = append(d.Specs, &ImportSpec{Imported: imported, Local: local})
			if !p.is("}") {
				p.expect(",")
			}
		}
		p.next()
	}
	if !p.isKw("from") {
		p.err("expecting 'from'")
	}
	p.next()
	d.From = p.parseModuleSpecifier()
	p.semicolon()
	return d
}

func (p *Parser) parseExportDecl() Node {
	pos := p.lx.tok.pos
	p.next()
	d := &ExportDecl{pos: pos}
	t := &p.lx.tok
	if p.is("*") {
		p.next()
		d.Star = true
		if p.isKw("as") {
			p.next()
			d.StarAs = p.parseModuleExportName()
		}
		if !p.isKw("from") {
			p.err("expecting 'from'")
		}
		p.next()
		d.From = p.parseModuleSpecifier()
		d.hasFrom = true
		p.semicolon()
		return d
	}
	if p.is("{") {
		p.next()
		for !p.is("}") {
			local := p.parseModuleExportName()
			exported := local
			if p.isKw("as") {
				p.next()
				exported = p.parseModuleExportName()
			}
			d.Specs = append(d.Specs, &ExportSpec{Local: local, Exported: exported})
			if !p.is("}") {
				p.expect(",")
			}
		}
		p.next()
		if p.isKw("from") {
			p.next()
			d.From = p.parseModuleSpecifier()
			d.hasFrom = true
		}
		p.semicolon()
		return d
	}
	if p.isKw("default") {
		p.next()
		dpos := p.lx.tok.pos
		if p.isKw("function") || p.isAsyncFunction() {
			isAsync := false
			if p.isKw("async") {
				isAsync = true
				p.next()
			}
			// function declaration, name optional
			save := p.lx
			p.next()
			if p.is("*") {
				p.next()
			}
			hasName := p.lx.tok.kind == tIdent
			p.lx = save
			if hasName {
				d.Decl = p.parseFunctionDecl(isAsync, dpos)
				d.Specs = []*ExportSpec{{Local: d.Decl.(*FuncDecl).F.Name, Exported: "default"}}
				return d
			}
			fe := p.parseFunctionExpr(isAsync, dpos).(*FuncExpr)
			fe.F.Name = "default"
			fd := &FuncDecl{pos: dpos, F: fe.F}
			fe.F.IsDecl = true
			fe.F.Name = "default"
			d.Decl = fd
			d.Specs = []*ExportSpec{{Local: "*default*", Exported: "default"}}
			return d
		}
		if p.isKw("class") {
			cpos := p.lx.tok.pos
			p.next()
			c := p.parseClassRest(cpos, false)
			if c.Name != "" {
				d.Decl = &ClassDecl{pos: cpos, C: c}
				d.Specs = []*ExportSpec{{Local: c.Name, Exported: "default"}}
				return d
			}
			d.Default = &ClassExpr{pos: cpos, C: c}
			return d
		}
		d.Default = p.parseAssign()
		p.semicolon()
		return d
	}
	if t.kind == tIdent {
		switch t.str {
		case "var", "let", "const":
			kind := t.str
			vpos := t.pos
			p.next()
			vd := p.parseVarDecls(kind, vpos, false)
			p.semicolon()
			d.Decl = vd
			return d
		case "function":
			d.Decl = p.parseFunctionDecl(false, t.pos)
			return d
		case "async":
			if p.isAsyncFunction() {
				apos := t.pos
				p.next()
				d.Decl = p.parseFunctionDecl(true, apos)
				return d
			}
		case "class":
			d.Decl = p.parseClassDecl()
			return d
		}
	}
	p.err("unexpected token in expression: '%s'", tokDesc(t))
	return nil
}

func nodePos(n Node) int {
	switch x := n.(type) {
	case *Ident:
		return x.pos
	case *NumLit:
		return x.pos
	case *StrLit:
		return x.pos
	case *BigIntLit:
		return x.pos
	case *TemplateLit:
		return x.pos
	case *TaggedTemplate:
		return x.pos
	case *RegExpLit:
		return x.pos
	case *BoolLit:
		return x.pos
	case *NullLit:
		return x.pos
	case *ThisExpr:
		return x.pos
	case *SuperExpr:
		return x.pos
	case *ArrayLit:
		return x.pos
	case *ObjectLit:
		return x.pos
	case *FuncExpr:
		return x.pos
	case *ArrowFunc:
		return x.pos
	case *ClassExpr:
		return x.pos
	case *UnaryExpr:
		return x.pos
	case *UpdateExpr:
		return x.pos
	case *BinaryExpr:
		return x.pos
	case *LogicalExpr:
		return x.pos
	case *AssignExpr:
		return x.pos
	case *CondExpr:
		return x.pos
	case *CallExpr:
		return x.pos
	case *NewExpr:
		return x.pos
	case *MemberExpr:
		return x.pos
	case *OptChain:
		return x.pos
	case *SeqExpr:
		return x.pos
	case *Spread:
		return x.pos
	case *YieldExpr:
		return x.pos
	case *AwaitExpr:
