		return True
	}
	return False
}
func Str(s *JSString) Value  { return Value{t: TagStr, p: unsafe.Pointer(s)} }
func StrGo(s string) Value   { return Str(newStr(s)) }
func Obj(o *Object) Value    { return Value{t: TagObj, p: unsafe.Pointer(o)} }
func Sym(s *Symbol) Value    { return Value{t: TagSym, p: unsafe.Pointer(s)} }
func BigV(b *big.Int) Value  { return Value{t: TagBigInt, p: unsafe.Pointer(b)} }
func ObjOrNull(o *Object) Value {
	if o == nil {
		return Null
	}
	return Obj(o)
}

func (v Value) str() *JSString  { return (*JSString)(v.p) }
func (v Value) obj() *Object    { return (*Object)(v.p) }
func (v Value) sym() *Symbol    { return (*Symbol)(v.p) }
func (v Value) big() *big.Int   { return (*big.Int)(v.p) }
func (v Value) IsUndef() bool   { return v.t == TagUndef }
func (v Value) IsNull() bool    { return v.t == TagNull }
func (v Value) IsNullish() bool { return v.t == TagUndef || v.t == TagNull }
func (v Value) IsObj() bool     { return v.t == TagObj }
func (v Value) IsStr() bool     { return v.t == TagStr }
func (v Value) IsNum() bool     { return v.t == TagNum }
func (v Value) bool() bool      { return v.n != 0 }

func (v Value) isCallable() bool {
	return v.t == TagObj && v.obj().isCallable()
}

func toBool(v Value) bool {
	switch v.t {
	case TagBool:
		return v.n != 0
	case TagNum:
		return !(v.n == 0 || v.n != v.n)
	case TagStr:
		return v.str().n > 0
	case TagUndef, TagNull, TagEmpty:
		return false
	case TagBigInt:
		return v.big().Sign() != 0
	case TagObj:
		return true
	case TagSym:
		return true
	}
	return false
}

func typeOf(v Value) string {
	switch v.t {
	case TagUndef, TagEmpty:
		return "undefined"
	case TagNull:
		return "object"
	case TagBool:
		return "boolean"
	case TagNum:
		return "number"
	case TagStr:
		return "string"
	case TagSym:
		return "symbol"
	case TagBigInt:
		return "bigint"
	case TagObj:
		if v.obj().isCallable() {
			return "function"
		}
		return "object"
	}
	return "undefined"
}

func toPrimitive(v Value, hint string) Value {
	if v.t != TagObj {
		return v
	}
	o := v.obj()
	exotic := getV(v, PropKey{sym: SymToPrimitive})
	if !exotic.IsNullish() {
		if !exotic.isCallable() {
			throwTypeError("not a function")
		}
		h := hint
		if h == "" {
			h = "default"
		}
		r := callValue(exotic, v, []Value{StrGo(h)})
		if r.t == TagObj {
			throwTypeError("toPrimitive")
		}
		return r
	}
	if hint == "" {
		hint = "number"
	}
	var order [2]string
	if hint == "string" {
		order = [2]string{"toString", "valueOf"}
	} else {
		order = [2]string{"valueOf", "toString"}
	}
	for _, name := range order {
		m := o.Get(strKey(name), v)
		if m.isCallable() {
			r := callValue(m, v, nil)
			if r.t != TagObj {
				return r
			}
		}
	}
	throwTypeError("toPrimitive")
	return Undefined
}

func toNumber(v Value) float64 {
	switch v.t {
	case TagNum:
		return v.n
	case TagBool:
		return v.n
	case TagUndef, TagEmpty:
		return math.NaN()
	case TagNull:
		return 0
	case TagStr:
		return stringToNumber(v.str())
	case TagSym:
		throwTypeError("cannot convert symbol to number")
	case TagBigInt:
		throwTypeError("cannot convert bigint to number")
	case TagObj:
		return toNumber(toPrimitive(v, "number"))
	}
	return math.NaN()
}

// toNumeric returns either a Number value or a BigInt value
func toNumeric(v Value) Value {
	if v.t == TagNum {
		return v
	}
	if v.t == TagObj {
		v = toPrimitive(v, "number")
	}
	if v.t == TagBigInt {
		return v
	}
	return Num(toNumber(v))
}

func isWSUnit(c uint16) bool {
	switch c {
	case 9, 10, 11, 12, 13, 32, 0xA0, 0x1680, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF:
		return true
	}
	if c >= 0x2000 && c <= 0x200A {
		return true
	}
	return false
}

func trimJS(s *JSString, left, right bool) *JSString {
	start, end := 0, s.n
	if left {
		for start < end && isWSUnit(s.At(start)) {
			start++
		}
	}
	if right {
		for end > start && isWSUnit(s.At(end-1)) {
			end--
		}
	}
	return s.Substring(start, end)
}

func stringToNumber(s *JSString) float64 {
	t := trimJS(s, true, true)
	if t.n == 0 {
		return 0
	}
	if t.wide {
		return math.NaN()
	}
	str := t.ASCII()
	return parseNumberLiteral(str)
}

func parseNumberLiteral(str string) float64 {
	if len(str) > 2 && str[0] == '0' {
		base := 0
		switch str[1] {
		case 'x', 'X':
			base = 16
		case 'o', 'O':
			base = 8
		case 'b', 'B':
			base = 2
		}
		if base != 0 {
			digits := str[2:]
			for i := 0; i < len(digits); i++ {
				h := hexVal(digits[i])
				if h < 0 || h >= base {
					return math.NaN()
				}
			}
			return parseIntDigits(digits, base)
		}
	}
	// decimal
	i := 0
	sign := 1.0
	if i < len(str) && (str[i] == '+' || str[i] == '-') {
		if str[i] == '-' {
			sign = -1
		}
		i++
	}
	rest := str[i:]
	if rest == "Infinity" {
		return sign * math.Inf(1)
	}
	// validate: digits [. digits] [e [+-] digits]
	j := 0
	nd := 0
	for j < len(rest) && rest[j] >= '0' && rest[j] <= '9' {
		j++
		nd++
	}
	if j < len(rest) && rest[j] == '.' {
		j++
		for j < len(rest) && rest[j] >= '0' && rest[j] <= '9' {
			j++
			nd++
		}
	}
	if nd == 0 {
		return math.NaN()
	}
	if j < len(rest) && (rest[j] == 'e' || rest[j] == 'E') {
		j++
		if j < len(rest) && (rest[j] == '+' || rest[j] == '-') {
			j++
		}
		ne := 0
		for j < len(rest) && rest[j] >= '0' && rest[j] <= '9' {
			j++
			ne++
		}
		if ne == 0 {
			return math.NaN()
		}
	}
	if j != len(rest) {
		return math.NaN()
	}
	return sign * parseFloatPrefix(rest)
}

func toString(v Value) *JSString {
	switch v.t {
	case TagStr:
		return v.str()
	case TagNum:
		return numberToString(v.n)
	case TagBool:
		if v.n != 0 {
			return strTrue
		}
		return strFalse
	case TagUndef, TagEmpty:
		return strUndefined
	case TagNull:
		return strNull
	case TagSym:
		throwTypeError("cannot convert symbol to string")
	case TagBigInt:
		return newStrASCII(v.big().String())
	case TagObj:
		return toString(toPrimitive(v, "string"))
	}
	return strUndefined
}

var (
	strTrue      = newStrASCII("true")
	strFalse     = newStrASCII("false")
	strUndefined = newStrASCII("undefined")
	strNull      = newStrASCII("null")
)

func toObject(v Value) *Object {
	switch v.t {
	case TagObj:
		return v.obj()
	case TagUndef, TagNull, TagEmpty:
		throwTypeError("cannot convert to object")
	case TagBool:
		return newPrimitiveWrapper(ClassBoolean, v)
	case TagNum:
		return newPrimitiveWrapper(ClassNumber, v)
	case TagStr:
		return newStringObject(v.str())
	case TagSym:
		return newPrimitiveWrapper(ClassSymbol, v)
	case TagBigInt:
		return newPrimitiveWrapper(ClassBigInt, v)
	}
	return nil
}

func toPropertyKey(v Value) PropKey {
	switch v.t {
	case TagStr:
		return strToKey(v.str())
	case TagSym:
		return PropKey{sym: v.sym()}
	case TagNum:
		f := v.n
		if f >= 0 && f < 1e9 && f == math.Floor(f) {
			return idxKey(uint32(f))
		}
		return strToKey(numberToString(f))
	case TagObj:
		p := toPrimitive(v, "string")
		return toPropertyKey(p)
	}
	return strToKey(toString(v))
}

func toInteger(v Value) float64 {
	f := toNumber(v)
	if f != f {
		return 0
	}
	if math.IsInf(f, 0) {
		return f
	}
	return math.Trunc(f)
}

func toInt32(v Value) int32 {
	if v.t == TagNum {
		return f64ToInt32(v.n)
	}
	return f64ToInt32(toNumber(v))
}

func f64ToInt32(f float64) int32 {
	if f >= -2147483648 && f <= 2147483647 {
		return int32(f)
	}
	if f != f || math.IsInf(f, 0) {
		return 0
	}
	f = math.Trunc(f)
	f = math.Mod(f, 4294967296)
	if f < 0 {
		f += 4294967296
	}
	return int32(uint32(f))
}

func toUint32(v Value) uint32 {
	return uint32(toInt32(v))
}

func toUint16(v Value) uint16 {
	return uint16(toInt32(v))
}

func toLength(v Value) int64 {
	f := toInteger(v)
	if f <= 0 {
		return 0
	}
	if f > 9007199254740991 {
		return 9007199254740991
	}
	return int64(f)
}

func toIndex(v Value) int64 {
	if v.IsUndef() {
		return 0
	}
	f := toInteger(v)
	if f < 0 || f > 9007199254740991 {
		throwRangeError("invalid array index")
	}
	return int64(f)
}

func sameValue(a, b Value) bool {
	if a.t == TagNum && b.t == TagNum {
		if a.n != a.n && b.n != b.n {
			return true
		}
		if a.n == 0 && b.n == 0 {
			return math.Signbit(a.n) == math.Signbit(b.n)
		}
		return a.n == b.n
	}
	return strictEquals(a, b)
}

func sameValueZero(a, b Value) bool {
	if a.t == TagNum && b.t == TagNum {
		if a.n != a.n && b.n != b.n {
			return true
		}
		return a.n == b.n
	}
	return strictEquals(a, b)
}

func strictEquals(a, b Value) bool {
	if a.t != b.t {
		if (a.t == TagUndef || a.t == TagEmpty) && (b.t == TagUndef || b.t == TagEmpty) {
			return true
		}
		return false
	}
	switch a.t {
	case TagUndef, TagNull, TagEmpty:
		return true
	case TagNum, TagBool:
		return a.n == b.n
	case TagStr:
		return strEquals(a.str(), b.str())
	case TagBigInt:
		return a.big().Cmp(b.big()) == 0
	default:
		return a.p == b.p
	}
}

func looseEquals(a, b Value) bool {
	for {
		if a.t == b.t {
			return strictEquals(a, b)
		}
		an := a.t == TagUndef || a.t == TagNull
		bn := b.t == TagUndef || b.t == TagNull
		if an && bn {
			return true
		}
		if an || bn {
			return false
		}
		if a.t == TagNum && b.t == TagStr {
			return a.n == stringToNumber(b.str())
		}
		if a.t == TagStr && b.t == TagNum {
			return stringToNumber(a.str()) == b.n
		}
		if a.t == TagBigInt && b.t == TagStr {
			bi, ok := stringToBigInt(b.str())
			if !ok {
				return false
			}
			return a.big().Cmp(bi) == 0
		}
		if a.t == TagStr && b.t == TagBigInt {
			a, b = b, a
			continue
		}
		if a.t == TagBool {
			a = Num(a.n)
			continue
		}
		if b.t == TagBool {
			b = Num(b.n)
			continue
		}
		if (a.t == TagNum || a.t == TagStr || a.t == TagBigInt || a.t == TagSym) && b.t == TagObj {
			b = toPrimitive(b, "")
			continue
		}
		if a.t == TagObj && (b.t == TagNum || b.t == TagStr || b.t == TagBigInt || b.t == TagSym) {
			a = toPrimitive(a, "")
			continue
		}
		if a.t == TagBigInt && b.t == TagNum {
			return bigEqualsNum(a.big(), b.n)
		}
		if a.t == TagNum && b.t == TagBigInt {
			return bigEqualsNum(b.big(), a.n)
		}
		return false
	}
}

func bigEqualsNum(b *big.Int, f float64) bool {
	if f != f || math.IsInf(f, 0) || f != math.Trunc(f) {
		return false
	}
	bf := new(big.Float).SetInt(b)
	return bf.Cmp(big.NewFloat(f)) == 0
}
EOF
echo ok"}

