	o := v.obj()
	exotic := getV(v, PropKey{sym: SymToPrimitive})
	if !exotic.IsNullish() {
		if !exotic.isCallable() {
			throwTypeError("not a function")
		}
		h := hint
		if h == "" {
			h = "default"
		}
		r := callValue(exotic, v, []Value{StrGo(h)})
		if r.t == TagObj {
			throwTypeError("toPrimitive")
		}
		return r
	}
	if hint == "" {
		hint = "number"
	}
	var order [2]string
	if hint == "string" {
		order = [2]string{"toString", "valueOf"}
	} else {
		order = [2]string{"valueOf", "toString"}
	}
	for _, name := range order {
		m := o.Get(strKey(name), v)
		if m.isCallable() {
			r := callValue(m, v, nil)
			if r.t != TagObj {
				return r
			}
		}
	}
