		return true
	case TagNum, TagBool:
		return a.n == b.n
	case TagStr:
		return strEquals(a.str(), b.str())
	case TagBigInt:
		return a.big().Cmp(b.big()) == 0
	default:
		return a.p == b.p
	}
}

func looseEquals(a, b Value) bool {
	for {
		if a.t == b.t {
			return strictEquals(a, b)
		}
		an := a.t == TagUndef || a.t == TagNull
		bn := b.t == TagUndef || b.t == TagNull
		if an && bn {
			return true
		}
		if an || bn {
			return false
		}
		if a.t == TagNum && b.t == TagStr {
			return a.n == stringToNumber(b.str())
		}
		if a.t == TagStr && b.t == TagNum {
			return stringToNumber(a.str()) == b.n
		}
		if a.t == TagBigInt && b.t == TagStr {
			bi, ok := stringToBigInt(b.str())
