func dataDesc(v Value, flags uint8) *PropDesc {
	return &PropDesc{value: v, hasValue: true, hasWritable: true, hasEnumerable: true, hasConfigurable: true,
		writable: flags&pWritable != 0, enumerable: flags&pEnumerable != 0, configurable: flags&pConfigurable != 0}
}

func propToDesc(p *Prop) *PropDesc {
	d := &PropDesc{hasEnumerable: true, hasConfigurable: true,
		enumerable: p.flags&pEnumerable != 0, configurable: p.flags&pConfigurable != 0}
	if p.flags&pAccessor != 0 {
		acc := p.accessor()
		d.hasGet, d.hasSet = true, true
		d.get = ObjOrUndef(acc.get)
		d.set = ObjOrUndef(acc.set)
	} else {
		d.hasValue, d.hasWritable = true, true
		d.value = p.v
		d.writable = p.flags&pWritable != 0
	}
	return d
}

func ObjOrUndef(o *Object) Value {
	if o == nil {
		return Undefined
	}
	return Obj(o)
}

// ---------- internal methods ----------

func (o *Object) GetPrototypeOf() *Object {
	if o.class == ClassProxy {
		return proxyGetPrototypeOf(o)
	}
	return o.proto
}

func (o *Object) SetPrototypeOf(p *Object) bool {
	if o.class == ClassProxy {
		return proxySetPrototypeOf(o, p)
	}
	if o.proto == p {
		return true
	}
	if !o.extensible {
		return false
	}
	if o == ObjectPrototype || isImmutableProto(o) {
		return false
	}
	for q := p; q != nil; q = q.proto {
		if q == o {
			return false
		}
		if q.class == ClassProxy {
			break
		}
	}
	o.proto = p
	return true
}

func (o *Object) IsExtensible() bool {
	if o.class == ClassProxy {
		return proxyIsExtensible(o)
	}
	return o.extensible
}

func (o *Object) PreventExtensions() bool {
	if o.class == ClassProxy {
		return proxyPreventExtensions(o)
	}
	if isTypedArrayClass(o.class) {
		ta := o.internal.(*TypedArray)
		if ta.lengthTracking || ta.buf.resizable {
			if !ta.buf.fixedLength() {
				return false
			}
		}
	}
	o.extensible = false
	return true
}

// GetOwnProperty returns a descriptor (nil if absent)
func (o *Object) GetOwnProperty(k PropKey) *PropDesc {
	switch o.class {
	case ClassArray, ClassArguments:
		if o.fastArr {
			if idx, ok := k.arrayIndex(); ok {
				if idx < uint32(len(o.arr)) {
					return dataDesc(o.arr[idx], pDefault)
				}
				if o.class == ClassArray {
					return nil
				}
			}
		}
		if o.class == ClassArray && k.sym == nil && k.s == "length" {
			fl := pWritable
			if o.lenRO {
				fl = 0
			}
			return dataDesc(Num(float64(o.alen)), fl)
		}
	case ClassString:
		s := o.internal.(*JSString)
		if idx, ok := k.arrayIndex(); ok && idx < uint32(s.n) {
			return dataDesc(Str(s.Substring(int(idx), int(idx)+1)), pEnumerable)
		}
		if k.sym == nil && k.s == "length" {
			return dataDesc(Int(s.n), 0)
		}
	case ClassProxy:
		return proxyGetOwnProperty(o, k)
	case ClassModuleNS:
		return moduleNSGetOwnProperty(o, k)
	case ClassMappedArguments:
		return mappedArgsGetOwnProperty(o, k)
	default:
		if isTypedArrayClass(o.class) {
			if k.sym == nil {
				if idx, isNum := canonicalNumericIndex(k.s); isNum {
					ta := o.internal.(*TypedArray)
					if !ta.validIndex(idx) {
						return nil
					}
					return dataDesc(ta.get(int(idx)), pDefault)
				}
			}
		}
	}
	i := o.findOwn(k)
	if i < 0 {
		return nil
	}
	return propToDesc(&o.props[i])
}

func (o *Object) HasOwnProperty(k PropKey) bool {
	if o.class == ClassObject || o.class == ClassFunction || o.class == ClassNativeFunction {
		return o.findOwn(k) >= 0
	}
	return o.GetOwnProperty(k) != nil
}

func (o *Object) HasProperty(k PropKey) bool {
	for x := o; x != nil; {
		if x.class == ClassProxy {
			return proxyHas(x, k)
		}
		if isTypedArrayClass(x.class) && k.sym == nil {
			if idx, isNum := canonicalNumericIndex(k.s); isNum {
				return x.internal.(*TypedArray).validIndex(idx)
			}
		}
		if x.HasOwnProperty(k) {
			return true
		}
		x = x.proto
	}
	return false
}

func (o *Object) Get(k PropKey, receiver Value) Value {
	x := o
	for x != nil {
		switch x.class {
		case ClassObject, ClassFunction, ClassNativeFunction, ClassError, ClassBoundFunction, ClassDate, ClassRegExp, ClassMap, ClassSet, ClassPromise, ClassGenerator:
			// ordinary
		case ClassArray, ClassArguments:
			if x.fastArr {
				if idx, ok := k.arrayIndex(); ok {
					if idx < uint32(len(x.arr)) {
						return x.arr[idx]
					}
					if x.class == ClassArray {
						x = x.proto
						continue
					}
				}
			}
			if x.class == ClassArray && k.sym == nil && k.s == "length" {
				return Num(float64(x.alen))
			}
		case ClassProxy:
			return proxyGet(x, k, receiver)
		default:
			if isTypedArrayClass(x.class) && k.sym == nil {
				if idx, isNum := canonicalNumericIndex(k.s); isNum {
					ta := x.internal.(*TypedArray)
					if !ta.validIndex(idx) {
						return Undefined
					}
					return ta.get(int(idx))
				}
			}
			if x.class == ClassString || x.class == ClassModuleNS || x.class == ClassMappedArguments {
				d := x.GetOwnProperty(k)
				if d != nil {
					if d.isAccessor() {
						if d.get.IsUndef() {
							return Undefined
						}
						return callValue(d.get, receiver, nil)
					}
					return d.value
				}
				x = x.proto
				continue
			}
		}
		i := x.findOwn(k)
		if i >= 0 {
			p := &x.props[i]
			if p.flags&pAccessor != 0 {
				g := p.accessor().get
				if g == nil {
					return Undefined
				}
				return callFunc(g, receiver, nil)
			}
			return p.v
		}
		x = x.proto
	}
	return Undefined
}

func (o *Object) GetIdx(i uint32) Value {
	if o.fastArr && i < uint32(len(o.arr)) {
		return o.arr[i]
	}
	if isTypedArrayClass(o.class) {
		ta := o.internal.(*TypedArray)
		if ta.validIndex(float64(i)) {
			return ta.get(int(i))
		}
		return Undefined
	}
	return o.Get(idxKey(i), Obj(o))
}

// Set implements [[Set]]; returns success
func (o *Object) Set(k PropKey, v Value, receiver Value, throw bool) bool {
	// fast path: ordinary own writable data property with receiver == o
	if receiver.t == TagObj && receiver.obj() == o {
		switch o.class {
		case ClassArray, ClassArguments:
			if o.fastArr {
				if idx, ok := k.arrayIndex(); ok {
					if idx < uint32(len(o.arr)) {
						o.arr[idx] = v
						return true
					}
				}
			}
		case ClassObject, ClassFunction, ClassError:
			i := o.findOwn(k)
			if i >= 0 {
				p := &o.props[i]
				if p.flags&(pAccessor|pWritable) == pWritable {
					p.v = v
					return true
				}
			}
		}
	}
	return o.setSlow(k, v, receiver, throw)
}

func (o *Object) setSlow(k PropKey, v Value, receiver Value, throw bool) bool {
	x := o
	for x != nil {
		if x.class == ClassProxy {
			ok := proxySet(x, k, v, receiver)
			if !ok && throw {
				throwTypeError("proxy: cannot set property '%s'", keyDisplay(k))
			}
			return ok
		}
		if isTypedArrayClass(x.class) && k.sym == nil {
			if idx, isNum := canonicalNumericIndex(k.s); isNum {
				ta := x.internal.(*TypedArray)
				if receiver.t == TagObj && receiver.obj() == x {
					ta.setValue(idx, v)
					return true
				}
				if !ta.validIndex(idx) {
					return true
				}
				break
			}
		}
		d := x.GetOwnProperty(k)
		if d != nil {
			if d.isAccessor() {
				if d.set.IsUndef() {
					if throw {
						throwTypeError("no setter for property")
					}
					return false
				}
				callValue(d.set, receiver, []Value{v})
				return true
			}
			if !d.writable {
				if throw {
					throwTypeError("'%s' is read-only", keyDisplay(k))
				}
				return false
			}
			break
		}
		x = x.proto
	}
	// define on receiver
	if receiver.t != TagObj {
		if throw {
			throwTypeError("cannot set property '%s' of %s", keyDisplay(k), typeOfForError(receiver))
		}
		return false
	}
	r := receiver.obj()
	if r.class == ClassProxy || r.class == ClassModuleNS || isTypedArrayClass(r.class) || r.class == ClassMappedArguments {
		ed := r.GetOwnProperty(k)
		if ed != nil {
			if ed.isAccessor() || !ed.writable {
				if throw {
					throwTypeError("'%s' is read-only", keyDisplay(k))
				}
				return false
			}
			ok := r.DefineOwnProperty(k, &PropDesc{value: v, hasValue: true}, false)
			if !ok && throw {
				throwTypeError("'%s' is read-only", keyDisplay(k))
			}
			return ok
		}
		ok := r.DefineOwnProperty(k, dataDesc(v, pDefault), false)
		if !ok && throw {
			throwTypeError("object is not extensible")
		}
		return ok
	}
	// ordinary receiver
	if r.class == ClassArray || r.class == ClassArguments {
		if idx, ok := k.arrayIndex(); ok {
			if r.fastArr {
				if idx < uint32(len(r.arr)) {
					r.arr[idx] = v
					return true
				}
			}
			return r.defineIndex(idx, v, throw)
		}
		if r.class == ClassArray && k.sym == nil && k.s == "length" {
			return r.setArrayLength(v, throw)
		}
	}
	i := r.findOwn(k)
	if i >= 0 {
		p := &r.props[i]
		if p.flags&pAccessor != 0 || p.flags&pWritable == 0 {
			if throw {
				throwTypeError("'%s' is read-only", keyDisplay(k))
			}
			return false
		}
		p.v = v
		return true
	}
	if r.class == ClassString {
		if d := r.GetOwnProperty(k); d != nil {
			if throw {
				throwTypeError("'%s' is read-only", keyDisplay(k))
			}
			return false
		}
	}
	if !r.extensible {
		if throw {
			throwTypeError("object is not extensible")
		}
		return false
	}
	r.addProp(k, v, pDefault)
	return true
}

func (o *Object) SetIdx(i uint32, v Value, throw bool) bool {
	if o.fastArr && i < uint32(len(o.arr)) && (o.class == ClassArray || o.class == ClassArguments) {
		o.arr[i] = v
		return true
	}
	if isTypedArrayClass(o.class) {
		o.internal.(*TypedArray).setValue(float64(i), v)
		return true
	}
	return o.Set(idxKey(i), v, Obj(o), throw)
}

// define index on array (data property with default flags) - used by Set & CreateDataProperty
func (o *Object) defineIndex(idx uint32, v Value, throw bool) bool {
	if o.fastArr {
		n := uint32(len(o.arr))
		if idx < n {
			o.arr[idx] = v
			return true
		}
		if idx == n && o.extensible {
			if o.class == ClassArray {
				if idx >= o.alen {
					if o.lenRO {
						if throw {
							throwTypeError("'length' is read-only")
						}
						return false
					}
					o.alen = idx + 1
				}
			}
			o.arr = append(o.arr, v)
			return true
		}
		o.convertToSlow()
	}
	if o.class == ClassArray && idx >= o.alen {
		if o.lenRO {
			if throw {
				throwTypeError("'length' is read-only")
			}
			return false
		}
	}
	k := idxKey(idx)
	i := o.findOwn(k)
	if i >= 0 {
		p := &o.props[i]
		if p.flags&pAccessor != 0 || p.flags&pWritable == 0 {
			if throw {
				throwTypeError("'%s' is read-only", k.s)
			}
			return false
		}
		p.v = v
		return true
	}
	if !o.extensible {
		if throw {
			throwTypeError("object is not extensible")
		}
		return false
	}
	o.addProp(k, v, pDefault)
	if o.class == ClassArray && idx >= o.alen {
		o.alen = idx + 1
	}
	return true
}

func (o *Object) setArrayLength(v Value, throw bool) bool {
	newLen := toArrayLengthValue(v)
	return o.setLen(newLen, throw)
}

func toArrayLengthValue(v Value) uint32 {
	var n float64
	if v.t == TagNum {
		n = v.n
	} else {
		n = toNumber(v)
	}
	u := toUint32(Num(n))
	if float64(u) != n {
		// recompute per spec: ToUint32(v) vs ToNumber(v)
		throwRangeError("invalid array length")
	}
	return u
}

func (o *Object) setLen(newLen uint32, throw bool) bool {
	if o.lenRO {
		if newLen == o.alen {
			return true
		}
		if throw {
			throwTypeError("'length' is read-only")
		}
		return false
	}
	if o.fastArr {
		if newLen < uint32(len(o.arr)) {
			for i := newLen; i < uint32(len(o.arr)); i++ {
				o.arr[i] = Undefined
			}
			o.arr = o.arr[:newLen]
		}
		o.alen = newLen
		return true
	}
	if newLen < o.alen {
		// delete index props >= newLen, from highest; stop at non-configurable
		var idxs []uint32
		for i, k := range o.keys {
			if o.props[i].flags&pDeleted != 0 {
				continue
			}
			if idx, ok := k.arrayIndex(); ok && idx >= newLen {
				idxs = append(idxs, idx)
			}
		}
		sort.Slice(idxs, func(a, b int) bool { return idxs[a] > idxs[b] })
		for _, idx := range idxs {
			j := o.findOwn(idxKey(idx))
			if o.props[j].flags&pConfigurable == 0 {
				o.alen = idx + 1
				if throw {
					throwTypeError("property is not configurable")
				}
				return false
			}
			o.removePropAt(j)
		}
	}
	o.alen = newLen
	return true
}

func (o *Object) Delete(k PropKey, throw bool) bool {
	switch o.class {
	case ClassProxy:
		ok := proxyDelete(o, k)
		if !ok && throw {
			throwTypeError("proxy: cannot delete property")
		}
		return ok
	case ClassArray, ClassArguments:
		if o.fastArr {
			if idx, ok := k.arrayIndex(); ok {
				n := uint32(len(o.arr))
				if idx >= n {
					if o.class == ClassArray {
						return true
					}
				} else {
					if idx == n-1 {
						o.arr[idx] = Undefined
						o.arr = o.arr[:idx]
						return true
					}
					o.convertToSlow()
				}
			}
		}
		if o.class == ClassArray && k.sym == nil && k.s == "length" {
			if throw {
				throwTypeError("property is not configurable")
			}
			return false
		}
	case ClassString:
		if d := o.GetOwnProperty(k); d != nil && !d.configurable {
			if o.findOwn(k) < 0 {
				if throw {
					throwTypeError("property is not configurable")
				}
				return false
			}
		}
	case ClassModuleNS:
		if moduleNSGetOwnProperty(o, k) != nil {
			if throw {
				throwTypeError("property is not configurable")
			}
			return false
		}
		return true
	case ClassMappedArguments:
		mappedArgsDelete(o, k)
	default:
		if isTypedArrayClass(o.class) && k.sym == nil {
			if idx, isNum := canonicalNumericIndex(k.s); isNum {
				if o.internal.(*TypedArray).validIndex(idx) {
					if throw {
						throwTypeError("property is not configurable")
					}
					return false
				}
				return true
			}
		}
	}
	i := o.findOwn(k)
	if i < 0 {
		return true
	}
	if o.props[i].flags&pConfigurable == 0 {
		if throw {
			throwTypeError("property is not configurable")
		}
		return false
	}
	o.removePropAt(i)
	return true
}

// DefineOwnProperty implements ValidateAndApplyPropertyDescriptor
func (o *Object) DefineOwnProperty(k PropKey, d *PropDesc, throw bool) bool {
	switch o.class {
	case ClassProxy:
		ok := proxyDefineOwnProperty(o, k, d)
		if !ok && throw {
			throwTypeError("proxy: defineProperty exception")
		}
		return ok
	case ClassArray:
		if k.sym == nil && k.s == "length" {
			return o.defineArrayLength(d, throw)
		}
		if idx, ok := k.arrayIndex(); ok {
			if o.fastArr {
				n := uint32(len(o.arr))
				isPlain := d.hasValue && (!d.hasWritable || d.writable) && (!d.hasEnumerable || d.enumerable) && (!d.hasConfigurable || d.configurable) && !d.isAccessor()
				fullPlain := isPlain && d.hasWritable && d.hasEnumerable && d.hasConfigurable
				if idx < n && isPlain {
					o.arr[idx] = d.value
					return true
				}
				if idx == n && fullPlain && o.extensible && !(idx >= o.alen && o.lenRO) {
					o.arr = append(o.arr, d.value)
					if idx >= o.alen {
						o.alen = idx + 1
					}
					return true
				}
				o.convertToSlow()
			}
			if idx >= o.alen && o.lenRO {
				if throw {
					throwTypeError("'length' is read-only")
				}
				return false
			}
			if !o.ordinaryDefine(k, d, throw) {
				return false
			}
			if idx >= o.alen {
				o.alen = idx + 1
			}
			return true
		}
	case ClassArguments:
		if _, ok := k.arrayIndex(); ok && o.fastArr {
			o.convertToSlow()
		}
	case ClassString:
		if cur := o.GetOwnProperty(k); cur != nil && o.findOwn(k) < 0 {
			// virtual property: only compatible redefinitions allowed
			if !isCompatibleDesc(cur, d) {
				if throw {
					throwTypeError("property is not configurable")
				}
				return false
			}
			return true
		}
	case ClassModuleNS:
		cur := moduleNSGetOwnProperty(o, k)
		if cur == nil {
			if throw {
				throwTypeError("object is not extensible")
			}
			return false
		}
		if !isCompatibleDesc(cur, d) || (d.hasValue && !sameValue(d.value, cur.value)) {
			if throw {
				throwTypeError("property is not configurable")
			}
			return false
		}
		return true
	case ClassMappedArguments:
		return mappedArgsDefine(o, k, d, throw)
	default:
		if isTypedArrayClass(o.class) && k.sym == nil {
			if idx, isNum := canonicalNumericIndex(k.s); isNum {
				ta := o.internal.(*TypedArray)
				if !ta.validIndex(idx) {
					if throw {
						throwTypeError("invalid typed array index")
					}
					return false
				}
				if (d.hasConfigurable && !d.configurable) || (d.hasEnumerable && !d.enumerable) || d.isAccessor() || (d.hasWritable && !d.writable) {
					if throw {
						throwTypeError("invalid descriptor")
					}
					return false
				}
				if d.hasValue {
					ta.setValue(idx, d.value)
				}
				return true
			}
		}
	}
	return o.ordinaryDefine(k, d, throw)
}

func isCompatibleDesc(cur, d *PropDesc) bool {
	if d.hasConfigurable && d.configurable != cur.configurable {
		return false
	}
	if d.hasEnumerable && d.enumerable != cur.enumerable {
		return false
	}
	if d.isAccessor() {
		return false
	}
	if d.hasWritable && d.writable != cur.writable {
		return false
	}
	if d.hasValue && !sameValue(d.value, cur.value) && !cur.writable {
		return false
	}
	return true
}

func (o *Object) defineArrayLength(d *PropDesc, throw bool) bool {
	if d.isAccessor() || (d.hasConfigurable && d.configurable) || (d.hasEnumerable && d.enumerable) {
		if throw {
			throwTypeError("property is not configurable")
		}
		return false
	}
	if d.hasValue {
		newLen := toArrayLengthValue(d.value)
		if o.lenRO && newLen != o.alen {
			if throw {
				throwTypeError("'length' is read-only")
			}
			return false
		}
		if !o.setLen(newLen, throw) {
			return false
		}
	}
	if d.hasWritable {
		if d.writable && o.lenRO {
			if throw {
				throwTypeError("property is not configurable")
			}
			return false
		}
		if !d.writable {
			o.lenRO = true
		}
	}
	return true
}

func (o *Object) ordinaryDefine(k PropKey, d *PropDesc, throw bool) bool {
	i := o.findOwn(k)
	if i < 0 {
		if !o.extensible {
			if throw {
				throwTypeError("object is not extensible")
			}
			return false
		}
		var flags uint8
		if d.hasEnumerable && d.enumerable {
			flags |= pEnumerable
		}
		if d.hasConfigurable && d.configurable {
			flags |= pConfigurable
		}
		if d.isAccessor() {
			acc := &Accessor{}
			if d.get.t == TagObj {
				acc.get = d.get.obj()
			}
			if d.set.t == TagObj {
				acc.set = d.set.obj()
			}
			v := Value{}
			v.p = ptrOf(acc)
			o.addProp(k, v, flags|pAccessor)
		} else {
			if d.hasWritable && d.writable {
				flags |= pWritable
			}
			v := d.value
			if !d.hasValue {
				v = Undefined
			}
			o.addProp(k, v, flags)
		}
		return true
	}
	p := &o.props[i]
	cur := propToDesc(p)
	if !cur.configurable {
		if d.hasConfigurable && d.configurable {
			goto reject
		}
		if d.hasEnumerable && d.enumerable != cur.enumerable {
			goto reject
		}
		if d.isAccessor() != cur.isAccessor() && (d.isAccessor() || d.isData()) {
			goto reject
		}
		if cur.isAccessor() {
			if d.hasGet && !sameValue(d.get, cur.get) {
				goto reject
			}
			if d.hasSet && !sameValue(d.set, cur.set) {
				goto reject
			}
		} else if !cur.writable {
			if d.hasWritable && d.writable {
				goto reject
			}
			if d.hasValue && !sameValue(d.value, cur.value) {
				goto reject
			}
		}
	}
	// apply
	{
		flags := p.flags &^ pDeleted
		if d.hasEnumerable {
			if d.enumerable {
				flags |= pEnumerable
			} else {
				flags &^= pEnumerable
			}
		}
		if d.hasConfigurable {
			if d.configurable {
				flags |= pConfigurable
			} else {
				flags &^= pConfigurable
			}
		}
		if d.isAccessor() {
			var acc *Accessor
			if flags&pAccessor != 0 {
				old := p.accessor()
				acc = &Accessor{get: old.get, set: old.set}
			} else {
				acc = &Accessor{}
				flags &^= pWritable
			}
			flags |= pAccessor
			if d.hasGet {
				acc.get = nil
				if d.get.t == TagObj {
					acc.get = d.get.obj()
				}
			}
			if d.hasSet {
				acc.set = nil
				if d.set.t == TagObj {
					acc.set = d.set.obj()
				}
			}
			v := Value{}
			v.p = ptrOf(acc)
			p.v = v
		} else if d.isData() || flags&pAccessor == 0 {
			if flags&pAccessor != 0 {
				flags &^= pAccessor
				p.v = Undefined
				if !d.hasWritable {
					flags &^= pWritable
				}
			}
			if d.hasWritable {
				if d.writable {
					flags |= pWritable
				} else {
					flags &^= pWritable
				}
			}
			if d.hasValue {
				p.v = d.value
			}
		}
		p.flags = flags
	}
	return true
reject:
	if throw {
		throwTypeError("property is not configurable")
	}
	return false
}

// OwnKeys returns all own property keys in spec order
func (o *Object) OwnKeys() []PropKey {
	switch o.class {
	case ClassProxy:
		return proxyOwnKeys(o)
	case ClassModuleNS:
		return moduleNSOwnKeys(o)
	}
	var idxs []uint32
	var strs []PropKey
	var syms []PropKey
	extraIdx := 0
	if o.fastArr {
		extraIdx = len(o.arr)
	}
	if o.class == ClassString {
		extraIdx = o.internal.(*JSString).n
	}
	if isTypedArrayClass(o.class) {
		extraIdx = o.internal.(*TypedArray).length()
	}
	for i, k := range o.keys {
		if o.props[i].flags&pDeleted != 0 {
			continue
		}
		if k.sym != nil {
			syms = append(syms, k)
		} else if idx, ok := k.intAtom(); ok {
			idxs = append(idxs, idx)
		} else {
			strs = append(strs, k)
		}
	}
	res := make([]PropKey, 0, extraIdx+len(idxs)+len(strs)+len(syms)+1)
	for i := 0; i < extraIdx; i++ {
		res = append(res, idxKey(uint32(i)))
	}
	if len(idxs) > 0 {
		sort.Slice(idxs, func(a, b int) bool { return idxs[a] < idxs[b] })
		for _, idx := range idxs {
			res = append(res, idxKey(idx))
		}
	}
	if o.class == ClassArray || o.class == ClassString {
		res = append(res, strKey("length"))
	}
	res = append(res, strs...)
	res = append(res, syms...)
	return res
}

func ptrOf(a *Accessor) unsafePointer { return unsafePointer(a) }

// ---------- convenience ----------

func getV(v Value, k PropKey) Value {
	if v.t == TagObj {
		return v.obj().Get(k, v)
	}
	switch v.t {
	case TagUndef, TagNull:
		throwTypeError("cannot read property '%s' of %s", keyDisplay(k), typeOfForError(v))
	case TagStr:
		s := v.str()
		if k.sym == nil {
			if k.s == "length" {
				return Int(s.n)
			}
			if idx, ok := k.arrayIndex(); ok {
				if idx < uint32(s.n) {
					return Str(s.Substring(int(idx), int(idx)+1))
				}
			}
		}
		return StringPrototype.Get(k, v)
	case TagNum:
		return NumberPrototype.Get(k, v)
	case TagBool:
		return BooleanPrototype.Get(k, v)
	case TagSym:
		return SymbolPrototype.Get(k, v)
	case TagBigInt:
		return BigIntPrototype.Get(k, v)
	}
	return Undefined
}

func getStr(v Value, name string) Value { return getV(v, strKey(name)) }

func setV(v Value, k PropKey, val Value, throw bool) {
	if v.t == TagObj {
		v.obj().Set(k, val, v, throw)
		return
	}
	switch v.t {
	case TagUndef, TagNull:
		throwTypeError("cannot set property '%s' of %s", keyDisplay(k), typeOfForError(v))
	}
	// primitives: lookup setter on prototype
	proto := protoForPrimitive(v)
	proto.Set(k, val, v, throw)
}

func protoForPrimitive(v Value) *Object {
	switch v.t {
	case TagStr:
		return StringPrototype
	case TagNum:
		return NumberPrototype
	case TagBool:
		return BooleanPrototype
	case TagSym:
		return SymbolPrototype
	case TagBigInt:
		return BigIntPrototype
	}
	return ObjectPrototype
}

func typeOfForError(v Value) string {
	if v.t == TagNull {
		return "null"
	}
	if v.t == TagUndef {
		return "undefined"
	}
	return typeOf(v)
}

func keyDisplay(k PropKey) string {
	if k.sym != nil {
		if k.sym.desc == nil {
			return ""
		}
		return k.sym.desc.ToUTF8()
	}
	return k.s
}

// CreateDataProperty
func createDataProp(o *Object, k PropKey, v Value) bool {
	if o.class == ClassArray {
		if idx, ok := k.arrayIndex(); ok {
			if o.fastArr {
				n := uint32(len(o.arr))
				if idx < n {
					o.arr[idx] = v
					return true
				}
				if idx == n && o.extensible && !(idx >= o.alen && o.lenRO) {
					o.arr = append(o.arr, v)
					if idx >= o.alen {
						o.alen = idx + 1
					}
					return true
				}
			}
		}
	}
	if o.class == ClassObject {
		i := o.findOwn(k)
		if i < 0 && o.extensible {
			o.addProp(k, v, pDefault)
			return true
		}
	}
	return o.DefineOwnProperty(k, dataDesc(v, pDefault), false)
}

func createDataPropOrThrow(o *Object, k PropKey, v Value) {
	if !createDataProp(o, k, v) {
		throwTypeError("cannot define property '%s'", keyDisplay(k))
	}
}

func canonicalNumericIndex(s string) (float64, bool) {
	if s == "-0" {
		return math.Copysign(0, -1), true
	}
	if len(s) == 0 {
		return 0, false
	}
	c := s[0]
	if !(c >= '0' && c <= '9' || c == '-' || c == 'I' || c == 'N') {
		return 0, false
	}
	if idx, ok := strArrayIndex(s); ok {
		return float64(idx), true
	}
	f := parseNumberLiteral(s)
	if numberToGoString(f) == s {
		return f, true
	}
	return 0, false
}

func lengthOfArrayLike(o *Object) int64 {
	if o.class == ClassArray {
		return int64(o.alen)
	}
	return toLength(o.Get(strKey("length"), Obj(o)))
}

func isImmutableProto(o *Object) bool {
	return false
}
