	f := newNativeFunc(name, length, fn)
	o.setOwn(PropKey{sym: sym}, Obj(f), pWritable|pConfigurable)
	return f
}

func defGetter(o *Object, name string, fn func(this Value, args []Value) Value) {
	g := newNativeFunc("get "+name, 0, fn)
	o.defineAccessorRaw(strKey(name), g, nil, pConfigurable)
}

func defGetterSym(o *Object, sym *Symbol, name string, fn func(this Value, args []Value) Value) {
	g := newNativeFunc("get "+name, 0, fn)
	o.defineAccessorRaw(PropKey{sym: sym}, g, nil, pConfigurable)
}

func defAccessor(o *Object, name string, get func(this Value, args []Value) Value, set func(this Value, args []Value) Value) {
	var g, s *Object
	if get != nil {
		g = newNativeFunc("get "+name, 0, get)
	}
	if set != nil {
		s = newNativeFunc("set "+name, 1, set)
	}
	o.defineAccessorRaw(strKey(name), g, s, pConfigurable)
}

func defProp(o *Object, name string, v Value) {
	o.setOwn(strKey(name), v, pWritable|pConfigurable)
}

func defConst(o *Object, name string, v Value) {
	o.setOwn(strKey(name), v, 0)
}
