		stackUsed = callStack[n-1].cum
	} else {
		stackUsed = 0
	}
}

// ---------- calling ----------

func callValue(fv Value, this Value, args []Value) Value {
	if fv.t != TagObj {
		throwTypeError("not a function")
	}
	return callFunc(fv.obj(), this, args)
}

func callFunc(fobj *Object, this Value, args []Value) Value {
	switch fobj.class {
	case ClassFunction:
		cl := fobj.internal.(*Closure)
		return callClosure(fobj, cl, this, args, nil)
	case ClassNativeFunction:
		nf := fobj.internal.(*NativeFunc)
		pushNative(fobj)
		r := nf.fn(this, args)
		popStack()
		return r
	case ClassBoundFunction:
		bf := fobj.internal.(*BoundFunc)
		nargs := args
		if len(bf.args) > 0 {
			nargs = make([]Value, 0, len(bf.args)+len(args))
			nargs = append(nargs, bf.args...)
			nargs = append(nargs, args...)
		}
		return callFunc(bf.target, bf.this, nargs)
	case ClassProxy:
		return proxyCall(fobj, this, args)
	}
	throwTypeError("not a function")
	return Undefined
}

func isConstructor(v Value) bool {
	if v.t != TagObj {
		return false
	}
	return v.obj().isConstructor()
}

func (o *Object) isConstructor() bool {
	switch o.class {
	case ClassFunction:
		return o.internal.(*Closure).code.isCtor
	case ClassNativeFunction:
		return o.internal.(*NativeFunc).ctor != nil
	case ClassBoundFunction:
		return o.internal.(*BoundFunc).target.isConstructor()
	case ClassProxy:
		pd := o.internal.(*ProxyData)
		return pd.isCtor
	}
	return false
}

func constructValue(fv Value, args []Value, newTarget *Object) Value {
	if fv.t != TagObj || !fv.obj().isCallable() {
		throwTypeError("not a function")
	}
	fobj := fv.obj()
	if !fobj.isConstructor() {
		throwTypeError("%s is not a constructor", funcNameForTrace(fobj))
	}
	if newTarget == nil {
		newTarget = fobj
	}
	return construct(fobj, args, newTarget)
}

func construct(fobj *Object, args []Value, newTarget *Object) Value {
	switch fobj.class {
	case ClassFunction:
		cl := fobj.internal.(*Closure)
		if cl.code.derived {
			return callClosure(fobj, cl, Undefined, args, newTarget)
		}
		proto := getPrototypeFromCtor(newTarget, ObjectPrototype)
		thisObj := newObjectProto(proto, ClassObject)
		if cl.classDef != nil {
			initInstanceElements(thisObj, fobj, cl)
		}
		r := callClosure(fobj, cl, Obj(thisObj), args, newTarget)
		if r.t == TagObj {
			return r
		}
		return Obj(thisObj)
	case ClassNativeFunction:
		nf := fobj.internal.(*NativeFunc)
		pushNative(fobj)
		r := nf.ctor(args, newTarget)
		popStack()
		return r
	case ClassBoundFunction:
		bf := fobj.internal.(*BoundFunc)
		nargs := make([]Value, 0, len(bf.args)+len(args))
		nargs = append(nargs, bf.args...)
		nargs = append(nargs, args...)
		if newTarget == fobj {
			newTarget = bf.target
		}
		return construct(bf.target, nargs, newTarget)
	case ClassProxy:
		return proxyConstruct(fobj, args, newTarget)
	}
	throwTypeError("not a constructor")
	return Undefined
}

func getPrototypeFromCtor(newTarget *Object, def *Object) *Object {
	if newTarget == nil {
		return def
	}
	p := newTarget.Get(strKey("prototype"), Obj(newTarget))
	if p.t == TagObj {
		return p.obj()
	}
	return def
}

func callClosure(fobj *Object, cl *Closure, this Value, args []Value, newTarget *Object) Value {
	code := cl.code
	if code.isClassCtor && newTarget == nil {
		throwTypeError("class constructors must be invoked with 'new'")
	}
	f := &Frame{code: code, fobj: fobj, cl: cl, args: args, env: cl.env}
	if code.nlocals > 0 {
		f.locals = make([]Value, code.nlocals)
	}
	if code.isArrow {
		f.thisFrame = cl.thisFrame
	} else {
		f.thisFrame = f
		f.homeObj = cl.homeObject
		if newTarget != nil {
			f.newTarget = Obj(newTarget)
		}
		if code.derived {
			f.thisInit = false
		} else {
			f.thisInit = true
			if code.strict {
				f.this = this
			} else if this.t == TagUndef || this.t == TagNull {
				f.this = Obj(GlobalObject)
			} else if this.t != TagObj {
				f.this = Obj(toObject(this))
			} else {
				f.this = this
			}
		}
	}
	if code.isGen || code.isAsync {
		return startCoroutineFunction(f, code)
	}
	pushFrame(f, code.cost+len(args)*16)
	code.prologue(f)
	if code.exprBody != nil {
		r := code.exprBody(f)
		popStack()
		return r
	}
	c := code.body(f)
	popStack()
	if c == cReturn {
		r := f.retVal
		if code.derived {
			return derivedCtorResult(f, r)
		}
		return r
	}
	if code.derived {
		return derivedCtorResult(f, Undefined)
	}
	return Undefined
}

func derivedCtorResult(f *Frame, r Value) Value {
	if r.t == TagObj {
		return r
	}
	if r.t != TagUndef {
		throwTypeError("derived class constructor must return an object or undefined")
	}
	if !f.thisInit {
		throwReferenceError("this is not initialized")
	}
	return f.this
}

// ---------- native function creation ----------

func newNativeFunc(name string, length int, fn func(this Value, args []Value) Value) *Object {
	o := &Object{proto: FunctionPrototype, class: ClassNativeFunction, extensible: true}
	o.internal = &NativeFunc{fn: fn, name: name}
	o.addProp(strKey("length"), Int(length), pConfigurable)
	o.addProp(strKey("name"), Str(newStr(name)), pConfigurable)
	return o
}

func newNativeCtor(name string, length int, fn func(this Value, args []Value) Value, ctor func(args []Value, nt *Object) Value) *Object {
	o := newNativeFunc(name, length, fn)
	o.internal.(*NativeFunc).ctor = ctor
	return o
}

func defMethod(o *Object, name string, length int, fn func(this Value, args []Value) Value) *Object {
	f := newNativeFunc(name, length, fn)
	o.setOwn(strKey(name), Obj(f), pWritable|pConfigurable)
	return f
}

func defMethodSym(o *Object, sym *Symbol, name string, length int, fn func(this Value, args []Value) Value) *Object {
	f := newNativeFunc(name, length, fn)
	o.setOwn(PropKey{sym: sym}, Obj(f), pWritable|pConfigurable)
	return f
}

func defGetter(o *Object, name string, fn func(this Value, args []Value) Value) {
	g := newNativeFunc("get "+name, 0, fn)
	o.defineAccessorRaw(strKey(name), g, nil, pConfigurable)
}

func defGetterSym(o *Object, sym *Symbol, name string, fn func(this Value, args []Value) Value) {
	g := newNativeFunc("get "+name, 0, fn)
	o.defineAccessorRaw(PropKey{sym: sym}, g, nil, pConfigurable)
}

func defAccessor(o *Object, name string, get func(this Value, args []Value) Value, set func(this Value, args []Value) Value) {
	var g, s *Object
	if get != nil {
		g = newNativeFunc("get "+name, 0, get)
	}
	if set != nil {
		s = newNativeFunc("set "+name, 1, set)
	}
	o.defineAccessorRaw(strKey(name), g, s, pConfigurable)
}

func defProp(o *Object, name string, v Value) {
	o.setOwn(strKey(name), v, pWritable|pConfigurable)
}

func defConst(o *Object, name string, v Value) {
	o.setOwn(strKey(name), v, 0)
}
