cat > resolve.go <<'EOF'
package main

type progKind int

const (
	pkScript progKind = iota
	pkModule
	pkEvalGlobal
	pkEvalFunc
)

type resolver struct {
	scope      *Scope
	fn         *FuncNode
	evalScopes []*Scope
	kind       progKind
	module     *ModuleRec
}

func (r *resolver) errAt(pos int, msg string) {
	panic(&SyntaxErr{msg: msg, pos: pos})
}

func resolveProgram(prog *Program, kind progKind, parent *Scope, mod *ModuleRec) (err *SyntaxErr) {
	defer func() {
		if x := recover(); x != nil {
			if se, ok := x.(*SyntaxErr); ok {
				err = se
				return
			}
			panic(x)
		}
	}()
	r := &resolver{kind: kind, module: mod}
	f := prog.F
	var top *Scope
	switch kind {
	case pkScript:
		top = newScope(scScript, nil, f)
	case pkModule:
		top = newScope(scModule, nil, f)
	case pkEvalGlobal:
		if f.Strict {
			top = newScope(scFunc, nil, f)
		} else {
			top = newScope(scScript, nil, f)
		}
	case pkEvalFunc:
		top = newScope(scFunc, parent, f)
	}
	f.paramScope = top
	f.bodyScope = top
	r.scope = top
	r.fn = f
	if kind == pkModule {
		for _, st := range prog.Body {
			if imp, ok := st.(*ImportDecl); ok {
				for _, sp := range imp.Specs {
					if top.lookupLocal(sp.Local) != nil {
						r.errAt(imp.pos, "invalid redefinition of lexical identifier")
					}
					b := &Binding{name: sp.Local, kind: bImport, importName: sp.Imported}
					top.add(b)
					sp.b = b
				}
			}
		}
	}
	var lexScope *Scope
	if (kind == pkEvalGlobal && !f.Strict) {
		// lexical declarations of eval code are local
		lexScope = newScope(scBlock, top, f)
		r.declareVars(prog.Body, top)
		r.declareLexical(prog.Body, lexScope, true)
		r.scope = lexScope
	} else {
		r.declareVars(prog.Body, top)
		r.declareLexical(prog.Body, top, true)
	}
	for _, st := range prog.Body {
		r.stmt(st)
	}
	if kind == pkModule {
		for _, b := range top.list {
			b.captured = true
		}
	}
	for _, s := range r.evalScopes {
		markEvalScope(s)
	}
	return nil
}

func markEvalScope(s *Scope) {
	for x := s; x != nil; x = x.parent {
		for _, b := range x.list {
			b.captured = true
		}
	}
}

// ---- declaration collection ----

func boundNames(n Node, out []*Ident) []*Ident {
	switch x := n.(type) {
	case *Ident:
		out = append(out, x)
	case *AssignPat:
		out = boundNames(x.Target, out)
	case *Spread:
		out = boundNames(x.X, out)
	case *ObjPattern:
		for _, p := range x.Props {
			out = boundNames(p.Value, out)
		}
		if x.Rest != nil {
			out = boundNames(x.Rest, out)
		}
	case *ArrPattern:
		for _, e := range x.Elems {
			if e != nil {
				out = boundNames(e, out)
			}
		}
		if x.Rest != nil {
			out = boundNames(x.Rest, out)
		}
	}
	return out
}

// collect var-declared names (recursively, not into functions)
func collectVars(n Node, out []*Ident) []*Ident {
	switch x := n.(type) {
	case *VarDecl:
		if x.Kind == "var" {
			for _, d := range x.Decls {
				out = boundNames(d.Target, out)
			}
		}
	case *BlockStmt:
		for _, s := range x.Body {
			out = collectVars(s, out)
		}
	case *IfStmt:
		out = collectVars(x.Cons, out)
		if x.Alt != nil {
			out = collectVars(x.Alt, out)
		}
	case *ForStmt:
		if x.Init != nil {
			out = collectVars(x.Init, out)
		}
		out = collectVars(x.Body, out)
	case *ForInStmt:
		out = collectVars(x.Left, out)
		out = collectVars(x.Body, out)
	case *WhileStmt:
		out = collectVars(x.Body, out)
	case *DoWhileStmt:
		out = collectVars(x.Body, out)
	case *TryStmt:
		out = collectVars(x.Block, out)
		if x.Handler != nil {
			out = collectVars(x.Handler, out)
		}
		if x.Finalizer != nil {
			out = collectVars(x.Finalizer, out)
		}
	case *SwitchStmt:
		for _, c := range x.Cases {
			for _, s := range c.Body {
				out = collectVars(s, out)
			}
		}
	case *LabeledStmt:
		out = collectVars(x.Body, out)
	case *WithStmt:
		out = collectVars(x.Body, out)
	case *ExportDecl:
		if x.Decl != nil {
			out = collectVars(x.Decl, out)
		}
	}
	return out
}

// annex B: function declarations nested in blocks (sloppy)
func collectAnnexBFuncs(n Node, out []*FuncDecl, top bool) []*FuncDecl {
	switch x := n.(type) {
	case *FuncDecl:
		if !top {
			out = append(out, x)
		}
	case *BlockStmt:
		for _, s := range x.Body {
			out = collectAnnexBFuncs(s, out, false)
		}
	case *IfStmt:
		out = collectAnnexBFuncs(x.Cons, out, false)
		if x.Alt != nil {
			out = collectAnnexBFuncs(x.Alt, out, false)
		}
	case *ForStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *ForInStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *WhileStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *DoWhileStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *TryStmt:
		out = collectAnnexBFuncs(x.Block, out, false)
		if x.Handler != nil {
			out = collectAnnexBFuncs(x.Handler, out, false)
		}
		if x.Finalizer != nil {
			out = collectAnnexBFuncs(x.Finalizer, out, false)
		}
	case *SwitchStmt:
		for _, c := range x.Cases {
			for _, s := range c.Body {
				out = collectAnnexBFuncs(s, out, false)
			}
		}
	case *LabeledStmt:
		out = collectAnnexBFuncs(x.Body, out, top)
	case *WithStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	}
	return out
}

func (r *resolver) declareVars(body []Node, vs *Scope) {
	var ids []*Ident
	for _, s := range body {
		ids = collectVars(s, ids)
	}
	for _, id := range ids {
		if b := vs.lookupLocal(id.Name); b != nil {
			if b.isLexical() {
				r.errAt(id.npos, "invalid redefinition of lexical identifier")
			}
			continue
		}
		vs.add(&Binding{name: id.Name, kind: bVar, pos: id.pos})
	}
	// top-level function declarations: var-like
	for _, s := range body {
		fd := topFuncDecl(s)
		if fd != nil {
			name := fd.F.Name
			if b := vs.lookupLocal(name); b != nil {
				if b.isLexical() {
					r.errAt(fd.F.NamePos, "invalid redefinition of lexical identifier")
				}
				if b.kind == bVar || b.kind == bParam || b.kind == bFunc {
					if b.kind == bVar {
						b.kind = bFunc
					}
					continue
				}
			}
			vs.add(&Binding{name: name, kind: bFunc, pos: fd.pos})
		}
	}
	vs.funcDecls = nil
	for _, s := range body {
		if fd := topFuncDecl(s); fd != nil {
			vs.funcDecls = append(vs.funcDecls, fd)
		}
	}
	// annex B
	if !vs.fn.Strict {
		var fds []*FuncDecl
		for _, s := range body {
			fds = collectAnnexBFuncs(s, fds, true)
		}
		for _, fd := range fds {
			if fd.F.IsAsync || fd.F.IsGen {
				continue
			}
			name := fd.F.Name
			b := vs.lookupLocal(name)
			if b == nil {
				// check no lexical conflict at top-level
				b = &Binding{name: name, kind: bVar, pos: fd.pos}
				vs.add(b)
			} else if b.isLexical() {
				continue
			}
			fd.annexB = b
		}
	}
}

func topFuncDecl(s Node) *FuncDecl {
	switch x := s.(type) {
	case *FuncDecl:
		return x
	case *ExportDecl:
		if fd, ok := x.Decl.(*FuncDecl); ok {
			return fd
		}
	case *LabeledStmt:
		return topFuncDecl(x.Body)
	}
	return nil
}

// declare lexical declarations of a statement list into scope s
func (r *resolver) declareLexical(body []Node, s *Scope, isTop bool) {
	var varIds []*Ident
	if !isTop {
		for _, st := range body {
			varIds = collectVars(st, varIds)
		}
	}
	declare := func(id *Ident, kind BindKind, funcDecl bool) {
		if b := s.lookupLocal(id.Name); b != nil {
			if funcDecl && b.funcDecl && !s.fn.Strict && s.kind != scScript {
				// sloppy: duplicate function declarations in block allowed
				return
			}
			if b.kind == bParam {
				r.errAt(id.npos, "invalid redefinition of parameter name")
			}
			if s.kind == scScript && (b.kind == bVar || b.kind == bFunc) && !b.funcDecl {
				r.errAt(id.npos, "invalid redefinition of global identifier")
			}
			r.errAt(id.npos, "invalid redefinition of lexical identifier")
		}
		for _, v := range varIds {
			if v.Name == id.Name {
				r.errAt(v.npos, "invalid redefinition of lexical identifier")
			}
		}
		b := &Binding{name: id.Name, kind: kind, pos: id.pos, funcDecl: funcDecl}
		if kind == bLet || kind == bConst || kind == bClass {
			b.tdz = true
		}
		s.add(b)
	}
	for _, st := range body {
		if ed, ok := st.(*ExportDecl); ok && ed.Decl != nil {
			st = ed.Decl
		}
		switch x := st.(type) {
		case *VarDecl:
			if x.Kind != "var" {
				kind := bLet
				if x.Kind == "const" {
					kind = bConst
				}
				var ids []*Ident
				for _, d := range x.Decls {
					ids = boundNames(d.Target, ids)
				}
				for _, id := range ids {
					declare(id, kind, false)
				}
			}
		case *ClassDecl:
			declare(&Ident{pos: x.C.NamePos, npos: x.C.NamePos, Name: x.C.Name}, bClass, false)
		case *FuncDecl:
			if !isTop {
				declare(&Ident{pos: x.F.NamePos, npos: x.F.NamePos, Name: x.F.Name}, bFunc, true)
			}
		case *LabeledStmt:
			if fd, ok := x.Body.(*FuncDecl); ok && !isTop {
				declare(&Ident{pos: fd.F.NamePos, npos: fd.F.NamePos, Name: fd.F.Name}, bFunc, true)
			}
		}
	}
	if !isTop {
		for _, st := range body {
			if fd, ok := st.(*FuncDecl); ok {
				s.funcDecls = append(s.funcDecls, fd)
			} else if ls, ok := st.(*LabeledStmt); ok {
				if fd, ok := ls.Body.(*FuncDecl); ok {
					s.funcDecls = append(s.funcDecls, fd)
				}
			}
		}
	}
	if s.kind == scModule {
		// export default expression binding
		for _, st := range body {
			if ed, ok := st.(*ExportDecl); ok && ed.Default != nil {
				b := &Binding{name: "*default*", kind: bConst}
				s.add(b)
				ed.defaultB = b
			}
			if ed, ok := st.(*ExportDecl); ok && ed.Decl != nil {
				if fd, ok := ed.Decl.(*FuncDecl); ok && fd.F.Name == "default" && len(ed.Specs) == 1 && ed.Specs[0].Local == "*default*" {
					b := &Binding{name: "*default*", kind: bFunc}
					s.add(b)
					ed.defaultB = b
				}
			}
		}
	}
}

// ---- resolution ----

func (r *resolver) lookup(name string) (*Binding, []*Binding) {
	var withs []*Binding
	for s := r.scope; s != nil; s = s.parent {
		if s.kind == scWith {
			wb := s.vars["%with"]
			withs = append(withs, wb)
			if wb.scope.fn != r.fn {
				wb.captured = true
			}
			continue
		}
		if b := s.lookupLocal(name); b != nil {
			if b.scope.fn != r.fn {
				b.captured = true
			}
			return b, withs
		}
		if name == "arguments" && s.kind == scFunc && s.fn != nil && s.fn.paramScope == s && isArgumentsFunc(s.fn) {
			b := &Binding{name: "arguments", kind: bArguments}
			s.add(b)
			s.fn.argsB = b
			s.fn.usesArgs = true
			if s.fn != r.fn {
				b.captured = true
			}
			return b, withs
		}
	}
	return nil, withs
}

func isArgumentsFunc(f *FuncNode) bool {
	return !f.IsArrow && f.Kind != FKFieldInit && f.Kind != FKClassStaticBlock && !f.isScript && !f.isModule && !f.isEvalCode
}

func (r *resolver) ref(id *Ident) {
	b, withs := r.lookup(id.Name)
	id.ref = &VarRef{b: b, withs: withs, scope: r.scope}
}

func (r *resolver) withScope(s *Scope, fn func()) {
	save := r.scope
	r.scope = s
	fn()
	r.scope = save
}

func (r *resolver) stmts(list []Node) {
	for _, s := range list {
		r.stmt(s)
	}
}

func (r *resolver) block(b *BlockStmt) {
	s := newScope(scBlock, r.scope, r.fn)
	b.scope = s
	r.declareLexical(b.Body, s, false)
	r.withScope(s, func() { r.stmts(b.Body) })
}

func (r *resolver) stmt(n Node) {
	switch x := n.(type) {
	case *VarDecl:
		for _, d := range x.Decls {
			r.pattern(d.Target)
			if d.Init != nil {
				r.expr(d.Init)
			}
		}
	case *FuncDecl:
		r.function(x.F)
		if x.annexB != nil {
			x.annexBRef = &Ident{pos: x.pos, Name: x.F.Name}
			// resolve the var binding reference from the function's declaring var scope
			x.annexBRef.ref = &VarRef{b: x.annexB, scope: r.scope}
			if x.annexB.scope.fn != r.fn {
				x.annexB.captured = true
			}
		}
	case *ClassDecl:
		r.class(x.C)
	case *ExprStmt:
		r.expr(x.X)
	case *BlockStmt:
		r.block(x)
	case *IfStmt:
		r.expr(x.Test)
		r.stmt(x.Cons)
		if x.Alt != nil {
			r.stmt(x.Alt)
		}
	case *ForStmt:
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		if vd, ok := x.Init.(*VarDecl); ok && vd.Kind != "var" {
			r.declareLexical([]Node{vd}, s, false)
		}
		r.withScope(s, func() {
			if x.Init != nil {
				if _, ok := x.Init.(*VarDecl); ok {
					r.stmt(x.Init)
				} else {
					r.expr(x.Init)
				}
			}
			if x.Test != nil {
				r.expr(x.Test)
			}
			if x.Update != nil {
				r.expr(x.Update)
			}
			r.stmt(x.Body)
		})
	case *ForInStmt:
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		if vd, ok := x.Left.(*VarDecl); ok && vd.Kind != "var" {
			r.declareLexical([]Node{vd}, s, false)
		}
		r.withScope(s, func() {
			r.expr(x.Right)
			if vd, ok := x.Left.(*VarDecl); ok {
				r.stmt(vd)
			} else {
				r.pattern(x.Left)
			}
			r.stmt(x.Body)
		})
	case *WhileStmt:
		r.expr(x.Test)
		r.stmt(x.Body)
	case *DoWhileStmt:
		r.stmt(x.Body)
		r.expr(x.Test)
	case *ReturnStmt:
		if x.X != nil {
			r.expr(x.X)
		}
	case *ThrowStmt:
		r.expr(x.X)
	case *TryStmt:
		r.block(x.Block)
		if x.Handler != nil {
			cs := newScope(scCatch, r.scope, r.fn)
			x.catchScope = cs
			if x.Param != nil {
				ids := boundNames(x.Param, nil)
				for _, id := range ids {
					if cs.lookupLocal(id.Name) != nil {
						r.errAt(id.npos, "invalid redefinition of lexical identifier")
					}
					cs.add(&Binding{name: id.Name, kind: bCatch, pos: id.pos})
				}
				// check handler lexical conflicts
				hs := newScope(scBlock, cs, r.fn)
				x.Handler.scope = hs
				r.declareLexical(x.Handler.Body, hs, false)
				for _, b := range hs.list {
					if cs.lookupLocal(b.name) != nil {
						r.errAt(b.pos, "invalid redefinition of lexical identifier")
					}
				}
				r.withScope(cs, func() {
					r.pattern(x.Param)
				})
				r.withScope(hs, func() { r.stmts(x.Handler.Body) })
			} else {
				r.withScope(cs, func() { r.block(x.Handler) })
			}
		}
		if x.Finalizer != nil {
			r.block(x.Finalizer)
		}
	case *SwitchStmt:
		r.expr(x.Disc)
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		var all []Node
		for _, c := range x.Cases {
			all = append(all, c.Body...)
		}
		r.declareLexical(all, s, false)
		r.withScope(s, func() {
			for _, c := range x.Cases {
				if c.Test != nil {
					r.expr(c.Test)
				}
				r.stmts(c.Body)
			}
		})
	case *LabeledStmt:
		r.stmt(x.Body)
	case *WithStmt:
		r.expr(x.Obj)
		s := newScope(scWith, r.scope, r.fn)
		x.scope = s
		wb := &Binding{name: "%with", kind: bWith}
		s.add(wb)
		x.wb = wb
		r.withScope(s, func() { r.stmt(x.Body) })
	case *EmptyStmt, *DebuggerStmt, *BreakStmt, *ContinueStmt:
	case *ImportDecl:
	case *ExportDecl:
		if x.Decl != nil {
			r.stmt(x.Decl)
		}
		if x.Default != nil {
			r.expr(x.Default)
		}
		if !x.hasFrom {
			for _, sp := range x.Specs {
				if sp.Local == "*default*" {
					continue
				}
				if b := r.scope.lookupLocal(sp.Local); b == nil {
					r.errAt(x.pos, "local export '"+sp.Local+"' not found")
				}
			}
		}
	default:
		r.expr(n)
	}
}

func (r *resolver) pattern(n Node) {
	switch x := n.(type) {
	case *Ident:
		r.ref(x)
	case *AssignPat:
		r.pattern(x.Target)
		r.expr(x.Default)
	case *Spread:
		r.pattern(x.X)
	case *ObjPattern:
		for _, p := range x.Props {
			if p.Computed {
				r.expr(p.Key)
			}
			r.pattern(p.Value)
		}
		if x.Rest != nil {
			r.pattern(x.Rest)
		}
	case *ArrPattern:
		for _, e := range x.Elems {
			if e != nil {
				r.pattern(e)
			}
		}
		if x.Rest != nil {
			r.pattern(x.Rest)
		}
	case *MemberExpr:
		r.expr(x)
	case *ParenExpr:
		r.pattern(x.X)
	default:
		r.expr(n)
	}
}

func (r *resolver) exprs(list []Node) {
	for _, e := range list {
		if e != nil {
			r.expr(e)
		}
	}
}

func (r *resolver) privateRef(name string, pos int) *Ident {
	id := &Ident{pos: pos, Name: name}
	b, _ := r.lookup(name)
	if b == nil {
		r.errAt(pos, "undefined private field '"+name+"'")
	}
	id.ref = &VarRef{b: b, scope: r.scope}
	return id
}

func (r *resolver) expr(n Node) {
	switch x := n.(type) {
	case nil:
	case *Ident:
		r.ref(x)
	case *NumLit, *StrLit, *BigIntLit, *RegExpLit, *BoolLit, *NullLit, *ThisExpr, *SuperExpr, *NewTargetExpr, *ImportMetaExpr:
	case *TemplateLit:
		r.exprs(x.Exprs)
	case *TaggedTemplate:
		r.expr(x.Tag)
		r.exprs(x.Tpl.Exprs)
	case *ArrayLit:
		r.exprs(x.Elems)
	case *ObjectLit:
		for _, p := range x.Props {
			if p.Computed {
				r.expr(p.Key)
			}
			r.expr(p.Value)
			if p.CoverInit != nil {
				r.expr(p.CoverInit)
			}
		}
	case *FuncExpr:
		r.function(x.F)
	case *ArrowFunc:
		r.function(x.F)
	case *ClassExpr:
		r.class(x.C)
	case *UnaryExpr:
		r.expr(x.X)
	case *UpdateExpr:
		r.expr(x.X)
	case *BinaryExpr:
		r.expr(x.L)
		r.expr(x.R)
	case *LogicalExpr:
		r.expr(x.L)
		r.expr(x.R)
	case *AssignExpr:
		r.pattern(x.L)
		r.expr(x.R)
	case *CondExpr:
		r.expr(x.Test)
		r.expr(x.Cons)
		r.expr(x.Alt)
	case *CallExpr:
		r.expr(x.Callee)
		r.exprs(x.Args)
		if x.isEval {
			x.evalScope = r.scope
			r.evalScopes = append(r.evalScopes, r.scope)
			for s := r.scope; s != nil; s = s.parent {
				s.hasEval = true
			}
			r.fn.hasEval = true
			// make sure enclosing function has arguments binding
			save := r.scope
			r.lookup("arguments")
			r.scope = save
			for fn := r.fn; fn != nil; {
				fn.hasEval = true
				break
			}
		}
	case *NewExpr:
		r.expr(x.Callee)
		r.exprs(x.Args)
	case *MemberExpr:
		r.expr(x.Obj)
		if x.Computed {
			r.expr(x.Prop)
		}
		if x.Private {
			x.privRef = r.privateRef(x.Name, x.pos)
		}
	case *OptChain:
		r.expr(x.X)
	case *SeqExpr:
		r.exprs(x.List)
	case *Spread:
		r.expr(x.X)
	case *YieldExpr:
		r.expr(x.X)
	case *AwaitExpr:
		r.expr(x.X)
	case *ImportCall:
		r.expr(x.X)
		r.expr(x.Opt)
	case *PrivateIn:
		x.ref = r.privateRef(x.Name, x.pos)
		r.expr(x.R)
	case *ParenExpr:
		r.expr(x.X)
	case *AssignPat:
		r.pattern(x)
	case *ObjPattern, *ArrPattern:
		r.pattern(x)
	}
}

func (r *resolver) function(f *FuncNode) {
	saveScope, saveFn := r.scope, r.fn
	parent := r.scope
	if f.IsExpr && f.Name != "" {
		ns := newScope(scFuncName, parent, f)
		b := &Binding{name: f.Name, kind: bFuncName}
		ns.add(b)
		f.funcNameB = b
		parent = ns
	}
	ps := newScope(scFunc, parent, f)
	f.paramScope = ps
	f.bodyScope = ps
	r.scope = ps
	r.fn = f
	// params
	var pids []*Ident
	for _, p := range f.Params {
		pids = boundNames(p, pids)
	}
	for _, id := range pids {
		if b := ps.lookupLocal(id.Name); b != nil {
			if !f.SimpleParams || f.Strict || f.IsArrow || f.Kind == FKMethod || f.Kind == FKGetter || f.Kind == FKSetter {
				r.errAt(id.pos, "duplicate argument names not allowed in this context")
			}
			continue
		}
		ps.add(&Binding{name: id.Name, kind: bParam, pos: id.pos})
	}
	for _, id := range pids {
		f.paramNames = append(f.paramNames, id.Name)
	}
	if f.ExprBody == nil {
		r.declareVars(f.Body, ps)
		// lexical top-level
		r.declareLexicalFuncTop(f.Body, ps)
	}
	for _, p := range f.Params {
		r.pattern(p)
		if _, ok := p.(*Ident); !ok {
			f.hasParamExprs = true
		}
	}
	if f.ExprBody != nil {
		r.expr(f.ExprBody)
	} else {
		r.stmts(f.Body)
	}
	r.scope, r.fn = saveScope, saveFn
}

func (r *resolver) declareLexicalFuncTop(body []Node, s *Scope) {
	for _, st := range body {
		switch x := st.(type) {
		case *VarDecl:
			if x.Kind != "var" {
				kind := bLet
				if x.Kind == "const" {
					kind = bConst
				}
				for _, id := range boundNames(x.Decls[0].Target, nil) {
					_ = id
				}
				var ids []*Ident
				for _, d := range x.Decls {
					ids = boundNames(d.Target, ids)
				}
				for _, id := range ids {
					if b := s.lookupLocal(id.Name); b != nil {
						if b.kind == bParam {
							r.errAt(id.npos, "invalid redefinition of parameter name")
						}
						r.errAt(id.npos, "invalid redefinition of lexical identifier")
					}
					s.add(&Binding{name: id.Name, kind: kind, pos: id.pos, tdz: true})
				}
			}
		case *ClassDecl:
			if b := s.lookupLocal(x.C.Name); b != nil {
				if b.kind == bParam {
					r.errAt(x.C.NamePos, "invalid redefinition of parameter name")
				}
				r.errAt(x.C.NamePos, "invalid redefinition of lexical identifier")
			}
			s.add(&Binding{name: x.C.Name, kind: bClass, pos: x.pos, tdz: true})
		}
	}
}

func (r *resolver) class(c *ClassNode) {
	cs := newScope(scClass, r.scope, r.fn)
	c.scope = cs
	if c.Name != "" {
		b := &Binding{name: c.Name, kind: bClassInner, tdz: true}
		cs.add(b)
		c.nameB = b
	}
	// private names
	for _, m := range c.Members {
		if m.Private {
			existing := cs.lookupLocal(m.KeyName)
			if existing != nil {
				// allow get/set pair
				if (m.Kind == "get" && existing.privKind == 3 || m.Kind == "set" && existing.privKind == 2) && existing.privStatic == m.Static {
					existing.privKind = 4
					m.privB = existing
					continue
				}
				r.errAt(m.pos, "private class field is already defined")
			}
			b := &Binding{name: m.KeyName, kind: bPrivate, privStatic: m.Static}
			switch m.Kind {
			case "field":
				b.privKind = 0
			case "method":
				b.privKind = 1
			case "get":
				b.privKind = 2
			case "set":
				b.privKind = 3
			}
			if m.Kind != "field" {
				if m.Static {
					c.hasStaticPrivMethods = true
				} else {
					c.hasPrivMethods = true
				}
			}
			cs.add(b)
			m.privB = b
		}
	}
	if c.hasPrivMethods || c.hasStaticPrivMethods {
		b := &Binding{name: "%brand", kind: bBrand}
		cs.add(b)
		c.brandB = b
	}
	save := r.scope
	r.scope = cs
	if c.Super != nil {
		r.expr(c.Super)
	}
	for _, m := range c.Members {
		if m.Computed {
			r.expr(m.Key)
		}
	}
	if c.Ctor != nil {
		r.function(c.Ctor)
	}
	for _, m := range c.Members {
		if m.Value != nil {
			r.function(m.Value)
		}
	}
	r.scope = save
}
EOF
echo ok"}

actions.command:
cd /workspace && python3 - <<'EOF'
src = open('ast.go').read()
src = src.replace('''	isEval   bool
	tail     bool''', '''	isEval   bool
	evalScope *Scope
	tail     bool''')
open('ast.go','w').write(src)
EOF
cat > resolve.go <<'EOF'
package main

type progKind int

const (
	pkScript progKind = iota
	pkModule
	pkEvalGlobal
	pkEvalFunc
)

type resolver struct {
	scope      *Scope
	fn         *FuncNode
	evalScopes []*Scope
	kind       progKind
	module     *ModuleRec
}

func (r *resolver) errAt(pos int, msg string) {
	panic(&SyntaxErr{msg: msg, pos: pos})
}

func resolveProgram(prog *Program, kind progKind, parent *Scope, mod *ModuleRec) (err *SyntaxErr) {
	defer func() {
		if x := recover(); x != nil {
			if se, ok := x.(*SyntaxErr); ok {
				err = se
				return
			}
			panic(x)
		}
	}()
	r := &resolver{kind: kind, module: mod}
	f := prog.F
	var top *Scope
	switch kind {
	case pkScript:
		top = newScope(scScript, nil, f)
	case pkModule:
		top = newScope(scModule, nil, f)
	case pkEvalGlobal:
		if f.Strict {
			top = newScope(scFunc, nil, f)
		} else {
			top = newScope(scScript, nil, f)
		}
	case pkEvalFunc:
		top = newScope(scFunc, parent, f)
	}
	f.paramScope = top
	f.bodyScope = top
	r.scope = top
	r.fn = f
	if kind == pkModule {
		for _, st := range prog.Body {
			if imp, ok := st.(*ImportDecl); ok {
				for _, sp := range imp.Specs {
					if top.lookupLocal(sp.Local) != nil {
						r.errAt(imp.pos, "invalid redefinition of lexical identifier")
					}
					b := &Binding{name: sp.Local, kind: bImport, importName: sp.Imported}
					top.add(b)
					sp.b = b
				}
			}
		}
	}
	var lexScope *Scope
	if (kind == pkEvalGlobal && !f.Strict) {
		// lexical declarations of eval code are local
		lexScope = newScope(scBlock, top, f)
		r.declareVars(prog.Body, top)
		r.declareLexical(prog.Body, lexScope, true)
		r.scope = lexScope
	} else {
		r.declareVars(prog.Body, top)
		r.declareLexical(prog.Body, top, true)
	}
	for _, st := range prog.Body {
		r.stmt(st)
	}
	if kind == pkModule {
		for _, b := range top.list {
			b.captured = true
		}
	}
	for _, s := range r.evalScopes {
		markEvalScope(s)
	}
	return nil
}

func markEvalScope(s *Scope) {
	for x := s; x != nil; x = x.parent {
		for _, b := range x.list {
			b.captured = true
		}
	}
}

// ---- declaration collection ----

func boundNames(n Node, out []*Ident) []*Ident {
	switch x := n.(type) {
	case *Ident:
		out = append(out, x)
	case *AssignPat:
		out = boundNames(x.Target, out)
	case *Spread:
		out = boundNames(x.X, out)
	case *ObjPattern:
		for _, p := range x.Props {
			out = boundNames(p.Value, out)
		}
		if x.Rest != nil {
			out = boundNames(x.Rest, out)
		}
	case *ArrPattern:
		for _, e := range x.Elems {
			if e != nil {
				out = boundNames(e, out)
			}
		}
		if x.Rest != nil {
			out = boundNames(x.Rest, out)
		}
	}
	return out
}

// collect var-declared names (recursively, not into functions)
func collectVars(n Node, out []*Ident) []*Ident {
	switch x := n.(type) {
	case *VarDecl:
		if x.Kind == "var" {
			for _, d := range x.Decls {
				out = boundNames(d.Target, out)
			}
		}
	case *BlockStmt:
		for _, s := range x.Body {
			out = collectVars(s, out)
		}
	case *IfStmt:
		out = collectVars(x.Cons, out)
		if x.Alt != nil {
			out = collectVars(x.Alt, out)
		}
	case *ForStmt:
		if x.Init != nil {
			out = collectVars(x.Init, out)
		}
		out = collectVars(x.Body, out)
	case *ForInStmt:
		out = collectVars(x.Left, out)
		out = collectVars(x.Body, out)
	case *WhileStmt:
		out = collectVars(x.Body, out)
	case *DoWhileStmt:
		out = collectVars(x.Body, out)
	case *TryStmt:
		out = collectVars(x.Block, out)
		if x.Handler != nil {
			out = collectVars(x.Handler, out)
		}
		if x.Finalizer != nil {
			out = collectVars(x.Finalizer, out)
		}
	case *SwitchStmt:
		for _, c := range x.Cases {
			for _, s := range c.Body {
				out = collectVars(s, out)
			}
		}
	case *LabeledStmt:
		out = collectVars(x.Body, out)
	case *WithStmt:
		out = collectVars(x.Body, out)
	case *ExportDecl:
		if x.Decl != nil {
			out = collectVars(x.Decl, out)
		}
	}
	return out
}

// annex B: function declarations nested in blocks (sloppy)
func collectAnnexBFuncs(n Node, out []*FuncDecl, top bool) []*FuncDecl {
	switch x := n.(type) {
	case *FuncDecl:
		if !top {
			out = append(out, x)
		}
	case *BlockStmt:
		for _, s := range x.Body {
			out = collectAnnexBFuncs(s, out, false)
		}
	case *IfStmt:
		out = collectAnnexBFuncs(x.Cons, out, false)
		if x.Alt != nil {
			out = collectAnnexBFuncs(x.Alt, out, false)
		}
	case *ForStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *ForInStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *WhileStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *DoWhileStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	case *TryStmt:
		out = collectAnnexBFuncs(x.Block, out, false)
		if x.Handler != nil {
			out = collectAnnexBFuncs(x.Handler, out, false)
		}
		if x.Finalizer != nil {
			out = collectAnnexBFuncs(x.Finalizer, out, false)
		}
	case *SwitchStmt:
		for _, c := range x.Cases {
			for _, s := range c.Body {
				out = collectAnnexBFuncs(s, out, false)
			}
		}
	case *LabeledStmt:
		out = collectAnnexBFuncs(x.Body, out, top)
	case *WithStmt:
		out = collectAnnexBFuncs(x.Body, out, false)
	}
	return out
}

func (r *resolver) declareVars(body []Node, vs *Scope) {
	var ids []*Ident
	for _, s := range body {
		ids = collectVars(s, ids)
	}
	for _, id := range ids {
		if b := vs.lookupLocal(id.Name); b != nil {
			if b.isLexical() {
				r.errAt(id.npos, "invalid redefinition of lexical identifier")
			}
			continue
		}
		vs.add(&Binding{name: id.Name, kind: bVar, pos: id.pos})
	}
	// top-level function declarations: var-like
	for _, s := range body {
		fd := topFuncDecl(s)
		if fd != nil {
			name := fd.F.Name
			if b := vs.lookupLocal(name); b != nil {
				if b.isLexical() {
					r.errAt(fd.F.NamePos, "invalid redefinition of lexical identifier")
				}
				if b.kind == bVar || b.kind == bParam || b.kind == bFunc {
					if b.kind == bVar {
						b.kind = bFunc
					}
					continue
				}
			}
			vs.add(&Binding{name: name, kind: bFunc, pos: fd.pos})
		}
	}
	vs.funcDecls = nil
	for _, s := range body {
		if fd := topFuncDecl(s); fd != nil {
			vs.funcDecls = append(vs.funcDecls, fd)
		}
	}
	// annex B
	if !vs.fn.Strict {
		var fds []*FuncDecl
		for _, s := range body {
			fds = collectAnnexBFuncs(s, fds, true)
		}
		for _, fd := range fds {
			if fd.F.IsAsync || fd.F.IsGen {
				continue
			}
			name := fd.F.Name
			b := vs.lookupLocal(name)
			if b == nil {
				// check no lexical conflict at top-level
				b = &Binding{name: name, kind: bVar, pos: fd.pos}
				vs.add(b)
			} else if b.isLexical() {
				continue
			}
			fd.annexB = b
		}
	}
}

func topFuncDecl(s Node) *FuncDecl {
	switch x := s.(type) {
	case *FuncDecl:
		return x
	case *ExportDecl:
		if fd, ok := x.Decl.(*FuncDecl); ok {
			return fd
		}
	case *LabeledStmt:
		return topFuncDecl(x.Body)
	}
	return nil
}

// declare lexical declarations of a statement list into scope s
func (r *resolver) declareLexical(body []Node, s *Scope, isTop bool) {
	var varIds []*Ident
	if !isTop {
		for _, st := range body {
			varIds = collectVars(st, varIds)
		}
	}
	declare := func(id *Ident, kind BindKind, funcDecl bool) {
		if b := s.lookupLocal(id.Name); b != nil {
			if funcDecl && b.funcDecl && !s.fn.Strict && s.kind != scScript {
				// sloppy: duplicate function declarations in block allowed
				return
			}
			if b.kind == bParam {
				r.errAt(id.npos, "invalid redefinition of parameter name")
			}
			if s.kind == scScript && (b.kind == bVar || b.kind == bFunc) && !b.funcDecl {
				r.errAt(id.npos, "invalid redefinition of global identifier")
			}
			r.errAt(id.npos, "invalid redefinition of lexical identifier")
		}
		for _, v := range varIds {
			if v.Name == id.Name {
				r.errAt(v.npos, "invalid redefinition of lexical identifier")
			}
		}
		b := &Binding{name: id.Name, kind: kind, pos: id.pos, funcDecl: funcDecl}
		if kind == bLet || kind == bConst || kind == bClass {
			b.tdz = true
		}
		s.add(b)
	}
	for _, st := range body {
		if ed, ok := st.(*ExportDecl); ok && ed.Decl != nil {
			st = ed.Decl
		}
		switch x := st.(type) {
		case *VarDecl:
			if x.Kind != "var" {
				kind := bLet
				if x.Kind == "const" {
					kind = bConst
				}
				var ids []*Ident
				for _, d := range x.Decls {
					ids = boundNames(d.Target, ids)
				}
				for _, id := range ids {
					declare(id, kind, false)
				}
			}
		case *ClassDecl:
			declare(&Ident{pos: x.C.NamePos, npos: x.C.NamePos, Name: x.C.Name}, bClass, false)
		case *FuncDecl:
			if !isTop {
				declare(&Ident{pos: x.F.NamePos, npos: x.F.NamePos, Name: x.F.Name}, bFunc, true)
			}
		case *LabeledStmt:
			if fd, ok := x.Body.(*FuncDecl); ok && !isTop {
				declare(&Ident{pos: fd.F.NamePos, npos: fd.F.NamePos, Name: fd.F.Name}, bFunc, true)
			}
		}
	}
	if !isTop {
		for _, st := range body {
			if fd, ok := st.(*FuncDecl); ok {
				s.funcDecls = append(s.funcDecls, fd)
			} else if ls, ok := st.(*LabeledStmt); ok {
				if fd, ok := ls.Body.(*FuncDecl); ok {
					s.funcDecls = append(s.funcDecls, fd)
				}
			}
		}
	}
	if s.kind == scModule {
		// export default expression binding
		for _, st := range body {
			if ed, ok := st.(*ExportDecl); ok && ed.Default != nil {
				b := &Binding{name: "*default*", kind: bConst}
				s.add(b)
				ed.defaultB = b
			}
			if ed, ok := st.(*ExportDecl); ok && ed.Decl != nil {
				if fd, ok := ed.Decl.(*FuncDecl); ok && fd.F.Name == "default" && len(ed.Specs) == 1 && ed.Specs[0].Local == "*default*" {
					b := &Binding{name: "*default*", kind: bFunc}
					s.add(b)
					ed.defaultB = b
				}
			}
		}
	}
}

// ---- resolution ----

func (r *resolver) lookup(name string) (*Binding, []*Binding) {
	var withs []*Binding
	for s := r.scope; s != nil; s = s.parent {
		if s.kind == scWith {
			wb := s.vars["%with"]
			withs = append(withs, wb)
			if wb.scope.fn != r.fn {
				wb.captured = true
			}
			continue
		}
		if b := s.lookupLocal(name); b != nil {
			if b.scope.fn != r.fn {
				b.captured = true
			}
			return b, withs
		}
		if name == "arguments" && s.kind == scFunc && s.fn != nil && s.fn.paramScope == s && isArgumentsFunc(s.fn) {
			b := &Binding{name: "arguments", kind: bArguments}
			s.add(b)
			s.fn.argsB = b
			s.fn.usesArgs = true
			if s.fn != r.fn {
				b.captured = true
			}
			return b, withs
		}
	}
	return nil, withs
}

func isArgumentsFunc(f *FuncNode) bool {
	return !f.IsArrow && f.Kind != FKFieldInit && f.Kind != FKClassStaticBlock && !f.isScript && !f.isModule && !f.isEvalCode
}

func (r *resolver) ref(id *Ident) {
	b, withs := r.lookup(id.Name)
	id.ref = &VarRef{b: b, withs: withs, scope: r.scope}
}

func (r *resolver) withScope(s *Scope, fn func()) {
	save := r.scope
	r.scope = s
	fn()
	r.scope = save
}

func (r *resolver) stmts(list []Node) {
	for _, s := range list {
		r.stmt(s)
	}
}

func (r *resolver) block(b *BlockStmt) {
	s := newScope(scBlock, r.scope, r.fn)
	b.scope = s
	r.declareLexical(b.Body, s, false)
	r.withScope(s, func() { r.stmts(b.Body) })
}

func (r *resolver) stmt(n Node) {
	switch x := n.(type) {
	case *VarDecl:
		for _, d := range x.Decls {
			r.pattern(d.Target)
			if d.Init != nil {
				r.expr(d.Init)
			}
		}
	case *FuncDecl:
		r.function(x.F)
		if x.annexB != nil {
			x.annexBRef = &Ident{pos: x.pos, Name: x.F.Name}
			// resolve the var binding reference from the function's declaring var scope
			x.annexBRef.ref = &VarRef{b: x.annexB, scope: r.scope}
			if x.annexB.scope.fn != r.fn {
				x.annexB.captured = true
			}
		}
	case *ClassDecl:
		r.class(x.C)
	case *ExprStmt:
		r.expr(x.X)
	case *BlockStmt:
		r.block(x)
	case *IfStmt:
		r.expr(x.Test)
		r.stmt(x.Cons)
		if x.Alt != nil {
			r.stmt(x.Alt)
		}
	case *ForStmt:
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		if vd, ok := x.Init.(*VarDecl); ok && vd.Kind != "var" {
			r.declareLexical([]Node{vd}, s, false)
		}
		r.withScope(s, func() {
			if x.Init != nil {
				if _, ok := x.Init.(*VarDecl); ok {
					r.stmt(x.Init)
				} else {
					r.expr(x.Init)
				}
			}
			if x.Test != nil {
				r.expr(x.Test)
			}
			if x.Update != nil {
				r.expr(x.Update)
			}
			r.stmt(x.Body)
		})
	case *ForInStmt:
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		if vd, ok := x.Left.(*VarDecl); ok && vd.Kind != "var" {
			r.declareLexical([]Node{vd}, s, false)
		}
		r.withScope(s, func() {
			r.expr(x.Right)
			if vd, ok := x.Left.(*VarDecl); ok {
				r.stmt(vd)
			} else {
				r.pattern(x.Left)
			}
			r.stmt(x.Body)
		})
	case *WhileStmt:
		r.expr(x.Test)
		r.stmt(x.Body)
	case *DoWhileStmt:
		r.stmt(x.Body)
		r.expr(x.Test)
	case *ReturnStmt:
		if x.X != nil {
			r.expr(x.X)
		}
	case *ThrowStmt:
		r.expr(x.X)
	case *TryStmt:
		r.block(x.Block)
		if x.Handler != nil {
			cs := newScope(scCatch, r.scope, r.fn)
			x.catchScope = cs
			if x.Param != nil {
				ids := boundNames(x.Param, nil)
				for _, id := range ids {
					if cs.lookupLocal(id.Name) != nil {
						r.errAt(id.npos, "invalid redefinition of lexical identifier")
					}
					cs.add(&Binding{name: id.Name, kind: bCatch, pos: id.pos})
				}
				// check handler lexical conflicts
				hs := newScope(scBlock, cs, r.fn)
				x.Handler.scope = hs
				r.declareLexical(x.Handler.Body, hs, false)
				for _, b := range hs.list {
					if cs.lookupLocal(b.name) != nil {
						r.errAt(b.pos, "invalid redefinition of lexical identifier")
					}
				}
				r.withScope(cs, func() {
					r.pattern(x.Param)
				})
				r.withScope(hs, func() { r.stmts(x.Handler.Body) })
			} else {
				r.withScope(cs, func() { r.block(x.Handler) })
			}
		}
		if x.Finalizer != nil {
			r.block(x.Finalizer)
		}
	case *SwitchStmt:
		r.expr(x.Disc)
		s := newScope(scBlock, r.scope, r.fn)
		x.scope = s
		var all []Node
		for _, c := range x.Cases {
			all = append(all, c.Body...)
		}
		r.declareLexical(all, s, false)
		r.withScope(s, func() {
			for _, c := range x.Cases {
				if c.Test != nil {
					r.expr(c.Test)
				}
				r.stmts(c.Body)
			}
		})
	case *LabeledStmt:
		r.stmt(x.Body)
	case *WithStmt:
		r.expr(x.Obj)
		s := newScope(scWith, r.scope, r.fn)
		x.scope = s
		wb := &Binding{name: "%with", kind: bWith}
		s.add(wb)
		x.wb = wb
		r.withScope(s, func() { r.stmt(x.Body) })
	case *EmptyStmt, *DebuggerStmt, *BreakStmt, *ContinueStmt:
	case *ImportDecl:
	case *ExportDecl:
		if x.Decl != nil {
			r.stmt(x.Decl)
		}
		if x.Default != nil {
			r.expr(x.Default)
		}
		if !x.hasFrom {
			for _, sp := range x.Specs {
				if sp.Local == "*default*" {
					continue
				}
				if b := r.scope.lookupLocal(sp.Local); b == nil {
					r.errAt(x.pos, "local export '"+sp.Local+"' not found")
				}
			}
		}
	default:
		r.expr(n)
	}
}

func (r *resolver) pattern(n Node) {
	switch x := n.(type) {
	case *Ident:
		r.ref(x)
	case *AssignPat:
		r.pattern(x.Target)
		r.expr(x.Default)
	case *Spread:
		r.pattern(x.X)
	case *ObjPattern:
		for _, p := range x.Props {
			if p.Computed {
				r.expr(p.Key)
			}
			r.pattern(p.Value)
		}
		if x.Rest != nil {
			r.pattern(x.Rest)
		}
	case *ArrPattern:
		for _, e := range x.Elems {
			if e != nil {
				r.pattern(e)
			}
		}
		if x.Rest != nil {
			r.pattern(x.Rest)
		}
	case *MemberExpr:
		r.expr(x)
	case *ParenExpr:
		r.pattern(x.X)
	default:
		r.expr(n)
	}
}

func (r *resolver) exprs(list []Node) {
	for _, e := range list {
		if e != nil {
			r.expr(e)
		}
	}
}

func (r *resolver) privateRef(name string, pos int) *Ident {
	id := &Ident{pos: pos, Name: name}
	b, _ := r.lookup(name)
	if b == nil {
		r.errAt(pos, "undefined private field '"+name+"'")
	}
	id.ref = &VarRef{b: b, scope: r.scope}
	return id
}

func (r *resolver) expr(n Node) {
	switch x := n.(type) {
	case nil:
	case *Ident:
		r.ref(x)
	case *NumLit, *StrLit, *BigIntLit, *RegExpLit, *BoolLit, *NullLit, *ThisExpr, *SuperExpr, *NewTargetExpr, *ImportMetaExpr:
	case *TemplateLit:
		r.exprs(x.Exprs)
	case *TaggedTemplate:
		r.expr(x.Tag)
		r.exprs(x.Tpl.Exprs)
	case *ArrayLit:
		r.exprs(x.Elems)
	case *ObjectLit:
		for _, p := range x.Props {
			if p.Computed {
				r.expr(p.Key)
			}
			r.expr(p.Value)
			if p.CoverInit != nil {
				r.expr(p.CoverInit)
			}
		}
	case *FuncExpr:
		r.function(x.F)
	case *ArrowFunc:
		r.function(x.F)
	case *ClassExpr:
		r.class(x.C)
	case *UnaryExpr:
		r.expr(x.X)
	case *UpdateExpr:
		r.expr(x.X)
	case *BinaryExpr:
		r.expr(x.L)
		r.expr(x.R)
	case *LogicalExpr:
		r.expr(x.L)
		r.expr(x.R)
	case *AssignExpr:
		r.pattern(x.L)
		r.expr(x.R)
	case *CondExpr:
		r.expr(x.Test)
		r.expr(x.Cons)
		r.expr(x.Alt)
	case *CallExpr:
		r.expr(x.Callee)
		r.exprs(x.Args)
		if x.isEval {
			x.evalScope = r.scope
			r.evalScopes = append(r.evalScopes, r.scope)
			for s := r.scope; s != nil; s = s.parent {
				s.hasEval = true
			}
			r.fn.hasEval = true
			// make sure enclosing function has arguments binding
			save := r.scope
			r.lookup("arguments")
			r.scope = save
			for fn := r.fn; fn != nil; {
				fn.hasEval = true
				break
			}
		}
	case *NewExpr:
		r.expr(x.Callee)
		r.exprs(x.Args)
	case *MemberExpr:
		r.expr(x.Obj)
		if x.Computed {
			r.expr(x.Prop)
		}
		if x.Private {
			x.privRef = r.privateRef(x.Name, x.pos)
		}
	case *OptChain:
		r.expr(x.X)
	case *SeqExpr:
		r.exprs(x.List)
	case *Spread:
		r.expr(x.X)
	case *YieldExpr:
		r.expr(x.X)
	case *AwaitExpr:
		r.expr(x.X)
	case *ImportCall:
		r.expr(x.X)
		r.expr(x.Opt)
	case *PrivateIn:
		x.ref = r.privateRef(x.Name, x.pos)
		r.expr(x.R)
	case *ParenExpr:
		r.expr(x.X)
	case *AssignPat:
		r.pattern(x)
	case *ObjPattern, *ArrPattern:
		r.pattern(x)
	}
}

func (r *resolver) function(f *FuncNode) {
	saveScope, saveFn := r.scope, r.fn
	parent := r.scope
	if f.IsExpr && f.Name != "" {
		ns := newScope(scFuncName, parent, f)
		b := &Binding{name: f.Name, kind: bFuncName}
		ns.add(b)
		f.funcNameB = b
		parent = ns
	}
	ps := newScope(scFunc, parent, f)
	f.paramScope = ps
	f.bodyScope = ps
	r.scope = ps
	r.fn = f
	// params
	var pids []*Ident
	for _, p := range f.Params {
		pids = boundNames(p, pids)
	}
	for _, id := range pids {
		if b := ps.lookupLocal(id.Name); b != nil {
			if !f.SimpleParams || f.Strict || f.IsArrow || f.Kind == FKMethod || f.Kind == FKGetter || f.Kind == FKSetter {
				r.errAt(id.pos, "duplicate argument names not allowed in this context")
			}
			continue
		}
		ps.add(&Binding{name: id.Name, kind: bParam, pos: id.pos})
	}
	for _, id := range pids {
		f.paramNames = append(f.paramNames, id.Name)
	}
	if f.ExprBody == nil {
		r.declareVars(f.Body, ps)
		// lexical top-level
		r.declareLexicalFuncTop(f.Body, ps)
	}
	for _, p := range f.Params {
		r.pattern(p)
		if _, ok := p.(*Ident); !ok {
			f.hasParamExprs = true
		}
	}
	if f.ExprBody != nil {
		r.expr(f.ExprBody)
	} else {
		r.stmts(f.Body)
	}
	r.scope, r.fn = saveScope, saveFn
}

func (r *resolver) declareLexicalFuncTop(body []Node, s *Scope) {
	for _, st := range body {
		switch x := st.(type) {
		case *VarDecl:
			if x.Kind != "var" {
				kind := bLet
				if x.Kind == "const" {
					kind = bConst
				}
				for _, id := range boundNames(x.Decls[0].Target, nil) {
					_ = id
				}
				var ids []*Ident
				for _, d := range x.Decls {
					ids = boundNames(d.Target, ids)
				}
				for _, id := range ids {
					if b := s.lookupLocal(id.Name); b != nil {
						if b.kind == bParam {
							r.errAt(id.npos, "invalid redefinition of parameter name")
						}
						r.errAt(id.npos, "invalid redefinition of lexical identifier")
					}
					s.add(&Binding{name: id.Name, kind: kind, pos: id.pos, tdz: true})
				}
			}
		case *ClassDecl:
			if b := s.lookupLocal(x.C.Name); b != nil {
				if b.kind == bParam {
					r.errAt(x.C.NamePos, "invalid redefinition of parameter name")
				}
				r.errAt(x.C.NamePos, "invalid redefinition of lexical identifier")
			}
			s.add(&Binding{name: x.C.Name, kind: bClass, pos: x.pos, tdz: true})
		}
	}
}

func (r *resolver) class(c *ClassNode) {
	cs := newScope(scClass, r.scope, r.fn)
	c.scope = cs
	if c.Name != "" {
		b := &Binding{name: c.Name, kind: bClassInner, tdz: true}
		cs.add(b)
		c.nameB = b
	}
	// private names
	for _, m := range c.Members {
		if m.Private {
			existing := cs.lookupLocal(m.KeyName)
			if existing != nil {
				// allow get/set pair
				if (m.Kind == "get" && existing.privKind == 3 || m.Kind == "set" && existing.privKind == 2) && existing.privStatic == m.Static {
					existing.privKind = 4
					m.privB = existing
					continue
				}
				r.errAt(m.pos, "private class field is already defined")
			}
			b := &Binding{name: m.KeyName, kind: bPrivate, privStatic: m.Static}
			switch m.Kind {
			case "field":
				b.privKind = 0
			case "method":
				b.privKind = 1
			case "get":
				b.privKind = 2
			case "set":
				b.privKind = 3
			}
			if m.Kind != "field" {
				if m.Static {
					c.hasStaticPrivMethods = true
				} else {
					c.hasPrivMethods = true
				}
			}
			cs.add(b)
			m.privB = b
		}
	}
	if c.hasPrivMethods || c.hasStaticPrivMethods {
		b := &Binding{name: "%brand", kind: bBrand}
		cs.add(b)
		c.brandB = b
	}
	save := r.scope
	r.scope = cs
	if c.Super != nil {
		r.expr(c.Super)
	}
	for _, m := range c.Members {
		if m.Computed {
			r.expr(m.Key)
		}
	}
	if c.Ctor != nil {
		r.function(c.Ctor)
	}
	for _, m := range c.Members {
		if m.Value != nil {
			r.function(m.Value)
		}
	}
	r.scope = save
}
EOF
