func opAdd(a, b Value) Value {
	if a.t == TagNum && b.t == TagNum {
		return Num(a.n + b.n)
	}
	if a.t == TagStr && b.t == TagStr {
		return Str(concatStr(a.str(), b.str()))
	}
	a = toPrimitive(a, "")
	b = toPrimitive(b, "")
	if a.t == TagStr || b.t == TagStr {
