	}
	return ordinaryHasInstance(target.obj(), v)
}

func ordinaryHasInstance(c *Object, v Value) bool {
	if !c.isCallable() {
		return false
	}
	if c.class == ClassBoundFunction {
		return opInstanceof(v, Obj(c.internal.(*BoundFunc).target))
	}
	if v.t != TagObj {
		return false
	}
	p := c.Get(strKey("prototype"), Obj(c))
	if p.t != TagObj {
		throwTypeError("operand 'prototype' property is not an object")
	}
	proto := p.obj()
	o := v.obj()
	for {
		o = o.GetPrototypeOf()
		if o == nil {
			return false
		}
		if o == proto {
			return true
		}
	}
}

func opIn(k Value, o Value) bool {
	if o.t != TagObj {
		throwTypeError("invalid 'in' operand")
	}
	return o.obj().HasProperty(toPropertyKey(k))
}

func opNeg(v Value) Value {
	if v.t == TagNum {
		return Num(-v.n)
	}
	n := toNumeric(v)
	if n.t == TagBigInt {
		return BigV(new(big.Int).Neg(n.big()))
	}
	return Num(-n.n)
}

func opBitNot(v Value) Value {
	if v.t == TagNum {
		return Num(float64(^f64ToInt32(v.n)))
	}
	n := toNumeric(v)
	if n.t == TagBigInt {
		return BigV(new(big.Int).Not(n.big()))
	}
	return Num(float64(^f64ToInt32(n.n)))
}

func opInc(v Value, delta float64) Value {
	if v.t == TagNum {
		return Num(v.n + delta)
	}
	if v.t == TagBigInt {
		return BigV(new(big.Int).Add(v.big(), big.NewInt(int64(delta))))
	}
	return Num(toNumber(v) + delta)
}

// ---------- property access helpers ----------

func getMemberNamed(obj Value, k PropKey) Value {
	if obj.t == TagObj {
		return obj.obj().Get(k, obj)
	}
	if obj.t == TagUndef || obj.t == TagNull {
		throwTypeError("cannot read property '%s' of %s", keyDisplay(k), typeOfForError(obj))
	}
	return getV(obj, k)
}

func getMemberComputed(obj Value, key Value) Value {
	if obj.t == TagObj {
		o := obj.obj()
		if key.t == TagNum {
			idx := key.n
			if idx >= 0 && idx < 4294967295 {
				i := uint32(idx)
				if float64(i) == idx {
					if o.fastArr && i < uint32(len(o.arr)) {
						return o.arr[i]
					}
					if isTypedArrayClass(o.class) {
						ta := o.internal.(*TypedArray)
						if int(i) < ta.length() {
							return ta.get(int(i))
						}
						return Undefined
					}
					return o.Get(idxKey(i), obj)
				}
			}
		}
		return o.Get(toPropertyKey(key), obj)
	}
	if obj.t == TagUndef || obj.t == TagNull {
		throwTypeError("cannot read property of %s", typeOfForError(obj))
	}
	if obj.t == TagStr && key.t == TagNum {
		s := obj.str()
		idx := key.n
		if idx >= 0 && idx < float64(s.n) && idx == math.Trunc(idx) {
			i := int(idx)
			return Str(strFromUnit(s.At(i)))
		}
	}
	return getV(obj, toPropertyKey(key))
}

func setMemberNamed(obj Value, k PropKey, v Value, strict bool) {
	if obj.t == TagObj {
		obj.obj().Set(k, v, obj, strict)
		return
	}
	if obj.t == TagUndef || obj.t == TagNull {
		throwTypeError("cannot set property '%s' of %s", keyDisplay(k), typeOfForError(obj))
	}
	proto := protoForPrimitive(obj)
	ok := proto.Set(k, v, obj, false)
	if !ok && strict {
		throwTypeError("cannot create property '%s' on %s", keyDisplay(k), typeOf(obj))
	}
}

func setMemberComputed(obj Value, key Value, v Value, strict bool) {
	if obj.t == TagObj {
		o := obj.obj()
		if key.t == TagNum {
			idx := key.n
			if idx >= 0 && idx < 4294967295 {
				i := uint32(idx)
				if float64(i) == idx {
					if o.fastArr && i < uint32(len(o.arr)) && (o.class == ClassArray || o.class == ClassArguments) {
						o.arr[i] = v
						return
					}
					if isTypedArrayClass(o.class) {
						o.internal.(*TypedArray).setValue(idx, v)
						return
					}
					if o.fastArr && o.class == ClassArray && i == uint32(len(o.arr)) && o.extensible && o.proto == ArrayPrototype && !arrayProtoHasIndex {
						if i >= o.alen {
							if o.lenRO {
								o.Set(idxKey(i), v, obj, strict)
								return
							}
							o.alen = i + 1
						}
						o.arr = append(o.arr, v)
						return
					}
					o.Set(idxKey(i), v, obj, strict)
					return
				}
			}
		}
		o.Set(toPropertyKey(key), v, obj, strict)
		return
	}
	if obj.t == TagUndef || obj.t == TagNull {
		k := toPropertyKey(key)
		throwTypeError("cannot set property '%s' of %s", keyDisplay(k), typeOfForError(obj))
	}
	setMemberNamed(obj, toPropertyKey(key), v, strict)
}

var arrayProtoHasIndex = false

func opDelete(obj Value, key Value, strict bool) bool {
	if obj.t == TagUndef || obj.t == TagNull {
		throwTypeError("cannot convert to object")
	}
	o := toObject(obj)
	k := toPropertyKey(key)
	ok := o.Delete(k, false)
	if !ok && strict {
		throwTypeError("could not delete property")
	}
	return ok
}
