func (c *compiler) allocScope(s *Scope) {
	if s.compiledEnv {
		return
	}
	s.compiledEnv = true
	n := 0
	for _, b := range s.list {
		if s.kind == scScript {
			continue
		}
		if b.captured || s.hasEval {
			b.captured = true
			b.inEnv = true
			b.idx = n
			n++
		} else {
			b.inEnv = false
			b.idx = c.nlocals
			c.nlocals++
		}
	}
	s.envSize = n
	s.needsEnv = n > 0
}

func (c *compiler) envHops(target *Scope) int {
	h := 0
	for s := c.scope; s != target; s = s.parent {
		if s == nil {
			panic("internal: scope not found")
		}
		if s.needsEnv {
			h++
		}
	}
	return h
}

// scope entry/exit code generation
func (c *compiler) scopeEnter(s *Scope) func(f *Frame) {
	c.allocScope(s)
	var tdzLocals []int
	var tdzEnv []int
	for _, b := range s.list {
		if s.kind == scScript {
			continue
		}
		if b.tdz || b.kind == bClassInner {
			if b.inEnv {
				tdzEnv = append(tdzEnv, b.idx)
			} else {
				tdzLocals = append(tdzLocals, b.idx)
			}
		}
	}
	n := s.envSize
	needsEnv := s.needsEnv
	if !needsEnv && len(tdzLocals) == 0 {
		return nil
	}
	return func(f *Frame) {
		if needsEnv {
			e := &Env{vals: make([]Value, n), parent: f.env}
			for _, i := range tdzEnv {
				e.vals[i] = Empty
			}
			f.env = e
		}
		for _, i := range tdzLocals {
			f.locals[i] = Empty
		}
	}
}

// ---------- program compile ----------

func compileProgram(prog *Program, kind progKind, sf *SourceFile, parent *Scope, mod *ModuleRec) (code *FuncCode, err *SyntaxErr) {
	defer func() {
		if x := recover(); x != nil {
			if se, ok := x.(*SyntaxErr); ok {
				err = se
				return
			}
			panic(x)
		}
	}()
	f := prog.F
	code = &FuncCode{node: f, name: "<eval>", strict: f.Strict, src: sf, topLevel: true, module: mod}
	if kind == pkModule {
		code.name = "<anonymous>"
		code.isAsync = moduleHasTLA(prog)
	}
	f.compiled = code
	c := &compiler{fn: f, code: code, sf: sf, strict: f.Strict, module: mod}
	c.isEval = kind == pkEvalGlobal || kind == pkEvalFunc
	c.completion = c.isEval
	top := f.paramScope
	c.scope = top
	var pro []func(f *Frame)
	if kind == pkModule {
		c.allocScope(top)
		mod.scope = top
		n := top.envSize
		pro = append(pro, func(fr *Frame) {
			fr.env = mod.env
			_ = n
		})
	} else {
		enter := c.scopeEnter(top)
		if enter != nil {
			pro = append(pro, enter)
		}
	}
	if top.kind == scScript {
		// global declaration instantiation
		pro = append(pro, c.globalDeclInit(prog, top))
	}
	inner := top
	if kind == pkEvalGlobal && !f.Strict {
		// lexical scope child
		for _, s := range prog.Body {
			_ = s
		}
		inner = findLexChild(prog, top)
	}
	if inner != top && inner != nil {
		c.scope = inner
		if e := c.scopeEnter(inner); e != nil {
			pro = append(pro, e)
		}
	}
	// hoisted functions
	fdecls := top.funcDecls
	if inner != top && inner != nil {
		fdecls = append(fdecls, inner.funcDecls...)
	}
	if hf := c.hoistFuncs(fdecls); hf != nil {
		pro = append(pro, hf)
	}
	if kind == pkModule {
		pro = append(pro, c.moduleInit(prog, top))
	}
	body := c.stmtList(prog.Body)
	code.body = body
	code.nlocals = c.nlocals
	code.prologue = func(fr *Frame) {
		for _, p := range pro {
			p(fr)
		}
	}
	return code, nil
}

func moduleHasTLA(prog *Program) bool {
	return true
}

func findLexChild(prog *Program, top *Scope) *Scope {
	// the lexical scope is created by resolver as child of top; find it via any binding
	return prog.F.lexScope
}

func (c *compiler) globalDeclInit(prog *Program, top *Scope) func(f *Frame) {
	type gv struct {
		name string
		isFunc bool
	}
	var vars []string
	var lex []*Binding
	for _, b := range top.list {
		if b.isLexical() {
			lex = append(lex, b)
		} else if b.kind == bVar {
			vars = append(vars, b.name)
		} else if b.kind == bFunc {
			vars = append(vars, b.name)
		}
	}
	isEval := c.isEval
	return func(f *Frame) {
		for _, b := range lex {
			if _, exists := globalLex[b.name]; exists {
				throwSyntaxError("invalid redefinition of lexical identifier")
			}
		}
		for _, name := range vars {
			k := strKey(name)
			if GlobalObject.findOwn(k) < 0 {
				flags := pWritable | pEnumerable
				if isEval {
					flags |= pConfigurable
				}
				GlobalObject.addProp(k, Undefined, flags)
			}
		}
		for _, b := range lex {
			gb := &GlobalLexBinding{v: Empty, isConst: b.kind == bConst}
			globalLex[b.name] = gb
			globalLexEpoch++
		}
	}
}

type GlobalLexBinding struct {
	v       Value
	isConst bool
}

var globalLex = map[string]*GlobalLexBinding{}
var globalLexEpoch = 0

// ---------- function compile ----------

type ClassDef struct {
	fields   []*fieldDef
	brand    *Symbol
	privMethods []*privMethodDef
}

type fieldDef struct {
	key     PropKey
	priv    *Symbol
	init    *Object
	isAnon  bool
}

type privMethodDef struct {
	sym *Symbol
}

func (c *compiler) compileFunction(fn *FuncNode) *FuncCode {
	if fn.compiled != nil {
		return fn.compiled
	}
	code := &FuncCode{node: fn, name: fn.Name, strict: fn.Strict, kind: fn.Kind, isArrow: fn.IsArrow,
		isAsync: fn.IsAsync, isGen: fn.IsGen, src: fn.src, length: fn.length, module: c.module}
	fn.compiled = code
	switch fn.Kind {
	case FKNormal:
		code.isCtor = !fn.IsAsync && !fn.IsGen
	case FKClassConstructor:
		code.isCtor = true
		code.isClassCtor = true
	case FKDerivedConstructor:
		code.isCtor = true
		code.isClassCtor = true
		code.derived = true
	}
	sub := &compiler{fn: fn, code: code, sf: fn.src, strict: fn.Strict, parent: c, module: c.module}
	var pro []func(f *Frame)
	// function name scope
	if fn.funcNameB != nil {
		ns := fn.funcNameB.scope
		sub.scope = ns.parent
		sub.allocScope(ns)
		sub.scope = ns
		b := fn.funcNameB
		if b.inEnv {
			pro = append(pro, func(f *Frame) {
				f.env = &Env{vals: []Value{Obj(f.fobj)}, parent: f.env}
			})
		} else {
			idx := b.idx
			pro = append(pro, func(f *Frame) {
				f.locals[idx] = Obj(f.fobj)
			})
		}
	} else {
		sub.scope = fn.paramScope.parent
	}
	ps := fn.paramScope
	if enter := sub.scopeEnter(ps); enter != nil {
		pro = append(pro, enter)
	}
	sub.scope = ps
	// arguments object
	if fn.argsB != nil {
		set := sub.bindingInit(fn.argsB)
		mapped := !fn.Strict && fn.SimpleParams
		if mapped && len(fn.Params) > 0 {
			// mapped arguments: map params to arguments
			var paramSlots []*Binding
			for _, p := range fn.Params {
				id := p.(*Ident)
				paramSlots = append(paramSlots, id.ref.b)
			}
			getters := make([]func(f *Frame) Value, len(paramSlots))
			setters := make([]func(f *Frame, v Value), len(paramSlots))
			for i, b := range paramSlots {
				getters[i] = sub.bindingGetRaw(b)
				setters[i] = sub.bindingInit(b)
			}
			pro = append(pro, func(f *Frame) {
				set(f, Obj(newMappedArguments(f, getters, setters)))
			})
		} else {
			pro = append(pro, func(f *Frame) {
				set(f, Obj(newArgumentsObject(f.args, f.fobj, fn.Strict || !fn.SimpleParams)))
			})
		}
	}
	// params
	if pb := sub.compileParams(fn); pb != nil {
		pro = append(pro, pb)
	}
	// hoisted function declarations
	if hf := sub.hoistFuncs(ps.funcDecls); hf != nil {
		pro = append(pro, hf)
	}
	if fn.ExprBody != nil {
		code.exprBody = sub.expr(fn.ExprBody)
		code.body = nil
	} else {
		code.body = sub.stmtList(fn.Body)
	}
	code.nlocals = sub.nlocals
	code.cost = 900 + 16*sub.nlocals
	switch len(pro) {
	case 0:
		code.prologue = func(f *Frame) {}
	case 1:
		code.prologue = pro[0]
	case 2:
		p0, p1 := pro[0], pro[1]
		code.prologue = func(f *Frame) { p0(f); p1(f) }
	default:
		code.prologue = func(f *Frame) {
			for _, p := range pro {
				p(f)
			}
		}
	}
	return code
}

func (c *compiler) compileParams(fn *FuncNode) func(f *Frame) {
	if fn.SimpleParams {
		type pset struct {
			i   int
			set func(f *Frame, v Value)
		}
		var sets []pset
		for i, p := range fn.Params {
			id := p.(*Ident)
			sets = append(sets, pset{i, c.bindingInit(id.ref.b)})
		}
		// duplicate params: last wins (iterate in order so later overrides)
		if len(sets) == 0 {
			return nil
		}
		// fast path for local slots
		allLocal := true
		var idxs []int
		for _, p := range fn.Params {
			b := p.(*Ident).ref.b
			if b.inEnv {
				allLocal = false
			}
			idxs = append(idxs, b.idx)
		}
		if allLocal {
			return func(f *Frame) {
				args := f.args
				for i, idx := range idxs {
					if i < len(args) {
						f.locals[idx] = args[i]
					} else {
						f.locals[idx] = Undefined
					}
				}
			}
		}
		return func(f *Frame) {
			args := f.args
			for _, s := range sets {
				if s.i < len(args) {
					s.set(f, args[s.i])
				} else {
					s.set(f, Undefined)
				}
			}
		}
	}
	type pinit struct {
		rest bool
		bind func(f *Frame, v Value)
	}
	var inits []pinit
	for _, p := range fn.Params {
		if sp, ok := p.(*Spread); ok {
			inits = append(inits, pinit{rest: true, bind: c.bindPattern(sp.X, true)})
			continue
		}
		inits = append(inits, pinit{bind: c.bindPattern(p, true)})
	}
	return func(f *Frame) {
		args := f.args
		for i, pi := range inits {
			if pi.rest {
				var rest []Value
				if i < len(args) {
					rest = make([]Value, len(args)-i)
					copy(rest, args[i:])
				}
				pi.bind(f, Obj(newArray(rest)))
				continue
			}
			v := Undefined
			if i < len(args) {
				v = args[i]
			}
			pi.bind(f, v)
		}
	}
}

func (c *compiler) hoistFuncs(decls []*FuncDecl) func(f *Frame) {
	if len(decls) == 0 {
		return nil
	}
	type hf struct {
		mk  func(f *Frame) Value
		set func(f *Frame, v Value)
		annex func(f *Frame, v Value)
	}
	var list []hf
	for _, fd := range decls {
		b := c.lookupBindingForDecl(fd.F.Name)
		mk := c.funcValue(fd.F, fd.F.Name)
		var set func(f *Frame, v Value)
		if b == nil || b.scope.kind == scScript {
			name := fd.F.Name
			isEval := c.isEval
			set = func(f *Frame, v Value) {
				k := strKey(name)
				i := GlobalObject.findOwn(k)
				if i >= 0 && GlobalObject.props[i].flags&pAccessor == 0 {
					if GlobalObject.props[i].flags&pConfigurable != 0 {
						fl := pWritable | pEnumerable
						if isEval {
							fl |= pConfigurable
						}
						GlobalObject.props[i] = Prop{v: v, flags: fl}
					} else {
						GlobalObject.props[i].v = v
					}
				} else {
					GlobalObject.Set(k, v, Obj(GlobalObject), false)
				}
			}
		} else {
			set = c.bindingInit(b)
		}
		var annex func(f *Frame, v Value)
		if fd.annexB != nil && fd.annexB != b {
			annex = c.refInit(fd.annexBRef)
		}
		list = append(list, hf{mk, set, annex})
	}
	return func(f *Frame) {
		for _, h := range list {
			v := h.mk(f)
			h.set(f, v)
			if h.annex != nil {
				h.annex(f, v)
			}
		}
	}
}

func (c *compiler) lookupBindingForDecl(name string) *Binding {
	for s := c.scope; s != nil; s = s.parent {
		if b := s.lookupLocal(name); b != nil {
			return b
		}
	}
	return nil
}

// ---------- binding access ----------

func (c *compiler) bindingLoc(b *Binding) (inEnv bool, hops int, idx int) {
	if b.inEnv {
		return true, c.envHops(b.scope), b.idx
	}
	return false, 0, b.idx
}

func envAt(f *Frame, hops int) *Env {
	e := f.env
	for ; hops > 0; hops-- {
		e = e.parent
	}
	return e
}

// raw get without TDZ check
func (c *compiler) bindingGetRaw(b *Binding) func(f *Frame) Value {
	if b.scope.kind == scScript {
		return c.globalGet(b.name, false)
	}
	inEnv, hops, idx := c.bindingLoc(b)
	if !inEnv {
		return func(f *Frame) Value { return f.locals[idx] }
	}
	return func(f *Frame) Value { return envAt(f, hops).vals[idx] }
}

func (c *compiler) bindingInit(b *Binding) func(f *Frame, v Value) {
	if b.scope.kind == scScript {
		name := b.name
		if b.isLexical() {
			return func(f *Frame, v Value) {
				globalLex[name].v = v
			}
		}
		return func(f *Frame, v Value) {
			GlobalObject.Set(strKey(name), v, Obj(GlobalObject), false)
		}
	}
	inEnv, hops, idx := c.bindingLoc(b)
	if !inEnv {
		return func(f *Frame, v Value) { f.locals[idx] = v }
	}
	switch hops {
	case 0:
		return func(f *Frame, v Value) { f.env.vals[idx] = v }
	case 1:
		return func(f *Frame, v Value) { f.env.parent.vals[idx] = v }
	}
	return func(f *Frame, v Value) { envAt(f, hops).vals[idx] = v }
}

func throwNotInit(name string) {
	throwReferenceError("%s is not initialized", name)
}

func (c *compiler) refGet(id *Ident) evalFn {
	return c.refGetOpt(id, false)
}

// typeofMode: don't throw for undeclared globals
func (c *compiler) refGetOpt(id *Ident, typeofMode bool) evalFn {
	ref := id.ref
	name := id.Name
	if ref == nil {
		return c.globalGet(name, typeofMode)
	}
	var base evalFn
	b := ref.b
	if b == nil || b.scope.kind == scScript {
		base = c.globalGet(name, typeofMode)
	} else if b.kind == bImport {
		base = c.importGet(b)
	} else {
		inEnv, hops, idx := c.bindingLoc(b)
		tdz := b.tdz || b.kind == bClassInner
		if !inEnv {
			if tdz {
				base = func(f *Frame) Value {
					v := f.locals[idx]
					if v.t == TagEmpty {
						throwNotInit(name)
					}
					return v
				}
			} else {
				base = func(f *Frame) Value { return f.locals[idx] }
			}
		} else {
			switch {
			case hops == 0 && !tdz:
				base = func(f *Frame) Value { return f.env.vals[idx] }
			case hops == 1 && !tdz:
				base = func(f *Frame) Value { return f.env.parent.vals[idx] }
			case hops == 2 && !tdz:
				base = func(f *Frame) Value { return f.env.parent.parent.vals[idx] }
			default:
				base = func(f *Frame) Value {
					v := envAt(f, hops).vals[idx]
					if v.t == TagEmpty {
						throwNotInit(name)
					}
					return v
				}
			}
		}
	}
	if len(ref.withs) > 0 {
		return c.withGet(id, base)
	}
	return base
}

func (c *compiler) withObjGetters(ref *VarRef) []func(f *Frame) Value {
	var gs []func(f *Frame) Value
	for _, wb := range ref.withs {
		inEnv, hops, idx := c.bindingLocFrom(wb, ref.scope)
		if inEnv {
			gs = append(gs, func(f *Frame) Value { return envAt(f, hops).vals[idx] })
		} else {
			gs = append(gs, func(f *Frame) Value { return f.locals[idx] })
		}
	}
	return gs
}

func (c *compiler) bindingLocFrom(b *Binding, from *Scope) (bool, int, int) {
	return c.bindingLoc(b)
}

func withHas(o *Object, k PropKey) bool {
	if !o.HasProperty(k) {
		return false
	}
	u := o.Get(PropKey{sym: SymUnscopables}, Obj(o))
	if u.t == TagObj {
		if toBool(u.obj().Get(k, u)) {
			return false
		}
	}
	return true
}

func (c *compiler) withGet(id *Ident, base evalFn) evalFn {
	gs := c.withObjGetters(id.ref)
	k := strKey(id.Name)
	return func(f *Frame) Value {
		for _, g := range gs {
			ov := g(f)
			if ov.t == TagObj && withHas(ov.obj(), k) {
				return ov.obj().Get(k, ov)
			}
		}
		return base(f)
	}
}

// returns the with-object for a call (this value) or undefined
func (c *compiler) withBase(id *Ident) func(f *Frame) Value {
	if id.ref == nil || len(id.ref.withs) == 0 {
		return nil
	}
	gs := c.withObjGetters(id.ref)
	k := strKey(id.Name)
	return func(f *Frame) Value {
		for _, g := range gs {
			ov := g(f)
			if ov.t == TagObj && withHas(ov.obj(), k) {
				return ov
			}
		}
		return Undefined
	}
}

func (c *compiler) globalGet(name string, typeofMode bool) evalFn {
	k := strKey(name)
	var lexB *GlobalLexBinding
	cache := -1
	epoch := -1
	return func(f *Frame) Value {
		if lexB != nil {
			v := lexB.v
			if v.t == TagEmpty {
				throwNotInit(name)
			}
			return v
		}
		g := GlobalObject
		if epoch == globalLexEpoch && cache >= 0 && cache < len(g.keys) {
			if g.keys[cache].s == name && g.keys[cache].sym == nil && g.props[cache].flags&(pAccessor|pDeleted) == 0 {
				return g.props[cache].v
			}
		}
		if gb, ok := globalLex[name]; ok {
			lexB = gb
			v := gb.v
			if v.t == TagEmpty {
				throwNotInit(name)
			}
			return v
		}
		epoch = globalLexEpoch
		i := g.findOwn(k)
		if i >= 0 {
			cache = i
			p := &g.props[i]
			if p.flags&pAccessor != 0 {
				return g.Get(k, Obj(g))
			}
			return p.v
		}
		if g.proto != nil && g.proto.HasProperty(k) {
			return g.Get(k, Obj(g))
		}
		if typeofMode {
			return Undefined
		}
		throwReferenceError("'%s' is not defined", name)
		return Undefined
	}
}

func (c *compiler) globalSet(name string, strict bool) func(f *Frame, v Value) {
	k := strKey(name)
	var lexB *GlobalLexBinding
	cache := -1
	epoch := -1
	return func(f *Frame, v Value) {
		if lexB != nil {
			if lexB.v.t == TagEmpty {
				throwNotInit(name)
			}
			if lexB.isConst {
				throwTypeError("'%s' is read-only", name)
			}
			lexB.v = v
			return
		}
		g := GlobalObject
		if epoch == globalLexEpoch && cache >= 0 && cache < len(g.keys) {
			if g.keys[cache].s == name && g.keys[cache].sym == nil && g.props[cache].flags&(pAccessor|pDeleted|pWritable) == pWritable {
				g.props[cache].v = v
				return
			}
		}
		if gb, ok := globalLex[name]; ok {
			lexB = gb
			if gb.v.t == TagEmpty {
				throwNotInit(name)
			}
			if gb.isConst {
				throwTypeError("'%s' is read-only", name)
			}
			gb.v = v
			return
		}
		epoch = globalLexEpoch
		i := g.findOwn(k)
		if i >= 0 {
			cache = i
			g.Set(k, v, Obj(g), strict)
			return
		}
		if strict && !g.HasProperty(k) {
			throwReferenceError("'%s' is not defined", name)
		}
		g.Set(k, v, Obj(g), strict)
	}
}

// assignment to identifier (not declaration)
func (c *compiler) refSet(id *Ident) func(f *Frame, v Value) {
	ref := id.ref
	name := id.Name
	var base func(f *Frame, v Value)
	if ref == nil || ref.b == nil || ref.b.scope.kind == scScript {
		base = c.globalSet(name, c.strict)
	} else {
		b := ref.b
		switch b.kind {
		case bConst, bClassInner, bImport:
			get := c.refGetNoWith(id)
			base = func(f *Frame, v Value) {
				get(f) // TDZ check
				throwTypeError("'%s' is read-only", name)
			}
		case bFuncName:
			if c.strict {
				base = func(f *Frame, v Value) { throwTypeError("'%s' is read-only", name) }
			} else {
				base = func(f *Frame, v Value) {}
			}
		default:
			inEnv, hops, idx := c.bindingLoc(b)
			tdz := b.tdz
			if !inEnv {
				if tdz {
					base = func(f *Frame, v Value) {
						if f.locals[idx].t == TagEmpty {
							throwNotInit(name)
						}
						f.locals[idx] = v
					}
				} else {
					base = func(f *Frame, v Value) { f.locals[idx] = v }
				}
			} else {
				if tdz {
					base = func(f *Frame, v Value) {
						e := envAt(f, hops)
						if e.vals[idx].t == TagEmpty {
							throwNotInit(name)
						}
						e.vals[idx] = v
					}
				} else if hops == 0 {
					base = func(f *Frame, v Value) { f.env.vals[idx] = v }
				} else {
					base = func(f *Frame, v Value) { envAt(f, hops).vals[idx] = v }
				}
			}
		}
	}
	if ref != nil && len(ref.withs) > 0 {
		gs := c.withObjGetters(ref)
		k := strKey(name)
		strict := c.strict
		return func(f *Frame, v Value) {
			for _, g := range gs {
				ov := g(f)
				if ov.t == TagObj && withHas(ov.obj(), k) {
					ov.obj().Set(k, v, ov, strict)
					return
				}
			}
			base(f, v)
		}
	}
	return base
}

func (c *compiler) refGetNoWith(id *Ident) evalFn {
	saved := id.ref.withs
	id.ref.withs = nil
	g := c.refGet(id)
	id.ref.withs = saved
	return g
}

// initialization of a declared binding (let/const/var declarations)
func (c *compiler) refInit(id *Ident) func(f *Frame, v Value) {
	ref := id.ref
	if ref == nil || ref.b == nil {
		return c.globalSet(id.Name, false)
	}
	b := ref.b
	if b.scope.kind == scScript {
		name := b.name
		if b.isLexical() {
			return func(f *Frame, v Value) {
				globalLex[name].v = v
			}
		}
		// var at global: assignment semantics (through with)
		if len(ref.withs) > 0 {
			return c.refSet(id)
		}
		k := strKey(name)
		return func(f *Frame, v Value) {
			GlobalObject.Set(k, v, Obj(GlobalObject), false)
		}
	}
	if b.kind == bVar && len(ref.withs) > 0 {
		return c.refSet(id)
	}
	return c.bindingInit(b)
}

func (c *compiler) importGet(b *Binding) evalFn {
	mod := c.module
	name := b.name
	return func(f *Frame) Value {
		cell := mod.importCells[b]
		if cell == nil {
			throwReferenceError("%s is not initialized", name)
		}
		if cell.ns != nil {
			return Obj(cell.ns)
		}
		v := cell.env.vals[cell.idx]
		if v.t == TagEmpty {
			throwNotInit(name)
		}
		return v
	}
}

// ---------- statements ----------

func (c *compiler) stmtList(list []Node) stmtFn {
	var fns []stmtFn
	for _, s := range list {
		if fn := c.stmt(s); fn != nil {
			fns = append(fns, fn)
		}
	}
	switch len(fns) {
	case 0:
		return func(f *Frame) ctrl { return cNormal }
	case 1:
		return fns[0]
	case 2:
		a, b := fns[0], fns[1]
		return func(f *Frame) ctrl {
			if r := a(f); r != cNormal {
				return r
			}
			return b(f)
		}
	}
	return func(f *Frame) ctrl {
		for _, s := range fns {
			if r := s(f); r != cNormal {
				return r
			}
		}
		return cNormal
	}
}

func (c *compiler) withScopeC(s *Scope, fn func()) {
	save := c.scope
	c.scope = s
	fn()
	c.scope = save
}

func (c *compiler) blockBody(s *Scope, body []Node) stmtFn {
	var enter func(f *Frame)
	var inner stmtFn
	var hoist func(f *Frame)
	save := c.scope
	enter = c.scopeEnter(s)
	c.scope = s
	hoist = c.hoistFuncs(s.funcDecls)
	inner = c.stmtList(body)
	c.scope = save
	needsEnv := s.needsEnv
	if enter == nil && hoist == nil {
		return inner
	}
	return func(f *Frame) ctrl {
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		if hoist != nil {
			hoist(f)
		}
		r := inner(f)
		if needsEnv {
			f.env = saveEnv
		}
		return r
	}
}

func (c *compiler) setPos(pos int) {}

func (c *compiler) stmt(n Node) stmtFn {
	switch x := n.(type) {
	case *EmptyStmt, *DebuggerStmt:
		return nil
	case *ExprStmt:
		e := c.expr(x.X)
		if c.completion {
			return func(f *Frame) ctrl {
				f.retVal = e(f)
				return cNormal
			}
		}
		return func(f *Frame) ctrl {
			e(f)
			return cNormal
		}
	case *VarDecl:
		return c.varDecl(x)
	case *FuncDecl:
		return nil // hoisted
	case *ClassDecl:
		mk := c.classValue(x.C, x.C.Name)
		set := c.declInitByName(x.C.Name)
		return func(f *Frame) ctrl {
			set(f, mk(f))
			return cNormal
		}
	case *BlockStmt:
		return c.blockBody(x.scope, x.Body)
	case *IfStmt:
		test := c.cond(x.Test)
		cons := c.stmtOrNop(x.Cons)
		if x.Alt == nil {
			if c.completion {
				return func(f *Frame) ctrl {
					if test(f) {
						return cons(f)
					}
					return cNormal
				}
			}
			return func(f *Frame) ctrl {
				if test(f) {
					return cons(f)
				}
				return cNormal
			}
		}
		alt := c.stmtOrNop(x.Alt)
		return func(f *Frame) ctrl {
			if test(f) {
				return cons(f)
			}
			return alt(f)
		}
	case *ReturnStmt:
		if x.X == nil {
			return func(f *Frame) ctrl {
				f.retVal = Undefined
				return cReturn
			}
		}
		e := c.expr(x.X)
		if c.fn.IsAsync && !c.fn.IsGen {
			return func(f *Frame) ctrl {
				f.retVal = e(f)
				return cReturn
			}
		}
		if c.fn.IsAsync && c.fn.IsGen {
			return func(f *Frame) ctrl {
				v := e(f)
				f.retVal = awaitValue(f, v)
				return cReturn
			}
		}
		return func(f *Frame) ctrl {
			f.retVal = e(f)
			return cReturn
		}
	case *ThrowStmt:
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) ctrl {
			v := e(f)
			f.pos = pos
			throwValue(v)
			return cNormal
		}
	case *WhileStmt:
		return c.whileStmt(x)
	case *DoWhileStmt:
		return c.doWhileStmt(x)
	case *ForStmt:
		return c.forStmt(x)
	case *ForInStmt:
		if x.Of {
			return c.forOfStmt(x)
		}
		return c.forInStmt(x)
	case *BreakStmt:
		label := x.Label
		return func(f *Frame) ctrl {
			f.label = label
			return cBreak
		}
	case *ContinueStmt:
		label := x.Label
		return func(f *Frame) ctrl {
			f.label = label
			return cContinue
		}
	case *LabeledStmt:
		body := c.stmtOrNop(x.Body)
		label := x.Label
		switch x.Body.(type) {
		case *ForStmt, *ForInStmt, *WhileStmt, *DoWhileStmt:
			// loops handle their own labels
			return func(f *Frame) ctrl {
				r := body(f)
				if r == cBreak && f.label == label {
					return cNormal
				}
				return r
			}
		}
		return func(f *Frame) ctrl {
			r := body(f)
			if r == cBreak && f.label == label {
				return cNormal
			}
			return r
		}
	case *TryStmt:
		return c.tryStmt(x)
	case *SwitchStmt:
		return c.switchStmt(x)
	case *WithStmt:
		return c.withStmt(x)
	case *ImportDecl:
		return nil
	case *ExportDecl:
		return c.exportDecl(x)
	}
	panic("unknown statement")
}

func (c *compiler) stmtOrNop(n Node) stmtFn {
	s := c.stmt(n)
	if s == nil {
		return func(f *Frame) ctrl { return cNormal }
	}
	return s
}

func (c *compiler) declInitByName(name string) func(f *Frame, v Value) {
	b := c.lookupBindingForDecl(name)
	if b == nil {
		return c.globalSet(name, false)
	}
	return c.bindingInit(b)
}

func (c *compiler) varDecl(x *VarDecl) stmtFn {
	var fns []func(f *Frame)
	for _, d := range x.Decls {
		d := d
		if d.Init == nil {
			if x.Kind == "var" {
				continue
			}
			// let x; => initialize to undefined
			set := c.bindPattern(d.Target, true)
			fns = append(fns, func(f *Frame) { set(f, Undefined) })
			continue
		}
		var init evalFn
		if id, ok := d.Target.(*Ident); ok {
			init = c.exprNamed(d.Init, id.Name)
		} else {
			init = c.expr(d.Init)
		}
		var set func(f *Frame, v Value)
		if x.Kind == "var" {
			set = c.bindPattern(d.Target, false)
			if id, ok := d.Target.(*Ident); ok {
				set = c.refInit(id)
			}
		} else {
			set = c.bindPattern(d.Target, true)
		}
		fns = append(fns, func(f *Frame) { set(f, init(f)) })
	}
	if len(fns) == 0 {
		return nil
	}
	if len(fns) == 1 {
		fn := fns[0]
		return func(f *Frame) ctrl {
			fn(f)
			return cNormal
		}
	}
	return func(f *Frame) ctrl {
		for _, fn := range fns {
			fn(f)
		}
		return cNormal
	}
}

func loopLabelMatch(f *Frame, labels []string) bool {
	if f.label == "" {
		return true
	}
	for _, l := range labels {
		if l == f.label {
			return true
		}
	}
	return false
}

func (c *compiler) whileStmt(x *WhileStmt) stmtFn {
	test := c.cond(x.Test)
	body := c.stmtOrNop(x.Body)
	labels := x.labels
	return func(f *Frame) ctrl {
		for test(f) {
			r := body(f)
			if r != cNormal {
				if r == cBreak && loopLabelMatch(f, labels) {
					f.label = ""
					break
				}
				if r == cContinue && loopLabelMatch(f, labels) {
					f.label = ""
					continue
				}
				return r
			}
		}
		return cNormal
	}
}

func (c *compiler) doWhileStmt(x *DoWhileStmt) stmtFn {
	test := c.cond(x.Test)
	body := c.stmtOrNop(x.Body)
	labels := x.labels
	return func(f *Frame) ctrl {
		for {
			r := body(f)
			if r != cNormal {
				if r == cBreak && loopLabelMatch(f, labels) {
					f.label = ""
					break
				}
				if r == cContinue && loopLabelMatch(f, labels) {
					f.label = ""
				} else {
					return r
				}
			}
			if !test(f) {
				break
			}
		}
		return cNormal
	}
}

func (c *compiler) forStmt(x *ForStmt) stmtFn {
	s := x.scope
	save := c.scope
	enter := c.scopeEnter(s)
	c.scope = s
	var init stmtFn
	if x.Init != nil {
		if vd, ok := x.Init.(*VarDecl); ok {
			init = c.varDecl(vd)
		} else {
			e := c.expr(x.Init)
			init = func(f *Frame) ctrl { e(f); return cNormal }
		}
	}
	var test func(f *Frame) bool
	if x.Test != nil {
		test = c.cond(x.Test)
	}
	var update evalFn
	if x.Update != nil {
		update = c.expr(x.Update)
	}
	body := c.stmtOrNop(x.Body)
	c.scope = save
	labels := x.labels
	perIter := s.needsEnv
	n := s.envSize
	return func(f *Frame) ctrl {
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		if init != nil {
			init(f)
		}
		for {
			if test != nil && !test(f) {
				break
			}
			r := body(f)
			if r != cNormal {
				if r == cBreak && loopLabelMatch(f, labels) {
					f.label = ""
					break
				}
				if r == cContinue && loopLabelMatch(f, labels) {
					f.label = ""
				} else {
					f.env = saveEnv
					return r
				}
			}
			if perIter {
				ne := &Env{vals: make([]Value, n), parent: f.env.parent}
				copy(ne.vals, f.env.vals)
				f.env = ne
			}
			if update != nil {
				update(f)
			}
		}
		f.env = saveEnv
		return cNormal
	}
}

func (c *compiler) forInOfTarget(x *ForInStmt) (enterIter func(f *Frame), bind func(f *Frame, v Value)) {
	s := x.scope
	if vd, ok := x.Left.(*VarDecl); ok {
		target := vd.Decls[0].Target
		if vd.Kind == "var" {
			if id, ok := target.(*Ident); ok {
				bind = c.refInit(id)
			} else {
				bind = c.bindPattern(target, false)
			}
		} else {
			bind = c.bindPattern(target, true)
		}
	} else {
		bind = c.assignPattern(x.Left)
	}
	if s.needsEnv {
		n := s.envSize
		enterIter = func(f *Frame) {
			f.env = &Env{vals: make([]Value, n), parent: f.env}
		}
	}
	return
}

func (c *compiler) forInStmt(x *ForInStmt) stmtFn {
	s := x.scope
	save := c.scope
	enter := c.scopeEnter(s)
	c.scope = s
	right := c.expr(x.Right)
	var initExpr evalFn
	var initSet func(f *Frame, v Value)
	if vd, ok := x.Left.(*VarDecl); ok && vd.Decls[0].Init != nil {
		if id, ok := vd.Decls[0].Target.(*Ident); ok {
			initExpr = c.exprNamed(vd.Decls[0].Init, id.Name)
			initSet = c.refInit(id)
		}
	}
	enterIter, bind := c.forInOfTarget(x)
	body := c.stmtOrNop(x.Body)
	c.scope = save
	labels := x.labels
	return func(f *Frame) ctrl {
		saveEnv := f.env
		if initExpr != nil {
			initSet(f, initExpr(f))
		}
		if enter != nil {
			enter(f)
		}
		obj := right(f)
		f.env = saveEnv
		if obj.IsNullish() {
			return cNormal
		}
		it := newForInIterator(toObject(obj))
		for {
			k, ok := it.next()
			if !ok {
				break
			}
			if enterIter != nil {
				enterIter(f)
			}
			bind(f, k)
			r := body(f)
			f.env = saveEnv
			if r != cNormal {
				if r == cBreak && loopLabelMatch(f, labels) {
					f.label = ""
					break
				}
				if r == cContinue && loopLabelMatch(f, labels) {
					f.label = ""
					continue
				}
				return r
			}
		}
		return cNormal
	}
}

func (c *compiler) forOfStmt(x *ForInStmt) stmtFn {
	s := x.scope
	save := c.scope
	enter := c.scopeEnter(s)
	c.scope = s
	right := c.expr(x.Right)
	enterIter, bind := c.forInOfTarget(x)
	body := c.stmtOrNop(x.Body)
	c.scope = save
	labels := x.labels
	isAwait := x.Await
	pos := nodePos(x.Right)
	return func(f *Frame) (result ctrl) {
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		obj := right(f)
		f.env = saveEnv
		f.pos = pos
		var it *IteratorRecord
		if isAwait {
			it = getAsyncIterator(obj)
		} else {
			// fast path for arrays with default iterator
			if obj.t == TagObj && obj.obj().fastArr && obj.obj().class == ClassArray && arrayIteratorPristine(obj.obj()) {
				return forOfFastArray(f, obj.obj(), enterIter, bind, body, labels, saveEnv)
			}
			it = getIterator(obj)
		}
		done := false
		defer func() {
			if !done {
				if r := recover(); r != nil {
					f.env = saveEnv
					if _, ok := r.(*JSThrow); ok {
						// iterator close on throw (errors from return are suppressed)
						iteratorCloseOnThrow(f, it, isAwait)
					} else {
						iteratorCloseOnThrow(f, it, isAwait)
					}
					panic(r)
				}
			}
		}()
		for {
			var v Value
			var ok bool
			if isAwait {
				v, ok = asyncIteratorStep(f, it)
			} else {
				v, ok = it.step()
			}
			if !ok {
				break
			}
			if enterIter != nil {
				enterIter(f)
			}
			bind(f, v)
			r := body(f)
			f.env = saveEnv
			if r != cNormal {
				if r == cContinue && loopLabelMatch(f, labels) {
					f.label = ""
					continue
				}
				done = true
				if isAwait {
					asyncIteratorClose(f, it)
				} else {
					it.close()
				}
				if r == cBreak && loopLabelMatch(f, labels) {
					f.label = ""
					return cNormal
				}
				return r
			}
		}
		done = true
		return cNormal
	}
}

func forOfFastArray(f *Frame, arr *Object, enterIter func(f *Frame), bind func(f *Frame, v Value), body stmtFn, labels []string, saveEnv *Env) ctrl {
	for i := 0; ; i++ {
		var v Value
		if arr.fastArr {
			if i >= len(arr.arr) {
				if uint32(i) >= arr.alen {
					break
				}
				v = arr.GetIdx(uint32(i))
			} else {
				v = arr.arr[i]
			}
		} else {
			if int64(i) >= lengthOfArrayLike(arr) {
				break
			}
			v = arr.GetIdx(uint32(i))
		}
		if enterIter != nil {
			enterIter(f)
		}
		bind(f, v)
		r := body(f)
		f.env = saveEnv
		if r != cNormal {
			if r == cBreak && loopLabelMatch(f, labels) {
				f.label = ""
				break
			}
			if r == cContinue && loopLabelMatch(f, labels) {
				f.label = ""
				continue
			}
			return r
		}
	}
	return cNormal
}

// run fn catching JS throws
func runProtected(f *Frame, fn stmtFn) (r ctrl, thrown interface{}) {
	defer func() {
		if x := recover(); x != nil {
			thrown = x
		}
	}()
	r = fn(f)
	return
}

func (c *compiler) tryStmt(x *TryStmt) stmtFn {
	block := c.stmtOrNop(x.Block)
	var handler stmtFn
	var bindParam func(f *Frame, v Value)
	var catchEnter func(f *Frame)
	catchNeedsEnv := false
	if x.Handler != nil {
		cs := x.catchScope
		save := c.scope
		catchEnter = c.scopeEnter(cs)
		catchNeedsEnv = cs.needsEnv
		c.scope = cs
		if x.Param != nil {
			bindParam = c.bindPattern(x.Param, true)
			handler = c.blockBody(x.Handler.scope, x.Handler.Body)
		} else {
			handler = c.stmtOrNop(x.Handler)
		}
		c.scope = save
	}
	var finalizer stmtFn
	if x.Finalizer != nil {
		finalizer = c.stmtOrNop(x.Finalizer)
	}
	_ = catchNeedsEnv
	return func(f *Frame) ctrl {
		saveEnv := f.env
		stackIdx := len(callStack)
		if f.stackIdx >= 0 && f.stackIdx < len(callStack) && callStack[f.stackIdx].frame == f {
			stackIdx = f.stackIdx + 1
		}
		r, thrown := runProtected(f, block)
		if thrown != nil {
			if t, ok := thrown.(*JSThrow); ok && handler != nil {
				truncateStack(stackIdx)
				f.env = saveEnv
				r, thrown = runProtected(f, func(f *Frame) ctrl {
					if catchEnter != nil {
						catchEnter(f)
					}
					if bindParam != nil {
						bindParam(f, t.v)
					}
					return handler(f)
				})
				f.env = saveEnv
			}
		}
		if finalizer != nil {
			if thrown != nil {
				if _, ok := thrown.(*JSThrow); ok {
					truncateStack(stackIdx)
				} else if _, ok := thrown.(*genReturnSignal); !ok {
					panic(thrown)
				}
			}
			f.env = saveEnv
			saveRet := f.retVal
			saveLabel := f.label
			fr := finalizer(f)
			if fr != cNormal {
				return fr
			}
			f.retVal = saveRet
			f.label = saveLabel
		}
		if thrown != nil {
			panic(thrown)
		}
		return r
	}
}

func (c *compiler) switchStmt(x *SwitchStmt) stmtFn {
	disc := c.expr(x.Disc)
	s := x.scope
	save := c.scope
	enter := c.scopeEnter(s)
	c.scope = s
	hoist := c.hoistFuncs(s.funcDecls)
	type cs struct {
		test evalFn
		body stmtFn
	}
	var cases []cs
	defIdx := -1
	for i, cc := range x.Cases {
		var t evalFn
		if cc.Test != nil {
			t = c.expr(cc.Test)
		} else {
			defIdx = i
		}
		cases = append(cases, cs{t, c.stmtList(cc.Body)})
	}
	c.scope = save
	labels := x.labels
	return func(f *Frame) ctrl {
		v := disc(f)
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		if hoist != nil {
			hoist(f)
		}
		start := -1
		for i, cc := range cases {
			if cc.test == nil {
				continue
			}
			if strictEquals(v, cc.test(f)) {
				start = i
				break
			}
		}
		if start < 0 {
			start = defIdx
		}
		if start >= 0 {
			for i := start; i < len(cases); i++ {
				r := cases[i].body(f)
				if r != cNormal {
					f.env = saveEnv
					if r == cBreak && (f.label == "" || containsStr(labels, f.label)) {
						f.label = ""
						return cNormal
					}
					return r
				}
			}
		}
		f.env = saveEnv
		return cNormal
	}
}

func containsStr(l []string, s string) bool {
	for _, x := range l {
		if x == s {
			return true
		}
	}
	return false
}

func (c *compiler) withStmt(x *WithStmt) stmtFn {
	obj := c.expr(x.Obj)
	s := x.scope
	save := c.scope
	enter := c.scopeEnter(s)
	c.scope = s
	set := c.bindingInit(x.wb)
	body := c.stmtOrNop(x.Body)
	c.scope = save
	return func(f *Frame) ctrl {
		v := obj(f)
		o := toObject(v)
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		set(f, Obj(o))
		r := body(f)
		f.env = saveEnv
		return r
	}
}

// ---------- conditions ----------

func (c *compiler) cond(n Node) func(f *Frame) bool {
	switch x := n.(type) {
	case *BinaryExpr:
		l := c.expr(x.L)
		r := c.expr(x.R)
		pos := x.pos
		switch x.Op {
		case "<":
			return func(f *Frame) bool {
				a, b := l(f), r(f)
				if a.t == TagNum && b.t == TagNum {
					return a.n < b.n
				}
				f.pos = pos
				return opLT(a, b)
			}
		case "<=":
			return func(f *Frame) bool {
				a, b := l(f), r(f)
				if a.t == TagNum && b.t == TagNum {
					return a.n <= b.n
				}
				f.pos = pos
				return opLE(a, b)
			}
		case ">":
			return func(f *Frame) bool {
				a, b := l(f), r(f)
				if a.t == TagNum && b.t == TagNum {
					return a.n > b.n
				}
				f.pos = pos
				return opGT(a, b)
			}
		case ">=":
			return func(f *Frame) bool {
				a, b := l(f), r(f)
				if a.t == TagNum && b.t == TagNum {
					return a.n >= b.n
				}
				f.pos = pos
				return opGE(a, b)
			}
		case "===":
			return func(f *Frame) bool { return strictEquals(l(f), r(f)) }
		case "!==":
			return func(f *Frame) bool { return !strictEquals(l(f), r(f)) }
		case "==":
			return func(f *Frame) bool { a, b := l(f), r(f); f.pos = pos; return looseEquals(a, b) }
		case "!=":
			return func(f *Frame) bool { a, b := l(f), r(f); f.pos = pos; return !looseEquals(a, b) }
		}
	case *UnaryExpr:
		if x.Op == "!" {
			inner := c.cond(x.X)
			return func(f *Frame) bool { return !inner(f) }
		}
	case *LogicalExpr:
		if x.Op == "&&" {
			l := c.cond(x.L)
			r := c.cond(x.R)
			return func(f *Frame) bool { return l(f) && r(f) }
		}
		if x.Op == "||" {
			l := c.cond(x.L)
			r := c.cond(x.R)
			return func(f *Frame) bool { return l(f) || r(f) }
		}
	}
	e := c.expr(n)
	return func(f *Frame) bool { return toBool(e(f)) }
}

var _ = math.Inf
EOF
echo ok"}

