package main

import (
	"math"
	"math/big"
)

const TagChain Tag = 10

var chainBreak = Value{t: TagChain}

func constFn(v Value) evalFn { return func(f *Frame) Value { return v } }

func unparen(n Node) Node {
	for {
		p, ok := n.(*ParenExpr)
		if !ok {
			return n
		}
		n = p.X
	}
}

func isAnonFn(n Node) bool {
	switch x := unparen(n).(type) {
	case *FuncExpr:
		return x.F.Name == ""
	case *ArrowFunc:
		return true
	case *ClassExpr:
		return x.C.Name == ""
	}
	return false
}

// expression with name inference for anonymous functions/classes
func (c *compiler) exprNamed(n Node, name string) evalFn {
	switch x := unparen(n).(type) {
	case *FuncExpr:
		if x.F.Name == "" {
			return c.funcValue(x.F, name)
		}
	case *ArrowFunc:
		return c.funcValue(x.F, name)
	case *ClassExpr:
		if x.C.Name == "" {
			return c.classValue(x.C, name)
		}
	}
	return c.expr(n)
}

// expression with runtime-computed name
func (c *compiler) exprNamedDyn(n Node) func(f *Frame, name Value) Value {
	if !isAnonFn(n) {
		e := c.expr(n)
		return func(f *Frame, name Value) Value { return e(f) }
	}
	e := c.exprNamed(n, "")
	return func(f *Frame, name Value) Value {
		v := e(f)
		setFunctionName(v.obj(), name, "")
		return v
	}
}

func (c *compiler) expr(n Node) evalFn {
	switch x := n.(type) {
	case *Ident:
