	case *ArrowFunc:
		return c.funcValue(x.F, "")
	case *ClassExpr:
		return c.classValue(x.C, x.C.Name)
	case *UnaryExpr:
		return c.unary(x)
	case *UpdateExpr:
		return c.update(x)
	case *BinaryExpr:
		return c.binary(x)
	case *LogicalExpr:
		return c.logical(x)
	case *AssignExpr:
		return c.assign(x)
	case *CondExpr:
		t := c.cond(x.Test)
		a := c.expr(x.Cons)
		b := c.expr(x.Alt)
		return func(f *Frame) Value {
			if t(f) {
				return a(f)
			}
			return b(f)
		}
	case *CallExpr:
		return c.call(x, false)
	case *NewExpr:
		return c.newExpr(x)
	case *MemberExpr:
		return c.member(x, false)
	case *OptChain:
		inner := c.chainExpr(x.X)
		return func(f *Frame) Value {
			v := inner(f)
			if v.t == TagChain {
				return Undefined
			}
			return v
		}
	case *SeqExpr:
		fns := make([]evalFn, len(x.List))
		for i, e := range x.List {
			fns[i] = c.expr(e)
		}
		return func(f *Frame) Value {
			var v Value
			for _, fn := range fns {
				v = fn(f)
			}
			return v
		}
	case *YieldExpr:
		return c.yieldExpr(x)
	case *AwaitExpr:
		e := c.expr(x.X)
		return func(f *Frame) Value {
			return awaitValue(f, e(f))
		}
	case *NewTargetExpr:
		return func(f *Frame) Value {
			if f.thisFrame == nil {
				return Undefined
			}
			return f.thisFrame.newTarget
		}
	case *ImportMetaExpr:
		mod := c.module
		return func(f *Frame) Value {
			return Obj(mod.importMeta())
		}
	case *ImportCall:
		e := c.expr(x.X)
		mod := c.module
		sf := c.sf
		return func(f *Frame) Value {
			spec := e(f)
			return dynamicImport(mod, sf, spec)
		}
	case *PrivateIn:
		get := c.refGet(x.ref)
		r := c.expr(x.R)
		pos := x.pos
		return func(f *Frame) Value {
			sym := get(f).sym()
			o := r(f)
			f.pos = pos
			if o.t != TagObj {
				throwTypeError("invalid 'in' operand")
			}
			return Bool(privateHas(o.obj(), sym))
		}
	case *Spread:
		panic(&SyntaxErr{msg: "unexpected '...'", pos: x.pos})
	case *SuperExpr:
		panic(&SyntaxErr{msg: "invalid use of 'super'", pos: x.pos})
	case *ObjPattern, *ArrPattern, *AssignPat:
		panic(&SyntaxErr{msg: "invalid destructuring target", pos: nodePos(n)})
	}
	panic("unknown expression")
}

func (c *compiler) thisExpr() evalFn {
	if c.fn.isScript || c.fn.isModule {
		if c.fn.isModule {
			return func(f *Frame) Value { return Undefined }
		}
		return func(f *Frame) Value { return f.thisFrame.this }
	}
	needCheck := false
	for fn := c.fn; fn != nil; {
		if fn.Kind == FKDerivedConstructor {
			needCheck = true
		}
		break
	}
	if c.fn.IsArrow || c.fn.isEvalCode {
		needCheck = true
	}
	if !needCheck {
		return func(f *Frame) Value { return f.this }
	}
	return func(f *Frame) Value {
		tf := f.thisFrame
		if !tf.thisInit {
			throwReferenceError("this is not initialized")
		}
		return tf.this
	}
}

func (c *compiler) templateLit(x *TemplateLit) evalFn {
	strs := x.Cooked
	exprs := make([]evalFn, len(x.Exprs))
	for i, e := range x.Exprs {
		exprs[i] = c.expr(e)
	}
	if len(exprs) == 0 {
		v := Str(strs[0])
		return constFn(v)
	}
	return func(f *Frame) Value {
		s := strs[0]
		for i, e := range exprs {
			v := e(f)
			var vs *JSString
			if v.t == TagStr {
				vs = v.str()
			} else {
				if v.t == TagSym {
					throwTypeError("cannot convert symbol to string")
				}
				vs = toString(v)
			}
			s = concatStr(s, vs)
			s = concatStr(s, strs[i+1])
		}
		return Str(s)
	}
}

func (c *compiler) taggedTemplate(x *TaggedTemplate) evalFn {
	var siteObj *Object
	tpl := x.Tpl
	getSite := func() Value {
		if siteObj == nil {
			n := len(tpl.Cooked)
			cooked := make([]Value, n)
			raws := make([]Value, n)
			for i := 0; i < n; i++ {
				if tpl.Cooked[i] == nil {
					cooked[i] = Undefined
				} else {
					cooked[i] = Str(tpl.Cooked[i])
				}
				raws[i] = Str(newStr(tpl.Raws[i]))
			}
			rawArr := newArray(raws)
			freezeObject(rawArr)
			arr := newArray(cooked)
			arr.setOwn(strKey("raw"), Obj(rawArr), 0)
			freezeObject(arr)
			siteObj = arr
		}
		return Obj(siteObj)
	}
	exprs := make([]evalFn, len(tpl.Exprs))
	for i, e := range tpl.Exprs {
		exprs[i] = c.expr(e)
	}
	pos := x.pos
	callee, thisFn := c.calleeAndThis(x.Tag)
	return func(f *Frame) Value {
		fn, this := callee(f)
		_ = thisFn
		args := make([]Value, len(exprs)+1)
		args[0] = getSite()
		for i, e := range exprs {
			args[i+1] = e(f)
		}
		f.pos = pos
		return callValue(fn, this, args)
	}
}

// returns function computing (callee, this)
func (c *compiler) calleeAndThis(n Node) (func(f *Frame) (Value, Value), bool) {
	switch x := unparen(n).(type) {
	case *MemberExpr:
		if _, ok := x.Obj.(*SuperExpr); ok {
			get := c.member(x, false)
			return func(f *Frame) (Value, Value) {
				return get(f), f.thisFrame.this
			}, true
		}
		obj := c.expr(x.Obj)
		pos := x.pos
		if x.Private {
			pget := c.refGet(x.privRef)
			return func(f *Frame) (Value, Value) {
				o := obj(f)
				f.pos = pos
				return privateGet(o, pget(f).sym()), o
			}, true
		}
		if x.Computed {
			key := c.expr(x.Prop)
			return func(f *Frame) (Value, Value) {
				o := obj(f)
				k := key(f)
				f.pos = pos
				return getMemberComputed(o, k), o
			}, true
		}
		k := strKey(x.Name)
		return func(f *Frame) (Value, Value) {
			o := obj(f)
			f.pos = pos
			return getMemberNamed(o, k), o
		}, true
	case *Ident:
		get := c.refGet(x)
		wb := c.withBase(x)
		if wb != nil {
			return func(f *Frame) (Value, Value) {
				return get(f), wb(f)
			}, true
		}
		return func(f *Frame) (Value, Value) { return get(f), Undefined }, false
	}
	e := c.expr(n)
	return func(f *Frame) (Value, Value) { return e(f), Undefined }, false
}

func (c *compiler) arrayLit(x *ArrayLit) evalFn {
	hasHole := false
	hasSpread := false
	for _, e := range x.Elems {
		if e == nil {
			hasHole = true
		} else if _, ok := e.(*Spread); ok {
			hasSpread = true
		}
	}
	if !hasHole && !hasSpread {
		fns := make([]evalFn, len(x.Elems))
		for i, e := range x.Elems {
			fns[i] = c.expr(e)
		}
		return func(f *Frame) Value {
			vals := make([]Value, len(fns))
			for i, fn := range fns {
				vals[i] = fn(f)
			}
			return Obj(newArray(vals))
		}
	}
	type el struct {
		fn     evalFn
		spread bool
		hole   bool
	}
	els := make([]el, len(x.Elems))
	for i, e := range x.Elems {
		if e == nil {
			els[i] = el{hole: true}
		} else if sp, ok := e.(*Spread); ok {
			els[i] = el{fn: c.expr(sp.X), spread: true}
		} else {
			els[i] = el{fn: c.expr(e)}
		}
	}
	return func(f *Frame) Value {
		arr := newArray(nil)
		idx := uint32(0)
		for _, e := range els {
			if e.hole {
				idx++
				continue
			}
			v := e.fn(f)
			if e.spread {
				iterateValue(v, func(item Value) bool {
					arr.defineIndex(idx, item, true)
					idx++
					return true
				})
				continue
			}
			arr.defineIndex(idx, v, true)
			idx++
		}
		if idx > arr.alen {
			arr.alen = idx
		}
		return Obj(arr)
	}
}

func propKeyFromLit(n Node, name string) PropKey {
	switch k := n.(type) {
	case *NumLit:
		return toPropertyKey(Num(k.Val))
	case *StrLit:
		return strToKey(k.Val)
	}
	return strKey(name)
}

func (c *compiler) objectLit(x *ObjectLit) evalFn {
	type prop struct {
		kind     PropKind
		key      PropKey
		keyFn    evalFn
		val      evalFn
		valDyn   func(f *Frame, name Value) Value
		method   *FuncNode
		computed bool
	}
	props := make([]prop, len(x.Props))
	simple := true
	for i, p := range x.Props {
		pr := prop{kind: p.Kind, computed: p.Computed}
		if p.Computed {
			pr.keyFn = c.expr(p.Key)
			simple = false
		} else if p.Kind != PSpread {
			pr.key = propKeyFromLit(p.Key, p.KeyName)
		}
		switch p.Kind {
		case PInit:
			if p.Computed {
				pr.valDyn = c.exprNamedDyn(p.Value)
			} else {
				pr.val = c.exprNamed(p.Value, keyToFuncName(pr.key))
			}
		case PProto:
			pr.val = c.expr(p.Value)
			simple = false
		case PSpread:
			pr.val = c.expr(p.Value)
			simple = false
		case PGet, PSet, PMethod:
			pr.method = p.Value.(*FuncExpr).F
			c.compileFunction(pr.method)
			simple = false
		}
		props[i] = pr
	}
	if simple {
		return func(f *Frame) Value {
			o := newObject()
			for i := range props {
				p := &props[i]
				v := p.val(f)
				if j := o.findOwn(p.key); j >= 0 {
					o.props[j] = Prop{v: v, flags: pDefault}
				} else {
					o.addProp(p.key, v, pDefault)
				}
			}
			return Obj(o)
		}
	}
	return func(f *Frame) Value {
		o := newObject()
		for i := range props {
			p := &props[i]
			switch p.kind {
			case PSpread:
				v := p.val(f)
				copyDataProperties(o, v, nil)
				continue
			case PProto:
				v := p.val(f)
				if v.t == TagObj {
					o.proto = v.obj()
				} else if v.t == TagNull {
					o.proto = nil
				}
				continue
			}
			key := p.key
			var keyV Value
			if p.computed {
				kv := p.keyFn(f)
				key = toPropertyKey(kv)
				keyV = key.toValue()
			}
			switch p.kind {
			case PInit:
				var v Value
				if p.computed {
					v = p.valDyn(f, keyV)
				} else {
					v = p.val(f)
				}
				createDataProp(o, key, v)
			case PMethod:
				fn := makeMethod(p.method, f, o, key, "")
				o.DefineOwnProperty(key, dataDesc(Obj(fn), pDefault), false)
			case PGet:
				fn := makeMethod(p.method, f, o, key, "get")
				o.DefineOwnProperty(key, &PropDesc{get: Obj(fn), hasGet: true, hasEnumerable: true, enumerable: true, hasConfigurable: true, configurable: true}, false)
			case PSet:
				fn := makeMethod(p.method, f, o, key, "set")
				o.DefineOwnProperty(key, &PropDesc{set: Obj(fn), hasSet: true, hasEnumerable: true, enumerable: true, hasConfigurable: true, configurable: true}, false)
			}
		}
		return Obj(o)
	}
}

func keyToFuncName(k PropKey) string {
	if k.sym != nil {
		if k.sym.desc == nil {
			return ""
		}
		return "[" + k.sym.desc.String() + "]"
	}
	return k.s
}

func makeMethod(fn *FuncNode, f *Frame, home *Object, key PropKey, prefix string) *Object {
	code := fn.compiled
	name := keyToFuncName(key)
	if prefix != "" {
		name = prefix + " " + name
	}
	o := makeClosure(code, f, home, name)
	return o
}

func (c *compiler) funcValue(fn *FuncNode, name string) evalFn {
	code := c.compileFunction(fn)
	if fn.Name != "" {
		name = fn.Name
	}
	return func(f *Frame) Value {
		return Obj(makeClosure(code, f, nil, name))
	}
}

func (c *compiler) unary(x *UnaryExpr) evalFn {
	switch x.Op {
	case "typeof":
		if id, ok := unparen(x.X).(*Ident); ok {
			g := c.refGetOpt(id, true)
			return func(f *Frame) Value { return Str(typeofStr(g(f))) }
		}
		e := c.expr(x.X)
		return func(f *Frame) Value { return Str(typeofStr(e(f))) }
	case "void":
		e := c.expr(x.X)
		return func(f *Frame) Value { e(f); return Undefined }
	case "!":
		e := c.cond(x.X)
		return func(f *Frame) Value { return Bool(!e(f)) }
	case "-":
		if nl, ok := x.X.(*NumLit); ok {
			return constFn(Num(-nl.Val))
		}
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			if v.t == TagNum {
				return Num(-v.n)
			}
			f.pos = pos
			return opNeg(v)
		}
	case "+":
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			if v.t == TagNum {
				return v
			}
			f.pos = pos
			return Num(toNumber(v))
		}
	case "~":
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			f.pos = pos
			return opBitNot(v)
		}
	case "delete":
		return c.deleteExpr(x)
	}
	panic("bad unary")
}

var typeofStrs = map[string]*JSString{}

func typeofStr(v Value) *JSString {
	s := typeOf(v)
	js, ok := typeofStrs[s]
	if !ok {
		js = newStr(s)
		typeofStrs[s] = js
	}
	return js
}

func (c *compiler) deleteExpr(x *UnaryExpr) evalFn {
	strict := c.strict
	pos := x.pos
	switch t := unparen(x.X).(type) {
	case *MemberExpr:
		if _, ok := t.Obj.(*SuperExpr); ok {
			return func(f *Frame) Value {
				throwReferenceError("unsupported reference to 'super'")
				return Undefined
			}
		}
		obj := c.expr(t.Obj)
		if t.Computed {
			key := c.expr(t.Prop)
			return func(f *Frame) Value {
				o := obj(f)
				k := key(f)
				f.pos = pos
				return Bool(opDelete(o, k, strict))
			}
		}
		k := Str(newStr(t.Name))
		return func(f *Frame) Value {
			o := obj(f)
			f.pos = pos
			return Bool(opDelete(o, k, strict))
		}
	case *Ident:
		ref := t.ref
		if ref != nil && ref.b != nil && ref.b.scope.kind != scScript && len(ref.withs) == 0 {
			return constFn(False)
		}
		name := t.Name
		gs := []func(f *Frame) Value{}
		if ref != nil && len(ref.withs) > 0 {
			gs = c.withObjGetters(ref)
		}
		isLocal := ref != nil && ref.b != nil && ref.b.scope.kind != scScript
		return func(f *Frame) Value {
			k := strKey(name)
			for _, g := range gs {
				ov := g(f)
				if ov.t == TagObj && withHas(ov.obj(), k) {
					return Bool(ov.obj().Delete(k, false))
				}
			}
			if isLocal {
				return False
			}
			if _, ok := globalLex[name]; ok {
				return False
			}
			if GlobalObject.findOwn(k) >= 0 {
				return Bool(GlobalObject.Delete(k, false))
			}
			return True
		}
	case *OptChain:
		inner := c.chainDelete(t.X)
		return inner
	}
	e := c.expr(x.X)
	return func(f *Frame) Value {
		e(f)
		return True
	}
}

func (c *compiler) chainDelete(n Node) evalFn {
	m, ok := n.(*MemberExpr)
	if !ok {
		e := c.chainExpr(n)
		return func(f *Frame) Value { e(f); return True }
	}
	obj := c.chainExpr(m.Obj)
	strict := c.strict
	var key evalFn
	if m.Computed {
		key = c.expr(m.Prop)
	} else {
		k := Str(newStr(m.Name))
		key = constFn(k)
	}
	opt := m.Optional
	return func(f *Frame) Value {
		o := obj(f)
		if o.t == TagChain {
			return True
		}
		if opt && o.IsNullish() {
			return True
		}
		return Bool(opDelete(o, key(f), strict))
	}
}

func (c *compiler) update(x *UpdateExpr) evalFn {
	delta := 1.0
	if x.Op == "--" {
		delta = -1
	}
	prefix := x.Prefix
	pos := x.pos
	switch t := unparen(x.X).(type) {
	case *Ident:
		// fast path for local non-tdz
		ref := t.ref
		if ref != nil && ref.b != nil && !ref.b.inEnv && ref.b.scope.kind != scScript && len(ref.withs) == 0 && (ref.b.kind == bVar || ref.b.kind == bLet || ref.b.kind == bParam) && !ref.b.tdz {
			idx := ref.b.idx
			return func(f *Frame) Value {
				v := f.locals[idx]
				if v.t == TagNum {
					nv := Num(v.n + delta)
					f.locals[idx] = nv
					if prefix {
						return nv
					}
					return v
				}
				f.pos = pos
				old := toNumeric(v)
				nv := opInc(old, delta)
				f.locals[idx] = nv
				if prefix {
					return nv
				}
				return old
			}
		}
		get := c.refGet(t)
		set := c.refSet(t)
		return func(f *Frame) Value {
			v := get(f)
			f.pos = pos
			old := toNumeric(v)
			nv := opInc(old, delta)
			set(f, nv)
			if prefix {
				return nv
			}
			return old
		}
	case *MemberExpr:
		ref := c.memberRef(t)
		return func(f *Frame) Value {
			r := ref(f)
			v := r.get(f)
			f.pos = pos
			old := toNumeric(v)
			nv := opInc(old, delta)
			r.set(f, nv)
			if prefix {
				return nv
			}
			return old
		}
	case *CallExpr:
		call := c.expr(t)
		return func(f *Frame) Value {
			call(f)
			throwReferenceError("invalid increment/decrement operand")
			return Undefined
		}
	}
	panic(&SyntaxErr{msg: "invalid increment/decrement operand", pos: x.pos})
}

// memberRef evaluates object and key once, returning get/set accessors
type memberRefT struct {
	obj  Value
	key  PropKey
	keyV Value
	get  func(f *Frame) Value
	set  func(f *Frame, v Value)
}

func (c *compiler) memberRef(m *MemberExpr) func(f *Frame) *memberRefT {
	strict := c.strict
	pos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		var keyFn evalFn
		var k PropKey
		if m.Computed {
			keyFn = c.expr(m.Prop)
		} else {
			k = strKey(m.Name)
		}
		return func(f *Frame) *memberRefT {
			r := &memberRefT{}
			key := k
			if keyFn != nil {
				key = toPropertyKey(keyFn(f))
			}
			this := f.thisFrame.this
			home := f.thisFrame.homeObj
			r.get = func(f *Frame) Value {
				return superGet(home, key, this)
			}
			r.set = func(f *Frame, v Value) {
				superSet(home, key, v, this, strict)
			}
			return r
		}
	}
	obj := c.expr(m.Obj)
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) *memberRefT {
			o := obj(f)
			sym := pget(f).sym()
			r := &memberRefT{obj: o}
			r.get = func(f *Frame) Value { f.pos = pos; return privateGet(o, sym) }
			r.set = func(f *Frame, v Value) { f.pos = pos; privateSet(o, sym, v) }
			return r
		}
	}
	if m.Computed {
		keyFn := c.expr(m.Prop)
		return func(f *Frame) *memberRefT {
			o := obj(f)
			kv := keyFn(f)
			f.pos = pos
			if o.IsNullish() {
				throwTypeError("cannot read property of %s", typeOfForError(o))
			}
			k := toPropertyKey(kv)
			r := &memberRefT{obj: o, key: k}
			r.get = func(f *Frame) Value { f.pos = pos; return getMemberNamed(o, k) }
			r.set = func(f *Frame, v Value) { f.pos = pos; setMemberNamed(o, k, v, strict) }
			return r
		}
	}
	k := strKey(m.Name)
	return func(f *Frame) *memberRefT {
		o := obj(f)
		r := &memberRefT{obj: o, key: k}
		r.get = func(f *Frame) Value { f.pos = pos; return getMemberNamed(o, k) }
		r.set = func(f *Frame, v Value) { f.pos = pos; setMemberNamed(o, k, v, strict) }
		return r
	}
}

func superGet(home *Object, key PropKey, this Value) Value {
	if home == nil {
		throwSyntaxError("'super' is only valid in a method")
	}
	p := home.GetPrototypeOf()
	if p == nil {
		throwTypeError("cannot read property '%s' of null", keyDisplay(key))
	}
	return p.Get(key, this)
}

func superSet(home *Object, key PropKey, v Value, this Value, strict bool) {
	p := home.GetPrototypeOf()
	if p == nil {
		throwTypeError("cannot set property '%s' of null", keyDisplay(key))
	}
	p.Set(key, v, this, strict)
}

func (c *compiler) binary(x *BinaryExpr) evalFn {
	l := c.expr(x.L)
	r := c.expr(x.R)
	pos := x.pos
	switch x.Op {
	case "+":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n + b.n)
			}
			f.pos = pos
			return opAdd(a, b)
		}
	case "-":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n - b.n)
			}
			f.pos = pos
			return opArith(aSub, a, b)
		}
	case "*":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n * b.n)
			}
			f.pos = pos
			return opArith(aMul, a, b)
		}
	case "/":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n / b.n)
			}
			f.pos = pos
			return opArith(aDiv, a, b)
		}
	case "%":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				x, y := a.n, b.n
				if x >= 0 && y > 0 && x <= 2147483647 && y <= 2147483647 {
					xi, yi := int32(x), int32(y)
					if float64(xi) == x && float64(yi) == y {
						return Num(float64(xi % yi))
					}
				}
				return Num(jsMod(x, y))
			}
			f.pos = pos
			return opArith(aMod, a, b)
		}
	case "**":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aExp, a, b) }
	case "&":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(float64(f64ToInt32(a.n) & f64ToInt32(b.n)))
			}
			f.pos = pos
			return opArith(aAnd, a, b)
		}
	case "|":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(float64(f64ToInt32(a.n) | f64ToInt32(b.n)))
			}
			f.pos = pos
			return opArith(aOr, a, b)
		}
	case "^":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aXor, a, b) }
	case "<<":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aShl, a, b) }
	case ">>":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aSar, a, b) }
	case ">>>":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aShr, a, b) }
	case "==", "!=", "===", "!==", "<", ">", "<=", ">=":
		cnd := c.cond(x)
		return func(f *Frame) Value { return Bool(cnd(f)) }
	case "instanceof":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return Bool(opInstanceof(a, b)) }
	case "in":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return Bool(opIn(a, b)) }
	}
	panic("bad binary op " + x.Op)
}

func (c *compiler) logical(x *LogicalExpr) evalFn {
	l := c.expr(x.L)
	r := c.expr(x.R)
	switch x.Op {
	case "&&":
		return func(f *Frame) Value {
			v := l(f)
			if !toBool(v) {
				return v
			}
			return r(f)
		}
	case "||":
		return func(f *Frame) Value {
			v := l(f)
			if toBool(v) {
				return v
			}
			return r(f)
		}
	case "??":
		return func(f *Frame) Value {
			v := l(f)
			if !v.IsNullish() {
				return v
			}
			return r(f)
		}
	}
	panic("bad logical")
}

func arithOpFor(op string) (arithOp, bool) {
	switch op {
	case "-=":
		return aSub, true
	case "*=":
		return aMul, true
	case "/=":
		return aDiv, true
	case "%=":
		return aMod, true
	case "**=":
		return aExp, true
	case "&=":
		return aAnd, true
	case "|=":
		return aOr, true
	case "^=":
		return aXor, true
	case "<<=":
		return aShl, true
	case ">>=":
		return aSar, true
	case ">>>=":
		return aShr, true
	}
	return 0, false
}

func compoundOp(op string, pos int) func(f *Frame, a, b Value) Value {
	if op == "+=" {
		return func(f *Frame, a, b Value) Value {
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n + b.n)
			}
			f.pos = pos
			return opAdd(a, b)
		}
	}
	aop, ok := arithOpFor(op)
	if !ok {
		panic("bad compound op " + op)
	}
	return func(f *Frame, a, b Value) Value {
		if a.t == TagNum && b.t == TagNum && aop <= aDiv {
			switch aop {
			case aSub:
				return Num(a.n - b.n)
			case aMul:
				return Num(a.n * b.n)
			case aDiv:
				return Num(a.n / b.n)
			}
		}
		f.pos = pos
		return opArith(aop, a, b)
	}
}

func (c *compiler) assign(x *AssignExpr) evalFn {
	pos := x.pos
	target := unparen(x.L)
	if x.Op == "=" {
		switch t := target.(type) {
		case *Ident:
			v := c.exprNamed(x.R, t.Name)
			set := c.refSet(t)
			return func(f *Frame) Value {
				val := v(f)
				f.pos = pos
				set(f, val)
				return val
			}
		case *MemberExpr:
			return c.memberAssign(t, x.R, pos)
		case *ObjPattern, *ArrPattern:
			v := c.expr(x.R)
			bind := c.assignPattern(t)
			return func(f *Frame) Value {
				val := v(f)
				bind(f, val)
				return val
			}
		case *CallExpr:
			call := c.expr(t)
			v := c.expr(x.R)
			return func(f *Frame) Value {
				call(f)
				v(f)
				throwReferenceError("invalid assignment left-hand side")
				return Undefined
			}
		}
		panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
	}
	// logical assignment
	if x.Op == "&&=" || x.Op == "||=" || x.Op == "??=" {
		op := x.Op
		test := func(v Value) bool {
			switch op {
			case "&&=":
				return toBool(v)
			case "||=":
				return !toBool(v)
			}
			return v.IsNullish()
		}
		switch t := target.(type) {
		case *Ident:
			get := c.refGet(t)
			set := c.refSet(t)
			v := c.exprNamed(x.R, t.Name)
			return func(f *Frame) Value {
				cur := get(f)
				if !test(cur) {
					return cur
				}
				nv := v(f)
				f.pos = pos
				set(f, nv)
				return nv
			}
		case *MemberExpr:
			ref := c.memberRef(t)
			v := c.expr(x.R)
			return func(f *Frame) Value {
				r := ref(f)
				cur := r.get(f)
				if !test(cur) {
					return cur
				}
				nv := v(f)
				r.set(f, nv)
				return nv
			}
		}
		panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
	}
	opf := compoundOp(x.Op, pos)
	switch t := target.(type) {
	case *Ident:
		ref := t.ref
		v := c.expr(x.R)
		if ref != nil && ref.b != nil && !ref.b.inEnv && ref.b.scope.kind != scScript && len(ref.withs) == 0 && (ref.b.kind == bVar || ref.b.kind == bLet || ref.b.kind == bParam) && !ref.b.tdz {
			idx := ref.b.idx
			return func(f *Frame) Value {
				cur := f.locals[idx]
				rv := v(f)
				nv := opf(f, cur, rv)
				f.locals[idx] = nv
				return nv
			}
		}
		get := c.refGet(t)
		set := c.refSet(t)
		return func(f *Frame) Value {
			cur := get(f)
			rv := v(f)
			nv := opf(f, cur, rv)
			f.pos = pos
			set(f, nv)
			return nv
		}
	case *MemberExpr:
		ref := c.memberRef(t)
		v := c.expr(x.R)
		return func(f *Frame) Value {
			r := ref(f)
			cur := r.get(f)
			rv := v(f)
			nv := opf(f, cur, rv)
			r.set(f, nv)
			return nv
		}
	case *CallExpr:
		call := c.expr(t)
		return func(f *Frame) Value {
			call(f)
			throwReferenceError("invalid assignment left-hand side")
			return Undefined
		}
	}
	panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
}

func (c *compiler) memberAssign(m *MemberExpr, rhs Node, pos int) evalFn {
	strict := c.strict
	mpos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		ref := c.memberRef(m)
		v := c.expr(rhs)
		return func(f *Frame) Value {
			r := ref(f)
			val := v(f)
			r.set(f, val)
			return val
		}
	}
	obj := c.expr(m.Obj)
	v := c.expr(rhs)
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) Value {
			o := obj(f)
			val := v(f)
			f.pos = mpos
			privateSet(o, pget(f).sym(), val)
			return val
		}
	}
	if m.Computed {
		key := c.expr(m.Prop)
		return func(f *Frame) Value {
			o := obj(f)
			k := key(f)
			val := v(f)
			f.pos = mpos
			setMemberComputed(o, k, val, strict)
			return val
		}
	}
	k := strKey(m.Name)
	return func(f *Frame) Value {
		o := obj(f)
		val := v(f)
		f.pos = mpos
		if o.t == TagObj {
			ob := o.obj()
			if ob.class == ClassObject {
				i := ob.findOwn(k)
				if i >= 0 && ob.props[i].flags&(pAccessor|pWritable) == pWritable {
					ob.props[i].v = val
					return val
				}
			}
			ob.Set(k, val, o, strict)
			return val
		}
		setMemberNamed(o, k, val, strict)
		return val
	}
}

// ---------- member access ----------

func (c *compiler) member(m *MemberExpr, inChain bool) evalFn {
	pos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		var keyFn evalFn
		var k PropKey
		if m.Computed {
			keyFn = c.expr(m.Prop)
		} else {
			k = strKey(m.Name)
		}
		return func(f *Frame) Value {
			key := k
			if keyFn != nil {
				key = toPropertyKey(keyFn(f))
			}
			tf := f.thisFrame
			if !tf.thisInit {
				throwReferenceError("this is not initialized")
			}
			return superGet(tf.homeObj, key, tf.this)
		}
	}
	var obj evalFn
	if inChain {
		obj = c.chainExpr(m.Obj)
	} else {
		obj = c.expr(m.Obj)
	}
	opt := m.Optional
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) Value {
			o := obj(f)
			if inChain {
				if o.t == TagChain || (opt && o.IsNullish()) {
					return chainBreak
				}
			}
			f.pos = pos
			return privateGet(o, pget(f).sym())
		}
	}
	if m.Computed {
		key := c.expr(m.Prop)
		if inChain {
			return func(f *Frame) Value {
				o := obj(f)
				if o.t == TagChain || (opt && o.IsNullish()) {
					return chainBreak
				}
				k := key(f)
				f.pos = pos
				return getMemberComputed(o, k)
			}
		}
		return func(f *Frame) Value {
			o := obj(f)
			k := key(f)
			f.pos = pos
			return getMemberComputed(o, k)
		}
	}
	k := strKey(m.Name)
	if inChain {
		return func(f *Frame) Value {
			o := obj(f)
			if o.t == TagChain || (opt && o.IsNullish()) {
				return chainBreak
			}
			f.pos = pos
			return getMemberNamed(o, k)
		}
	}
	if m.Name == "length" {
		return func(f *Frame) Value {
			o := obj(f)
			if o.t == TagObj && o.obj().class == ClassArray {
				return Num(float64(o.obj().alen))
			}
			if o.t == TagStr {
				return Int(o.str().n)
			}
			f.pos = pos
			return getMemberNamed(o, k)
		}
	}
	return func(f *Frame) Value {
		o := obj(f)
		if o.t == TagObj {
			ob := o.obj()
			if ob.class == ClassObject {
				i := ob.findOwn(k)
				if i >= 0 && ob.props[i].flags&pAccessor == 0 {
					return ob.props[i].v
				}
			}
			f.pos = pos
			return ob.Get(k, o)
		}
		f.pos = pos
		return getMemberNamed(o, k)
	}
}

// compile expression inside optional chain
func (c *compiler) chainExpr(n Node) evalFn {
	switch x := n.(type) {
	case *MemberExpr:
		return c.member(x, true)
	case *CallExpr:
		return c.call(x, true)
	}
	return c.expr(n)
}

// ---------- calls ----------

func (c *compiler) args(list []Node) func(f *Frame) []Value {
	if len(list) == 0 {
		return func(f *Frame) []Value { return nil }
	}
	hasSpread := false
	for _, a := range list {
		if _, ok := a.(*Spread); ok {
			hasSpread = true
		}
	}
	if !hasSpread {
		fns := make([]evalFn, len(list))
		for i, a := range list {
			fns[i] = c.expr(a)
		}
		switch len(fns) {
		case 1:
			a0 := fns[0]
			return func(f *Frame) []Value { return []Value{a0(f)} }
		case 2:
			a0, a1 := fns[0], fns[1]
			return func(f *Frame) []Value {
				v0 := a0(f)
				return []Value{v0, a1(f)}
			}
		}
		return func(f *Frame) []Value {
			args := make([]Value, len(fns))
			for i, fn := range fns {
				args[i] = fn(f)
			}
			return args
		}
	}
	type ae struct {
		fn     evalFn
		spread bool
	}
	els := make([]ae, len(list))
	for i, a := range list {
		if sp, ok := a.(*Spread); ok {
			els[i] = ae{c.expr(sp.X), true}
		} else {
			els[i] = ae{c.expr(a), false}
		}
	}
	return func(f *Frame) []Value {
		var args []Value
		for _, e := range els {
			v := e.fn(f)
			if e.spread {
				iterateValue(v, func(item Value) bool {
					args = append(args, item)
					return true
				})
			} else {
				args = append(args, v)
			}
		}
		return args
	}
}

func doCall(f *Frame, pos int, fn Value, this Value, args []Value) Value {
	f.pos = pos
	if fn.t != TagObj {
		throwTypeError("not a function")
	}
	o := fn.obj()
	if o.class == ClassFunction {
		return callClosure(o, o.internal.(*Closure), this, args, nil)
	}
	return callFunc(o, this, args)
}

func (c *compiler) call(x *CallExpr, inChain bool) evalFn {
	pos := x.pos
	if x.tail {
		pos = x.retPos
	}
	args := c.args(x.Args)
	opt := x.Optional
	callee := unparen(x.Callee)
	if _, ok := callee.(*SuperExpr); ok {
		return c.superCall(x, args)
	}
	if m, ok := callee.(*MemberExpr); ok && x.Callee == callee {
		if _, isSuper := m.Obj.(*SuperExpr); isSuper {
			get := c.member(m, false)
			return func(f *Frame) Value {
				fn := get(f)
				a := args(f)
				return doCall(f, pos, fn, f.thisFrame.this, a)
			}
		}
		var obj evalFn
		if inChain {
			obj = c.chainExpr(m.Obj)
		} else {
			obj = c.expr(m.Obj)
		}
		mopt := m.Optional
		mpos := m.pos
		if m.Private {
			pget := c.refGet(m.privRef)
			return func(f *Frame) Value {
				o := obj(f)
				if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
					return chainBreak
				}
				f.pos = mpos
				fn := privateGet(o, pget(f).sym())
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, o, a)
			}
		}
		if m.Computed {
			key := c.expr(m.Prop)
			return func(f *Frame) Value {
				o := obj(f)
				if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
					return chainBreak
				}
				k := key(f)
				f.pos = mpos
				fn := getMemberComputed(o, k)
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, o, a)
			}
		}
		k := strKey(m.Name)
		return func(f *Frame) Value {
			o := obj(f)
			if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
				return chainBreak
			}
			f.pos = mpos
			var fn Value
			if o.t == TagObj {
				fn = o.obj().Get(k, o)
			} else {
				fn = getMemberNamed(o, k)
			}
			if opt && fn.IsNullish() {
				return chainBreak
			}
			a := args(f)
			return doCall(f, pos, fn, o, a)
		}
	}
	if id, ok := callee.(*Ident); ok {
		get := c.refGet(id)
		wb := c.withBase(id)
		if x.isEval {
			evalScope := x.evalScope
			strict := c.strict
			parentC := c
			return func(f *Frame) Value {
				fn := get(f)
				a := args(f)
				if fn.t == TagObj && fn.obj() == EvalFunction {
					f.pos = pos
					return directEval(f, arg(a, 0), evalScope, strict, parentC)
				}
				this := Undefined
				if wb != nil {
					this = wb(f)
				}
				return doCall(f, pos, fn, this, a)
			}
		}
		if wb != nil {
			return func(f *Frame) Value {
				fn := get(f)
				this := wb(f)
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, this, a)
			}
		}
		return func(f *Frame) Value {
			fn := get(f)
			if opt && fn.IsNullish() {
				return chainBreak
			}
			a := args(f)
			return doCall(f, pos, fn, Undefined, a)
		}
	}
	var fnE evalFn
	if inChain {
		fnE = c.chainExpr(x.Callee)
	} else {
		fnE = c.expr(x.Callee)
	}
	return func(f *Frame) Value {
		fn := fnE(f)
		if inChain && fn.t == TagChain {
			return chainBreak
		}
		if opt && fn.IsNullish() {
			return chainBreak
		}
		a := args(f)
		return doCall(f, pos, fn, Undefined, a)
	}
}

func (c *compiler) superCall(x *CallExpr, args func(f *Frame) []Value) evalFn {
	pos := x.pos
	return func(f *Frame) Value {
		a := args(f)
		tf := f.thisFrame
		active := tf.fobj
		parent := active.GetPrototypeOf()
		f.pos = pos
		if parent == nil || !parent.isConstructor() {
			throwTypeError("parent class must be constructor")
		}
		nt := tf.newTarget
		var ntObj *Object
		if nt.t == TagObj {
			ntObj = nt.obj()
		}
		r := construct(parent, a, ntObj)
		if tf.thisInit {
			throwReferenceError("'this' can be initialized only once")
		}
		tf.this = r
		tf.thisInit = true
		cl := active.internal.(*Closure)
		if cl.classDef != nil && r.t == TagObj {
			initInstanceElements(r.obj(), active, cl)
		}
		return r
	}
}

func (c *compiler) newExpr(x *NewExpr) evalFn {
	callee := c.expr(x.Callee)
	args := c.args(x.Args)
	pos := x.pos
	return func(f *Frame) Value {
		fn := callee(f)
		a := args(f)
		f.pos = pos
		return constructValue(fn, a, nil)
	}
}

// ---------- yield ----------

func (c *compiler) yieldExpr(x *YieldExpr) evalFn {
	var e evalFn
	if x.X != nil {
		e = c.expr(x.X)
	} else {
		e = constFn(Undefined)
	}
	isAsync := c.fn.IsAsync
	if x.Delegate {
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			f.pos = pos
			return yieldDelegate(f, v, isAsync)
		}
	}
	return func(f *Frame) Value {
		v := e(f)
		if isAsync {
			return asyncGenYield(f, v)
		}
		return generatorYield(f, v)
	}
}

var _ = math.NaN
EOF
echo ok"}

actions.command:
cd /workspace && cat > compile_expr.go <<'EOF'
package main

import (
	"math"
	"math/big"
)

const TagChain Tag = 10

var chainBreak = Value{t: TagChain}

func constFn(v Value) evalFn { return func(f *Frame) Value { return v } }

func unparen(n Node) Node {
	for {
		p, ok := n.(*ParenExpr)
		if !ok {
			return n
		}
		n = p.X
	}
}

func isAnonFn(n Node) bool {
	switch x := unparen(n).(type) {
	case *FuncExpr:
		return x.F.Name == ""
	case *ArrowFunc:
		return true
	case *ClassExpr:
		return x.C.Name == ""
	}
	return false
}

// expression with name inference for anonymous functions/classes
func (c *compiler) exprNamed(n Node, name string) evalFn {
	switch x := unparen(n).(type) {
	case *FuncExpr:
		if x.F.Name == "" {
			return c.funcValue(x.F, name)
		}
	case *ArrowFunc:
		return c.funcValue(x.F, name)
	case *ClassExpr:
		if x.C.Name == "" {
			return c.classValue(x.C, name)
		}
	}
	return c.expr(n)
}

// expression with runtime-computed name
func (c *compiler) exprNamedDyn(n Node) func(f *Frame, name Value) Value {
	if !isAnonFn(n) {
		e := c.expr(n)
		return func(f *Frame, name Value) Value { return e(f) }
	}
	e := c.exprNamed(n, "")
	return func(f *Frame, name Value) Value {
		v := e(f)
		setFunctionName(v.obj(), name, "")
		return v
	}
}

func (c *compiler) expr(n Node) evalFn {
	switch x := n.(type) {
	case *Ident:
		if x.Name == "undefined" && (x.ref == nil || x.ref.b == nil) && len(x.ref.withs) == 0 {
			return c.refGet(x)
		}
		return c.refGet(x)
	case *NumLit:
		return constFn(Num(x.Val))
	case *StrLit:
		return constFn(Str(x.Val))
	case *BigIntLit:
		bi := new(big.Int)
		bi.SetString(x.Digits, 10)
		return constFn(BigV(bi))
	case *BoolLit:
		return constFn(Bool(x.Val))
	case *NullLit:
		return constFn(Null)
	case *TemplateLit:
		return c.templateLit(x)
	case *TaggedTemplate:
		return c.taggedTemplate(x)
	case *RegExpLit:
		pattern := newStr(x.Pattern)
		flags := x.Flags
		pos := x.pos
		re, err := compileRegExp(pattern, flags)
		if err != "" {
			panic(&SyntaxErr{msg: err, pos: pos})
		}
		return func(f *Frame) Value {
			return Obj(newRegExpObject(re, pattern, flags, nil))
		}
	case *ThisExpr:
		return c.thisExpr()
	case *ParenExpr:
		return c.expr(x.X)
	case *ArrayLit:
		return c.arrayLit(x)
	case *ObjectLit:
		return c.objectLit(x)
	case *FuncExpr:
		return c.funcValue(x.F, x.F.Name)
	case *ArrowFunc:
		return c.funcValue(x.F, "")
	case *ClassExpr:
		return c.classValue(x.C, x.C.Name)
	case *UnaryExpr:
		return c.unary(x)
	case *UpdateExpr:
		return c.update(x)
	case *BinaryExpr:
		return c.binary(x)
	case *LogicalExpr:
		return c.logical(x)
	case *AssignExpr:
		return c.assign(x)
	case *CondExpr:
		t := c.cond(x.Test)
		a := c.expr(x.Cons)
		b := c.expr(x.Alt)
		return func(f *Frame) Value {
			if t(f) {
				return a(f)
			}
			return b(f)
		}
	case *CallExpr:
		return c.call(x, false)
	case *NewExpr:
		return c.newExpr(x)
	case *MemberExpr:
		return c.member(x, false)
	case *OptChain:
		inner := c.chainExpr(x.X)
		return func(f *Frame) Value {
			v := inner(f)
			if v.t == TagChain {
				return Undefined
			}
			return v
		}
	case *SeqExpr:
		fns := make([]evalFn, len(x.List))
		for i, e := range x.List {
			fns[i] = c.expr(e)
		}
		return func(f *Frame) Value {
			var v Value
			for _, fn := range fns {
				v = fn(f)
			}
			return v
		}
	case *YieldExpr:
		return c.yieldExpr(x)
	case *AwaitExpr:
		e := c.expr(x.X)
		return func(f *Frame) Value {
			return awaitValue(f, e(f))
		}
	case *NewTargetExpr:
		return func(f *Frame) Value {
			if f.thisFrame == nil {
				return Undefined
			}
			return f.thisFrame.newTarget
		}
	case *ImportMetaExpr:
		mod := c.module
		return func(f *Frame) Value {
			return Obj(mod.importMeta())
		}
	case *ImportCall:
		e := c.expr(x.X)
		mod := c.module
		sf := c.sf
		return func(f *Frame) Value {
			spec := e(f)
			return dynamicImport(mod, sf, spec)
		}
	case *PrivateIn:
		get := c.refGet(x.ref)
		r := c.expr(x.R)
		pos := x.pos
		return func(f *Frame) Value {
			sym := get(f).sym()
			o := r(f)
			f.pos = pos
			if o.t != TagObj {
				throwTypeError("invalid 'in' operand")
			}
			return Bool(privateHas(o.obj(), sym))
		}
	case *Spread:
		panic(&SyntaxErr{msg: "unexpected '...'", pos: x.pos})
	case *SuperExpr:
		panic(&SyntaxErr{msg: "invalid use of 'super'", pos: x.pos})
	case *ObjPattern, *ArrPattern, *AssignPat:
		panic(&SyntaxErr{msg: "invalid destructuring target", pos: nodePos(n)})
	}
	panic("unknown expression")
}

func (c *compiler) thisExpr() evalFn {
	if c.fn.isScript || c.fn.isModule {
		if c.fn.isModule {
			return func(f *Frame) Value { return Undefined }
		}
		return func(f *Frame) Value { return f.thisFrame.this }
	}
	needCheck := false
	for fn := c.fn; fn != nil; {
		if fn.Kind == FKDerivedConstructor {
			needCheck = true
		}
		break
	}
	if c.fn.IsArrow || c.fn.isEvalCode {
		needCheck = true
	}
	if !needCheck {
		return func(f *Frame) Value { return f.this }
	}
	return func(f *Frame) Value {
		tf := f.thisFrame
		if !tf.thisInit {
			throwReferenceError("this is not initialized")
		}
		return tf.this
	}
}

func (c *compiler) templateLit(x *TemplateLit) evalFn {
	strs := x.Cooked
	exprs := make([]evalFn, len(x.Exprs))
	for i, e := range x.Exprs {
		exprs[i] = c.expr(e)
	}
	if len(exprs) == 0 {
		v := Str(strs[0])
		return constFn(v)
	}
	return func(f *Frame) Value {
		s := strs[0]
		for i, e := range exprs {
			v := e(f)
			var vs *JSString
			if v.t == TagStr {
				vs = v.str()
			} else {
				if v.t == TagSym {
					throwTypeError("cannot convert symbol to string")
				}
				vs = toString(v)
			}
			s = concatStr(s, vs)
			s = concatStr(s, strs[i+1])
		}
		return Str(s)
	}
}

func (c *compiler) taggedTemplate(x *TaggedTemplate) evalFn {
	var siteObj *Object
	tpl := x.Tpl
	getSite := func() Value {
		if siteObj == nil {
			n := len(tpl.Cooked)
			cooked := make([]Value, n)
			raws := make([]Value, n)
			for i := 0; i < n; i++ {
				if tpl.Cooked[i] == nil {
					cooked[i] = Undefined
				} else {
					cooked[i] = Str(tpl.Cooked[i])
				}
				raws[i] = Str(newStr(tpl.Raws[i]))
			}
			rawArr := newArray(raws)
			freezeObject(rawArr)
			arr := newArray(cooked)
			arr.setOwn(strKey("raw"), Obj(rawArr), 0)
			freezeObject(arr)
			siteObj = arr
		}
		return Obj(siteObj)
	}
	exprs := make([]evalFn, len(tpl.Exprs))
	for i, e := range tpl.Exprs {
		exprs[i] = c.expr(e)
	}
	pos := x.pos
	callee, thisFn := c.calleeAndThis(x.Tag)
	return func(f *Frame) Value {
		fn, this := callee(f)
		_ = thisFn
		args := make([]Value, len(exprs)+1)
		args[0] = getSite()
		for i, e := range exprs {
			args[i+1] = e(f)
		}
		f.pos = pos
		return callValue(fn, this, args)
	}
}

// returns function computing (callee, this)
func (c *compiler) calleeAndThis(n Node) (func(f *Frame) (Value, Value), bool) {
	switch x := unparen(n).(type) {
	case *MemberExpr:
		if _, ok := x.Obj.(*SuperExpr); ok {
			get := c.member(x, false)
			return func(f *Frame) (Value, Value) {
				return get(f), f.thisFrame.this
			}, true
		}
		obj := c.expr(x.Obj)
		pos := x.pos
		if x.Private {
			pget := c.refGet(x.privRef)
			return func(f *Frame) (Value, Value) {
				o := obj(f)
				f.pos = pos
				return privateGet(o, pget(f).sym()), o
			}, true
		}
		if x.Computed {
			key := c.expr(x.Prop)
			return func(f *Frame) (Value, Value) {
				o := obj(f)
				k := key(f)
				f.pos = pos
				return getMemberComputed(o, k), o
			}, true
		}
		k := strKey(x.Name)
		return func(f *Frame) (Value, Value) {
			o := obj(f)
			f.pos = pos
			return getMemberNamed(o, k), o
		}, true
	case *Ident:
		get := c.refGet(x)
		wb := c.withBase(x)
		if wb != nil {
			return func(f *Frame) (Value, Value) {
				return get(f), wb(f)
			}, true
		}
		return func(f *Frame) (Value, Value) { return get(f), Undefined }, false
	}
	e := c.expr(n)
	return func(f *Frame) (Value, Value) { return e(f), Undefined }, false
}

func (c *compiler) arrayLit(x *ArrayLit) evalFn {
	hasHole := false
	hasSpread := false
	for _, e := range x.Elems {
		if e == nil {
			hasHole = true
		} else if _, ok := e.(*Spread); ok {
			hasSpread = true
		}
	}
	if !hasHole && !hasSpread {
		fns := make([]evalFn, len(x.Elems))
		for i, e := range x.Elems {
			fns[i] = c.expr(e)
		}
		return func(f *Frame) Value {
			vals := make([]Value, len(fns))
			for i, fn := range fns {
				vals[i] = fn(f)
			}
			return Obj(newArray(vals))
		}
	}
	type el struct {
		fn     evalFn
		spread bool
		hole   bool
	}
	els := make([]el, len(x.Elems))
	for i, e := range x.Elems {
		if e == nil {
			els[i] = el{hole: true}
		} else if sp, ok := e.(*Spread); ok {
			els[i] = el{fn: c.expr(sp.X), spread: true}
		} else {
			els[i] = el{fn: c.expr(e)}
		}
	}
	return func(f *Frame) Value {
		arr := newArray(nil)
		idx := uint32(0)
		for _, e := range els {
			if e.hole {
				idx++
				continue
			}
			v := e.fn(f)
			if e.spread {
				iterateValue(v, func(item Value) bool {
					arr.defineIndex(idx, item, true)
					idx++
					return true
				})
				continue
			}
			arr.defineIndex(idx, v, true)
			idx++
		}
		if idx > arr.alen {
			arr.alen = idx
		}
		return Obj(arr)
	}
}

func propKeyFromLit(n Node, name string) PropKey {
	switch k := n.(type) {
	case *NumLit:
		return toPropertyKey(Num(k.Val))
	case *StrLit:
		return strToKey(k.Val)
	}
	return strKey(name)
}

func (c *compiler) objectLit(x *ObjectLit) evalFn {
	type prop struct {
		kind     PropKind
		key      PropKey
		keyFn    evalFn
		val      evalFn
		valDyn   func(f *Frame, name Value) Value
		method   *FuncNode
		computed bool
	}
	props := make([]prop, len(x.Props))
	simple := true
	for i, p := range x.Props {
		pr := prop{kind: p.Kind, computed: p.Computed}
		if p.Computed {
			pr.keyFn = c.expr(p.Key)
			simple = false
		} else if p.Kind != PSpread {
			pr.key = propKeyFromLit(p.Key, p.KeyName)
		}
		switch p.Kind {
		case PInit:
			if p.Computed {
				pr.valDyn = c.exprNamedDyn(p.Value)
			} else {
				pr.val = c.exprNamed(p.Value, keyToFuncName(pr.key))
			}
		case PProto:
			pr.val = c.expr(p.Value)
			simple = false
		case PSpread:
			pr.val = c.expr(p.Value)
			simple = false
		case PGet, PSet, PMethod:
			pr.method = p.Value.(*FuncExpr).F
			c.compileFunction(pr.method)
			simple = false
		}
		props[i] = pr
	}
	if simple {
		return func(f *Frame) Value {
			o := newObject()
			for i := range props {
				p := &props[i]
				v := p.val(f)
				if j := o.findOwn(p.key); j >= 0 {
					o.props[j] = Prop{v: v, flags: pDefault}
				} else {
					o.addProp(p.key, v, pDefault)
				}
			}
			return Obj(o)
		}
	}
	return func(f *Frame) Value {
		o := newObject()
		for i := range props {
			p := &props[i]
			switch p.kind {
			case PSpread:
				v := p.val(f)
				copyDataProperties(o, v, nil)
				continue
			case PProto:
				v := p.val(f)
				if v.t == TagObj {
					o.proto = v.obj()
				} else if v.t == TagNull {
					o.proto = nil
				}
				continue
			}
			key := p.key
			var keyV Value
			if p.computed {
				kv := p.keyFn(f)
				key = toPropertyKey(kv)
				keyV = key.toValue()
			}
			switch p.kind {
			case PInit:
				var v Value
				if p.computed {
					v = p.valDyn(f, keyV)
				} else {
					v = p.val(f)
				}
				createDataProp(o, key, v)
			case PMethod:
				fn := makeMethod(p.method, f, o, key, "")
				o.DefineOwnProperty(key, dataDesc(Obj(fn), pDefault), false)
			case PGet:
				fn := makeMethod(p.method, f, o, key, "get")
				o.DefineOwnProperty(key, &PropDesc{get: Obj(fn), hasGet: true, hasEnumerable: true, enumerable: true, hasConfigurable: true, configurable: true}, false)
			case PSet:
				fn := makeMethod(p.method, f, o, key, "set")
				o.DefineOwnProperty(key, &PropDesc{set: Obj(fn), hasSet: true, hasEnumerable: true, enumerable: true, hasConfigurable: true, configurable: true}, false)
			}
		}
		return Obj(o)
	}
}

func keyToFuncName(k PropKey) string {
	if k.sym != nil {
		if k.sym.desc == nil {
			return ""
		}
		return "[" + k.sym.desc.String() + "]"
	}
	return k.s
}

func makeMethod(fn *FuncNode, f *Frame, home *Object, key PropKey, prefix string) *Object {
	code := fn.compiled
	name := keyToFuncName(key)
	if prefix != "" {
		name = prefix + " " + name
	}
	o := makeClosure(code, f, home, name)
	return o
}

func (c *compiler) funcValue(fn *FuncNode, name string) evalFn {
	code := c.compileFunction(fn)
	if fn.Name != "" {
		name = fn.Name
	}
	return func(f *Frame) Value {
		return Obj(makeClosure(code, f, nil, name))
	}
}

func (c *compiler) unary(x *UnaryExpr) evalFn {
	switch x.Op {
	case "typeof":
		if id, ok := unparen(x.X).(*Ident); ok {
			g := c.refGetOpt(id, true)
			return func(f *Frame) Value { return Str(typeofStr(g(f))) }
		}
		e := c.expr(x.X)
		return func(f *Frame) Value { return Str(typeofStr(e(f))) }
	case "void":
		e := c.expr(x.X)
		return func(f *Frame) Value { e(f); return Undefined }
	case "!":
		e := c.cond(x.X)
		return func(f *Frame) Value { return Bool(!e(f)) }
	case "-":
		if nl, ok := x.X.(*NumLit); ok {
			return constFn(Num(-nl.Val))
		}
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			if v.t == TagNum {
				return Num(-v.n)
			}
			f.pos = pos
			return opNeg(v)
		}
	case "+":
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			if v.t == TagNum {
				return v
			}
			f.pos = pos
			return Num(toNumber(v))
		}
	case "~":
		e := c.expr(x.X)
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			f.pos = pos
			return opBitNot(v)
		}
	case "delete":
		return c.deleteExpr(x)
	}
	panic("bad unary")
}

var typeofStrs = map[string]*JSString{}

func typeofStr(v Value) *JSString {
	s := typeOf(v)
	js, ok := typeofStrs[s]
	if !ok {
		js = newStr(s)
		typeofStrs[s] = js
	}
	return js
}

func (c *compiler) deleteExpr(x *UnaryExpr) evalFn {
	strict := c.strict
	pos := x.pos
	switch t := unparen(x.X).(type) {
	case *MemberExpr:
		if _, ok := t.Obj.(*SuperExpr); ok {
			return func(f *Frame) Value {
				throwReferenceError("unsupported reference to 'super'")
				return Undefined
			}
		}
		obj := c.expr(t.Obj)
		if t.Computed {
			key := c.expr(t.Prop)
			return func(f *Frame) Value {
				o := obj(f)
				k := key(f)
				f.pos = pos
				return Bool(opDelete(o, k, strict))
			}
		}
		k := Str(newStr(t.Name))
		return func(f *Frame) Value {
			o := obj(f)
			f.pos = pos
			return Bool(opDelete(o, k, strict))
		}
	case *Ident:
		ref := t.ref
		if ref != nil && ref.b != nil && ref.b.scope.kind != scScript && len(ref.withs) == 0 {
			return constFn(False)
		}
		name := t.Name
		gs := []func(f *Frame) Value{}
		if ref != nil && len(ref.withs) > 0 {
			gs = c.withObjGetters(ref)
		}
		isLocal := ref != nil && ref.b != nil && ref.b.scope.kind != scScript
		return func(f *Frame) Value {
			k := strKey(name)
			for _, g := range gs {
				ov := g(f)
				if ov.t == TagObj && withHas(ov.obj(), k) {
					return Bool(ov.obj().Delete(k, false))
				}
			}
			if isLocal {
				return False
			}
			if _, ok := globalLex[name]; ok {
				return False
			}
			if GlobalObject.findOwn(k) >= 0 {
				return Bool(GlobalObject.Delete(k, false))
			}
			return True
		}
	case *OptChain:
		inner := c.chainDelete(t.X)
		return inner
	}
	e := c.expr(x.X)
	return func(f *Frame) Value {
		e(f)
		return True
	}
}

func (c *compiler) chainDelete(n Node) evalFn {
	m, ok := n.(*MemberExpr)
	if !ok {
		e := c.chainExpr(n)
		return func(f *Frame) Value { e(f); return True }
	}
	obj := c.chainExpr(m.Obj)
	strict := c.strict
	var key evalFn
	if m.Computed {
		key = c.expr(m.Prop)
	} else {
		k := Str(newStr(m.Name))
		key = constFn(k)
	}
	opt := m.Optional
	return func(f *Frame) Value {
		o := obj(f)
		if o.t == TagChain {
			return True
		}
		if opt && o.IsNullish() {
			return True
		}
		return Bool(opDelete(o, key(f), strict))
	}
}

func (c *compiler) update(x *UpdateExpr) evalFn {
	delta := 1.0
	if x.Op == "--" {
		delta = -1
	}
	prefix := x.Prefix
	pos := x.pos
	switch t := unparen(x.X).(type) {
	case *Ident:
		// fast path for local non-tdz
		ref := t.ref
		if ref != nil && ref.b != nil && !ref.b.inEnv && ref.b.scope.kind != scScript && len(ref.withs) == 0 && (ref.b.kind == bVar || ref.b.kind == bLet || ref.b.kind == bParam) && !ref.b.tdz {
			idx := ref.b.idx
			return func(f *Frame) Value {
				v := f.locals[idx]
				if v.t == TagNum {
					nv := Num(v.n + delta)
					f.locals[idx] = nv
					if prefix {
						return nv
					}
					return v
				}
				f.pos = pos
				old := toNumeric(v)
				nv := opInc(old, delta)
				f.locals[idx] = nv
				if prefix {
					return nv
				}
				return old
			}
		}
		get := c.refGet(t)
		set := c.refSet(t)
		return func(f *Frame) Value {
			v := get(f)
			f.pos = pos
			old := toNumeric(v)
			nv := opInc(old, delta)
			set(f, nv)
			if prefix {
				return nv
			}
			return old
		}
	case *MemberExpr:
		ref := c.memberRef(t)
		return func(f *Frame) Value {
			r := ref(f)
			v := r.get(f)
			f.pos = pos
			old := toNumeric(v)
			nv := opInc(old, delta)
			r.set(f, nv)
			if prefix {
				return nv
			}
			return old
		}
	case *CallExpr:
		call := c.expr(t)
		return func(f *Frame) Value {
			call(f)
			throwReferenceError("invalid increment/decrement operand")
			return Undefined
		}
	}
	panic(&SyntaxErr{msg: "invalid increment/decrement operand", pos: x.pos})
}

// memberRef evaluates object and key once, returning get/set accessors
type memberRefT struct {
	obj  Value
	key  PropKey
	keyV Value
	get  func(f *Frame) Value
	set  func(f *Frame, v Value)
}

func (c *compiler) memberRef(m *MemberExpr) func(f *Frame) *memberRefT {
	strict := c.strict
	pos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		var keyFn evalFn
		var k PropKey
		if m.Computed {
			keyFn = c.expr(m.Prop)
		} else {
			k = strKey(m.Name)
		}
		return func(f *Frame) *memberRefT {
			r := &memberRefT{}
			key := k
			if keyFn != nil {
				key = toPropertyKey(keyFn(f))
			}
			this := f.thisFrame.this
			home := f.thisFrame.homeObj
			r.get = func(f *Frame) Value {
				return superGet(home, key, this)
			}
			r.set = func(f *Frame, v Value) {
				superSet(home, key, v, this, strict)
			}
			return r
		}
	}
	obj := c.expr(m.Obj)
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) *memberRefT {
			o := obj(f)
			sym := pget(f).sym()
			r := &memberRefT{obj: o}
			r.get = func(f *Frame) Value { f.pos = pos; return privateGet(o, sym) }
			r.set = func(f *Frame, v Value) { f.pos = pos; privateSet(o, sym, v) }
			return r
		}
	}
	if m.Computed {
		keyFn := c.expr(m.Prop)
		return func(f *Frame) *memberRefT {
			o := obj(f)
			kv := keyFn(f)
			f.pos = pos
			if o.IsNullish() {
				throwTypeError("cannot read property of %s", typeOfForError(o))
			}
			k := toPropertyKey(kv)
			r := &memberRefT{obj: o, key: k}
			r.get = func(f *Frame) Value { f.pos = pos; return getMemberNamed(o, k) }
			r.set = func(f *Frame, v Value) { f.pos = pos; setMemberNamed(o, k, v, strict) }
			return r
		}
	}
	k := strKey(m.Name)
	return func(f *Frame) *memberRefT {
		o := obj(f)
		r := &memberRefT{obj: o, key: k}
		r.get = func(f *Frame) Value { f.pos = pos; return getMemberNamed(o, k) }
		r.set = func(f *Frame, v Value) { f.pos = pos; setMemberNamed(o, k, v, strict) }
		return r
	}
}

func superGet(home *Object, key PropKey, this Value) Value {
	if home == nil {
		throwSyntaxError("'super' is only valid in a method")
	}
	p := home.GetPrototypeOf()
	if p == nil {
		throwTypeError("cannot read property '%s' of null", keyDisplay(key))
	}
	return p.Get(key, this)
}

func superSet(home *Object, key PropKey, v Value, this Value, strict bool) {
	p := home.GetPrototypeOf()
	if p == nil {
		throwTypeError("cannot set property '%s' of null", keyDisplay(key))
	}
	p.Set(key, v, this, strict)
}

func (c *compiler) binary(x *BinaryExpr) evalFn {
	l := c.expr(x.L)
	r := c.expr(x.R)
	pos := x.pos
	switch x.Op {
	case "+":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n + b.n)
			}
			f.pos = pos
			return opAdd(a, b)
		}
	case "-":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n - b.n)
			}
			f.pos = pos
			return opArith(aSub, a, b)
		}
	case "*":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n * b.n)
			}
			f.pos = pos
			return opArith(aMul, a, b)
		}
	case "/":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n / b.n)
			}
			f.pos = pos
			return opArith(aDiv, a, b)
		}
	case "%":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				x, y := a.n, b.n
				if x >= 0 && y > 0 && x <= 2147483647 && y <= 2147483647 {
					xi, yi := int32(x), int32(y)
					if float64(xi) == x && float64(yi) == y {
						return Num(float64(xi % yi))
					}
				}
				return Num(jsMod(x, y))
			}
			f.pos = pos
			return opArith(aMod, a, b)
		}
	case "**":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aExp, a, b) }
	case "&":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(float64(f64ToInt32(a.n) & f64ToInt32(b.n)))
			}
			f.pos = pos
			return opArith(aAnd, a, b)
		}
	case "|":
		return func(f *Frame) Value {
			a, b := l(f), r(f)
			if a.t == TagNum && b.t == TagNum {
				return Num(float64(f64ToInt32(a.n) | f64ToInt32(b.n)))
			}
			f.pos = pos
			return opArith(aOr, a, b)
		}
	case "^":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aXor, a, b) }
	case "<<":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aShl, a, b) }
	case ">>":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aSar, a, b) }
	case ">>>":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return opArith(aShr, a, b) }
	case "==", "!=", "===", "!==", "<", ">", "<=", ">=":
		cnd := c.cond(x)
		return func(f *Frame) Value { return Bool(cnd(f)) }
	case "instanceof":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return Bool(opInstanceof(a, b)) }
	case "in":
		return func(f *Frame) Value { a, b := l(f), r(f); f.pos = pos; return Bool(opIn(a, b)) }
	}
	panic("bad binary op " + x.Op)
}

func (c *compiler) logical(x *LogicalExpr) evalFn {
	l := c.expr(x.L)
	r := c.expr(x.R)
	switch x.Op {
	case "&&":
		return func(f *Frame) Value {
			v := l(f)
			if !toBool(v) {
				return v
			}
			return r(f)
		}
	case "||":
		return func(f *Frame) Value {
			v := l(f)
			if toBool(v) {
				return v
			}
			return r(f)
		}
	case "??":
		return func(f *Frame) Value {
			v := l(f)
			if !v.IsNullish() {
				return v
			}
			return r(f)
		}
	}
	panic("bad logical")
}

func arithOpFor(op string) (arithOp, bool) {
	switch op {
	case "-=":
		return aSub, true
	case "*=":
		return aMul, true
	case "/=":
		return aDiv, true
	case "%=":
		return aMod, true
	case "**=":
		return aExp, true
	case "&=":
		return aAnd, true
	case "|=":
		return aOr, true
	case "^=":
		return aXor, true
	case "<<=":
		return aShl, true
	case ">>=":
		return aSar, true
	case ">>>=":
		return aShr, true
	}
	return 0, false
}

func compoundOp(op string, pos int) func(f *Frame, a, b Value) Value {
	if op == "+=" {
		return func(f *Frame, a, b Value) Value {
			if a.t == TagNum && b.t == TagNum {
				return Num(a.n + b.n)
			}
			f.pos = pos
			return opAdd(a, b)
		}
	}
	aop, ok := arithOpFor(op)
	if !ok {
		panic("bad compound op " + op)
	}
	return func(f *Frame, a, b Value) Value {
		if a.t == TagNum && b.t == TagNum && aop <= aDiv {
			switch aop {
			case aSub:
				return Num(a.n - b.n)
			case aMul:
				return Num(a.n * b.n)
			case aDiv:
				return Num(a.n / b.n)
			}
		}
		f.pos = pos
		return opArith(aop, a, b)
	}
}

func (c *compiler) assign(x *AssignExpr) evalFn {
	pos := x.pos
	target := unparen(x.L)
	if x.Op == "=" {
		switch t := target.(type) {
		case *Ident:
			v := c.exprNamed(x.R, t.Name)
			set := c.refSet(t)
			return func(f *Frame) Value {
				val := v(f)
				f.pos = pos
				set(f, val)
				return val
			}
		case *MemberExpr:
			return c.memberAssign(t, x.R, pos)
		case *ObjPattern, *ArrPattern:
			v := c.expr(x.R)
			bind := c.assignPattern(t)
			return func(f *Frame) Value {
				val := v(f)
				bind(f, val)
				return val
			}
		case *CallExpr:
			call := c.expr(t)
			v := c.expr(x.R)
			return func(f *Frame) Value {
				call(f)
				v(f)
				throwReferenceError("invalid assignment left-hand side")
				return Undefined
			}
		}
		panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
	}
	// logical assignment
	if x.Op == "&&=" || x.Op == "||=" || x.Op == "??=" {
		op := x.Op
		test := func(v Value) bool {
			switch op {
			case "&&=":
				return toBool(v)
			case "||=":
				return !toBool(v)
			}
			return v.IsNullish()
		}
		switch t := target.(type) {
		case *Ident:
			get := c.refGet(t)
			set := c.refSet(t)
			v := c.exprNamed(x.R, t.Name)
			return func(f *Frame) Value {
				cur := get(f)
				if !test(cur) {
					return cur
				}
				nv := v(f)
				f.pos = pos
				set(f, nv)
				return nv
			}
		case *MemberExpr:
			ref := c.memberRef(t)
			v := c.expr(x.R)
			return func(f *Frame) Value {
				r := ref(f)
				cur := r.get(f)
				if !test(cur) {
					return cur
				}
				nv := v(f)
				r.set(f, nv)
				return nv
			}
		}
		panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
	}
	opf := compoundOp(x.Op, pos)
	switch t := target.(type) {
	case *Ident:
		ref := t.ref
		v := c.expr(x.R)
		if ref != nil && ref.b != nil && !ref.b.inEnv && ref.b.scope.kind != scScript && len(ref.withs) == 0 && (ref.b.kind == bVar || ref.b.kind == bLet || ref.b.kind == bParam) && !ref.b.tdz {
			idx := ref.b.idx
			return func(f *Frame) Value {
				cur := f.locals[idx]
				rv := v(f)
				nv := opf(f, cur, rv)
				f.locals[idx] = nv
				return nv
			}
		}
		get := c.refGet(t)
		set := c.refSet(t)
		return func(f *Frame) Value {
			cur := get(f)
			rv := v(f)
			nv := opf(f, cur, rv)
			f.pos = pos
			set(f, nv)
			return nv
		}
	case *MemberExpr:
		ref := c.memberRef(t)
		v := c.expr(x.R)
		return func(f *Frame) Value {
			r := ref(f)
			cur := r.get(f)
			rv := v(f)
			nv := opf(f, cur, rv)
			r.set(f, nv)
			return nv
		}
	case *CallExpr:
		call := c.expr(t)
		return func(f *Frame) Value {
			call(f)
			throwReferenceError("invalid assignment left-hand side")
			return Undefined
		}
	}
	panic(&SyntaxErr{msg: "invalid assignment left-hand side", pos: pos})
}

func (c *compiler) memberAssign(m *MemberExpr, rhs Node, pos int) evalFn {
	strict := c.strict
	mpos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		ref := c.memberRef(m)
		v := c.expr(rhs)
		return func(f *Frame) Value {
			r := ref(f)
			val := v(f)
			r.set(f, val)
			return val
		}
	}
	obj := c.expr(m.Obj)
	v := c.expr(rhs)
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) Value {
			o := obj(f)
			val := v(f)
			f.pos = mpos
			privateSet(o, pget(f).sym(), val)
			return val
		}
	}
	if m.Computed {
		key := c.expr(m.Prop)
		return func(f *Frame) Value {
			o := obj(f)
			k := key(f)
			val := v(f)
			f.pos = mpos
			setMemberComputed(o, k, val, strict)
			return val
		}
	}
	k := strKey(m.Name)
	return func(f *Frame) Value {
		o := obj(f)
		val := v(f)
		f.pos = mpos
		if o.t == TagObj {
			ob := o.obj()
			if ob.class == ClassObject {
				i := ob.findOwn(k)
				if i >= 0 && ob.props[i].flags&(pAccessor|pWritable) == pWritable {
					ob.props[i].v = val
					return val
				}
			}
			ob.Set(k, val, o, strict)
			return val
		}
		setMemberNamed(o, k, val, strict)
		return val
	}
}

// ---------- member access ----------

func (c *compiler) member(m *MemberExpr, inChain bool) evalFn {
	pos := m.pos
	if _, ok := m.Obj.(*SuperExpr); ok {
		var keyFn evalFn
		var k PropKey
		if m.Computed {
			keyFn = c.expr(m.Prop)
		} else {
			k = strKey(m.Name)
		}
		return func(f *Frame) Value {
			key := k
			if keyFn != nil {
				key = toPropertyKey(keyFn(f))
			}
			tf := f.thisFrame
			if !tf.thisInit {
				throwReferenceError("this is not initialized")
			}
			return superGet(tf.homeObj, key, tf.this)
		}
	}
	var obj evalFn
	if inChain {
		obj = c.chainExpr(m.Obj)
	} else {
		obj = c.expr(m.Obj)
	}
	opt := m.Optional
	if m.Private {
		pget := c.refGet(m.privRef)
		return func(f *Frame) Value {
			o := obj(f)
			if inChain {
				if o.t == TagChain || (opt && o.IsNullish()) {
					return chainBreak
				}
			}
			f.pos = pos
			return privateGet(o, pget(f).sym())
		}
	}
	if m.Computed {
		key := c.expr(m.Prop)
		if inChain {
			return func(f *Frame) Value {
				o := obj(f)
				if o.t == TagChain || (opt && o.IsNullish()) {
					return chainBreak
				}
				k := key(f)
				f.pos = pos
				return getMemberComputed(o, k)
			}
		}
		return func(f *Frame) Value {
			o := obj(f)
			k := key(f)
			f.pos = pos
			return getMemberComputed(o, k)
		}
	}
	k := strKey(m.Name)
	if inChain {
		return func(f *Frame) Value {
			o := obj(f)
			if o.t == TagChain || (opt && o.IsNullish()) {
				return chainBreak
			}
			f.pos = pos
			return getMemberNamed(o, k)
		}
	}
	if m.Name == "length" {
		return func(f *Frame) Value {
			o := obj(f)
			if o.t == TagObj && o.obj().class == ClassArray {
				return Num(float64(o.obj().alen))
			}
			if o.t == TagStr {
				return Int(o.str().n)
			}
			f.pos = pos
			return getMemberNamed(o, k)
		}
	}
	return func(f *Frame) Value {
		o := obj(f)
		if o.t == TagObj {
			ob := o.obj()
			if ob.class == ClassObject {
				i := ob.findOwn(k)
				if i >= 0 && ob.props[i].flags&pAccessor == 0 {
					return ob.props[i].v
				}
			}
			f.pos = pos
			return ob.Get(k, o)
		}
		f.pos = pos
		return getMemberNamed(o, k)
	}
}

// compile expression inside optional chain
func (c *compiler) chainExpr(n Node) evalFn {
	switch x := n.(type) {
	case *MemberExpr:
		return c.member(x, true)
	case *CallExpr:
		return c.call(x, true)
	}
	return c.expr(n)
}

// ---------- calls ----------

func (c *compiler) args(list []Node) func(f *Frame) []Value {
	if len(list) == 0 {
		return func(f *Frame) []Value { return nil }
	}
	hasSpread := false
	for _, a := range list {
		if _, ok := a.(*Spread); ok {
			hasSpread = true
		}
	}
	if !hasSpread {
		fns := make([]evalFn, len(list))
		for i, a := range list {
			fns[i] = c.expr(a)
		}
		switch len(fns) {
		case 1:
			a0 := fns[0]
			return func(f *Frame) []Value { return []Value{a0(f)} }
		case 2:
			a0, a1 := fns[0], fns[1]
			return func(f *Frame) []Value {
				v0 := a0(f)
				return []Value{v0, a1(f)}
			}
		}
		return func(f *Frame) []Value {
			args := make([]Value, len(fns))
			for i, fn := range fns {
				args[i] = fn(f)
			}
			return args
		}
	}
	type ae struct {
		fn     evalFn
		spread bool
	}
	els := make([]ae, len(list))
	for i, a := range list {
		if sp, ok := a.(*Spread); ok {
			els[i] = ae{c.expr(sp.X), true}
		} else {
			els[i] = ae{c.expr(a), false}
		}
	}
	return func(f *Frame) []Value {
		var args []Value
		for _, e := range els {
			v := e.fn(f)
			if e.spread {
				iterateValue(v, func(item Value) bool {
					args = append(args, item)
					return true
				})
			} else {
				args = append(args, v)
			}
		}
		return args
	}
}

func doCall(f *Frame, pos int, fn Value, this Value, args []Value) Value {
	f.pos = pos
	if fn.t != TagObj {
		throwTypeError("not a function")
	}
	o := fn.obj()
	if o.class == ClassFunction {
		return callClosure(o, o.internal.(*Closure), this, args, nil)
	}
	return callFunc(o, this, args)
}

func (c *compiler) call(x *CallExpr, inChain bool) evalFn {
	pos := x.pos
	if x.tail {
		pos = x.retPos
	}
	args := c.args(x.Args)
	opt := x.Optional
	callee := unparen(x.Callee)
	if _, ok := callee.(*SuperExpr); ok {
		return c.superCall(x, args)
	}
	if m, ok := callee.(*MemberExpr); ok && x.Callee == callee {
		if _, isSuper := m.Obj.(*SuperExpr); isSuper {
			get := c.member(m, false)
			return func(f *Frame) Value {
				fn := get(f)
				a := args(f)
				return doCall(f, pos, fn, f.thisFrame.this, a)
			}
		}
		var obj evalFn
		if inChain {
			obj = c.chainExpr(m.Obj)
		} else {
			obj = c.expr(m.Obj)
		}
		mopt := m.Optional
		mpos := m.pos
		if m.Private {
			pget := c.refGet(m.privRef)
			return func(f *Frame) Value {
				o := obj(f)
				if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
					return chainBreak
				}
				f.pos = mpos
				fn := privateGet(o, pget(f).sym())
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, o, a)
			}
		}
		if m.Computed {
			key := c.expr(m.Prop)
			return func(f *Frame) Value {
				o := obj(f)
				if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
					return chainBreak
				}
				k := key(f)
				f.pos = mpos
				fn := getMemberComputed(o, k)
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, o, a)
			}
		}
		k := strKey(m.Name)
		return func(f *Frame) Value {
			o := obj(f)
			if inChain && (o.t == TagChain || (mopt && o.IsNullish())) {
				return chainBreak
			}
			f.pos = mpos
			var fn Value
			if o.t == TagObj {
				fn = o.obj().Get(k, o)
			} else {
				fn = getMemberNamed(o, k)
			}
			if opt && fn.IsNullish() {
				return chainBreak
			}
			a := args(f)
			return doCall(f, pos, fn, o, a)
		}
	}
	if id, ok := callee.(*Ident); ok {
		get := c.refGet(id)
		wb := c.withBase(id)
		if x.isEval {
			evalScope := x.evalScope
			strict := c.strict
			parentC := c
			return func(f *Frame) Value {
				fn := get(f)
				a := args(f)
				if fn.t == TagObj && fn.obj() == EvalFunction {
					f.pos = pos
					return directEval(f, arg(a, 0), evalScope, strict, parentC)
				}
				this := Undefined
				if wb != nil {
					this = wb(f)
				}
				return doCall(f, pos, fn, this, a)
			}
		}
		if wb != nil {
			return func(f *Frame) Value {
				fn := get(f)
				this := wb(f)
				if opt && fn.IsNullish() {
					return chainBreak
				}
				a := args(f)
				return doCall(f, pos, fn, this, a)
			}
		}
		return func(f *Frame) Value {
			fn := get(f)
			if opt && fn.IsNullish() {
				return chainBreak
			}
			a := args(f)
			return doCall(f, pos, fn, Undefined, a)
		}
	}
	var fnE evalFn
	if inChain {
		fnE = c.chainExpr(x.Callee)
	} else {
		fnE = c.expr(x.Callee)
	}
	return func(f *Frame) Value {
		fn := fnE(f)
		if inChain && fn.t == TagChain {
			return chainBreak
		}
		if opt && fn.IsNullish() {
			return chainBreak
		}
		a := args(f)
		return doCall(f, pos, fn, Undefined, a)
	}
}

func (c *compiler) superCall(x *CallExpr, args func(f *Frame) []Value) evalFn {
	pos := x.pos
	return func(f *Frame) Value {
		a := args(f)
		tf := f.thisFrame
		active := tf.fobj
		parent := active.GetPrototypeOf()
		f.pos = pos
		if parent == nil || !parent.isConstructor() {
			throwTypeError("parent class must be constructor")
		}
		nt := tf.newTarget
		var ntObj *Object
		if nt.t == TagObj {
			ntObj = nt.obj()
		}
		r := construct(parent, a, ntObj)
		if tf.thisInit {
			throwReferenceError("'this' can be initialized only once")
		}
		tf.this = r
		tf.thisInit = true
		cl := active.internal.(*Closure)
		if cl.classDef != nil && r.t == TagObj {
			initInstanceElements(r.obj(), active, cl)
		}
		return r
	}
}

func (c *compiler) newExpr(x *NewExpr) evalFn {
	callee := c.expr(x.Callee)
	args := c.args(x.Args)
	pos := x.pos
	return func(f *Frame) Value {
		fn := callee(f)
		a := args(f)
		f.pos = pos
		return constructValue(fn, a, nil)
	}
}

// ---------- yield ----------

func (c *compiler) yieldExpr(x *YieldExpr) evalFn {
	var e evalFn
	if x.X != nil {
		e = c.expr(x.X)
	} else {
		e = constFn(Undefined)
	}
	isAsync := c.fn.IsAsync
	if x.Delegate {
		pos := x.pos
		return func(f *Frame) Value {
			v := e(f)
			f.pos = pos
			return yieldDelegate(f, v, isAsync)
		}
	}
	return func(f *Frame) Value {
		v := e(f)
		if isAsync {
			return asyncGenYield(f, v)
		}
		return generatorYield(f, v)
	}
}

