// bindPattern returns a binder storing v into the pattern targets.
// isDecl: initialize declared bindings (let/const/param/catch/var)
func (c *compiler) bindPattern(n Node, isDecl bool) func(f *Frame, v Value) {
	switch x := n.(type) {
	case *Ident:
		if isDecl {
			return c.refInit(x)
		}
