			ref := c.memberRef(x)
			return func(f *Frame, v Value) {
				ref(f).set(f, v)
			}
		}
		obj := c.expr(x.Obj)
		pos := x.pos
		if x.Private {
			pget := c.refGet(x.privRef)
			return func(f *Frame, v Value) {
				o := obj(f)
				f.pos = pos
				privateSet(o, pget(f).sym(), v)
			}
		}
		if x.Computed {
			key := c.expr(x.Prop)
			return func(f *Frame, v Value) {
				o := obj(f)
				k := key(f)
				f.pos = pos
				setMemberComputed(o, k, v, strict)
			}
		}
		k := strKey(x.Name)
		return func(f *Frame, v Value) {
			o := obj(f)
			f.pos = pos
			setMemberNamed(o, k, v, strict)
		}
	case *AssignPat:
		var def evalFn
		if id, ok := unparen(x.Target).(*Ident); ok {
			def = c.exprNamed(x.Default, id.Name)
		} else {
			def = c.expr(x.Default)
		}
		target := c.bindPattern(x.Target, isDecl)
		return func(f *Frame, v Value) {
			if v.t == TagUndef {
				v = def(f)
			}
			target(f, v)
		}
	case *ObjPattern:
		return c.objPattern(x, isDecl)
	case *ArrPattern:
		return c.arrPattern(x, isDecl)
	case *CallExpr:
		call := c.expr(x)
		return func(f *Frame, v Value) {
