func (c *compiler) objPattern(x *ObjPattern, isDecl bool) func(f *Frame, v Value) {
	type pp struct {
		key      PropKey
		keyFn    evalFn
		computed bool
		target   func(f *Frame, v Value)
		// for target with default where we need name
	}
	props := make([]pp, len(x.Props))
	for i, p := range x.Props {
		e := pp{computed: p.Computed}
		if p.Computed {
			e.keyFn = c.expr(p.Key)
		} else {
			e.key = propKeyFromLit(p.Key, p.KeyName)
		}
		e.target = c.bindPattern(p.Value, isDecl)
		props[i] = e
	}
	var rest func(f *Frame, v Value)
	if x.Rest != nil {
		rest = c.bindPattern(x.Rest, isDecl)
	}
	return func(f *Frame, v Value) {
		if v.t == TagUndef || v.t == TagNull {
			throwTypeError("cannot convert to object")
		}
		var used []PropKey
