func (c *compiler) arrPattern(x *ArrPattern, isDecl bool) func(f *Frame, v Value) {
	elems := make([]func(f *Frame, v Value), len(x.Elems))
	for i, e := range x.Elems {
		if e != nil {
			elems[i] = c.bindPattern(e, isDecl)
		}
	}
	var rest func(f *Frame, v Value)
	if x.Rest != nil {
		rest = c.bindPattern(x.Rest, isDecl)
	}
	return func(f *Frame, v Value) {
		if v.t == TagObj && v.obj().fastArr && v.obj().class == ClassArray && arrayIteratorPristine(v.obj()) {
			arr := v.obj()
			for i, el := range elems {
				var item Value
				if i < len(arr.arr) {
					item = arr.arr[i]
				} else {
