				}
				if el != nil {
					el(f, item)
				}
			}
			if rest != nil {
				var vals []Value
				if len(elems) < len(arr.arr) {
					vals = make([]Value, len(arr.arr)-len(elems))
					copy(vals, arr.arr[len(elems):])
				}
				rest(f, Obj(newArray(vals)))
			}
			return
		}
		it := getIterator(v)
		done := false
		completed := false
		defer func() {
			if !completed && !done {
				if r := recover(); r != nil {
					iteratorCloseOnThrow(f, it, false)
					panic(r)
				}
			}
		}()
		for _, el := range elems {
			item := Undefined
			if !done {
				var ok bool
				func() {
					// errors from next() must not close
					d := done
					done = true
					item, ok = it.step()
					done = d
				}()
				if !ok {
					done = true
					item = Undefined
				}
			}
			if el != nil {
				el(f, item)
			}
		}
		if rest != nil {
			var vals []Value
			for !done {
				var item Value
				var ok bool
				func() {
					d := done
					done = true
					item, ok = it.step()
					done = d
				}()
				if !ok {
					done = true
					break
				}
				vals = append(vals, item)
			}
			rest(f, Obj(newArray(vals)))
		}
		completed = true
		if !done {
			it.close()
		}
	}
}
