package main

type PrivInfo struct {
	kind   int // 1 method, 2 getter, 3 setter, 4 accessor
	method *Object
	getter *Object
	setter *Object
	brand  *Symbol
}

func makeClosure(code *FuncCode, f *Frame, home *Object, name string) *Object {
	cl := &Closure{code: code, env: f.env, homeObject: home}
	if code.isArrow {
		cl.thisFrame = f.thisFrame
	}
	var proto *Object
	switch {
	case code.isAsync && code.isGen:
		proto = AsyncGeneratorFunctionPrototype
	case code.isGen:
		proto = GeneratorFunctionPrototype
	case code.isAsync:
		proto = AsyncFunctionPrototype
	default:
		proto = FunctionPrototype
	}
	o := &Object{proto: proto, class: ClassFunction, extensible: true, internal: cl}
	o.keys = make([]PropKey, 0, 3)
	o.props = make([]Prop, 0, 3)
	o.addProp(keyLength, Int(code.length), pConfigurable)
	o.addProp(keyName, Str(newStr(name)), pConfigurable)
	if code.isGen {
		var pp *Object
		if code.isAsync {
			pp = newObjectProto(AsyncGeneratorPrototype, ClassObject)
		} else {
			pp = newObjectProto(GeneratorPrototype, ClassObject)
		}
		o.addProp(keyPrototype, Obj(pp), pWritable)
	} else if code.isCtor && !code.isClassCtor {
		p := newObject()
		p.addProp(keyConstructor, Obj(o), pWritable|pConfigurable)
		o.addProp(keyPrototype, Obj(p), pWritable)
	}
	return o
}

var (
	keyLength      = strKey("length")
	keyName        = strKey("name")
	keyPrototype   = strKey("prototype")
	keyConstructor = strKey("constructor")
)

func setFunctionName(o *Object, name Value, prefix string) {
	var s *JSString
	if name.t == TagSym {
		sym := name.sym()
		if sym.desc == nil {
			s = emptyStr
		} else {
			s = concatStr(concatStr(newStrASCII("["), sym.desc), newStrASCII("]"))
		}
	} else {
		s = toString(name)
	}
	if prefix != "" {
		s = concatStr(newStr(prefix+" "), s)
	}
	o.setOwn(keyName, Str(s), pConfigurable)
}

type classMemberC struct {
	m        *ClassMember
	keyFn    evalFn
	key      PropKey
	code     *FuncCode
	privSet  func(f *Frame, v Value)
	privGet  func(f *Frame) Value
	isAnon   bool
}

func (c *compiler) classValue(cn *ClassNode, name string) evalFn {
	cs := cn.scope
	save := c.scope
	enter := c.scopeEnter(cs)
	needsEnv := cs.needsEnv
	c.scope = cs
	var superFn evalFn
	if cn.Super != nil {
		superFn = c.expr(cn.Super)
	}
	if cn.Name != "" {
		name = cn.Name
	}
	var ctorCode *FuncCode
	if cn.Ctor != nil {
		ctorCode = c.compileFunction(cn.Ctor)
	} else {
		ctorCode = &FuncCode{name: name, isCtor: true, isClassCtor: true, derived: cn.HasSuper, strict: true, src: c.sf, module: c.module, cost: 900}
		ctorCode.prologue = func(f *Frame) {}
		if cn.HasSuper {
			ctorCode.body = func(f *Frame) ctrl {
				parent := f.fobj.GetPrototypeOf()
				if parent == nil || !parent.isConstructor() {
					throwTypeError("parent class must be constructor")
				}
				var nt *Object
				if f.newTarget.t == TagObj {
					nt = f.newTarget.obj()
				}
				r := construct(parent, f.args, nt)
				f.this = r
				f.thisInit = true
				cl := f.fobj.internal.(*Closure)
				if cl.classDef != nil && r.t == TagObj {
					initInstanceElements(r.obj(), f.fobj, cl)
				}
				return cNormal
			}
		} else {
			ctorCode.body = func(f *Frame) ctrl { return cNormal }
		}
	}
	ctorCode.classNode = cn
	ctorCode.length = 0
	if cn.Ctor != nil {
		ctorCode.length = cn.Ctor.length
	}
	members := make([]*classMemberC, len(cn.Members))
	for i, m := range cn.Members {
		mc := &classMemberC{m: m}
		if m.Computed {
			mc.keyFn = c.expr(m.Key)
		} else if !m.Private {
			mc.key = propKeyFromLit(m.Key, m.KeyName)
		}
		if m.Value != nil {
			if m.Kind == "field" && m.Value.ExprBody != nil {
				mc.isAnon = isAnonFn(m.Value.ExprBody)
			}
			mc.code = c.compileFunction(m.Value)
		}
		if m.Private {
			mc.privSet = c.bindingInit(m.privB)
			mc.privGet = c.bindingGetRaw(m.privB)
		}
		members[i] = mc
	}
	var innerSet func(f *Frame, v Value)
	if cn.nameB != nil {
		innerSet = c.bindingInit(cn.nameB)
	}
	var brandSet func(f *Frame, v Value)
	if cn.brandB != nil {
		brandSet = c.bindingInit(cn.brandB)
	}
	// private name bindings to create
	type privDecl struct {
		set  func(f *Frame, v Value)
		name string
		kind int
	}
	var privs []privDecl
	seen := map[*Binding]bool{}
	for _, m := range cn.Members {
		if m.Private && !seen[m.privB] {
			seen[m.privB] = true
			privs = append(privs, privDecl{set: c.bindingInit(m.privB), name: m.KeyName, kind: m.privB.privKind})
		}
	}
	c.scope = save
	hasSuper := cn.HasSuper
	pos := cn.pos
	return func(f *Frame) Value {
		saveEnv := f.env
		if enter != nil {
			enter(f)
		}
		var brand *Symbol
		if brandSet != nil {
			brand = &Symbol{desc: newStr("<brand>"), private: true, brand: true}
			brandSet(f, Sym(brand))
		}
		for _, p := range privs {
			sym := &Symbol{desc: newStr(p.name), private: true}
			if p.kind != 0 {
				sym.priv = &PrivInfo{kind: p.kind, brand: brand}
			}
			p.set(f, Sym(sym))
		}
		protoParent := ObjectPrototype
		ctorParent := FunctionPrototype
		if hasSuper {
			sv := superFn(f)
			f.pos = pos
			if sv.t == TagNull {
				protoParent = nil
			} else {
				if !isConstructor(sv) {
					throwTypeError("parent class must be constructor")
				}
				pp := getV(sv, keyPrototype)
				if pp.t == TagObj {
					protoParent = pp.obj()
				} else if pp.t == TagNull {
					protoParent = nil
				} else {
					throwTypeError("parent prototype must be an object or null")
				}
				ctorParent = sv.obj()
			}
		}
		proto := newObjectProto(protoParent, ClassObject)
		cl := &Closure{code: ctorCode, env: f.env, homeObject: proto}
		F := &Object{proto: ctorParent, class: ClassFunction, extensible: true, internal: cl}
		F.addProp(keyLength, Int(ctorCode.length), pConfigurable)
		F.addProp(keyName, Str(newStr(name)), pConfigurable)
		F.addProp(keyPrototype, Obj(proto), 0)
		proto.addProp(keyConstructor, Obj(F), pWritable|pConfigurable)
		cdef := &ClassDef{}
		if brand != nil && cn.hasPrivMethods {
			cdef.brand = brand
		}
		type staticInit struct {
			field *fieldDef
			block *Object
		}
		var statics []staticInit
		for _, mc := range members {
			m := mc.m
			target := proto
			if m.Static {
				target = F
			}
			key := mc.key
			var keyV Value
			if mc.keyFn != nil {
				key = toPropertyKey(mc.keyFn(f))
				keyV = key.toValue()
			}
			_ = keyV
			switch m.Kind {
			case "method", "get", "set":
				prefix := ""
				if m.Kind != "method" {
					prefix = m.Kind
				}
				var fn *Object
				if m.Private {
					fn = makeClosure(mc.code, f, target, prefix)
					nm := m.KeyName
					if prefix != "" {
						nm = prefix + " " + nm
					}
					fn.setOwn(keyName, Str(newStr(nm)), pConfigurable)
					sym := mc.privGet(f).sym()
					switch m.Kind {
					case "method":
						sym.priv.method = fn
					case "get":
						sym.priv.getter = fn
					case "set":
						sym.priv.setter = fn
					}
					continue
				}
				fn = makeMethod(mc.m.Value, f, target, key, prefix)
				if m.Kind == "method" {
					target.DefineOwnProperty(key, dataDesc(Obj(fn), pWritable|pConfigurable), true)
				} else if m.Kind == "get" {
					target.DefineOwnProperty(key, &PropDesc{get: Obj(fn), hasGet: true, hasEnumerable: true, hasConfigurable: true, configurable: true}, true)
				} else {
					target.DefineOwnProperty(key, &PropDesc{set: Obj(fn), hasSet: true, hasEnumerable: true, hasConfigurable: true, configurable: true}, true)
				}
			case "field":
				fd := &fieldDef{key: key, isAnon: mc.isAnon}
				if m.Private {
					fd.priv = mc.privGet(f).sym()
				}
				if mc.code != nil {
					fd.init = makeClosure(mc.code, f, target, "<field_init>")
				}
				if m.Static {
					statics = append(statics, staticInit{field: fd})
				} else {
					cdef.fields = append(cdef.fields, fd)
				}
			case "static-block":
				blk := makeClosure(mc.code, f, F, "<static_initializer>")
				statics = append(statics, staticInit{block: blk})
			}
		}
		cl.classDef = cdef
		if innerSet != nil {
			innerSet(f, Obj(F))
		}
		if brand != nil && cn.hasStaticPrivMethods {
			F.addProp(PropKey{sym: brand}, Undefined, pDefault)
		}
		for _, s := range statics {
			if s.block != nil {
				callFunc(s.block, Obj(F), nil)
				continue
			}
			defineField(F, s.field)
		}
		if needsEnv {
			f.env = saveEnv
		}
		return Obj(F)
	}
}

func defineField(obj *Object, fd *fieldDef) {
	v := Undefined
	if fd.init != nil {
		v = callFunc(fd.init, Obj(obj), nil)
		if fd.isAnon && v.t == TagObj {
			if fd.priv != nil {
				setFunctionName(v.obj(), Str(fd.priv.desc), "")
			} else {
				setFunctionName(v.obj(), fd.key.toValue(), "")
			}
		}
	}
	if fd.priv != nil {
		k := PropKey{sym: fd.priv}
		if obj.findOwn(k) >= 0 {
			throwTypeError("private class field is already defined")
		}
		if obj.class == ClassProxy {
			throwTypeError("cannot define private field on proxy")
		}
		obj.addProp(k, v, pDefault)
		return
	}
	if !obj.DefineOwnProperty(fd.key, dataDesc(v, pDefault), false) {
		throwTypeError("cannot define property '%s'", keyDisplay(fd.key))
	}
}

func initInstanceElements(obj *Object, F *Object, cl *Closure) {
	cd := cl.classDef
	if cd == nil {
		return
	}
	if cd.brand != nil {
		k := PropKey{sym: cd.brand}
		if obj.findOwn(k) >= 0 {
			throwTypeError("private method is already present")
		}
		obj.addProp(k, Undefined, pDefault)
	}
	for _, fd := range cd.fields {
		defineField(obj, fd)
	}
}

func privateHas(o *Object, sym *Symbol) bool {
	if sym.priv != nil {
		return o.findOwn(PropKey{sym: sym.priv.brand}) >= 0
	}
	return o.findOwn(PropKey{sym: sym}) >= 0
}

func privateGet(v Value, sym *Symbol) Value {
	if v.t != TagObj {
		throwTypeError("not an object")
	}
	o := v.obj()
	if pi := sym.priv; pi != nil {
		if o.findOwn(PropKey{sym: pi.brand}) < 0 {
			throwTypeError("invalid brand on object")
		}
		switch pi.kind {
		case 1:
			return Obj(pi.method)
		default:
			if pi.getter == nil {
				throwTypeError("no getter for private field")
			}
			return callFunc(pi.getter, v, nil)
		}
	}
	i := o.findOwn(PropKey{sym: sym})
	if i < 0 {
		throwTypeError("private class field '%s' does not exist", sym.desc.String())
	}
	return o.props[i].v
}

func privateSet(v Value, sym *Symbol, val Value) {
	if v.t != TagObj {
		throwTypeError("not an object")
	}
	o := v.obj()
	if pi := sym.priv; pi != nil {
		if o.findOwn(PropKey{sym: pi.brand}) < 0 {
			throwTypeError("invalid brand on object")
		}
		switch pi.kind {
		case 1:
			throwTypeError("private method is read-only")
		default:
			if pi.setter == nil {
				throwTypeError("no setter for private field")
			}
			callFunc(pi.setter, v, []Value{val})
			return
		}
	}
	i := o.findOwn(PropKey{sym: sym})
	if i < 0 {
		throwTypeError("private class field '%s' does not exist", sym.desc.String())
	}
	o.props[i].v = val
}
