type AsyncGenState struct {
	co    *Coroutine
	frame *Frame
	code  *FuncCode
	state int
	queue []*agRequest
}

func asyncGenEnqueue(this Value, kind int, v Value) Value {
	cap := newPromiseCap()
	if this.t != TagObj || this.obj().class != ClassAsyncGenerator {
		cap.reject(Obj(makeError(TypeErrorPrototype, "not an AsyncGenerator object")))
		return Obj(cap.promise)
	}
	ag := this.obj().internal.(*AsyncGenState)
	ag.queue = append(ag.queue, &agRequest{kind: kind, v: v, cap: cap})
	if ag.state != agExecuting && ag.state != agAwaitingReturn {
		ag.resumeNext()
	}
	return Obj(cap.promise)
}

func (ag *AsyncGenState) dequeue() *agRequest {
	r := ag.queue[0]
	ag.queue = ag.queue[1:]
	return r
}

func (ag *AsyncGenState) resumeNext() {
	for len(ag.queue) > 0 {
		if ag.state == agExecuting || ag.state == agAwaitingReturn {
			return
		}
		req := ag.queue[0]
		if req.kind == coReturn || req.kind == coThrow {
