func asyncGenEnqueue(this Value, kind int, v Value) Value {
	cap := newPromiseCap()
	if this.t != TagObj || this.obj().class != ClassAsyncGenerator {
		cap.reject(Obj(makeError(TypeErrorPrototype, "not an AsyncGenerator object")))
		return Obj(cap.promise)
	}
