package main

import (
	"math"
	"math/big"
	"strconv"
	"strings"
)

func numberToGoString(f float64) string {
	if f != f {
		return "NaN"
	}
	if f == 0 {
		return "0"
	}
	if math.IsInf(f, 1) {
		return "Infinity"
	}
	if math.IsInf(f, -1) {
		return "-Infinity"
	}
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return strconv.FormatInt(int64(f), 10)
	}
	neg := f < 0
	if neg {
		f = -f
	}
	// shortest repr digits
	s := strconv.FormatFloat(f, 'e', -1, 64)
	// s like d.ddddde+XX
	mant := s
	exp := 0
	if i := strings.IndexByte(s, 'e'); i >= 0 {
		mant = s[:i]
		exp, _ = strconv.Atoi(s[i+1:])
	}
	digits := strings.Replace(mant, ".", "", 1)
	k := len(digits)
	n := exp + 1
	var out string
	if k <= n && n <= 21 {
		out = digits + strings.Repeat("0", n-k)
	} else if 0 < n && n <= 21 {
		out = digits[:n] + "." + digits[n:]
	} else if -6 < n && n <= 0 {
		out = "0." + strings.Repeat("0", -n) + digits
	} else {
		e := n - 1
		sign := "+"
		if e < 0 {
			sign = "-"
			e = -e
		}
		if k == 1 {
			out = digits + "e" + sign + strconv.Itoa(e)
		} else {
			out = digits[:1] + "." + digits[1:] + "e" + sign + strconv.Itoa(e)
		}
	}
	if neg {
		return "-" + out
	}
	return out
}

