package main

func toPropertyDescriptor(v Value) *PropDesc {
	if v.t != TagObj {
		throwTypeError("not an object")
	}
	o := v.obj()
	d := &PropDesc{}
	if o.HasProperty(strKey("enumerable")) {
		d.hasEnumerable = true
		d.enumerable = toBool(o.Get(strKey("enumerable"), v))
	}
	if o.HasProperty(strKey("configurable")) {
		d.hasConfigurable = true
		d.configurable = toBool(o.Get(strKey("configurable"), v))
	}
	if o.HasProperty(keyValue) {
		d.hasValue = true
		d.value = o.Get(keyValue, v)
	}
	if o.HasProperty(strKey("writable")) {
		d.hasWritable = true
		d.writable = toBool(o.Get(strKey("writable"), v))
	}
	if o.HasProperty(strKey("get")) {
		d.hasGet = true
		d.get = o.Get(strKey("get"), v)
		if !d.get.IsUndef() && !d.get.isCallable() {
			throwTypeError("invalid getter")
		}
	}
	if o.HasProperty(strKey("set")) {
		d.hasSet = true
		d.set = o.Get(strKey("set"), v)
		if !d.set.IsUndef() && !d.set.isCallable() {
			throwTypeError("invalid setter")
		}
	}
	if (d.hasGet || d.hasSet) && (d.hasValue || d.hasWritable) {
		throwTypeError("cannot have setter/getter and value or writable")
	}
	return d
}

func fromPropertyDescriptor(d *PropDesc) Value {
	if d == nil {
		return Undefined
	}
	o := newObject()
	if d.isAccessor() {
		o.addProp(strKey("get"), d.get, pDefault)
		o.addProp(strKey("set"), d.set, pDefault)
	} else {
		o.addProp(keyValue, d.value, pDefault)
		o.addProp(strKey("writable"), Bool(d.writable), pDefault)
	}
	o.addProp(strKey("enumerable"), Bool(d.enumerable), pDefault)
	o.addProp(strKey("configurable"), Bool(d.configurable), pDefault)
	return Obj(o)
}

func ownEnumerableKeys(o *Object, withSymbols bool) []PropKey {
	var out []PropKey
	for _, k := range o.OwnKeys() {
		if k.sym != nil && !withSymbols {
			continue
		}
		d := o.GetOwnProperty(k)
		if d != nil && d.enumerable {
			out = append(out, k)
		}
	}
	return out
}

func freezeObject(o *Object) {
	setIntegrityLevel(o, true)
}

func setIntegrityLevel(o *Object, frozen bool) bool {
	if !o.PreventExtensions() {
		return false
	}
	if o.fastArr {
		o.convertToSlow()
	}
	keys := o.OwnKeys()
	if o.class == ClassProxy || isTypedArrayClass(o.class) || o.class == ClassModuleNS || o.class == ClassString || o.class == ClassArray || o.class == ClassMappedArguments {
		for _, k := range keys {
			if !frozen {
				o.DefineOwnProperty(k, &PropDesc{hasConfigurable: true}, true)
				continue
			}
			cur := o.GetOwnProperty(k)
			if cur == nil {
				continue
			}
			if cur.isAccessor() {
				o.DefineOwnProperty(k, &PropDesc{hasConfigurable: true}, true)
			} else {
				o.DefineOwnProperty(k, &PropDesc{hasConfigurable: true, hasWritable: true}, true)
			}
		}
		return true
	}
	for i := range o.props {
		p := &o.props[i]
		if p.flags&pDeleted != 0 {
			continue
		}
		p.flags &^= pConfigurable
		if frozen && p.flags&pAccessor == 0 {
			p.flags &^= pWritable
		}
