func newArrayIterator(o *Object, kind int) *Object {
	it := newObjectProto(ArrayIteratorPrototype, ClassArrayIterator)
	it.internal = &ArrayIter{obj: o, kind: kind}
	return it
}

func arrayIteratorStep(it *Object) (Value, bool) {
	ai := it.internal.(*ArrayIter)
	if ai.done || ai.obj == nil {
		return Undefined, false
	}
	o := ai.obj
	var n int64
	if isTypedArrayClass(o.class) {
		ta := o.internal.(*TypedArray)
		if ta.isOutOfBounds() {
			throwTypeError("ArrayBuffer is detached or out of bounds")
		}
		n = int64(ta.length())
	} else if o.class == ClassArray {
		n = int64(o.alen)
	} else {
		n = lengthOfArrayLike(o)
	}
	if ai.idx >= n {
		ai.done = true
		ai.obj = nil
		return Undefined, false
	}
	i := ai.idx
	ai.idx++
	switch ai.kind {
	case 0:
		return Num(float64(i)), true
	case 1:
		return objGetI(o, i), true
	}
	return Obj(newArray([]Value{Num(float64(i)), objGetI(o, i)})), true
}

