func sortValues(vals []Value, cmp Value) {
	// merge sort (stable), matching typical engine call patterns loosely
	tmp := make([]Value, len(vals))
	var ms func(lo, hi int)
	ms = func(lo, hi int) {
		if hi-lo < 2 {
			return
		}
		if hi-lo <= 8 {
			// insertion sort
			for i := lo + 1; i < hi; i++ {
				x := vals[i]
				j := i - 1
				for j >= lo && sortCompare(vals[j], x, cmp) > 0 {
					vals[j+1] = vals[j]
					j--
				}
				vals[j+1] = x
			}
			return
		}
		mid := (lo + hi) / 2
		ms(lo, mid)
		ms(mid, hi)
		if sortCompare(vals[mid-1], vals[mid], cmp) <= 0 {
			return
		}
		copy(tmp[lo:hi], vals[lo:hi])
		i, j, k := lo, mid, lo
		for i < mid && j < hi {
			if sortCompare(tmp[j], tmp[i], cmp) < 0 {
				vals[k] = tmp[j]
				j++
			} else {
				vals[k] = tmp[i]
				i++
			}
			k++
		}
		for i < mid {
			vals[k] = tmp[i]
			i++
			k++
		}
		for j < hi {
			vals[k] = tmp[j]
			j++
			k++
		}
	}
	ms(0, len(vals))
