package main

type IterHelper struct {
	next     func() (Value, bool)
	ret      func()
	done     bool
	running  bool
	underlying *IteratorRecord
}

var IteratorHelperPrototype *Object
var IteratorWrapPrototype *Object
var AsyncFromSyncIteratorPrototype *Object
var IteratorCtor *Object

func getIteratorDirect(v Value) *IteratorRecord {
	if v.t != TagObj {
		throwTypeError("not an object")
	}
	next := getV(v, keyNext)
	return &IteratorRecord{iter: v.obj(), next: next}
}

func newIterHelper(h *IterHelper) Value {
	o := newObjectProto(IteratorHelperPrototype, ClassIteratorHelper)
	o.internal = h
	return Obj(o)
}

func initIteratorProtos() {
	IteratorPrototype = newObject()
	ip := IteratorPrototype
	ctor := makeCtor("Iterator", 0, ip, func(this Value, args []Value) Value {
		throwTypeError("must be called with new")
		return Undefined
	}, func(args []Value, nt *Object) Value {
		if nt == nil || nt == IteratorCtor {
			throwTypeError("abstract class not constructable")
		}
		return Obj(newObjectProto(getPrototypeFromCtor(nt, IteratorPrototype), ClassObject))
	})
	IteratorCtor = ctor
	addGlobal("Iterator", Obj(ctor))
	defMethod(ctor, "concat", 0, func(this Value, args []Value) Value {
		type item struct {
			iterable Value
			method   Value
		}
		var items []item
		for _, a := range args {
			if a.t != TagObj {
				throwTypeError("not an object")
			}
			m := getV(a, PropKey{sym: SymIterator})
			if !m.isCallable() {
				throwTypeError("not a function")
			}
			items = append(items, item{a, m})
		}
		idx := 0
		var cur *IteratorRecord
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			for {
				if cur == nil {
					if idx >= len(items) {
						return Undefined, false
					}
					cur = getIteratorFromMethod(items[idx].iterable, items[idx].method)
					idx++
				}
				r := callValue(cur.next, Obj(cur.iter), nil)
				if r.t != TagObj {
					throwTypeError("iterator must return an object")
				}
				if toBool(getV(r, keyDone)) {
					cur = nil
					continue
				}
				return getV(r, keyValue), true
			}
		}
		h.ret = func() {
			if cur != nil {
				cur.close()
			}
		}
		return newIterHelper(h)
	})
	defMethod(ctor, "from", 1, func(this Value, args []Value) Value {
		o := arg(args, 0)
		var rec *IteratorRecord
		if o.t == TagStr {
			rec = getIterator(o)
		} else {
			if o.t != TagObj {
				throwTypeError("not an object")
			}
			m := getV(o, PropKey{sym: SymIterator})
			if m.IsNullish() {
				rec = getIteratorDirect(o)
			} else {
				if !m.isCallable() {
					throwTypeError("not a function")
				}
				rec = getIteratorFromMethod(o, m)
			}
		}
		if ordinaryHasInstance(IteratorCtor, Obj(rec.iter)) {
			return Obj(rec.iter)
		}
		w := newObjectProto(IteratorWrapPrototype, ClassIteratorWrap)
		w.internal = rec
		return Obj(w)
	})
	// prototype methods
	helper := func(name string, length int, mk func(rec *IteratorRecord, args []Value) *IterHelper) {
		defMethod(ip, name, length, func(this Value, args []Value) Value {
			if this.t != TagObj {
				throwTypeError("not an object")
			}
			rec := &IteratorRecord{iter: this.obj()}
			h := func() (h *IterHelper) {
				defer func() {
					if x := recover(); x != nil {
						iteratorCloseOnThrow(nil, rec, false)
						panic(x)
					}
				}()
				return mk(rec, args)
			}()
			rec.next = getV(this, keyNext)
			h.underlying = rec
			if h.ret == nil {
				h.ret = func() { rec.close() }
			}
			return newIterHelper(h)
		})
	}
	stepRec := func(rec *IteratorRecord) (Value, bool) {
		r := callValue(rec.next, Obj(rec.iter), nil)
		if r.t != TagObj {
			throwTypeError("iterator must return an object")
		}
		if toBool(getV(r, keyDone)) {
			return Undefined, false
		}
		return getV(r, keyValue), true
	}
	callCB := func(rec *IteratorRecord, fn Value, args []Value) Value {
		var r Value
		thr := catchJSRaw(func() { r = callValue(fn, Undefined, args) })
		if thr != nil {
			iteratorCloseOnThrow(nil, rec, false)
			panic(thr)
		}
		return r
	}
	helper("drop", 1, func(rec *IteratorRecord, args []Value) *IterHelper {
		lim := toNumber(arg(args, 0))
		if lim != lim {
			throwRangeError("must be positive")
		}
		l := toInteger(Num(lim))
		if l < 0 {
			throwRangeError("must be positive")
		}
		dropped := 0.0
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			for dropped < l {
				dropped++
				if _, ok := stepRec(rec); !ok {
					return Undefined, false
				}
			}
			return stepRec(rec)
		}
		return h
	})
	helper("filter", 1, func(rec *IteratorRecord, args []Value) *IterHelper {
		fn := callbackFn(arg(args, 0))
		cnt := 0
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			for {
				v, ok := stepRec(rec)
				if !ok {
					return Undefined, false
				}
				r := callCB(rec, fn, []Value{v, Int(cnt)})
				cnt++
				if toBool(r) {
					return v, true
				}
			}
		}
		return h
	})
	helper("flatMap", 1, func(rec *IteratorRecord, args []Value) *IterHelper {
		fn := callbackFn(arg(args, 0))
		cnt := 0
		var inner *IteratorRecord
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			for {
				if inner != nil {
					var v Value
					var ok bool
					thr := catchJSRaw(func() { v, ok = stepRec(inner) })
					if thr != nil {
						iteratorCloseOnThrow(nil, rec, false)
						panic(thr)
					}
					if ok {
						return v, true
					}
					inner = nil
				}
				v, ok := stepRec(rec)
				if !ok {
					return Undefined, false
				}
				m := callCB(rec, fn, []Value{v, Int(cnt)})
				cnt++
				thr := catchJSRaw(func() {
					if m.t != TagObj && m.t != TagStr {
						throwTypeError("not an object")
					}
					meth := getV(m, PropKey{sym: SymIterator})
					if meth.IsNullish() {
						inner = getIteratorDirect(m)
					} else {
						inner = getIteratorFromMethod(m, meth)
					}
				})
				if thr != nil {
					iteratorCloseOnThrow(nil, rec, false)
					panic(thr)
				}
			}
		}
		h.ret = func() {
			if inner != nil {
				inner.close()
			}
			rec.close()
		}
		return h
	})
	helper("map", 1, func(rec *IteratorRecord, args []Value) *IterHelper {
		fn := callbackFn(arg(args, 0))
		cnt := 0
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			v, ok := stepRec(rec)
			if !ok {
				return Undefined, false
			}
			r := callCB(rec, fn, []Value{v, Int(cnt)})
			cnt++
			return r, true
		}
		return h
	})
	helper("take", 1, func(rec *IteratorRecord, args []Value) *IterHelper {
		lim := toNumber(arg(args, 0))
		if lim != lim {
			throwRangeError("must be positive")
		}
		l := toInteger(Num(lim))
		if l < 0 {
			throwRangeError("must be positive")
		}
		taken := 0.0
		h := &IterHelper{}
		h.next = func() (Value, bool) {
			if taken >= l {
				rec.close()
				return Undefined, false
			}
			taken++
			return stepRec(rec)
		}
		return h
	})
	consumer := func(name string, fn func(this Value, rec *IteratorRecord, args []Value) Value) {
		defMethod(ip, name, 1, func(this Value, args []Value) Value {
			if this.t != TagObj {
				throwTypeError("not an object")
			}
			rec := &IteratorRecord{iter: this.obj()}
			return fn(this, rec, args)
		})
	}
	consumer("every", func(this Value, rec *IteratorRecord, args []Value) Value {
		f := arg(args, 0)
		if !f.isCallable() {
			iteratorCloseOnThrow(nil, rec, false)
			throwTypeError("not a function")
		}
		rec.next = getV(this, keyNext)
		cnt := 0
		for {
			v, ok := stepRec(rec)
			if !ok {
				return True
			}
			if !toBool(callCB(rec, f, []Value{v, Int(cnt)})) {
				rec.close()
				return False
			}
			cnt++
		}
	})
	consumer("find", func(this Value, rec *IteratorRecord, args []Value) Value {
		f := arg(args, 0)
		if !f.isCallable() {
			iteratorCloseOnThrow(nil, rec, false)
			throwTypeError("not a function")
		}
		rec.next = getV(this, keyNext)
		cnt := 0
		for {
			v, ok := stepRec(rec)
			if !ok {
				return Undefined
			}
			if toBool(callCB(rec, f, []Value{v, Int(cnt)})) {
				rec.close()
				return v
			}
			cnt++
		}
	})
	consumer("forEach", func(this Value, rec *IteratorRecord, args []Value) Value {
		f := arg(args, 0)
		if !f.isCallable() {
			iteratorCloseOnThrow(nil, rec, false)
			throwTypeError("not a function")
		}
		rec.next = getV(this, keyNext)
		cnt := 0
		for {
			v, ok := stepRec(rec)
			if !ok {
				return Undefined
			}
			callCB(rec, f, []Value{v, Int(cnt)})
			cnt++
		}
	})
	consumer("some", func(this Value, rec *IteratorRecord, args []Value) Value {
		f := arg(args, 0)
		if !f.isCallable() {
			iteratorCloseOnThrow(nil, rec, false)
			throwTypeError("not a function")
		}
		rec.next = getV(this, keyNext)
		cnt := 0
		for {
			v, ok := stepRec(rec)
			if !ok {
				return False
			}
			if toBool(callCB(rec, f, []Value{v, Int(cnt)})) {
				rec.close()
				return True
			}
			cnt++
		}
	})
	consumer("reduce", func(this Value, rec *IteratorRecord, args []Value) Value {
		f := arg(args, 0)
		if !f.isCallable() {
			iteratorCloseOnThrow(nil, rec, false)
			throwTypeError("not a function")
		}
		rec.next = getV(this, keyNext)
		var acc Value
		cnt := 0
		if len(args) < 2 {
			v, ok := stepRec(rec)
			if !ok {
				throwTypeError("empty iterator")
			}
			acc = v
			cnt = 1
		} else {
			acc = args[1]
		}
		for {
			v, ok := stepRec(rec)
			if !ok {
				return acc
			}
			acc = callCB(rec, f, []Value{acc, v, Int(cnt)})
			cnt++
		}
	})
	consumer("toArray", func(this Value, rec *IteratorRecord, args []Value) Value {
		rec.next = getV(this, keyNext)
		var vals []Value
		for {
			v, ok := stepRec(rec)
			if !ok {
				return Obj(newArray(vals))
			}
			vals = append(vals, v)
		}
