		func() {
			defer func() {
				h.running = false
				if x := recover(); x != nil {
					h.done = true
					panic(x)
				}
			}()
			v, ok = h.next()
		}()
		if !ok {
			h.done = true
			return iterResult(Undefined, true)
		}
		return iterResult(v, false)
