	defMethod(IteratorHelperPrototype, "return", 0, func(this Value, args []Value) Value {
		h := thisHelper(this)
		if h.running {
			throwTypeError("cannot invoke a running iterator")
		}
		if !h.done {
			h.done = true
			if h.ret != nil {
				h.ret()
			}
		}
		return iterResult(Undefined, true)
	})
	IteratorHelperPrototype.setOwn(PropKey{sym: SymToStringTag}, StrGo("Iterator Helper"), pConfigurable)

	IteratorWrapPrototype = newObjectProto(ip, ClassObject)
	defMethod(IteratorWrapPrototype, "next", 0, func(this Value, args []Value) Value {
		if this.t != TagObj || this.obj().class != ClassIteratorWrap {
