		return iterResult(v, false)
	})
	ArrayIteratorPrototype.setOwn(PropKey{sym: SymToStringTag}, StrGo("Array Iterator"), pConfigurable)

	AsyncIteratorPrototype = newObject()
	defMethodSym(AsyncIteratorPrototype, SymAsyncIterator, "[Symbol.asyncIterator]", 0, func(this Value, args []Value) Value { return this })

