		defMethod(AsyncFromSyncIteratorPrototype, name, 1, func(this Value, args []Value) Value {
			cap := newPromiseCap()
			rec := this.obj().internal.(*IteratorRecord)
			var result Value
			thr := catchJS(func() {
				switch name {
				case "next":
					if len(args) > 0 {
						result = callValue(rec.next, Obj(rec.iter), []Value{args[0]})
					} else {
						result = callValue(rec.next, Obj(rec.iter), nil)
					}
				case "return":
					m := getV(Obj(rec.iter), keyReturn)
					if m.IsNullish() {
						result = iterResult(arg(args, 0), true)
						return
					}
					result = callValue(m, Obj(rec.iter), args)
