					throwTypeError("iterator must return an object")
				}
			})
			if thr != nil {
				cap.reject(*thr)
				return Obj(cap.promise)
			}
			var done bool
			var value Value
			thr = catchJS(func() {
				done = toBool(getV(result, keyDone))
				value = getV(result, keyValue)
			})
			if thr != nil {
				cap.reject(*thr)
				return Obj(cap.promise)
			}
			var vw *Object
			thr = catchJS(func() { vw = promiseResolveIntrinsic(value) })
			if thr != nil {
