				cap.reject(*thr)
				return Obj(cap.promise)
			}
			performPromiseThenNative(vw, func(v Value) {
				cap.resolve(iterResult(v, done))
			}, func(e Value) {
				if !done && name != "return" {
					iteratorCloseOnThrow(nil, rec, false)
				}
				cap.reject(e)
			})
			return Obj(cap.promise)
		})
	}
	asyncFromSync("next")
	asyncFromSync("return")
	asyncFromSync("throw")
