func createAsyncFromSyncIterator(rec *IteratorRecord) *IteratorRecord {
	o := newObjectProto(AsyncFromSyncIteratorPrototype, ClassAsyncFromSyncIterator)
	o.internal = rec
	return &IteratorRecord{iter: o, next: getV(Obj(o), keyNext)}
}

func thisHelper(v Value) *IterHelper {
	if v.t != TagObj || v.obj().class != ClassIteratorHelper {
		throwTypeError("not an Iterator Helper")
	}
	return v.obj().internal.(*IterHelper)
}

// catchJSRaw returns the raw panic value for JS throws
func catchJSRaw(fn func()) (thrown interface{}) {
	depth := len(callStack)
	defer func() {
		if x := recover(); x != nil {
			if _, ok := x.(*JSThrow); ok {
				truncateStack(depth)
				thrown = x
				return
			}
			panic(x)
		}
	}()
	fn()
	return nil
}

