	AsyncGeneratorFunctionPrototype = newObjectProto(FunctionPrototype, ClassObject)
	AsyncGeneratorPrototype = newObjectProto(AsyncIteratorPrototype, ClassObject)
	agp := AsyncGeneratorPrototype
	defMethod(agp, "next", 1, func(this Value, args []Value) Value {
		return asyncGenEnqueue(this, coNext, arg(args, 0))
	})
	defMethod(agp, "return", 1, func(this Value, args []Value) Value {
		return asyncGenEnqueue(this, coReturn, arg(args, 0))
	})
	defMethod(agp, "throw", 1, func(this Value, args []Value) Value {
