func strCompareCodePoints(a, b *JSString) int {
	i, j := 0, 0
	for i < a.n && j < b.n {
		ca, la := a.CodePointAt(i)
		cb, lb := b.CodePointAt(j)
		if ca != cb {
			if ca < cb {
				return -1
			}
			return 1
		}
		i += la
		j += lb
	}
	if i < a.n {
		return 1
	}
	if j < b.n {
		return -1
	}
	return 0
}

