		name = toString(nv).ToUTF8()
	}
	msg := ""
	if !mv.IsUndef() {
		msg = toString(mv).ToUTF8()
	}
	if name == "" {
		p.sb.WriteString(msg)
	} else if msg == "" {
		p.sb.WriteString(name)
	} else {
		p.sb.WriteString(name)
