		for i, k := range o.keys {
			pr := &o.props[i]
			if pr.flags&pDeleted != 0 || pr.flags&pEnumerable == 0 {
				continue
			}
			if !first {
				p.sb.WriteString(",")
			}
			first = false
			p.sb.WriteString(" ")
			p.prop(k, pr, level)
		}
	}
	if first {
		p.sb.WriteString(" ")
	}
}

func (p *printer) prop(k PropKey, pr *Prop, level int) {
	p.writeKey(k)
	p.sb.WriteString(": ")
	if pr.flags&pAccessor != 0 {
		acc := pr.accessor()
		if acc.get != nil && acc.set != nil {
			p.sb.WriteString("[Getter/Setter]")
		} else if acc.get != nil {
			p.sb.WriteString("[Getter]")
		} else if acc.set != nil {
			p.sb.WriteString("[Setter]")
		} else {
			p.sb.WriteString("undefined")
		}
		return
	}
	p.value(pr.v, level+1)
}

func (p *printer) props(o *Object, level int, _ bool, _ int) {
	p.sb.WriteString("{")
	first := true
	n := 0
	for i, k := range o.keys {
		pr := &o.props[i]
		if pr.flags&pDeleted != 0 || pr.flags&pEnumerable == 0 {
			continue
		}
		if n >= maxPrintItems {
			n++
			continue
		}
		if !first {
			p.sb.WriteString(",")
		}
		first = false
		p.sb.WriteString(" ")
		p.prop(k, pr, level)
		n++
	}
	if n > maxPrintItems {
		p.sb.WriteString(", ... ")
		p.moreItems(n - maxPrintItems)
	}
