	}
}

func printValueString(v Value) string {
	p := &printer{}
	p.value(v, 0)
	return p.sb.String()
}

func consoleLogString(args []Value) string {
	p := &printer{}
	for i, a := range args {
		if i > 0 {
			p.sb.WriteByte(' ')
		}
		if a.t == TagStr {
			p.sb.WriteString(a.str().ToUTF8())
		} else {
			p.value(a, 0)
		}
	}
	return p.sb.String()
}

var stdoutBuf []byte

func writeStdout(s string) {
	stdoutBuf = append(stdoutBuf, s...)
	if len(stdoutBuf) > 1<<16 {
		flushStdout()
	}
}

func flushStdout() {
	if len(stdoutBuf) > 0 {
		os.Stdout.Write(stdoutBuf)
		stdoutBuf = stdoutBuf[:0]
	}
}

func initConsole() {
	console := newObject()
	logFn := func(this Value, args []Value) Value {
		writeStdout(consoleLogString(args) + "\n")
		return Undefined
	}
	defMethod(console, "log", 0, logFn)
	addGlobal("console", Obj(console))
	perf := newObject()
	defMethod(perf, "now", 0, func(this Value, args []Value) Value {
		return Num(perfNow())
	})
	addGlobal("performance", Obj(perf))
	addGlobal("scriptArgs", Undefined)
	addGlobal("print", Obj(newNativeFunc("print", 0, logFn)))
	addGlobal("__loadScript", Obj(newNativeFunc("__loadScript", 1, func(this Value, args []Value) Value {
		name := toString(arg(args, 0)).String()
		return loadScriptFile(name)
	})))
}

