				p.sb.WriteString(",")
			}
			first = false
			p.sb.WriteString(" ")
			v := ta.get(i)
			if v.t == TagBigInt {
				p.sb.WriteString(v.big().String())
			} else {
				p.value(v, level+1)
			}
		}
		if n > maxPrintItems {
			p.sb.WriteString(", ... ")
			p.moreItems(n - maxPrintItems)
		}
		p.propsInline(o, level, !first)
		p.sb.WriteString(" ]")
		return
	}
	if isArray {
		p.sb.WriteString("[")
		first := true
		if o.fastArr {
			n := len(o.arr)
			for i := 0; i < n && i < maxPrintItems; i++ {
				if !first {
					p.sb.WriteString(",")
				}
				first = false
				p.sb.WriteString(" ")
				p.value(o.arr[i], level+1)
			}
			if n > maxPrintItems {
				p.sb.WriteString(", ... ")
				p.moreItems(n - maxPrintItems)
			} else if uint32(n) < o.alen {
				if !first {
					p.sb.WriteString(",")
				}
				first = false
				p.sb.WriteString(" <")
				e := int(o.alen) - n
				p.sb.WriteString(strconv.Itoa(e))
				if e == 1 {
					p.sb.WriteString(" empty item>")
				} else {
					p.sb.WriteString(" empty items>")
				}
			}
		}
		p.propsInline(o, level, !first)
		p.sb.WriteString(" ]")
		return
	}
	if o.class != ClassObject {
		p.sb.WriteString(objClassNameForPrint(o))
		p.sb.WriteString(" ")
	}
	p.props(o, level, false, 0)
}

func (p *printer) moreItems(n int) {
	p.sb.WriteString(strconv.Itoa(n))
	if n == 1 {
		p.sb.WriteString(" more item")
	} else {
		p.sb.WriteString(" more items")
	}
}

func (p *printer) errorHeader(o *Object) {
	nv := o.Get(keyName, Obj(o))
	mv := o.Get(strKey("message"), Obj(o))
	name := "Error"
	if !nv.IsUndef() {
		name = toString(nv).ToUTF8()
	}
	msg := ""
	if !mv.IsUndef() {
		msg = toString(mv).ToUTF8()
	}
	if name == "" {
		p.sb.WriteString(msg)
	} else if msg == "" {
		p.sb.WriteString(name)
	} else {
		p.sb.WriteString(name)
		p.sb.WriteString(": ")
		p.sb.WriteString(msg)
	}
	sv := o.Get(strKey("stack"), Obj(o))
	if sv.t == TagStr {
		s := sv.str().ToUTF8()
		s = strings.TrimSuffix(s, "\n")
		if s != "" {
			p.sb.WriteString("\n")
			p.sb.WriteString(s)
		}
	}
}

func (p *printer) hasPrintableProps(o *Object) bool {
	for i := range o.keys {
		pr := &o.props[i]
		if pr.flags&pDeleted != 0 || pr.flags&pEnumerable == 0 {
			continue
		}
		return true
	}
	return false
}

// props printed inside array/map brackets after elements
func (p *printer) propsInline(o *Object, level int, hadItems bool) {
	first := !hadItems
	if !first || true {
		for i, k := range o.keys {
			pr := &o.props[i]
			if pr.flags&pDeleted != 0 || pr.flags&pEnumerable == 0 {
				continue
			}
			if !first {
				p.sb.WriteString(",")
			}
			first = false
			p.sb.WriteString(" ")
			p.prop(k, pr, level)
		}
	}
	if first {
		p.sb.WriteString(" ")
	}
}

func (p *printer) prop(k PropKey, pr *Prop, level int) {
	p.writeKey(k)
	p.sb.WriteString(": ")
	if pr.flags&pAccessor != 0 {
		acc := pr.accessor()
		if acc.get != nil && acc.set != nil {
			p.sb.WriteString("[Getter/Setter]")
		} else if acc.get != nil {
			p.sb.WriteString("[Getter]")
		} else if acc.set != nil {
			p.sb.WriteString("[Setter]")
		} else {
			p.sb.WriteString("undefined")
		}
		return
	}
	p.value(pr.v, level+1)
}

func (p *printer) props(o *Object, level int, _ bool, _ int) {
	p.sb.WriteString("{")
	first := true
	n := 0
	for i, k := range o.keys {
		pr := &o.props[i]
		if pr.flags&pDeleted != 0 || pr.flags&pEnumerable == 0 {
			continue
		}
		if n >= maxPrintItems {
			n++
			continue
		}
		if !first {
			p.sb.WriteString(",")
		}
		first = false
		p.sb.WriteString(" ")
		p.prop(k, pr, level)
		n++
	}
	if n > maxPrintItems {
		p.sb.WriteString(", ... ")
		p.moreItems(n - maxPrintItems)
	}
	p.sb.WriteString("  }"[0:2])
	if first {
		p.sb.WriteString(" }")
	} else {
		p.sb.WriteString("}")
	}
}

func printValueString(v Value) string {
	p := &printer{}
	p.value(v, 0)
	return p.sb.String()
}

func consoleLogString(args []Value) string {
	p := &printer{}
	for i, a := range args {
		if i > 0 {
			p.sb.WriteByte(' ')
		}
		if a.t == TagStr {
			p.sb.WriteString(a.str().ToUTF8())
		} else {
			p.value(a, 0)
		}
	}
	return p.sb.String()
}

var stdoutBuf []byte

func writeStdout(s string) {
	stdoutBuf = append(stdoutBuf, s...)
	if len(stdoutBuf) > 1<<16 {
		flushStdout()
	}
}

func flushStdout() {
	if len(stdoutBuf) > 0 {
		os.Stdout.Write(stdoutBuf)
		stdoutBuf = stdoutBuf[:0]
	}
}

func initConsole() {
	console := newObject()
	logFn := func(this Value, args []Value) Value {
		writeStdout(consoleLogString(args) + "\n")
		return Undefined
	}
	defMethod(console, "log", 0, logFn)
	addGlobal("console", Obj(console))
	perf := newObject()
	defMethod(perf, "now", 0, func(this Value, args []Value) Value {
		return Num(perfNow())
	})
	addGlobal("performance", Obj(perf))
	addGlobal("scriptArgs", Undefined)
	addGlobal("print", Obj(newNativeFunc("print", 0, logFn)))
	addGlobal("__loadScript", Obj(newNativeFunc("__loadScript", 1, func(this Value, args []Value) Value {
		name := toString(arg(args, 0)).String()
		return loadScriptFile(name)
	})))
}

