func runTopLevel(code *FuncCode, this Value, parentFrame *Frame) Value {
	f := &Frame{code: code, this: this, thisInit: true}
	if parentFrame != nil {
		f.thisFrame = parentFrame.thisFrame
		f.env = parentFrame.env
