	sf := newSourceFile("<input>", src.str().String())
	tf := f.thisFrame
	ec := &evalContext{strict: strict}
	if tf != nil && tf.code != nil && !tf.code.topLevel {
		ec.inFunction = true
		ec.allowNewTarget = true
		k := tf.code.kind
		if k == FKMethod || k == FKGetter || k == FKSetter || k == FKClassConstructor || k == FKDerivedConstructor || k == FKFieldInit || k == FKClassStaticBlock {
			ec.allowSuperProp = true
