			global = false
			break
		}
		if s.kind == scBlock || s.kind == scCatch || s.kind == scWith {
			if s.needsEnv {
				global = false
				break
			}
		}
	}
	kind := pkEvalFunc
	var parent *Scope = scope
	if global && !prog.F.Strict {
		kind = pkEvalGlobal
		parent = nil
	}
	if se = resolveProgram(prog, kind, parent, c.module); se != nil {
		throwValue(Obj(makeSyntaxErrorAt(se, sf)))
	}
	code, se := compileProgram(prog, kind, sf, parent, c.module)
	if se != nil {
		throwValue(Obj(makeSyntaxErrorAt(se, sf)))
