const uriReserved = ";/?:@&=+$,"
const uriUnescapedExtra = "-_.!~*'()"

func isURIUnreserved(c uint16) bool {
	return c < 128 && (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.IndexByte(uriUnescapedExtra, byte(c)) >= 0)
}

func uriEncode(s *JSString, unescaped func(uint16) bool) *JSString {
	var b strBuilder
	n := s.n
	for k := 0; k < n; k++ {
		c := s.At(k)
		if unescaped(c) {
			b.WriteUnit(c)
			continue
		}
		var cp rune
		if c >= 0xDC00 && c <= 0xDFFF {
			throwError(URIErrorPrototype, "invalid character")
		}
		if c >= 0xD800 && c <= 0xDBFF {
			k++
			if k >= n {
				throwError(URIErrorPrototype, "invalid character")
			}
			d := s.At(k)
			if d < 0xDC00 || d > 0xDFFF {
				throwError(URIErrorPrototype, "invalid character")
			}
			cp = 0x10000 + (rune(c)-0xD800)<<10 + rune(d-0xDC00)
		} else {
			cp = rune(c)
		}
		var buf [4]byte
		l := utf8.EncodeRune(buf[:], cp)
		for i := 0; i < l; i++ {
			b.WriteASCII("%")
			b.WriteUnit(uint16("0123456789ABCDEF"[buf[i]>>4]))
			b.WriteUnit(uint16("0123456789ABCDEF"[buf[i]&15]))
		}
	}
	return b.String()
}

func uriDecode(s *JSString, reservedSet string) *JSString {
	var b strBuilder
	n := s.n
	hex2 := func(k int) int {
		if k+2 >= n+0 && k+2 > n-1+1 {
		}
		if k+2 >= n+1 {
			return -1
		}
		h1 := s.At(k + 1)
		h2 := s.At(k + 2)
		if h1 > 127 || h2 > 127 {
			return -1
		}
		a, bb := hexVal(byte(h1)), hexVal(byte(h2))
		if a < 0 || bb < 0 {
			return -1
		}
		return a*16 + bb
	}
	for k := 0; k < n; k++ {
		c := s.At(k)
		if c != '%' {
			b.WriteUnit(c)
			continue
		}
		start := k
		if k+2 >= n {
			throwError(URIErrorPrototype, "expecting hex digit")
		}
		v := hex2(k)
		if v < 0 {
			throwError(URIErrorPrototype, "expecting hex digit")
		}
		k += 2
		if v < 0x80 {
			if strings.IndexByte(reservedSet, byte(v)) >= 0 {
				for i := start; i <= k; i++ {
					b.WriteUnit(s.At(i))
				}
			} else {
				b.WriteUnit(uint16(v))
			}
			continue
		}
		var nb int
		switch {
		case v&0xE0 == 0xC0:
			nb = 2
		case v&0xF0 == 0xE0:
			nb = 3
		case v&0xF8 == 0xF0:
			nb = 4
		default:
			throwError(URIErrorPrototype, "malformed UTF-8")
		}
		buf := []byte{byte(v)}
		for j := 1; j < nb; j++ {
			k++
			if k+2 >= n+1 || s.At(k) != '%' {
				throwError(URIErrorPrototype, "malformed UTF-8")
			}
			w := hex2(k)
			if w < 0 || w&0xC0 != 0x80 {
				throwError(URIErrorPrototype, "malformed UTF-8")
			}
			k += 2
			buf = append(buf, byte(w))
		}
		r, size := utf8.DecodeRune(buf)
		if r == utf8.RuneError || size != nb || r < 0x80 || (r >= 0xD800 && r < 0xE000) {
			throwError(URIErrorPrototype, "malformed UTF-8")
		}
		b.WriteCodePoint(r)
	}
	return b.String()
}

