		s := toString(arg(args, 0))
		var b strBuilder
		for i := 0; i < s.n; i++ {
			c := s.At(i)
			if c < 128 && (c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || strings.IndexByte("@*_+-./", byte(c)) >= 0) {
				b.WriteUnit(c)
			} else if c < 256 {
				b.WriteASCII("%")
				b.WriteUnit(uint16("0123456789ABCDEF"[c>>4]))
				b.WriteUnit(uint16("0123456789ABCDEF"[c&15]))
			} else {
				b.WriteASCII("%u")
				for sh := 12; sh >= 0; sh -= 4 {
					b.WriteUnit(uint16("0123456789ABCDEF"[(c>>uint(sh))&15]))
				}
			}
		}
		return Str(b.String())
	})))
	addGlobal("unescape", Obj(newNativeFunc("unescape", 1, func(this Value, args []Value) Value {
		s := toString(arg(args, 0))
		var b strBuilder
		n := s.n
		hx := func(i int) int {
			c := s.At(i)
			if c > 127 {
				return -1
			}
			return hexVal(byte(c))
		}
		for i := 0; i < n; i++ {
			c := s.At(i)
			if c == '%' {
				if i+6 <= n && s.At(i+1) == 'u' {
					a, b2, c2, d := hx(i+2), hx(i+3), hx(i+4), hx(i+5)
					if a >= 0 && b2 >= 0 && c2 >= 0 && d >= 0 {
						b.WriteUnit(uint16(a<<12 | b2<<8 | c2<<4 | d))
						i += 5
						continue
					}
				}
				if i+3 <= n {
					a, b2 := hx(i+1), hx(i+2)
					if a >= 0 && b2 >= 0 {
						b.WriteUnit(uint16(a<<4 | b2))
						i += 2
						continue
					}
				}
			}
			b.WriteUnit(c)
		}
		return Str(b.String())
	})))
	addGlobal("Infinity", Num(math.Inf(1)))
	addGlobal("NaN", NaNVal)
	addGlobal("undefined", Undefined)
	EvalFunction = newNativeFunc("eval", 1, func(this Value, args []Value) Value {
		return indirectEval(arg(args, 0))
	})
	addGlobal("eval", Obj(EvalFunction))
}
