		case '\n':
			b.WriteASCII("\\n")
		case '\r':
			b.WriteASCII("\\r")
		case '\t':
			b.WriteASCII("\\t")
		default:
			if c < 0x20 {
				b.WriteASCII("\\u00")
				b.WriteUnit(uint16(digitChars[c>>4]))
				b.WriteUnit(uint16(digitChars[c&15]))
			} else if c >= 0xD800 && c < 0xDC00 && i+1 < n && s.At(i+1) >= 0xDC00 && s.At(i+1) < 0xE000 {
				b.WriteUnit(c)
				b.WriteUnit(s.At(i + 1))
				i++
			} else if c >= 0xD800 && c < 0xE000 {
				b.WriteASCII("\\u")
				b.WriteASCII(strconv.FormatUint(uint64(c), 16))
			} else {
				b.WriteUnit(c)
			}
		}
	}
	b.WriteUnit('"')
}

func (js *jsonStringifier) serialize(holder *Object, key PropKey, val Value) bool {
	if val.t == TagObj || val.t == TagBigInt {
		tj := getV(val, strKey("toJSON"))
		if tj.isCallable() {
			val = callValue(tj, val, []Value{key.toValue()})
		}
	}
	if js.replacer.isCallable() {
		val = callValue(js.replacer, Obj(holder), []Value{key.toValue(), val})
	}
	if val.t == TagObj {
		o := val.obj()
		switch o.class {
		case ClassNumber:
			val = Num(toNumber(val))
		case ClassString:
			val = Str(toString(val))
		case ClassBoolean:
			val = o.internal.(Value)
		case ClassBigInt:
			val = o.internal.(Value)
		}
	}
	switch val.t {
	case TagNull:
		js.sb.WriteASCII("null")
		return true
	case TagBool:
		if val.n != 0 {
			js.sb.WriteASCII("true")
		} else {
			js.sb.WriteASCII("false")
		}
		return true
	case TagStr:
		jsonQuote(&js.sb, val.str())
		return true
	case TagNum:
		if math.IsInf(val.n, 0) || val.n != val.n {
			js.sb.WriteASCII("null")
		} else {
			js.sb.WriteStr(numberToString(val.n))
		}
		return true
	case TagBigInt:
		throwTypeError("Do not know how to serialize a BigInt")
	case TagObj:
		if val.obj().isCallable() {
			return false
		}
		if val.obj().isArray() {
			js.serializeArray(val.obj())
		} else {
			js.serializeObject(val.obj())
		}
		return true
	}
	return false
}

func (js *jsonStringifier) enter(o *Object) {
	for _, x := range js.stack {
		if x == o {
			throwTypeError("circular reference")
		}
	}
	js.stack = append(js.stack, o)
}

func (js *jsonStringifier) serializeObject(o *Object) {
	js.enter(o)
	stepback := js.indent
	js.indent += js.gap
	var keys []PropKey
	if js.hasList {
		keys = js.propList
	} else {
		keys = ownEnumerableKeys(o, false)
	}
	js.sb.WriteUnit('{')
	any := false
	for _, k := range keys {
		v := o.Get(k, Obj(o))
		mark := js.sb.Len()
		var saved strBuilder
		saved = js.sb
		if any {
			js.sb.WriteUnit(',')
		}
		if js.gap != "" {
			js.sb.WriteASCII("\n")
			js.sb.WriteGo(js.indent)
		}
		jsonQuote(&js.sb, newStr(k.s))
		js.sb.WriteUnit(':')
		if js.gap != "" {
			js.sb.WriteUnit(' ')
		}
		if !js.serialize(o, k, v) {
			// roll back
			js.sb = saved
			_ = mark
			if js.sb.wide {
				js.sb.u = js.sb.u[:mark]
			} else {
				js.sb.a = js.sb.a[:mark]
			}
			continue
		}
		any = true
	}
	if any && js.gap != "" {
		js.sb.WriteASCII("\n")
		js.sb.WriteGo(stepback)
	}
	js.sb.WriteUnit('}')
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
}

func (js *jsonStringifier) serializeArray(o *Object) {
	js.enter(o)
	stepback := js.indent
	js.indent += js.gap
	n := lengthOfArrayLike(o)
	js.sb.WriteUnit('[')
	for i := int64(0); i < n; i++ {
		if i > 0 {
			js.sb.WriteUnit(',')
		}
		if js.gap != "" {
			js.sb.WriteASCII("\n")
			js.sb.WriteGo(js.indent)
		}
		v := objGetI(o, i)
		if !js.serialize(o, keyForIndex(i), v) {
			js.sb.WriteASCII("null")
		}
	}
	if n > 0 && js.gap != "" {
		js.sb.WriteASCII("\n")
		js.sb.WriteGo(stepback)
	}
	js.sb.WriteUnit(']')
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
}

func jsonStringify(val, replacer, space Value) Value {
	js := &jsonStringifier{replacer: Undefined}
	if replacer.isCallable() {
		js.replacer = replacer
	} else if replacer.t == TagObj && replacer.obj().isArray() {
		js.hasList = true
		ro := replacer.obj()
		n := lengthOfArrayLike(ro)
		seen := map[string]bool{}
		for i := int64(0); i < n; i++ {
			v := objGetI(ro, i)
			var item *JSString
			switch v.t {
			case TagStr:
				item = v.str()
			case TagNum:
				item = toString(v)
			case TagObj:
				if v.obj().class == ClassString || v.obj().class == ClassNumber {
					item = toString(v)
				}
			}
			if item != nil {
				s := item.String()
				if !seen[s] {
					seen[s] = true
					js.propList = append(js.propList, strKey(s))
				}
			}
		}
	}
	if space.t == TagObj {
		if space.obj().class == ClassNumber {
			space = Num(toNumber(space))
		} else if space.obj().class == ClassString {
			space = Str(toString(space))
		}
	}
	if space.t == TagNum {
		n := toInteger(space)
		if n > 10 {
			n = 10
		}
		if n >= 1 {
			js.gap = strings.Repeat(" ", int(n))
		}
	} else if space.t == TagStr {
		s := space.str()
		if s.n > 10 {
			s = s.Substring(0, 10)
		}
		js.gap = s.String()
	}
	wrapper := newObject()
	createDataProp(wrapper, strKey(""), val)
	if !js.serialize(wrapper, strKey(""), val) {
		return Undefined
	}
	return Str(js.sb.String())
}

func initJSON() {
	j := newObject()
	addGlobal("JSON", Obj(j))
	defMethod(j, "isRawJSON", 1, func(this Value, args []Value) Value {
		v := arg(args, 0)
		return Bool(v.t == TagObj && v.obj().internal == rawJSONMarker)
	})
	defMethod(j, "parse", 2, func(this Value, args []Value) Value {
		return jsonParse(toString(arg(args, 0)), arg(args, 1))
	})
	defMethod(j, "rawJSON", 1, func(this Value, args []Value) Value {
		s := toString(arg(args, 0))
		jsonParse(s, Undefined)
		o := newObjectProto(nil, ClassObject)
		o.internal = rawJSONMarker
		o.addProp(strKey("rawJSON"), Str(s), pEnumerable)
		o.extensible = false
		return Obj(o)
	})
	defMethod(j, "stringify", 3, func(this Value, args []Value) Value {
		return jsonStringify(arg(args, 0), arg(args, 1), arg(args, 2))
	})
	j.setOwn(PropKey{sym: SymToStringTag}, StrGo("JSON"), pConfigurable)
}

var rawJSONMarker = &struct{ x int }{1}
EOF
echo ok"}

