cd /workspace && cat > builtin_json.go <<'EOF'
package main

import (
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

type jsonParser struct {
	s   string // UTF-8 (WTF-8)
	pos int
	sf  *SourceFile
}

func (p *jsonParser) fail(pos int, msg string) {
	if p.sf == nil {
		p.sf = newSourceFile("<input>", p.s)
	}
	se := &SyntaxErr{msg: msg, pos: pos}
	throwValue(Obj(makeSyntaxErrorAt(se, p.sf)))
}

func (p *jsonParser) ws() {
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			p.pos++
		} else {
			break
		}
	}
}

func (p *jsonParser) tokenText(start int) string {
	i := start
	for i < len(p.s) {
		c := p.s[i]
		if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_' || c == '$' {
			i++
		} else {
			break
		}
	}
	if i == start {
		if start < len(p.s) {
			_, sz := utf8.DecodeRuneInString(p.s[start:])
			return p.s[start : start+sz]
		}
		return ""
	}
	return p.s[start:i]
}

func (p *jsonParser) value() Value {
	p.ws()
	if p.pos >= len(p.s) {
		p.fail(p.pos, "Unexpected end of JSON input")
	}
	c := p.s[p.pos]
	switch {
	case c == '{':
		p.pos++
		o := newObject()
		p.ws()
		if p.pos < len(p.s) && p.s[p.pos] == '}' {
			p.pos++
			return Obj(o)
		}
		for {
			p.ws()
			if p.pos >= len(p.s) {
				p.fail(p.pos, "Unexpected end of JSON input")
			}
			if p.s[p.pos] != '"' {
				p.fail(p.pos, "expecting property name")
			}
			k := p.str()
			p.ws()
			if p.pos >= len(p.s) {
				p.fail(p.pos, "Unexpected end of JSON input")
			}
			if p.s[p.pos] != ':' {
				p.fail(p.pos, "expecting ':'")
			}
			p.pos++
			v := p.value()
			createDataProp(o, strToKey(k), v)
			p.ws()
			if p.pos >= len(p.s) {
				p.fail(p.pos, "Unexpected end of JSON input")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == '}' {
				p.pos++
				return Obj(o)
			}
			p.fail(p.pos, "expecting '}'")
		}
	case c == '[':
		p.pos++
		var vals []Value
		p.ws()
		if p.pos < len(p.s) && p.s[p.pos] == ']' {
			p.pos++
			return Obj(newArray(vals))
		}
		for {
			vals = append(vals, p.value())
			p.ws()
			if p.pos >= len(p.s) {
				p.fail(p.pos, "Unexpected end of JSON input")
			}
			if p.s[p.pos] == ',' {
				p.pos++
				continue
			}
			if p.s[p.pos] == ']' {
				p.pos++
				return Obj(newArray(vals))
			}
			p.fail(p.pos, "expecting ']'")
		}
	case c == '"':
		return Str(p.str())
	case c == '-' || c >= '0' && c <= '9':
		return p.number()
	default:
		t := p.tokenText(p.pos)
		switch t {
		case "true":
			p.pos += 4
			return True
		case "false":
			p.pos += 5
			return False
		case "null":
			p.pos += 4
			return Null
		}
		p.fail(p.pos, "unexpected token: '"+t+"'")
	}
	return Undefined
}

func (p *jsonParser) number() Value {
	start := p.pos
	if p.s[p.pos] == '-' {
		p.pos++
		if p.pos >= len(p.s) || p.s[p.pos] < '0' || p.s[p.pos] > '9' {
			ch := ""
			if p.pos < len(p.s) {
				_, sz := utf8.DecodeRuneInString(p.s[p.pos:])
				ch = p.s[p.pos:p.pos+sz] + "'"
			}
			p.fail(p.pos, "Unexpected token '"+ch)
		}
	}
	if p.s[p.pos] == '0' {
		p.pos++
		if p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.fail(start, "Unexpected number")
		}
	} else {
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.s) && p.s[p.pos] == '.' {
		p.pos++
		if p.pos >= len(p.s) || p.s[p.pos] < '0' || p.s[p.pos] > '9' {
			p.fail(p.pos, "Unterminated fractional number")
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	}
	if p.pos < len(p.s) && (p.s[p.pos] == 'e' || p.s[p.pos] == 'E') {
		p.pos++
		if p.pos < len(p.s) && (p.s[p.pos] == '+' || p.s[p.pos] == '-') {
			p.pos++
		}
		if p.pos >= len(p.s) || p.s[p.pos] < '0' || p.s[p.pos] > '9' {
			p.fail(p.pos, "Exponent part is missing a number")
		}
		for p.pos < len(p.s) && p.s[p.pos] >= '0' && p.s[p.pos] <= '9' {
			p.pos++
		}
	}
	f, _ := strconv.ParseFloat(p.s[start:p.pos], 64)
	return Num(f)
}

func (p *jsonParser) str() *JSString {
	start := p.pos
	p.pos++
	var b strBuilder
	for {
		if p.pos >= len(p.s) {
			p.fail(start, "Unexpected end of JSON input")
		}
		c := p.s[p.pos]
		if c == '"' {
			p.pos++
			return b.String()
		}
		if c < 0x20 {
			p.fail(p.pos, "Bad control character in string literal")
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.s) {
				p.fail(start, "Unexpected end of JSON input")
			}
			e := p.s[p.pos]
			switch e {
			case '"', '\\', '/':
				b.WriteUnit(uint16(e))
			case 'b':
				b.WriteUnit('\b')
			case 'f':
				b.WriteUnit('\f')
			case 'n':
				b.WriteUnit('\n')
			case 'r':
				b.WriteUnit('\r')
			case 't':
				b.WriteUnit('\t')
			case 'u':
				v := 0
				for i := 1; i <= 4; i++ {
					if p.pos+i >= len(p.s) {
						p.fail(p.pos+i, "Bad Unicode escape")
					}
					h := hexVal(p.s[p.pos+i])
					if h < 0 {
						p.fail(p.pos+i, "Bad Unicode escape")
					}
					v = v*16 + h
				}
				b.WriteUnit(uint16(v))
				p.pos += 4
			default:
				p.fail(p.pos, "Bad escaped character")
			}
			p.pos++
			continue
		}
		if c < 0x80 {
			b.WriteUnit(uint16(c))
			p.pos++
			continue
		}
		r, sz := utf8.DecodeRuneInString(p.s[p.pos:])
		if r == utf8.RuneError && sz == 3 {
			// WTF-8 surrogate
			u := wtf8ToUTF16(p.s[p.pos : p.pos+3])
			b.WriteUnits(u)
		} else {
			b.WriteCodePoint(r)
		}
		p.pos += sz
	}
}

func jsonParse(text *JSString, reviver Value) Value {
	p := &jsonParser{s: text.String()}
	v := p.value()
	p.ws()
	if p.pos < len(p.s) {
		p.fail(p.pos, "unexpected data at the end")
	}
	if reviver.isCallable() {
		root := newObject()
		createDataProp(root, strKey(""), v)
		return internalize(root, strKey(""), reviver)
	}
	return v
}

func internalize(holder *Object, name PropKey, reviver Value) Value {
	val := holder.Get(name, Obj(holder))
	if val.t == TagObj {
		o := val.obj()
		if o.isArray() {
			n := lengthOfArrayLike(o)
			for i := int64(0); i < n; i++ {
				k := keyForIndex(i)
				nv := internalize(o, k, reviver)
				if nv.IsUndef() {
					o.Delete(k, false)
				} else {
					createDataProp(o, k, nv)
				}
			}
		} else {
			for _, k := range o.OwnKeys() {
				if k.sym != nil {
					continue
				}
				d := o.GetOwnProperty(k)
				if d == nil || !d.enumerable {
					continue
				}
				nv := internalize(o, k, reviver)
				if nv.IsUndef() {
					o.Delete(k, false)
				} else {
					createDataProp(o, k, nv)
				}
			}
		}
	}
	return callValue(reviver, Obj(holder), []Value{name.toValue(), val})
}

type jsonStringifier struct {
	replacer Value
	propList []PropKey
	hasList  bool
	gap      string
	indent   string
	stack    []*Object
	sb       strBuilder
}

func jsonQuote(b *strBuilder, s *JSString) {
	b.WriteUnit('"')
	n := s.n
	for i := 0; i < n; i++ {
		c := s.At(i)
		switch c {
		case '"':
			b.WriteASCII("\\\"")
		case '\\':
			b.WriteASCII("\\\\")
		case '\b':
			b.WriteASCII("\\b")
		case '\f':
			b.WriteASCII("\\f")
		case '\n':
			b.WriteASCII("\\n")
		case '\r':
			b.WriteASCII("\\r")
		case '\t':
			b.WriteASCII("\\t")
		default:
			if c < 0x20 {
				b.WriteASCII("\\u00")
				b.WriteUnit(uint16(digitChars[c>>4]))
				b.WriteUnit(uint16(digitChars[c&15]))
			} else if c >= 0xD800 && c < 0xDC00 && i+1 < n && s.At(i+1) >= 0xDC00 && s.At(i+1) < 0xE000 {
				b.WriteUnit(c)
				b.WriteUnit(s.At(i + 1))
				i++
			} else if c >= 0xD800 && c < 0xE000 {
				b.WriteASCII("\\u")
				b.WriteASCII(strconv.FormatUint(uint64(c), 16))
			} else {
				b.WriteUnit(c)
			}
		}
	}
	b.WriteUnit('"')
}

func (js *jsonStringifier) serialize(holder *Object, key PropKey, val Value) bool {
	if val.t == TagObj || val.t == TagBigInt {
		tj := getV(val, strKey("toJSON"))
		if tj.isCallable() {
			val = callValue(tj, val, []Value{key.toValue()})
		}
	}
	if js.replacer.isCallable() {
		val = callValue(js.replacer, Obj(holder), []Value{key.toValue(), val})
	}
	if val.t == TagObj {
		o := val.obj()
		switch o.class {
		case ClassNumber:
			val = Num(toNumber(val))
		case ClassString:
			val = Str(toString(val))
		case ClassBoolean:
			val = o.internal.(Value)
		case ClassBigInt:
			val = o.internal.(Value)
		}
	}
	switch val.t {
	case TagNull:
		js.sb.WriteASCII("null")
		return true
	case TagBool:
		if val.n != 0 {
			js.sb.WriteASCII("true")
		} else {
			js.sb.WriteASCII("false")
		}
		return true
	case TagStr:
		jsonQuote(&js.sb, val.str())
		return true
	case TagNum:
		if math.IsInf(val.n, 0) || val.n != val.n {
			js.sb.WriteASCII("null")
		} else {
			js.sb.WriteStr(numberToString(val.n))
		}
		return true
	case TagBigInt:
		throwTypeError("Do not know how to serialize a BigInt")
	case TagObj:
		if val.obj().isCallable() {
			return false
		}
		if val.obj().isArray() {
			js.serializeArray(val.obj())
		} else {
			js.serializeObject(val.obj())
		}
		return true
	}
	return false
}

func (js *jsonStringifier) enter(o *Object) {
	for _, x := range js.stack {
		if x == o {
			throwTypeError("circular reference")
		}
	}
	js.stack = append(js.stack, o)
}

func (js *jsonStringifier) serializeObject(o *Object) {
	js.enter(o)
	stepback := js.indent
	js.indent += js.gap
	var keys []PropKey
	if js.hasList {
		keys = js.propList
	} else {
		keys = ownEnumerableKeys(o, false)
	}
	js.sb.WriteUnit('{')
	any := false
	for _, k := range keys {
		v := o.Get(k, Obj(o))
		mark := js.sb.Len()
		var saved strBuilder
		saved = js.sb
		if any {
			js.sb.WriteUnit(',')
		}
		if js.gap != "" {
			js.sb.WriteASCII("\n")
			js.sb.WriteGo(js.indent)
		}
		jsonQuote(&js.sb, newStr(k.s))
		js.sb.WriteUnit(':')
		if js.gap != "" {
			js.sb.WriteUnit(' ')
		}
		if !js.serialize(o, k, v) {
			// roll back
			js.sb = saved
			_ = mark
			if js.sb.wide {
				js.sb.u = js.sb.u[:mark]
			} else {
				js.sb.a = js.sb.a[:mark]
			}
			continue
		}
		any = true
	}
	if any && js.gap != "" {
		js.sb.WriteASCII("\n")
		js.sb.WriteGo(stepback)
	}
	js.sb.WriteUnit('}')
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
}

func (js *jsonStringifier) serializeArray(o *Object) {
	js.enter(o)
	stepback := js.indent
	js.indent += js.gap
	n := lengthOfArrayLike(o)
	js.sb.WriteUnit('[')
	for i := int64(0); i < n; i++ {
		if i > 0 {
			js.sb.WriteUnit(',')
		}
		if js.gap != "" {
			js.sb.WriteASCII("\n")
			js.sb.WriteGo(js.indent)
		}
		v := objGetI(o, i)
		if !js.serialize(o, keyForIndex(i), v) {
			js.sb.WriteASCII("null")
		}
	}
	if n > 0 && js.gap != "" {
		js.sb.WriteASCII("\n")
		js.sb.WriteGo(stepback)
	}
	js.sb.WriteUnit(']')
	js.stack = js.stack[:len(js.stack)-1]
	js.indent = stepback
}

func jsonStringify(val, replacer, space Value) Value {
	js := &jsonStringifier{replacer: Undefined}
	if replacer.isCallable() {
		js.replacer = replacer
	} else if replacer.t == TagObj && replacer.obj().isArray() {
		js.hasList = true
		ro := replacer.obj()
		n := lengthOfArrayLike(ro)
		seen := map[string]bool{}
		for i := int64(0); i < n; i++ {
			v := objGetI(ro, i)
			var item *JSString
			switch v.t {
			case TagStr:
				item = v.str()
			case TagNum:
				item = toString(v)
			case TagObj:
				if v.obj().class == ClassString || v.obj().class == ClassNumber {
					item = toString(v)
				}
			}
			if item != nil {
				s := item.String()
				if !seen[s] {
					seen[s] = true
					js.propList = append(js.propList, strKey(s))
				}
			}
		}
	}
	if space.t == TagObj {
		if space.obj().class == ClassNumber {
			space = Num(toNumber(space))
		} else if space.obj().class == ClassString {
			space = Str(toString(space))
		}
	}
	if space.t == TagNum {
		n := toInteger(space)
		if n > 10 {
			n = 10
		}
		if n >= 1 {
			js.gap = strings.Repeat(" ", int(n))
		}
	} else if space.t == TagStr {
		s := space.str()
		if s.n > 10 {
			s = s.Substring(0, 10)
		}
		js.gap = s.String()
	}
	wrapper := newObject()
	createDataProp(wrapper, strKey(""), val)
	if !js.serialize(wrapper, strKey(""), val) {
		return Undefined
	}
	return Str(js.sb.String())
}

