type mapKey struct {
	t Tag
	n float64
	p unsafe.Pointer
	s string
}

func toMapKey(v Value) mapKey {
	switch v.t {
	case TagNum:
		n := v.n
		if n == 0 {
			n = 0
		}
		if n != n {
			return mapKey{t: TagNum, s: "NaN"}
		}
		return mapKey{t: TagNum, n: n}
	case TagStr:
		return mapKey{t: TagStr, s: v.str().String()}
	case TagBigInt:
		return mapKey{t: TagBigInt, s: v.big().String()}
	case TagBool:
		return mapKey{t: TagBool, n: v.n}
	case TagUndef, TagNull, TagEmpty:
		t := v.t
		if t == TagEmpty {
			t = TagUndef
		}
		return mapKey{t: t}
	}
	return mapKey{t: v.t, p: v.p}
}

type mapEntry struct {
	key, value Value
	next, prev *mapEntry
	deleted    bool
}

type MapData struct {
	m     map[mapKey]*mapEntry
	first *mapEntry
	last  *mapEntry
	size  int
}

func newMapData() *MapData { return &MapData{m: make(map[mapKey]*mapEntry)} }

func (md *MapData) get(k Value) *mapEntry {
	return md.m[toMapKey(k)]
}

func (md *MapData) set(k, v Value) {
	mk := toMapKey(k)
	if e, ok := md.m[mk]; ok {
		e.value = v
		return
	}
	if k.t == TagNum && k.n == 0 {
		k = Num(0)
	}
	e := &mapEntry{key: k, value: v}
	md.m[mk] = e
	if md.last == nil {
		md.first = e
		md.last = e
	} else {
		md.last.next = e
		e.prev = md.last
		md.last = e
	}
	md.size++
}

func (md *MapData) delete(k Value) bool {
	mk := toMapKey(k)
	e, ok := md.m[mk]
	if !ok {
		return false
	}
	delete(md.m, mk)
	md.unlink(e)
	return true
}

func (md *MapData) unlink(e *mapEntry) {
	e.deleted = true
	e.value = Undefined
	if e.prev != nil {
		e.prev.next = e.next
	} else {
		md.first = e.next
	}
	if e.next != nil {
		e.next.prev = e.prev
	} else {
		md.last = e.prev
	}
	md.size--
}

func (md *MapData) clear() {
	for e := md.first; e != nil; e = e.next {
		e.deleted = true
		e.value = Undefined
	}
	md.m = make(map[mapKey]*mapEntry)
	md.first = nil
	md.last = nil
	md.size = 0
}

// iterate with support for mutation during iteration
func (md *MapData) forEach(fn func(e *mapEntry)) {
	e := md.first
	for e != nil {
		if !e.deleted {
			fn(e)
		}
		nx := e.next
		for nx != nil && nx.deleted {
			nx = nx.next
		}
		e = nx
	}
}

type mapIter struct {
	md   *MapData
	cur  *mapEntry
	kind int // 0 keys 1 values 2 entries
	started bool
	done bool
}

func (it *mapIter) step() (*mapEntry, bool) {
	if it.done {
		return nil, false
	}
	var e *mapEntry
	if !it.started {
		it.started = true
		e = it.md.first
	} else if it.cur != nil {
		e = it.cur.next
	}
	for e != nil && e.deleted {
		e = e.next
	}
	if e == nil {
		it.done = true
		it.cur = nil
		return nil, false
	}
	it.cur = e
	return e, true
}

