type setRecord struct {
	obj  Value
	size float64
	has  Value
	keys Value
}

func getSetRecord(v Value) *setRecord {
	if v.t != TagObj {
		throwTypeError("not an object")
	}
	rs := getV(v, strKey("size"))
	n := toNumber(rs)
	if n != n {
		throwTypeError("invalid size")
	}
	sz := toInteger(Num(n))
	if sz < 0 {
		throwRangeError("invalid size")
	}
	has := getV(v, strKey("has"))
	if !has.isCallable() {
		throwTypeError("not a function")
	}
	keys := getV(v, strKey("keys"))
	if !keys.isCallable() {
		throwTypeError("not a function")
	}
	return &setRecord{obj: v, size: sz, has: has, keys: keys}
}

func (sr *setRecord) iterate(fn func(v Value) bool) {
	it := callValue(sr.keys, sr.obj, nil)
	if it.t != TagObj {
		throwTypeError("not an object")
	}
	next := getV(it, keyNext)
	rec := &IteratorRecord{iter: it.obj(), next: next}
	for {
		v, ok := rec.step()
		if !ok {
			return
		}
		if !fn(v) {
			rec.close()
			return
		}
	}
}

