package main

import (
	"encoding/binary"
	"math"
	"math/big"
)

type ArrayBufferData struct {
	data      []byte
	detached  bool
	resizable bool
	maxLen    int
	shared    bool
}

func (b *ArrayBufferData) fixedLength() bool { return !b.resizable }

type TypedArray struct {
	buf            *ArrayBufferData
	bufObj         *Object
	offset         int
	fixedLen       int
	lengthTracking bool
	kind           ClassID
	esize          int
}

var typedArrayElemSize = map[ClassID]int{
	ClassUint8C: 1, ClassInt8: 1, ClassUint8: 1, ClassInt16: 2, ClassUint16: 2, ClassInt32: 4, ClassUint32: 4,
	ClassBigInt64: 8, ClassBigUint64: 8, ClassFloat16: 2, ClassFloat32: 4, ClassFloat64: 8,
}

func (ta *TypedArray) isOutOfBounds() bool {
	if ta.buf.detached {
		return true
	}
	bl := len(ta.buf.data)
	if ta.offset > bl {
		return true
	}
	if !ta.lengthTracking && ta.offset+ta.fixedLen*ta.esize > bl {
		return true
	}
	return false
}

func (ta *TypedArray) length() int {
	if ta.isOutOfBounds() {
		return 0
	}
	if ta.lengthTracking {
		return (len(ta.buf.data) - ta.offset) / ta.esize
	}
	return ta.fixedLen
}

func (ta *TypedArray) byteLength() int { return ta.length() * ta.esize }

func (ta *TypedArray) validIndex(idx float64) bool {
	if idx != math.Trunc(idx) || (idx == 0 && math.Signbit(idx)) {
		return false
	}
	return idx >= 0 && idx < float64(ta.length())
}

func isBigIntKind(k ClassID) bool { return k == ClassBigInt64 || k == ClassBigUint64 }

func getRawElem(data []byte, kind ClassID, little bool) Value {
	var bo binary.ByteOrder = binary.LittleEndian
	if !little {
		bo = binary.BigEndian
	}
	switch kind {
	case ClassInt8:
		return Num(float64(int8(data[0])))
	case ClassUint8, ClassUint8C:
		return Num(float64(data[0]))
	case ClassInt16:
		return Num(float64(int16(bo.Uint16(data))))
	case ClassUint16:
		return Num(float64(bo.Uint16(data)))
	case ClassInt32:
		return Num(float64(int32(bo.Uint32(data))))
	case ClassUint32:
		return Num(float64(bo.Uint32(data)))
	case ClassFloat16:
		return Num(float16ToFloat64(bo.Uint16(data)))
	case ClassFloat32:
		return Num(float64(math.Float32frombits(bo.Uint32(data))))
	case ClassFloat64:
		return Num(math.Float64frombits(bo.Uint64(data)))
	case ClassBigInt64:
		return BigV(big.NewInt(int64(bo.Uint64(data))))
	case ClassBigUint64:
		return BigV(new(big.Int).SetUint64(bo.Uint64(data)))
	}
	return Undefined
}

func bigToUint64(b *big.Int) uint64 {
	m := new(big.Int).And(b, new(big.Int).SetUint64(math.MaxUint64))
	return m.Uint64()
}

// v must already be converted (number or bigint)
func setRawElem(data []byte, kind ClassID, v Value, little bool) {
	var bo binary.ByteOrder = binary.LittleEndian
	if !little {
		bo = binary.BigEndian
	}
	switch kind {
	case ClassInt8, ClassUint8:
		data[0] = byte(f64ToInt32(v.n))
	case ClassUint8C:
		f := v.n
		if f != f || f <= 0 {
			data[0] = 0
		} else if f >= 255 {
			data[0] = 255
		} else {
			data[0] = byte(math.RoundToEven(f))
		}
	case ClassInt16, ClassUint16:
		bo.PutUint16(data, uint16(f64ToInt32(v.n)))
	case ClassInt32, ClassUint32:
		bo.PutUint32(data, uint32(f64ToInt32(v.n)))
	case ClassFloat16:
		bo.PutUint16(data, float64ToFloat16(v.n))
	case ClassFloat32:
		bo.PutUint32(data, math.Float32bits(float32(v.n)))
	case ClassFloat64:
		bo.PutUint64(data, math.Float64bits(v.n))
	case ClassBigInt64, ClassBigUint64:
		bo.PutUint64(data, bigToUint64(v.big()))
	}
}

func (ta *TypedArray) get(i int) Value {
	off := ta.offset + i*ta.esize
	return getRawElem(ta.buf.data[off:off+ta.esize], ta.kind, true)
}

func (ta *TypedArray) convert(v Value) Value {
	if isBigIntKind(ta.kind) {
		return BigV(toBigInt(v))
	}
	if v.t == TagNum {
		return v
	}
	return Num(toNumber(v))
}

func (ta *TypedArray) setValue(idx float64, v Value) {
	cv := ta.convert(v)
	if !ta.validIndex(idx) {
		return
	}
	i := int(idx)
	off := ta.offset + i*ta.esize
	setRawElem(ta.buf.data[off:off+ta.esize], ta.kind, cv, true)
}

func (ta *TypedArray) setConverted(i int, cv Value) {
	off := ta.offset + i*ta.esize
	setRawElem(ta.buf.data[off:off+ta.esize], ta.kind, cv, true)
}

var ArrayBufferPrototype, SharedArrayBufferPrototype, TypedArrayPrototype, DataViewPrototype *Object
var ArrayBufferCtor, TypedArrayCtor *Object
var typedArrayCtors = map[ClassID]*Object{}
var typedArrayProtos = map[ClassID]*Object{}

func thisBuffer(this Value, shared bool) *ArrayBufferData {
	want := ClassArrayBuffer
	if shared {
		want = ClassSharedArrayBuffer
	}
	if this.t == TagObj && this.obj().class == want {
		return this.obj().internal.(*ArrayBufferData)
	}
