func newArrayBufferObj(proto *Object, n int, shared bool) *Object {
	class := ClassArrayBuffer
	if shared {
		class = ClassSharedArrayBuffer
	}
	if n > 1<<31 {
		throwRangeError("invalid array buffer length")
	}
	o := newObjectProto(proto, class)
	o.internal = &ArrayBufferData{data: make([]byte, n), shared: shared}
	return o
}

func thisTA(this Value) *TypedArray {
	if this.t == TagObj && isTypedArrayClass(this.obj().class) {
		return this.obj().internal.(*TypedArray)
	}
	throwTypeError("not a TypedArray")
	return nil
}

func validTA(this Value) (*Object, *TypedArray) {
	ta := thisTA(this)
	if ta.isOutOfBounds() {
		throwTypeError("ArrayBuffer is detached or out of bounds")
	}
	return this.obj(), ta
}

func createTypedArray(kind ClassID, proto *Object, n int) *Object {
	es := typedArrayElemSize[kind]
	if n < 0 || n*es > 1<<31 {
		throwRangeError("invalid array buffer length")
	}
	buf := newArrayBufferObj(ArrayBufferPrototype, n*es, false)
	o := newObjectProto(proto, kind)
	o.internal = &TypedArray{buf: buf.internal.(*ArrayBufferData), bufObj: buf, fixedLen: n, kind: kind, esize: es}
	return o
}

func typedArraySpeciesCreate(exemplar *Object, args []Value) *Object {
	ta := exemplar.internal.(*TypedArray)
	def := typedArrayCtors[ta.kind]
	c := speciesConstructor(exemplar, def)
	r := constructValue(c, args, nil)
	if r.t != TagObj || !isTypedArrayClass(r.obj().class) {
		throwTypeError("not a TypedArray")
	}
	rta := r.obj().internal.(*TypedArray)
	if rta.isOutOfBounds() {
		throwTypeError("ArrayBuffer is detached or out of bounds")
	}
	if isBigIntKind(rta.kind) != isBigIntKind(ta.kind) {
		throwTypeError("TypedArray content type mismatch")
	}
	if len(args) == 1 && args[0].t == TagNum && float64(rta.length()) < args[0].n {
		throwTypeError("TypedArray is too small")
	}
	return r.obj()
}

func typedArrayCreateFromCtor(c Value, n int) *Object {
	r := constructValue(c, []Value{Int(n)}, nil)
	if r.t != TagObj || !isTypedArrayClass(r.obj().class) {
		throwTypeError("not a TypedArray")
	}
	rta := r.obj().internal.(*TypedArray)
	if rta.isOutOfBounds() {
		throwTypeError("ArrayBuffer is detached or out of bounds")
	}
	if rta.length() < n {
		throwTypeError("TypedArray is too small")
	}
	return r.obj()
}

