		return Obj(o)
	})
	ArrayBufferCtor = abCtor
	addGlobal("ArrayBuffer", Obj(abCtor))
	defMethod(abCtor, "isView", 1, func(this Value, args []Value) Value {
		v := arg(args, 0)
		return Bool(v.t == TagObj && (isTypedArrayClass(v.obj().class) || v.obj().class == ClassDataView))
	})
	finishCtor(abCtor, abp)
	speciesGetter(abCtor)
	ci := abp.findOwn(keyConstructor)
	abp.removePropAt(ci)
	abp.compact()
	defGetter(abp, "byteLength", func(this Value, args []Value) Value {
		b := thisBuffer(this, false)
		if b.detached {
			return Int(0)
		}
		return Int(len(b.data))
	})
	defGetter(abp, "maxByteLength", func(this Value, args []Value) Value {
		b := thisBuffer(this, false)
		if b.detached {
			return Int(0)
		}
		if b.resizable {
			return Int(b.maxLen)
		}
		return Int(len(b.data))
	})
	defGetter(abp, "resizable", func(this Value, args []Value) Value {
		return Bool(thisBuffer(this, false).resizable)
	})
	defGetter(abp, "detached", func(this Value, args []Value) Value {
		return Bool(thisBuffer(this, false).detached)
	})
	defMethod(abp, "resize", 1, func(this Value, args []Value) Value {
		b := thisBuffer(this, false)
		if !b.resizable {
			throwTypeError("array buffer is not resizable")
		}
		n := toIndex(arg(args, 0))
		if b.detached {
			throwTypeError("array buffer is detached")
		}
		if int(n) > b.maxLen {
			throwRangeError("invalid array buffer length")
		}
		nd := make([]byte, n)
		copy(nd, b.data)
		b.data = nd
		return Undefined
	})
	defMethod(abp, "slice", 2, func(this Value, args []Value) Value {
		b := thisBuffer(this, false)
		if b.detached {
			throwTypeError("array buffer is detached")
		}
		n := int64(len(b.data))
		first := relIndex(arg(args, 0), n, 0)
		fin := relIndex(arg(args, 1), n, n)
		l := fin - first
		if l < 0 {
			l = 0
		}
		c := speciesConstructor(this.obj(), ArrayBufferCtor)
		nv := constructValue(c, []Value{Num(float64(l))}, nil)
		if nv.t != TagObj || nv.obj().class != ClassArrayBuffer {
			throwTypeError("not an ArrayBuffer")
		}
		nb := nv.obj().internal.(*ArrayBufferData)
		if nv.obj() == this.obj() {
			throwTypeError("cannot use identical ArrayBuffer")
		}
		if int64(len(nb.data)) < l {
			throwTypeError("ArrayBuffer is too small")
		}
		if b.detached {
			throwTypeError("array buffer is detached")
		}
		copy(nb.data, b.data[first:first+l])
		return nv
	})
	transfer := func(fixed bool) func(this Value, args []Value) Value {
		return func(this Value, args []Value) Value {
			b := thisBuffer(this, false)
			n := len(b.data)
			if l := arg(args, 0); !l.IsUndef() {
				n = int(toIndex(l))
			}
			if b.detached {
				throwTypeError("array buffer is detached")
			}
			o := newArrayBufferObj(ArrayBufferPrototype, n, false)
			nb := o.internal.(*ArrayBufferData)
			copy(nb.data, b.data)
			if !fixed && b.resizable {
				nb.resizable = true
				nb.maxLen = b.maxLen
			}
			b.data = nil
			b.detached = true
			return Obj(o)
		}
	}
	defMethod(abp, "transfer", 0, transfer(false))
	defMethod(abp, "transferToFixedLength", 0, transfer(true))
	abp.setOwn(keyConstructor, Obj(abCtor), pWritable|pConfigurable)
	abp.setOwn(PropKey{sym: SymToStringTag}, StrGo("ArrayBuffer"), pConfigurable)

	// SharedArrayBuffer
	SharedArrayBufferPrototype = newObject()
	sabp := SharedArrayBufferPrototype
	sabCtor := makeCtor("SharedArrayBuffer", 1, sabp, func(this Value, args []Value) Value {
		throwTypeError("must be called with new")
		return Undefined
	}, func(args []Value, nt *Object) Value {
		n := toIndex(arg(args, 0))
		return Obj(newArrayBufferObj(getPrototypeFromCtor(nt, SharedArrayBufferPrototype), int(n), true))
	})
	addGlobal("SharedArrayBuffer", Obj(sabCtor))
	finishCtor(sabCtor, sabp)
	speciesGetter(sabCtor)
	defGetter(sabp, "byteLength", func(this Value, args []Value) Value {
		return Int(len(thisBuffer(this, true).data))
	})
	defMethod(sabp, "slice", 2, func(this Value, args []Value) Value {
		b := thisBuffer(this, true)
		n := int64(len(b.data))
		first := relIndex(arg(args, 0), n, 0)
		fin := relIndex(arg(args, 1), n, n)
		l := fin - first
		if l < 0 {
			l = 0
		}
		o := newArrayBufferObj(SharedArrayBufferPrototype, int(l), true)
		copy(o.internal.(*ArrayBufferData).data, b.data[first:first+l])
		return Obj(o)
	})
	sabp.setOwn(PropKey{sym: SymToStringTag}, StrGo("SharedArrayBuffer"), pConfigurable)

	// %TypedArray%
	TypedArrayPrototype = newObject()
	tap := TypedArrayPrototype
	taCtor := makeCtor("TypedArray", 0, tap, func(this Value, args []Value) Value {
		throwTypeError("must be called with new")
		return Undefined
	}, func(args []Value, nt *Object) Value {
		throwTypeError("cannot be called")
		return Undefined
	})
	TypedArrayCtor = taCtor
	defMethod(taCtor, "from", 1, func(this Value, args []Value) Value {
		if !isConstructor(this) {
			throwTypeError("not a constructor")
		}
		src := arg(args, 0)
		mapFn := arg(args, 1)
		thisArg := arg(args, 2)
		if !mapFn.IsUndef() && !mapFn.isCallable() {
			throwTypeError("not a function")
		}
