		m := getV(src, PropKey{sym: SymIterator})
		if !m.IsNullish() {
			if !m.isCallable() {
				throwTypeError("not a function")
			}
			it := getIteratorFromMethod(src, m)
			for {
				v, ok := it.step()
				if !ok {
					break
				}
				vals = append(vals, v)
			}
		} else {
			o := toObject(src)
			n := lengthOfArrayLike(o)
			for i := int64(0); i < n; i++ {
				vals = append(vals, objGetI(o, i))
			}
		}
		t := typedArrayCreateFromCtor(this, len(vals))
		for i, v := range vals {
			if !mapFn.IsUndef() {
				v = callValue(mapFn, thisArg, []Value{v, Int(i)})
			}
			t.Set(idxKey(uint32(i)), v, Obj(t), true)
		}
		return Obj(t)
	})
	defMethod(taCtor, "of", 0, func(this Value, args []Value) Value {
		if !isConstructor(this) {
			throwTypeError("not a constructor")
		}
		t := typedArrayCreateFromCtor(this, len(args))
		for i, v := range args {
			t.Set(idxKey(uint32(i)), v, Obj(t), true)
		}
		return Obj(t)
	})
	finishCtor(taCtor, tap)
	speciesGetter(taCtor)
	ci = tap.findOwn(keyConstructor)
	tap.removePropAt(ci)
	tap.compact()
	initTypedArrayProto(tap)
	tap.setOwn(keyConstructor, Obj(taCtor), pWritable|pConfigurable)
	tsf := tap.findOwn(strKey("toString"))
	_ = tsf

	for _, kind := range []ClassID{ClassUint8C, ClassInt8, ClassUint8, ClassInt16, ClassUint16, ClassInt32, ClassUint32, ClassBigInt64, ClassBigUint64, ClassFloat16, ClassFloat32, ClassFloat64} {
		kind := kind
		name := classNames[kind]
		proto := newObjectProto(tap, ClassObject)
		es := typedArrayElemSize[kind]
		ctor := makeCtor(name, 3, proto, func(this Value, args []Value) Value {
			throwTypeError("must be called with new")
			return Undefined
		}, func(args []Value, nt *Object) Value {
			return constructTypedArray(kind, getPrototypeFromCtor(nt, typedArrayProtos[kind]), args)
		})
		ctor.proto = taCtor
		defConst(ctor, "BYTES_PER_ELEMENT", Int(es))
		finishCtor(ctor, proto)
		ci := proto.findOwn(keyConstructor)
		proto.removePropAt(ci)
		proto.compact()
		defConst(proto, "BYTES_PER_ELEMENT", Int(es))
		proto.setOwn(keyConstructor, Obj(ctor), pWritable|pConfigurable)
		typedArrayCtors[kind] = ctor
		typedArrayProtos[kind] = proto
		addGlobal(name, Obj(ctor))
	}
	initDataView()
	initAtomics()
}

func constructTypedArray(kind ClassID, proto *Object, args []Value) Value {
	es := typedArrayElemSize[kind]
	a0 := arg(args, 0)
	if a0.t != TagObj {
		n := toIndex(a0)
		return Obj(createTypedArray(kind, proto, int(n)))
	}
	src := a0.obj()
	switch {
	case src.class == ClassArrayBuffer || src.class == ClassSharedArrayBuffer:
		bd := src.internal.(*ArrayBufferData)
		off := toIndex(arg(args, 1))
		if int(off)%es != 0 {
			throwRangeError("invalid offset")
		}
		lv := arg(args, 2)
		var newLen int64
		if !lv.IsUndef() {
			newLen = toIndex(lv)
		}
		if bd.detached {
			throwTypeError("array buffer is detached")
		}
		bl := int64(len(bd.data))
		o := newObjectProto(proto, kind)
		ta := &TypedArray{buf: bd, bufObj: src, offset: int(off), kind: kind, esize: es}
		if lv.IsUndef() {
			if bd.resizable {
				ta.lengthTracking = true
				if off > bl {
					throwRangeError("invalid offset")
				}
			} else {
				if bl%int64(es) != 0 {
					throwRangeError("invalid length")
				}
				nb := bl - off
				if nb < 0 {
					throwRangeError("invalid offset")
				}
				ta.fixedLen = int(nb / int64(es))
			}
		} else {
			if off+newLen*int64(es) > bl {
				throwRangeError("invalid length")
			}
			ta.fixedLen = int(newLen)
		}
		o.internal = ta
		return Obj(o)
	case isTypedArrayClass(src.class):
		sta := src.internal.(*TypedArray)
		if sta.isOutOfBounds() {
			throwTypeError("ArrayBuffer is detached or out of bounds")
		}
		n := sta.length()
		o := createTypedArray(kind, proto, n)
		ta := o.internal.(*TypedArray)
		if isBigIntKind(kind) != isBigIntKind(sta.kind) {
			throwTypeError("TypedArray content type mismatch")
		}
		for i := 0; i < n; i++ {
			ta.setConverted(i, ta.convert(sta.get(i)))
		}
		return Obj(o)
	default:
		var vals []Value
		m := src.Get(PropKey{sym: SymIterator}, a0)
		if !m.IsNullish() {
			if !m.isCallable() {
				throwTypeError("not a function")
			}
			if src.class == ClassArray && src.fastArr && arrayIteratorPristine(src) {
				n := lengthOfArrayLike(src)
				for i := int64(0); i < n; i++ {
					vals = append(vals, objGetI(src, i))
				}
			} else {
				it := getIteratorFromMethod(a0, m)
				for {
					v, ok := it.step()
					if !ok {
						break
					}
					vals = append(vals, v)
				}
			}
		} else {
			n := lengthOfArrayLike(src)
			for i := int64(0); i < n; i++ {
				vals = append(vals, objGetI(src, i))
			}
		}
		o := createTypedArray(kind, proto, len(vals))
		ta := o.internal.(*TypedArray)
		for i, v := range vals {
			ta.setConverted(i, ta.convert(v))
		}
		return Obj(o)
	}
}

func initTypedArrayProto(tap *Object) {
	defGetter(tap, "length", func(this Value, args []Value) Value {
		return Int(thisTA(this).length())
	})
	defMethod(tap, "at", 1, func(this Value, args []Value) Value {
		_, ta := validTA(this)
		n := ta.length()
		k := toInteger(arg(args, 0))
