		if !ta.validIndex(rel) {
			throwRangeError("invalid array index")
		}
		r := createTypedArray(ta.kind, typedArrayProtos[ta.kind], n)
		rta := r.internal.(*TypedArray)
		for i := 0; i < n; i++ {
			if i == int(rel) {
