			return Undefined
		}
		so := toObject(src)
		sl := lengthOfArrayLike(so)
		if float64(sl)+off > float64(n) {
			throwRangeError("invalid offset")
		}
		for i := int64(0); i < sl; i++ {
			v := ta.convert(objGetI(so, i))
