type DataViewData struct {
	buf            *ArrayBufferData
	bufObj         *Object
	offset         int
	length         int
	lengthTracking bool
}

func (dv *DataViewData) byteLen() int {
	if dv.lengthTracking {
		return len(dv.buf.data) - dv.offset
	}
	return dv.length
}

func (dv *DataViewData) outOfBounds() bool {
	if dv.buf.detached {
		return true
	}
	if dv.offset > len(dv.buf.data) {
		return true
	}
	if !dv.lengthTracking && dv.offset+dv.length > len(dv.buf.data) {
		return true
	}
	return false
}

