		tzSet = true
	} else if c == '+' || c == '-' {
		sg := 1
		if c == '-' {
			sg = -1
		}
		d.p++
		th, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		if d.peek() == ':' {
			d.p++
		}
		tm, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		tzSet = true
		tzOff = sg * (th*60 + tm)
	}
	if d.p != len(s) {
		return 0, false
	}
	dayv := makeDay(float64(y), float64(mon-1), float64(day))
	t := makeDate(dayv, makeTime(float64(h), float64(mi), float64(sec), float64(ms)))
	if tzSet {
		t -= float64(tzOff) * 60000
	} else if hasTime {
		t = utcFromLocal(t)
	}
	return t, true
}

func monthIndex(w string) int {
	lw := strings.ToLower(w)
	for i, m := range monthNames {
		if len(lw) >= 3 && strings.HasPrefix(lw, strings.ToLower(m)) {
			return i
		}
	}
	return -1
}

func parseLegacyDate(s string) float64 {
	// tokenise
	type tok struct {
		kind int // 0 number,1 word,2 punct
		s    string
		n    int
		nd   int
	}
	var toks []tok
	i := 0
	for i < len(s) {
		c := s[i]
		if c >= '0' && c <= '9' {
			j := i
			v := 0
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				v = v*10 + int(s[j]-'0')
				j++
			}
			toks = append(toks, tok{kind: 0, s: s[i:j], n: v, nd: j - i})
			i = j
		} else if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
			j := i
			for j < len(s) && (s[j] >= 'a' && s[j] <= 'z' || s[j] >= 'A' && s[j] <= 'Z') {
				j++
			}
			toks = append(toks, tok{kind: 1, s: s[i:j]})
			i = j
		} else if c == '(' {
			// comment
			depth := 0
			for i < len(s) {
				if s[i] == '(' {
					depth++
				} else if s[i] == ')' {
					depth--
					if depth == 0 {
						i++
						break
					}
				}
				i++
			}
		} else {
			if c != ' ' && c != ',' {
				toks = append(toks, tok{kind: 2, s: string(c)})
			} else if c == ',' {
				toks = append(toks, tok{kind: 2, s: ","})
			}
			i++
		}
	}
	year, mon, day := -1, -1, -1
	h, mi, sec, ms := 0, 0, 0, 0
	tzSet := false
	tzOff := 0
	pm, am := false, false
	var nums []int
	var numDigits []int
	for k := 0; k < len(toks); k++ {
		t := toks[k]
		switch t.kind {
		case 0:
			// time?
			if k+1 < len(toks) && toks[k+1].kind == 2 && toks[k+1].s == ":" {
				h = t.n
				if k+2 < len(toks) && toks[k+2].kind == 0 {
					mi = toks[k+2].n
					k += 2
					if k+1 < len(toks) && toks[k+1].s == ":" && k+2 < len(toks) && toks[k+2].kind == 0 {
						sec = toks[k+2].n
						k += 2
						if k+1 < len(toks) && toks[k+1].s == "." && k+2 < len(toks) && toks[k+2].kind == 0 {
							v := toks[k+2].n
							n := toks[k+2].nd
							for n > 3 {
								v /= 10
								n--
							}
							for n < 3 {
								v *= 10
								n++
							}
							ms = v
							k += 2
						}
					}
				} else {
					return math.NaN()
				}
				continue
			}
			if k+1 < len(toks) && toks[k+1].kind == 2 && (toks[k+1].s == "/" || toks[k+1].s == "-") && k+2 < len(toks) && toks[k+2].kind == 0 {
				sep := toks[k+1].s
				a, b := t.n, toks[k+2].n
				k += 2
				c := -1
				if k+1 < len(toks) && toks[k+1].s == sep && k+2 < len(toks) && toks[k+2].kind == 0 {
					c = toks[k+2].n
					k += 2
				}
				if t.nd >= 3 {
					year, mon, day = a, b-1, 1
					if c >= 0 {
						day = c
					}
				} else {
					mon, day = a-1, b
					if c >= 0 {
						year = c
						if toks[k].nd <= 2 {
							if year < 50 {
								year += 2000
							} else {
								year += 1900
							}
						}
					}
				}
				continue
			}
			nums = append(nums, t.n)
			numDigits = append(numDigits, t.nd)
		case 1:
			w := strings.ToLower(t.s)
			switch {
			case w == "am":
				am = true
			case w == "pm":
				pm = true
			case w == "gmt" || w == "utc" || w == "ut" || w == "z":
				tzSet = true
				if k+1 < len(toks) && toks[k+1].kind == 2 && (toks[k+1].s == "+" || toks[k+1].s == "-") && k+2 < len(toks) && toks[k+2].kind == 0 {
					sg := 1
					if toks[k+1].s == "-" {
						sg = -1
					}
					v := toks[k+2].n
					nd := toks[k+2].nd
					k += 2
					var hh, mm int
					if nd <= 2 {
						hh = v
						if k+1 < len(toks) && toks[k+1].s == ":" && k+2 < len(toks) && toks[k+2].kind == 0 {
							mm = toks[k+2].n
							k += 2
						}
					} else {
						hh, mm = v/100, v%100
					}
					tzOff = sg * (hh*60 + mm)
				}
			case monthIndex(w) >= 0:
				mon = monthIndex(w)
			default:
				isDay := false
				for _, dn := range dayNames {
					if strings.HasPrefix(w, strings.ToLower(dn)) {
						isDay = true
					}
				}
				if !isDay {
					return math.NaN()
				}
			}
		case 2:
			if (t.s == "+" || t.s == "-") && k+1 < len(toks) && toks[k+1].kind == 0 && (h != 0 || mi != 0 || tzSet) && toks[k+1].nd == 4 {
				sg := 1
				if t.s == "-" {
					sg = -1
				}
				v := toks[k+1].n
				tzOff = sg * ((v/100)*60 + v%100)
				tzSet = true
				k++
			}
		}
	}
	// assign remaining numbers
	for idx, n := range nums {
		if numDigits[idx] >= 3 || n > 31 {
			if year < 0 {
				year = n
				continue
			}
		}
		if day < 0 && mon >= 0 {
			day = n
		} else if day < 0 && mon < 0 {
			day = n
		} else if year < 0 {
			year = n
			if numDigits[idx] <= 2 {
				if year < 50 {
					year += 2000
				} else {
					year += 1900
				}
			}
		}
	}
	if year < 0 || mon < 0 {
		return math.NaN()
	}
	if day < 0 {
		day = 1
	}
	if pm && h < 12 {
		h += 12
	}
	if am && h == 12 {
		h = 0
	}
	if mon > 11 || day > 31 || day < 1 || h > 24 || mi > 59 || sec > 59 {
		return math.NaN()
	}
	t := makeDate(makeDay(float64(year), float64(mon), float64(day)), makeTime(float64(h), float64(mi), float64(sec), float64(ms)))
	if tzSet {
		t -= float64(tzOff) * 60000
	} else {
		t = utcFromLocal(t)
	}
	return t
}

func parseDate(s string) float64 {
	s = strings.TrimSpace(s)
	if t, ok := parseISODate(s); ok {
		return timeClip(t)
	}
	return timeClip(parseLegacyDate(s))
}

func toLocaleDateStr(lt float64) string {
	y, mo, d := ymdFromTime(lt)
	return fmt.Sprintf("%02d/%02d/%s", mo+1, d, yearStr(y))
}

func toLocaleTimeStr(lt float64) string {
	h, mi, s, _ := timeParts(lt)
	ap := "AM"
	if h >= 12 {
		ap = "PM"
	}
	h12 := h % 12
	if h12 == 0 {
		h12 = 12
	}
	return fmt.Sprintf("%02d:%02d:%02d %s", h12, mi, s, ap)
}

func initDate() {
	dp := newObject()
	ctor := makeCtor("Date", 7, dp, func(this Value, args []Value) Value {
		t := dateNow()
		return StrGo(dateString(localTime(t)) + " " + timeString(localTime(t), t))
	}, func(args []Value, nt *Object) Value {
		var t float64
		switch len(args) {
		case 0:
			t = dateNow()
		case 1:
			v := args[0]
			if v.t == TagObj && v.obj().class == ClassDate {
				t = v.obj().internal.(*DateData).t
			} else {
				p := toPrimitive(v, "")
				if p.t == TagStr {
					t = parseDate(p.str().String())
				} else {
					t = timeClip(toNumber(p))
				}
			}
		default:
			nums := make([]float64, 7)
			nums[2] = 1
			for i := 0; i < 7 && i < len(args); i++ {
				nums[i] = toNumber(args[i])
			}
			y := nums[0]
			if y == y {
				yi := math.Trunc(y)
				if yi >= 0 && yi <= 99 {
					y = 1900 + yi
				}
			}
			fin := makeDate(makeDay(y, nums[1], nums[2]), makeTime(nums[3], nums[4], nums[5], nums[6]))
			t = timeClip(utcFromLocal(fin))
		}
		o := newObjectProto(getPrototypeFromCtor(nt, dp), ClassDate)
		o.internal = &DateData{t: t}
		return Obj(o)
	})
	addGlobal("Date", Obj(ctor))
	defMethod(ctor, "now", 0, func(this Value, args []Value) Value { return Num(dateNow()) })
	defMethod(ctor, "parse", 1, func(this Value, args []Value) Value {
		return Num(parseDate(toString(arg(args, 0)).String()))
	})
	defMethod(ctor, "UTC", 7, func(this Value, args []Value) Value {
		nums := make([]float64, 7)
		nums[2] = 1
		for i := 0; i < 7 && i < len(args); i++ {
			nums[i] = toNumber(args[i])
		}
		if len(args) == 0 {
			return NaNVal
		}
		y := nums[0]
		if y == y {
			yi := math.Trunc(y)
			if yi >= 0 && yi <= 99 {
				y = 1900 + yi
			}
		}
		return Num(timeClip(makeDate(makeDay(y, nums[1], nums[2]), makeTime(nums[3], nums[4], nums[5], nums[6]))))
	})
	finishCtor(ctor, dp)
	ci := dp.findOwn(keyConstructor)
	dp.removePropAt(ci)
	dp.compact()

	defMethod(dp, "valueOf", 0, func(this Value, args []Value) Value { return Num(thisDate(this).t) })
	defMethod(dp, "toString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		lt := localTime(t)
		return StrGo(dateString(lt) + " " + timeString(lt, t))
	})
	utcStr := func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		y, mo, d := ymdFromTime(t)
		h, mi, s, _ := timeParts(t)
		return StrGo(fmt.Sprintf("%s, %02d %s %s %02d:%02d:%02d GMT", dayNames[weekDay(t)], d, monthNames[mo], yearStr(y), h, mi, s))
	}
	defMethod(dp, "toUTCString", 0, utcStr)
	defMethod(dp, "toGMTString", 0, utcStr)
	defMethod(dp, "toISOString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			throwRangeError("Date value is NaN")
		}
		return StrGo(dateToISO(t))
	})
	defMethod(dp, "toDateString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(dateString(localTime(t)))
	})
	defMethod(dp, "toTimeString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(timeString(localTime(t), t))
	})
	defMethod(dp, "toLocaleString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		lt := localTime(t)
		return StrGo(toLocaleDateStr(lt) + ", " + toLocaleTimeStr(lt))
	})
	defMethod(dp, "toLocaleDateString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(toLocaleDateStr(localTime(t)))
	})
	defMethod(dp, "toLocaleTimeString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(toLocaleTimeStr(localTime(t)))
	})
	defMethod(dp, "getTimezoneOffset", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return NaNVal
		}
		return Num(-localTZA(t, true) / 60000)
	})
	defMethod(dp, "getTime", 0, func(this Value, args []Value) Value { return Num(thisDate(this).t) })
	getter := func(name string, local bool, f func(t float64) float64) {
		defMethod(dp, name, 0, func(this Value, args []Value) Value {
			t := thisDate(this).t
			if t != t {
				return NaNVal
			}
			if local {
				t = localTime(t)
			}
			return Num(f(t))
		})
	}
	fy := func(t float64) float64 { y, _, _ := ymdFromTime(t); return y }
	fm := func(t float64) float64 { _, m, _ := ymdFromTime(t); return float64(m) }
	fd := func(t float64) float64 { _, _, d := ymdFromTime(t); return float64(d) }
	fh := func(t float64) float64 { h, _, _, _ := timeParts(t); return float64(h) }
	fmi := func(t float64) float64 { _, m, _, _ := timeParts(t); return float64(m) }
	fs := func(t float64) float64 { _, _, s, _ := timeParts(t); return float64(s) }
	fms := func(t float64) float64 { _, _, _, ms := timeParts(t); return float64(ms) }
	fwd := func(t float64) float64 { return float64(weekDay(t)) }
	getter("getYear", true, func(t float64) float64 { return fy(t) - 1900 })
	getter("getFullYear", true, fy)
	getter("getUTCFullYear", false, fy)
	getter("getMonth", true, fm)
	getter("getUTCMonth", false, fm)
	getter("getDate", true, fd)
	getter("getUTCDate", false, fd)
	getter("getHours", true, fh)
	getter("getUTCHours", false, fh)
	getter("getMinutes", true, fmi)
	getter("getUTCMinutes", false, fmi)
	getter("getSeconds", true, fs)
	getter("getUTCSeconds", false, fs)
	getter("getMilliseconds", true, fms)
	getter("getUTCMilliseconds", false, fms)
	getter("getDay", true, fwd)
	getter("getUTCDay", false, fwd)
	defMethod(dp, "setTime", 1, func(this Value, args []Value) Value {
		d := thisDate(this)
		d.t = timeClip(toNumber(arg(args, 0)))
		return Num(d.t)
	})
	// setters: field index 0 year,1 month,2 date,3 hours,4 min,5 sec,6 ms
	setter := func(name string, local bool, first int, maxArgs int) {
		defMethod(dp, name, maxArgs, func(this Value, args []Value) Value {
			d := thisDate(this)
			t := d.t
			var vals []float64
			for i := 0; i < maxArgs && i < len(args); i++ {
				vals = append(vals, toNumber(args[i]))
			}
			if len(args) == 0 {
				vals = append(vals, math.NaN())
			}
			if t != t {
				if first != 0 {
					return NaNVal
				}
				t = 0
			} else if local {
				t = localTime(t)
			}
			y, mo, dd := ymdFromTime(t)
			h, mi, s, ms := timeParts(t)
			f := []float64{y, float64(mo), float64(dd), float64(h), float64(mi), float64(s), float64(ms)}
			for i, v := range vals {
				f[first+i] = v
			}
			nt := makeDate(makeDay(f[0], f[1], f[2]), makeTime(f[3], f[4], f[5], f[6]))
			if local {
				nt = utcFromLocal(nt)
			}
			d.t = timeClip(nt)
			return Num(d.t)
		})
	}
	setter("setMilliseconds", true, 6, 1)
	setter("setUTCMilliseconds", false, 6, 1)
	setter("setSeconds", true, 5, 2)
	setter("setUTCSeconds", false, 5, 2)
	setter("setMinutes", true, 4, 3)
	setter("setUTCMinutes", false, 4, 3)
	setter("setHours", true, 3, 4)
	setter("setUTCHours", false, 3, 4)
	setter("setDate", true, 2, 1)
	setter("setUTCDate", false, 2, 1)
	setter("setMonth", true, 1, 2)
	setter("setUTCMonth", false, 1, 2)
	defMethod(dp, "setYear", 1, func(this Value, args []Value) Value {
		d := thisDate(this)
		y := toNumber(arg(args, 0))
		if y != y {
			d.t = math.NaN()
			return NaNVal
		}
		yi := math.Trunc(y)
		if yi >= 0 && yi <= 99 {
			yi += 1900
		}
		t := d.t
		if t != t {
			t = 0
		} else {
			t = localTime(t)
		}
		_, mo, dd := ymdFromTime(t)
		nt := makeDate(makeDay(yi, float64(mo), float64(dd)), posMod(t, msPerDay))
		d.t = timeClip(utcFromLocal(nt))
		return Num(d.t)
	})
	setter("setFullYear", true, 0, 3)
	setter("setUTCFullYear", false, 0, 3)
	defMethod(dp, "toJSON", 1, func(this Value, args []Value) Value {
		o := toObject(this)
		tv := toPrimitive(Obj(o), "number")
		if tv.t == TagNum && (tv.n != tv.n || math.IsInf(tv.n, 0)) {
			return Null
		}
		f := o.Get(strKey("toISOString"), Obj(o))
		return callValue(f, Obj(o), nil)
	})
	dp.setOwn(keyConstructor, Obj(ctor), pWritable|pConfigurable)
	tp := newNativeFunc("[Symbol.toPrimitive]", 1, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		h := arg(args, 0)
		hint := ""
		if h.t == TagStr {
			hint = h.str().String()
		}
		var order []string
		switch hint {
		case "string", "default":
			order = []string{"toString", "valueOf"}
		case "number":
			order = []string{"valueOf", "toString"}
		default:
			throwTypeError("invalid hint")
		}
		for _, n := range order {
			m := getV(this, strKey(n))
			if m.isCallable() {
				r := callValue(m, this, nil)
				if r.t != TagObj {
					return r
				}
			}
		}
		throwTypeError("toPrimitive")
		return Undefined
	})
	dp.setOwn(PropKey{sym: SymToPrimitive}, Obj(tp), pConfigurable)
}
