package main

import (
	"fmt"
	"math"
	"strings"
	"time"
)

type DateData struct {
	t float64
}

const msPerDay = 86400000.0

func dayFromYear(y float64) float64 {
	return 365*(y-1970) + math.Floor((y-1969)/4) - math.Floor((y-1901)/100) + math.Floor((y-1601)/400)
}

func daysInYear(y float64) float64 {
	yi := int64(y)
	if yi%4 != 0 {
		return 365
	}
	if yi%100 != 0 {
		return 366
	}
	if yi%400 != 0 {
		return 365
	}
	return 366
}

func yearFromTime(t float64) float64 {
	d := math.Floor(t / msPerDay)
	y := math.Floor(d/365.2425) + 1970
	for dayFromYear(y) > d {
		y--
	}
	for dayFromYear(y+1) <= d {
		y++
	}
	return y
}

var monthStartDays = [2][13]int{
	{0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334, 365},
	{0, 31, 60, 91, 121, 152, 182, 213, 244, 274, 305, 335, 366},
}

// returns year, month (0-11), day (1-31)
func ymdFromTime(t float64) (float64, int, int) {
	y := yearFromTime(t)
	dayInYear := int(math.Floor(t/msPerDay) - dayFromYear(y))
	leap := 0
	if daysInYear(y) == 366 {
		leap = 1
	}
	m := 0
	for m < 11 && dayInYear >= monthStartDays[leap][m+1] {
		m++
	}
	return y, m, dayInYear - monthStartDays[leap][m] + 1
}

func weekDay(t float64) int {
	r := int(math.Mod(math.Floor(t/msPerDay)+4, 7))
	if r < 0 {
		r += 7
	}
	return r
}

func posMod(a, b float64) float64 {
	r := math.Mod(a, b)
	if r < 0 {
		r += b
	}
	return r
}

func makeTime(h, m, s, ms float64) float64 {
	if math.IsInf(h, 0) || math.IsInf(m, 0) || math.IsInf(s, 0) || math.IsInf(ms, 0) || h != h || m != m || s != s || ms != ms {
		return math.NaN()
	}
	return math.Trunc(h)*3600000 + math.Trunc(m)*60000 + math.Trunc(s)*1000 + math.Trunc(ms)
}

func makeDay(y, m, d float64) float64 {
	if math.IsInf(y, 0) || math.IsInf(m, 0) || math.IsInf(d, 0) || y != y || m != m || d != d {
		return math.NaN()
	}
	y, m, d = math.Trunc(y), math.Trunc(m), math.Trunc(d)
	ym := y + math.Floor(m/12)
	if math.Abs(ym) > 400000 {
		return math.NaN()
	}
	mn := int(posMod(m, 12))
	leap := 0
	if daysInYear(ym) == 366 {
		leap = 1
	}
	day := dayFromYear(ym) + float64(monthStartDays[leap][mn])
	return day + d - 1
}

func makeDate(day, t float64) float64 {
	if math.IsInf(day, 0) || math.IsInf(t, 0) || day != day || t != t {
		return math.NaN()
	}
	return day*msPerDay + t
}

func timeClip(t float64) float64 {
	if t != t || math.Abs(t) > 8.64e15 {
		return math.NaN()
	}
	return math.Trunc(t) + 0
}

// local time zone offset in minutes for UTC time t (ms)
func localTZA(t float64, isUTC bool) float64 {
	if t != t {
		return 0
	}
	sec := int64(math.Floor(t / 1000))
	if isUTC {
		_, off := time.Unix(sec, 0).In(time.Local).Zone()
		return float64(off) * 1000
	}
	// t is local time: approximate
	_, off := time.Unix(sec, 0).In(time.Local).Zone()
	_, off2 := time.Unix(sec-int64(off), 0).In(time.Local).Zone()
	return float64(off2) * 1000
}

func localTime(t float64) float64 { return t + localTZA(t, true) }
func utcFromLocal(t float64) float64 {
	if t != t {
		return t
	}
	return t - localTZA(t, false)
}

var dayNames = []string{"Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"}
var monthNames = []string{"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}

func timeParts(t float64) (h, m, s, ms int) {
	tw := posMod(t, msPerDay)
	h = int(tw / 3600000)
	m = int(math.Mod(tw/60000, 60))
	s = int(math.Mod(tw/1000, 60))
	ms = int(math.Mod(tw, 1000))
	return
}

func yearStr(y float64) string {
	if y >= 0 {
		return fmt.Sprintf("%04d", int64(y))
	}
	return fmt.Sprintf("-%06d", int64(-y))
}

func dateToISO(t float64) string {
	y, mo, d := ymdFromTime(t)
	h, mi, s, ms := timeParts(t)
	var ys string
	if y >= 0 && y <= 9999 {
		ys = fmt.Sprintf("%04d", int64(y))
	} else if y < 0 {
		ys = fmt.Sprintf("-%06d", int64(-y))
	} else {
		ys = fmt.Sprintf("+%06d", int64(y))
	}
	return fmt.Sprintf("%s-%02d-%02dT%02d:%02d:%02d.%03dZ", ys, mo+1, d, h, mi, s, ms)
}

func tzString(t float64) string {
	off := localTZA(t, true) / 60000
	sign := "+"
	if off < 0 {
		sign = "-"
		off = -off
	}
	return fmt.Sprintf("GMT%s%02d%02d", sign, int(off)/60, int(off)%60)
}

func dateString(lt float64) string {
	y, mo, d := ymdFromTime(lt)
	return fmt.Sprintf("%s %s %02d %s", dayNames[weekDay(lt)], monthNames[mo], d, yearStr(y))
}

func timeString(lt float64, t float64) string {
	h, mi, s, _ := timeParts(lt)
	return fmt.Sprintf("%02d:%02d:%02d %s", h, mi, s, tzString(t))
}

func thisDate(this Value) *DateData {
	if this.t == TagObj && this.obj().class == ClassDate {
		return this.obj().internal.(*DateData)
	}
	throwTypeError("not a Date object")
	return nil
}

func dateNow() float64 {
	return float64(time.Now().UnixNano()/1e6)
}

// ---------- parsing ----------

type dateScanner struct {
	s string
	p int
}

func (d *dateScanner) peek() byte {
	if d.p < len(d.s) {
		return d.s[d.p]
	}
	return 0
}

func (d *dateScanner) digits(min, max int) (int, int, bool) {
	start := d.p
	v := 0
	for d.p < len(d.s) && d.p-start < max && d.s[d.p] >= '0' && d.s[d.p] <= '9' {
		v = v*10 + int(d.s[d.p]-'0')
		d.p++
	}
	n := d.p - start
	if n < min {
		d.p = start
		return 0, 0, false
	}
	return v, n, true
}

func parseISODate(s string) (float64, bool) {
	d := &dateScanner{s: s}
	var y int
	sign := 1
	if c := d.peek(); c == '+' || c == '-' {
		if c == '-' {
			sign = -1
		}
		d.p++
		v, n, ok := d.digits(6, 6)
		if !ok || n != 6 {
			return 0, false
		}
		if sign == -1 && v == 0 {
			return 0, false
		}
		y = sign * v
	} else {
		v, _, ok := d.digits(4, 4)
		if !ok {
			return 0, false
		}
		y = v
	}
	mon, day := 1, 1
	if d.peek() == '-' {
		d.p++
		v, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		mon = v
		if d.peek() == '-' {
			d.p++
			v, _, ok := d.digits(2, 2)
			if !ok {
				return 0, false
			}
			day = v
		}
	}
	if mon < 1 || mon > 12 || day < 1 || day > 31 {
		return 0, false
	}
	h, mi, sec, ms := 0, 0, 0, 0
	hasTime := false
	tzSet := false
	tzOff := 0
	if c := d.peek(); c == 'T' || c == 't' || (c == ' ' && d.p+1 < len(s) && s[d.p+1] >= '0' && s[d.p+1] <= '9') {
		d.p++
		hasTime = true
		v, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		h = v
		if d.peek() != ':' {
			return 0, false
		}
		d.p++
		v, _, ok = d.digits(2, 2)
		if !ok {
			return 0, false
		}
		mi = v
		if d.peek() == ':' {
			d.p++
			v, _, ok = d.digits(2, 2)
			if !ok {
				return 0, false
			}
			sec = v
			if d.peek() == '.' || d.peek() == ',' {
				d.p++
				start := d.p
				v, n, ok := d.digits(1, 9)
				if !ok {
					return 0, false
				}
				_ = start
				for n > 3 {
					v /= 10
					n--
				}
				for n < 3 {
					v *= 10
					n++
				}
				ms = v
			}
		}
		if h > 24 || mi > 59 || sec > 59 || (h == 24 && (mi != 0 || sec != 0 || ms != 0)) {
			return 0, false
		}
	}
	if c := d.peek(); c == 'Z' || c == 'z' {
		d.p++
		tzSet = true
	} else if c == '+' || c == '-' {
		sg := 1
		if c == '-' {
			sg = -1
		}
		d.p++
		th, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		if d.peek() == ':' {
			d.p++
		}
		tm, _, ok := d.digits(2, 2)
		if !ok {
			return 0, false
		}
		tzSet = true
		tzOff = sg * (th*60 + tm)
	}
	if d.p != len(s) {
		return 0, false
	}
	dayv := makeDay(float64(y), float64(mon-1), float64(day))
	t := makeDate(dayv, makeTime(float64(h), float64(mi), float64(sec), float64(ms)))
	if tzSet {
		t -= float64(tzOff) * 60000
	} else if hasTime {
		t = utcFromLocal(t)
	}
	return t, true
}

func monthIndex(w string) int {
	lw := strings.ToLower(w)
	for i, m := range monthNames {
		if len(lw) >= 3 && strings.HasPrefix(lw, strings.ToLower(m)) {
			return i
		}
	}
	return -1
}

func parseLegacyDate(s string) float64 {
	// tokenise
	type tok struct {
		kind int // 0 number,1 word,2 punct
		s    string
		n    int
		nd   int
	}
	var toks []tok
	i := 0
	for i < len(s) {
		c := s[i]
		if c >= '0' && c <= '9' {
			j := i
			v := 0
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				v = v*10 + int(s[j]-'0')
				j++
			}
			toks = append(toks, tok{kind: 0, s: s[i:j], n: v, nd: j - i})
			i = j
		} else if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' {
			j := i
			for j < len(s) && (s[j] >= 'a' && s[j] <= 'z' || s[j] >= 'A' && s[j] <= 'Z') {
				j++
			}
			toks = append(toks, tok{kind: 1, s: s[i:j]})
			i = j
		} else if c == '(' {
			// comment
			depth := 0
			for i < len(s) {
				if s[i] == '(' {
					depth++
				} else if s[i] == ')' {
					depth--
					if depth == 0 {
						i++
						break
					}
				}
				i++
			}
		} else {
			if c != ' ' && c != ',' {
				toks = append(toks, tok{kind: 2, s: string(c)})
			} else if c == ',' {
				toks = append(toks, tok{kind: 2, s: ","})
			}
			i++
		}
	}
	year, mon, day := -1, -1, -1
	h, mi, sec, ms := 0, 0, 0, 0
	tzSet := false
	tzOff := 0
	pm, am := false, false
	var nums []int
	var numDigits []int
	for k := 0; k < len(toks); k++ {
		t := toks[k]
		switch t.kind {
		case 0:
			// time?
			if k+1 < len(toks) && toks[k+1].kind == 2 && toks[k+1].s == ":" {
				h = t.n
				if k+2 < len(toks) && toks[k+2].kind == 0 {
					mi = toks[k+2].n
					k += 2
					if k+1 < len(toks) && toks[k+1].s == ":" && k+2 < len(toks) && toks[k+2].kind == 0 {
						sec = toks[k+2].n
						k += 2
						if k+1 < len(toks) && toks[k+1].s == "." && k+2 < len(toks) && toks[k+2].kind == 0 {
							v := toks[k+2].n
							n := toks[k+2].nd
							for n > 3 {
								v /= 10
								n--
							}
							for n < 3 {
								v *= 10
								n++
							}
							ms = v
							k += 2
						}
					}
				} else {
					return math.NaN()
				}
				continue
			}
			if k+1 < len(toks) && toks[k+1].kind == 2 && (toks[k+1].s == "/" || toks[k+1].s == "-") && k+2 < len(toks) && toks[k+2].kind == 0 {
				sep := toks[k+1].s
				a, b := t.n, toks[k+2].n
				k += 2
				c := -1
				if k+1 < len(toks) && toks[k+1].s == sep && k+2 < len(toks) && toks[k+2].kind == 0 {
					c = toks[k+2].n
					k += 2
				}
				if t.nd >= 3 {
					year, mon, day = a, b-1, 1
					if c >= 0 {
						day = c
					}
				} else {
					mon, day = a-1, b
					if c >= 0 {
						year = c
						if toks[k].nd <= 2 {
							if year < 50 {
								year += 2000
							} else {
								year += 1900
							}
						}
					}
				}
				continue
			}
			nums = append(nums, t.n)
			numDigits = append(numDigits, t.nd)
		case 1:
			w := strings.ToLower(t.s)
			switch {
			case w == "am":
				am = true
			case w == "pm":
				pm = true
			case w == "gmt" || w == "utc" || w == "ut" || w == "z":
				tzSet = true
				if k+1 < len(toks) && toks[k+1].kind == 2 && (toks[k+1].s == "+" || toks[k+1].s == "-") && k+2 < len(toks) && toks[k+2].kind == 0 {
					sg := 1
					if toks[k+1].s == "-" {
						sg = -1
					}
					v := toks[k+2].n
					nd := toks[k+2].nd
					k += 2
					var hh, mm int
					if nd <= 2 {
						hh = v
						if k+1 < len(toks) && toks[k+1].s == ":" && k+2 < len(toks) && toks[k+2].kind == 0 {
							mm = toks[k+2].n
							k += 2
						}
					} else {
						hh, mm = v/100, v%100
					}
					tzOff = sg * (hh*60 + mm)
				}
			case monthIndex(w) >= 0:
				mon = monthIndex(w)
			default:
				isDay := false
				for _, dn := range dayNames {
					if strings.HasPrefix(w, strings.ToLower(dn)) {
						isDay = true
					}
				}
				if !isDay {
					return math.NaN()
				}
			}
		case 2:
			if (t.s == "+" || t.s == "-") && k+1 < len(toks) && toks[k+1].kind == 0 && (h != 0 || mi != 0 || tzSet) && toks[k+1].nd == 4 {
				sg := 1
				if t.s == "-" {
					sg = -1
				}
				v := toks[k+1].n
				tzOff = sg * ((v/100)*60 + v%100)
				tzSet = true
				k++
			}
		}
	}
	// assign remaining numbers
	for idx, n := range nums {
		if numDigits[idx] >= 3 || n > 31 {
			if year < 0 {
				year = n
				continue
			}
		}
		if day < 0 && mon >= 0 {
			day = n
		} else if day < 0 && mon < 0 {
			day = n
		} else if year < 0 {
			year = n
			if numDigits[idx] <= 2 {
				if year < 50 {
					year += 2000
				} else {
					year += 1900
				}
			}
		}
	}
	if year < 0 || mon < 0 {
		return math.NaN()
	}
	if day < 0 {
		day = 1
	}
	if pm && h < 12 {
		h += 12
	}
	if am && h == 12 {
		h = 0
	}
	if mon > 11 || day > 31 || day < 1 || h > 24 || mi > 59 || sec > 59 {
		return math.NaN()
	}
	t := makeDate(makeDay(float64(year), float64(mon), float64(day)), makeTime(float64(h), float64(mi), float64(sec), float64(ms)))
	if tzSet {
		t -= float64(tzOff) * 60000
	} else {
		t = utcFromLocal(t)
	}
	return t
}

func parseDate(s string) float64 {
	s = strings.TrimSpace(s)
	if t, ok := parseISODate(s); ok {
		return timeClip(t)
	}
	return timeClip(parseLegacyDate(s))
}

func toLocaleDateStr(lt float64) string {
	y, mo, d := ymdFromTime(lt)
	return fmt.Sprintf("%02d/%02d/%s", mo+1, d, yearStr(y))
}

func toLocaleTimeStr(lt float64) string {
	h, mi, s, _ := timeParts(lt)
	ap := "AM"
	if h >= 12 {
		ap = "PM"
	}
	h12 := h % 12
	if h12 == 0 {
		h12 = 12
	}
	return fmt.Sprintf("%02d:%02d:%02d %s", h12, mi, s, ap)
}

func initDate() {
	dp := newObject()
	ctor := makeCtor("Date", 7, dp, func(this Value, args []Value) Value {
		t := dateNow()
		return StrGo(dateString(localTime(t)) + " " + timeString(localTime(t), t))
	}, func(args []Value, nt *Object) Value {
		var t float64
		switch len(args) {
		case 0:
			t = dateNow()
		case 1:
			v := args[0]
			if v.t == TagObj && v.obj().class == ClassDate {
				t = v.obj().internal.(*DateData).t
			} else {
				p := toPrimitive(v, "")
				if p.t == TagStr {
					t = parseDate(p.str().String())
				} else {
					t = timeClip(toNumber(p))
				}
			}
		default:
			nums := make([]float64, 7)
			nums[2] = 1
			for i := 0; i < 7 && i < len(args); i++ {
				nums[i] = toNumber(args[i])
			}
			y := nums[0]
			if y == y {
				yi := math.Trunc(y)
				if yi >= 0 && yi <= 99 {
					y = 1900 + yi
				}
			}
			fin := makeDate(makeDay(y, nums[1], nums[2]), makeTime(nums[3], nums[4], nums[5], nums[6]))
			t = timeClip(utcFromLocal(fin))
		}
		o := newObjectProto(getPrototypeFromCtor(nt, dp), ClassDate)
		o.internal = &DateData{t: t}
		return Obj(o)
	})
	addGlobal("Date", Obj(ctor))
	defMethod(ctor, "now", 0, func(this Value, args []Value) Value { return Num(dateNow()) })
	defMethod(ctor, "parse", 1, func(this Value, args []Value) Value {
		return Num(parseDate(toString(arg(args, 0)).String()))
	})
	defMethod(ctor, "UTC", 7, func(this Value, args []Value) Value {
		nums := make([]float64, 7)
		nums[2] = 1
		for i := 0; i < 7 && i < len(args); i++ {
			nums[i] = toNumber(args[i])
		}
		if len(args) == 0 {
			return NaNVal
		}
		y := nums[0]
		if y == y {
			yi := math.Trunc(y)
			if yi >= 0 && yi <= 99 {
				y = 1900 + yi
			}
		}
		return Num(timeClip(makeDate(makeDay(y, nums[1], nums[2]), makeTime(nums[3], nums[4], nums[5], nums[6]))))
	})
	finishCtor(ctor, dp)
	ci := dp.findOwn(keyConstructor)
	dp.removePropAt(ci)
	dp.compact()

	defMethod(dp, "valueOf", 0, func(this Value, args []Value) Value { return Num(thisDate(this).t) })
	defMethod(dp, "toString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		lt := localTime(t)
		return StrGo(dateString(lt) + " " + timeString(lt, t))
	})
	utcStr := func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		y, mo, d := ymdFromTime(t)
		h, mi, s, _ := timeParts(t)
		return StrGo(fmt.Sprintf("%s, %02d %s %s %02d:%02d:%02d GMT", dayNames[weekDay(t)], d, monthNames[mo], yearStr(y), h, mi, s))
	}
	defMethod(dp, "toUTCString", 0, utcStr)
	defMethod(dp, "toGMTString", 0, utcStr)
	defMethod(dp, "toISOString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			throwRangeError("Date value is NaN")
		}
		return StrGo(dateToISO(t))
	})
	defMethod(dp, "toDateString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(dateString(localTime(t)))
	})
	defMethod(dp, "toTimeString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(timeString(localTime(t), t))
	})
	defMethod(dp, "toLocaleString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		lt := localTime(t)
		return StrGo(toLocaleDateStr(lt) + ", " + toLocaleTimeStr(lt))
	})
	defMethod(dp, "toLocaleDateString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(toLocaleDateStr(localTime(t)))
	})
	defMethod(dp, "toLocaleTimeString", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return StrGo("Invalid Date")
		}
		return StrGo(toLocaleTimeStr(localTime(t)))
	})
	defMethod(dp, "getTimezoneOffset", 0, func(this Value, args []Value) Value {
		t := thisDate(this).t
		if t != t {
			return NaNVal
		}
		return Num(-localTZA(t, true) / 60000)
	})
	defMethod(dp, "getTime", 0, func(this Value, args []Value) Value { return Num(thisDate(this).t) })
	getter := func(name string, local bool, f func(t float64) float64) {
		defMethod(dp, name, 0, func(this Value, args []Value) Value {
			t := thisDate(this).t
			if t != t {
				return NaNVal
			}
			if local {
				t = localTime(t)
			}
			return Num(f(t))
		})
	}
	fy := func(t float64) float64 { y, _, _ := ymdFromTime(t); return y }
	fm := func(t float64) float64 { _, m, _ := ymdFromTime(t); return float64(m) }
	fd := func(t float64) float64 { _, _, d := ymdFromTime(t); return float64(d) }
