package main

import (
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf16"
)

// ---------- character sets ----------

type runeRange struct{ lo, hi rune }

type charSet struct {
	ranges []runeRange
	tables []*unicode.RangeTable
	ntables []*unicode.RangeTable // negated tables (\P)
	neg    bool
	// for v-flag string alternatives (\q{...})
	strs [][]rune
}

func (cs *charSet) addRange(lo, hi rune) { cs.ranges = append(cs.ranges, runeRange{lo, hi}) }

func (cs *charSet) addSet(o *charSet) {
	if o.neg {
		// add complement of o
		comp := o.complementRanges()
		cs.ranges = append(cs.ranges, comp...)
		return
	}
	cs.ranges = append(cs.ranges, o.ranges...)
	cs.tables = append(cs.tables, o.tables...)
	cs.ntables = append(cs.ntables, o.ntables...)
	cs.strs = append(cs.strs, o.strs...)
}

func (cs *charSet) normalize() {
	if len(cs.ranges) < 2 {
		return
	}
	sort.Slice(cs.ranges, func(i, j int) bool { return cs.ranges[i].lo < cs.ranges[j].lo })
	out := cs.ranges[:1]
	for _, r := range cs.ranges[1:] {
		last := &out[len(out)-1]
		if r.lo <= last.hi+1 {
			if r.hi > last.hi {
				last.hi = r.hi
			}
		} else {
			out = append(out, r)
		}
	}
	cs.ranges = out
}

func (cs *charSet) complementRanges() []runeRange {
	c := &charSet{ranges: append([]runeRange{}, cs.ranges...)}
	// materialize tables
	for _, t := range cs.tables {
		c.ranges = append(c.ranges, tableRanges(t)...)
	}
	c.normalize()
	var out []runeRange
	prev := rune(0)
	for _, r := range c.ranges {
		if r.lo > prev {
			out = append(out, runeRange{prev, r.lo - 1})
		}
		prev = r.hi + 1
	}
	if prev <= 0x10FFFF {
		out = append(out, runeRange{prev, 0x10FFFF})
	}
	return out
}

func tableRanges(t *unicode.RangeTable) []runeRange {
	var out []runeRange
	for _, r := range t.R16 {
		if r.Stride == 1 {
			out = append(out, runeRange{rune(r.Lo), rune(r.Hi)})
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				out = append(out, runeRange{c, c})
			}
		}
	}
	for _, r := range t.R32 {
		if r.Stride == 1 {
			out = append(out, runeRange{rune(r.Lo), rune(r.Hi)})
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				out = append(out, runeRange{c, c})
			}
		}
	}
	return out
}

func (cs *charSet) has(c rune) bool {
	r := cs.hasRaw(c)
	if cs.neg {
		return !r
	}
	return r
}

func (cs *charSet) hasRaw(c rune) bool {
	rs := cs.ranges
	lo, hi := 0, len(rs)
	for lo < hi {
		m := (lo + hi) / 2
		if c < rs[m].lo {
			hi = m
		} else if c > rs[m].hi {
			lo = m + 1
		} else {
			return true
		}
	}
	for _, t := range cs.tables {
		if unicode.Is(t, c) {
			return true
		}
	}
	for _, t := range cs.ntables {
		if !unicode.Is(t, c) {
			return true
		}
	}
	return false
}

// ---------- AST ----------

type reAST struct {
	kind     int // 0 char,1 any,2 class,3 seq,4 alt,5 group,6 repeat,7 bol,8 eol,9 wordb,10 notwordb,11 backref,12 look,13 empty, 14 modifiers group
	c        rune
	cs       *charSet
	items    []*reAST
	idx      int
	name     string
	min, max int
	greedy   bool
	neg      bool
	behind   bool
	refs     []int
	refName  string
	capStart int
	capEnd   int
	icase    int // -1 inherit, 0 off, 1 on (modifiers)
	multi    int
	dotall   int
}

// ---------- parser ----------

type reParser struct {
	src        []rune
	pos        int
	unicode    bool
	vmode      bool
	ngroups    int
	names      map[string][]int
	groupNames []string
	hasNamed   bool
	err        string
	backrefs   []*reAST
}

type reSyntaxError struct{ msg string }

func (p *reParser) fail(msg string) {
	panic(&reSyntaxError{msg})
}

func (p *reParser) eof() bool { return p.pos >= len(p.src) }
func (p *reParser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}
func (p *reParser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return -1
}

func (p *reParser) parseDisjunction() *reAST {
	alts := []*reAST{p.parseAlternative()}
	for p.peek() == '|' {
		p.pos++
		alts = append(alts, p.parseAlternative())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reAST{kind: 4, items: alts}
}

func (p *reParser) parseAlternative() *reAST {
	var items []*reAST
	for !p.eof() && p.peek() != '|' && p.peek() != ')' {
		t := p.parseTerm()
		if t != nil {
			items = append(items, t)
		}
	}
	return &reAST{kind: 3, items: items}
}

func (p *reParser) parseTerm() *reAST {
	c := p.peek()
	capBefore := p.ngroups
	var atom *reAST
	switch c {
	case '^':
		p.pos++
		return &reAST{kind: 7}
	case '$':
		p.pos++
		return &reAST{kind: 8}
	case '\\':
		if p.peekAt(1) == 'b' {
			p.pos += 2
			return &reAST{kind: 9}
		}
		if p.peekAt(1) == 'B' {
			p.pos += 2
			return &reAST{kind: 10}
		}
		p.pos++
		atom = p.parseAtomEscape()
	case '(':
		p.pos++
		if p.peek() == '?' {
			p.pos++
			switch p.peek() {
			case ':':
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 5, idx: -1, items: []*reAST{d}}
			case '=', '!':
				neg := p.peek() == '!'
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 12, neg: neg, items: []*reAST{d}}
				if p.unicode {
					return atom // lookaheads not quantifiable in unicode mode
				}
			case '<':
				if p.peekAt(1) == '=' || p.peekAt(1) == '!' {
					neg := p.peekAt(1) == '!'
					p.pos += 2
					d := p.parseDisjunction()
					p.expect(')')
					return &reAST{kind: 12, neg: neg, behind: true, items: []*reAST{d}}
				}
				p.pos++
				name := p.parseGroupName()
				p.ngroups++
				idx := p.ngroups
				if p.names == nil {
					p.names = map[string][]int{}
				}
				if len(p.names[name]) > 0 {
					p.fail("duplicate group name")
				}
				p.names[name] = append(p.names[name], idx)
				for len(p.groupNames) <= idx {
					p.groupNames = append(p.groupNames, "")
				}
				p.groupNames[idx] = name
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 5, idx: idx, name: name, items: []*reAST{d}}
			default:
				// modifiers (?ims-ims:...)
				start := p.pos
				add, rem := "", ""
				cur := &add
				for !p.eof() && p.peek() != ':' {
					ch := p.peek()
					if ch == '-' {
						if cur == &rem {
							p.fail("invalid group")
						}
						cur = &rem
						p.pos++
						continue
					}
					if ch != 'i' && ch != 'm' && ch != 's' {
						p.pos = start
						p.fail("invalid group")
					}
					if strings.ContainsRune(add, ch) || strings.ContainsRune(rem, ch) {
						p.fail("invalid group")
					}
					*cur += string(ch)
					p.pos++
				}
				if p.eof() || (add == "" && rem == "") {
					p.fail("invalid group")
				}
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				g := &reAST{kind: 14, items: []*reAST{d}, icase: -1, multi: -1, dotall: -1}
				set := func(s string, v int) {
					for _, ch := range s {
						switch ch {
						case 'i':
							g.icase = v
						case 'm':
							g.multi = v
						case 's':
							g.dotall = v
						}
					}
				}
				set(add, 1)
				set(rem, 0)
				atom = g
			}
		} else {
			p.ngroups++
			idx := p.ngroups
			for len(p.groupNames) <= idx {
				p.groupNames = append(p.groupNames, "")
			}
			d := p.parseDisjunction()
			p.expect(')')
			atom = &reAST{kind: 5, idx: idx, items: []*reAST{d}}
		}
	case '.':
		p.pos++
		atom = &reAST{kind: 1}
	case '[':
		p.pos++
		atom = &reAST{kind: 2, cs: p.parseClass()}
	case '*', '+', '?':
		p.fail("nothing to repeat")
	case '{':
		if p.unicode {
			p.fail("nothing to repeat")
		}
		// annex B: literal if not a valid quantifier
		save := p.pos
		if _, _, ok := p.tryQuantifierBraces(); ok {
			p.fail("nothing to repeat")
		}
		p.pos = save + 1
		atom = &reAST{kind: 0, c: '{'}
	case ')':
		p.fail("unexpected ')'")
	case ']', '}':
		if p.unicode {
			p.fail("syntax error")
		}
		p.pos++
		atom = &reAST{kind: 0, c: c}
	default:
		p.pos++
		atom = &reAST{kind: 0, c: c}
	}
	return p.parseQuantifier(atom, capBefore)
}

func (p *reParser) expect(c rune) {
	if p.peek() != c {
		p.fail("expecting '" + string(c) + "'")
	}
	p.pos++
}

func (p *reParser) tryQuantifierBraces() (int, int, bool) {
	// at '{'
	save := p.pos
	p.pos++
	readInt := func() (int, bool) {
		start := p.pos
		v := 0
		for !p.eof() && p.peek() >= '0' && p.peek() <= '9' {
			if v < 1<<30 {
				v = v*10 + int(p.peek()-'0')
			}
			p.pos++
		}
		return v, p.pos > start
	}
	min, ok := readInt()
	if !ok {
		p.pos = save
		return 0, 0, false
	}
	max := min
	if p.peek() == ',' {
		p.pos++
		if p.peek() == '}' {
			max = -1
		} else {
			m, ok := readInt()
			if !ok {
				p.pos = save
				return 0, 0, false
			}
			max = m
		}
	}
	if p.peek() != '}' {
		p.pos = save
		return 0, 0, false
	}
	p.pos++
	return min, max, true
}

func (p *reParser) parseQuantifier(atom *reAST, capBefore int) *reAST {
	c := p.peek()
	min, max := -2, 0
	switch c {
	case '*':
		min, max = 0, -1
		p.pos++
	case '+':
		min, max = 1, -1
		p.pos++
	case '?':
		min, max = 0, 1
		p.pos++
	case '{':
		save := p.pos
		mn, mx, ok := p.tryQuantifierBraces()
		if !ok {
			if p.unicode {
				p.fail("invalid repetition count")
			}
			p.pos = save
			return atom
		}
		if mx >= 0 && mn > mx {
			p.fail("invalid repetition count")
		}
		min, max = mn, mx
	default:
		return atom
	}
	if atom.kind == 7 || atom.kind == 8 || atom.kind == 9 || atom.kind == 10 || (atom.kind == 12 && atom.behind) {
		p.fail("nothing to repeat")
	}
	greedy := true
	if p.peek() == '?' {
		greedy = false
		p.pos++
	}
	return &reAST{kind: 6, items: []*reAST{atom}, min: min, max: max, greedy: greedy, capStart: capBefore + 1, capEnd: p.ngroups + 1}
}

func (p *reParser) parseGroupName() string {
	var sb []rune
	for {
		if p.eof() {
			p.fail("invalid group name")
		}
		c := p.peek()
		if c == '>' {
			p.pos++
			break
		}
		if c == '\\' {
			p.pos++
			if p.peek() != 'u' {
				p.fail("invalid group name")
			}
			p.pos++
			cp := p.parseUnicodeEscapeAfterU(true)
			if cp < 0 {
				p.fail("invalid group name")
			}
			c = cp
		} else {
			p.pos++
			if c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 {
				c = utf16.DecodeRune(c, p.peek())
				p.pos++
			}
		}
		if len(sb) == 0 {
			if !isIDStart(c) {
				p.fail("invalid group name")
			}
		} else if !isIDPart(c) {
			p.fail("invalid group name")
		}
		sb = append(sb, c)
	}
	if len(sb) == 0 {
		p.fail("invalid group name")
	}
	return string(sb)
}

func (p *reParser) parseUnicodeEscapeAfterU(allowBrace bool) rune {
	if p.peek() == '{' && (p.unicode || allowBrace) {
		p.pos++
		var v rune
		n := 0
		for !p.eof() && p.peek() != '}' {
			h := hexVal(byte(p.peek()))
			if p.peek() > 127 || h < 0 {
				return -1
			}
			v = v*16 + rune(h)
			if v > 0x10FFFF {
				p.fail("invalid escape sequence in regular expression")
			}
			n++
			p.pos++
		}
		if p.eof() || n == 0 {
			return -1
		}
		p.pos++
		return v
	}
	v := rune(0)
	for i := 0; i < 4; i++ {
		c := p.peekAt(i)
		if c < 0 || c > 127 || hexVal(byte(c)) < 0 {
			return -1
		}
		v = v*16 + rune(hexVal(byte(c)))
	}
	p.pos += 4
	if (p.unicode || allowBrace) && v >= 0xD800 && v < 0xDC00 && p.peek() == '\\' && p.peekAt(1) == 'u' {
		save := p.pos
		p.pos += 2
		w := rune(0)
		ok := true
		for i := 0; i < 4; i++ {
			c := p.peekAt(i)
			if c < 0 || c > 127 || hexVal(byte(c)) < 0 {
				ok = false
				break
			}
			w = w*16 + rune(hexVal(byte(c)))
		}
		if ok && w >= 0xDC00 && w < 0xE000 {
			p.pos += 4
			return utf16.DecodeRune(v, w)
		}
		p.pos = save
	}
	return v
}

var (
	digitSet = &charSet{ranges: []runeRange{{'0', '9'}}}
	wordSet  = &charSet{ranges: []runeRange{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}}
	spaceSet = &charSet{ranges: []runeRange{{9, 13}, {32, 32}, {0xA0, 0xA0}, {0x1680, 0x1680}, {0x2000, 0x200A}, {0x2028, 0x2029}, {0x202F, 0x202F}, {0x205F, 0x205F}, {0x3000, 0x3000}, {0xFEFF, 0xFEFF}}}
)

func negSet(s *charSet) *charSet {
	return &charSet{ranges: s.ranges, tables: s.tables, ntables: s.ntables, neg: !s.neg}
}

// parse escape after '\' in atom context
func (p *reParser) parseAtomEscape() *reAST {
	if p.eof() {
		p.fail("unexpected end")
	}
	c := p.peek()
	switch {
	case c >= '1' && c <= '9':
		save := p.pos
		v := 0
		for !p.eof() && p.peek() >= '0' && p.peek() <= '9' {
			v = v*10 + int(p.peek()-'0')
			p.pos++
			if v > 1<<20 {
				break
			}
		}
		node := &reAST{kind: 11, refs: []int{v}}
		node.idx = save
		p.backrefs = append(p.backrefs, node)
		return node
	case c == 'k':
		p.pos++
		if p.peek() != '<' {
			if p.unicode || p.hasNamed {
				p.fail("expecting group name")
			}
			return &reAST{kind: 0, c: 'k'}
		}
		save := p.pos
		p.pos++
		func() {
			defer func() {
				if x := recover(); x != nil {
					if !p.unicode && !p.hasNamed {
						p.pos = save
						return
					}
					panic(x)
				}
			}()
			name := p.parseGroupName()
			node := &reAST{kind: 11, refName: name}
			p.backrefs = append(p.backrefs, node)
			panic(node)
		}()
		return &reAST{kind: 0, c: 'k'}
	}
	cs := p.parseClassEscape(false)
	if cs != nil {
		return &reAST{kind: 2, cs: cs}
	}
	return &reAST{kind: 0, c: p.parseCharEscape(false)}
}

// returns non-nil for class escapes \d\D\w\W\s\S\p\P
func (p *reParser) parseClassEscape(inClass bool) *charSet {
	c := p.peek()
	switch c {
	case 'd':
		p.pos++
		return digitSet
	case 'D':
		p.pos++
		return negSet(digitSet)
	case 'w':
		p.pos++
		return wordSet
	case 'W':
		p.pos++
		return negSet(wordSet)
	case 's':
		p.pos++
		return spaceSet
	case 'S':
		p.pos++
		return negSet(spaceSet)
	case 'p', 'P':
		if !p.unicode {
			return nil
		}
		neg := c == 'P'
		p.pos++
		if p.peek() != '{' {
			p.fail("expecting '{' after \\p")
		}
		p.pos++
		start := p.pos
		for !p.eof() && p.peek() != '}' {
			p.pos++
		}
		if p.eof() {
			p.fail("expecting '}'")
		}
		name := string(p.src[start:p.pos])
		p.pos++
		cs := unicodePropertySet(name)
		if cs == nil {
			p.fail("unknown unicode property name")
		}
		if neg {
			return negSet(cs)
		}
		return cs
	}
	return nil
}

func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 't':
		return '\t'
	case 'n':
		return '\n'
	case 'v':
		return '\v'
	case 'f':
		return '\f'
	case 'r':
		return '\r'
	case 'c':
		n := p.peek()
		if n >= 'a' && n <= 'z' || n >= 'A' && n <= 'Z' || (inClass && !p.unicode && (n >= '0' && n <= '9' || n == '_')) {
			p.pos++
			return n % 32
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		p.pos--
		return '\\'
	case '0':
		if !(p.peek() >= '0' && p.peek() <= '9') {
			return 0
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		fallthrough
	case '1', '2', '3', '4', '5', '6', '7':
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		v := c - '0'
		if p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + p.peek() - '0'
			p.pos++
			if c <= '3' && p.peek() >= '0' && p.peek() <= '7' {
				v = v*8 + p.peek() - '0'
				p.pos++
			}
		}
		return v
	case 'x':
		h1, h2 := p.peek(), p.peekAt(1)
		if h1 >= 0 && h1 < 128 && h2 >= 0 && h2 < 128 && hexVal(byte(h1)) >= 0 && hexVal(byte(h2)) >= 0 {
			p.pos += 2
			return rune(hexVal(byte(h1))*16 + hexVal(byte(h2)))
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		return 'x'
	case 'u':
		cp := p.parseUnicodeEscapeAfterU(false)
		if cp < 0 {
			if p.unicode {
				p.fail("invalid escape sequence in regular expression")
			}
			return 'u'
		}
		return cp
	case '-':
		if inClass || !p.unicode {
			return '-'
		}
		p.fail("invalid escape sequence in regular expression")
	case -1:
		p.fail("unexpected end")
	}
	if p.unicode {
		if strings.ContainsRune("^$\\.*+?()[]{}|/", c) {
			return c
		}
		p.fail("invalid escape sequence in regular expression")
	}
	if c == 'k' && p.hasNamed {
		p.fail("invalid escape sequence in regular expression")
	}
	if c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 && p.unicode {
		r := utf16.DecodeRune(c, p.peek())
		p.pos++
		return r
	}
	return c
}

func (p *reParser) parseClass() *charSet {
	cs := &charSet{}
	if p.peek() == '^' {
		cs.neg = true
		p.pos++
	}
	if p.vmode {
		p.parseClassV(cs)
		return cs
	}
	for {
		if p.eof() {
			p.fail("unexpected end")
		}
		if p.peek() == ']' {
			p.pos++
			break
		}
		a, aset := p.parseClassAtom()
		if p.peek() == '-' && p.peekAt(1) != ']' && p.peekAt(1) != -1 {
			p.pos++
			b, bset := p.parseClassAtom()
			if aset != nil || bset != nil {
				if p.unicode {
					p.fail("invalid class range")
				}
				if aset != nil {
					cs.addSet(aset)
				} else {
					cs.addRange(a, a)
				}
				cs.addRange('-', '-')
				if bset != nil {
					cs.addSet(bset)
				} else {
					cs.addRange(b, b)
				}
				continue
			}
			if a > b {
				p.fail("invalid class range")
			}
			cs.addRange(a, b)
			continue
		}
		if aset != nil {
			cs.addSet(aset)
		} else {
			cs.addRange(a, a)
		}
	}
	cs.normalize()
	return cs
}

func (p *reParser) parseClassAtom() (rune, *charSet) {
	c := p.peek()
	if c == '\\' {
		p.pos++
		if p.eof() {
			p.fail("unexpected end")
		}
		if cs := p.parseClassEscape(true); cs != nil {
			return 0, cs
		}
		if p.peek() == 'b' {
			p.pos++
			return '\b', nil
		}
		if p.peek() == '-' && p.unicode {
			p.pos++
			return '-', nil
		}
		if !p.unicode && p.peek() >= '1' && p.peek() <= '9' && p.peek() >= '8' {
			c := p.peek()
			p.pos++
			return c, nil
		}
		return p.parseCharEscape(true), nil
	}
	p.pos++
	if p.unicode && c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 {
		r := utf16.DecodeRune(c, p.peek())
		p.pos++
		return r, nil
	}
	return c, nil
}

// v-mode class (set notation) - simplified
func (p *reParser) parseClassV(cs *charSet) {
	var cur *charSet = &charSet{}
	op := 0 // 0 union, 1 intersection, 2 subtraction
	var acc *charSet
	first := true
	flush := func() {
		cur.normalize()
		if first {
			acc = cur
			first = false
		} else {
			switch op {
			case 1:
				acc = intersectSets(acc, cur)
			case 2:
				acc = subtractSets(acc, cur)
			default:
				acc.addSet(cur)
				acc.normalize()
			}
		}
		cur = &charSet{}
	}
	for {
		if p.eof() {
			p.fail("unexpected end")
		}
		c := p.peek()
		if c == ']' {
			p.pos++
			break
		}
		if c == '&' && p.peekAt(1) == '&' {
			p.pos += 2
			flush()
			op = 1
			continue
		}
		if c == '-' && p.peekAt(1) == '-' {
			p.pos += 2
			flush()
			op = 2
			continue
		}
		if c == '[' {
			p.pos++
			sub := &charSet{}
			if p.peek() == '^' {
				sub.neg = true
				p.pos++
			}
			p.parseClassV(sub)
			cur.addSet(sub)
			continue
		}
		if c == '\\' && p.peekAt(1) == 'q' && p.peekAt(2) == '{' {
			p.pos += 3
			var str []rune
			for !p.eof() && p.peek() != '}' {
				if p.peek() == '|' {
					p.pos++
					if len(str) == 1 {
						cur.addRange(str[0], str[0])
					} else {
						cur.strs = append(cur.strs, str)
					}
					str = nil
					continue
				}
				if p.peek() == '\\' {
					p.pos++
					str = append(str, p.parseCharEscape(true))
					continue
				}
				str = append(str, p.peek())
				p.pos++
			}
			p.pos++
			if len(str) == 1 {
				cur.addRange(str[0], str[0])
			} else {
				cur.strs = append(cur.strs, str)
			}
			continue
		}
		a, aset := p.parseClassAtom()
		if aset != nil {
			cur.addSet(aset)
			continue
		}
		if p.peek() == '-' && p.peekAt(1) != '-' && p.peekAt(1) != ']' {
			p.pos++
			b, _ := p.parseClassAtom()
			if a > b {
				p.fail("invalid class range")
			}
			cur.addRange(a, b)
			continue
		}
		cur.addRange(a, a)
	}
	flush()
	cs.ranges = acc.ranges
	cs.tables = acc.tables
	cs.ntables = acc.ntables
	cs.strs = acc.strs
	cs.normalize()
}

func materialize(s *charSet) []runeRange {
	if s.neg {
		return s.complementRanges()
	}
	c := &charSet{ranges: append([]runeRange{}, s.ranges...)}
	for _, t := range s.tables {
		c.ranges = append(c.ranges, tableRanges(t)...)
	}
	for _, t := range s.ntables {
		cc := &charSet{tables: []*unicode.RangeTable{t}}
		c.ranges = append(c.ranges, cc.complementRanges()...)
	}
	c.normalize()
	return c.ranges
}

func intersectSets(a, b *charSet) *charSet {
	ar, br := materialize(a), materialize(b)
	out := &charSet{}
	i, j := 0, 0
	for i < len(ar) && j < len(br) {
		lo := ar[i].lo
		if br[j].lo > lo {
			lo = br[j].lo
		}
		hi := ar[i].hi
		if br[j].hi < hi {
			hi = br[j].hi
		}
		if lo <= hi {
			out.addRange(lo, hi)
		}
		if ar[i].hi < br[j].hi {
			i++
		} else {
			j++
		}
	}
	return out
}

func subtractSets(a, b *charSet) *charSet {
	nb := &charSet{ranges: materialize(b), neg: true}
	return intersectSets(&charSet{ranges: materialize(a)}, nb)
}

// ---------- unicode properties ----------

var gcAliases = map[string]string{
	"Letter": "L", "Cased_Letter": "LC", "Uppercase_Letter": "Lu", "Lowercase_Letter": "Ll", "Titlecase_Letter": "Lt",
	"Modifier_Letter": "Lm", "Other_Letter": "Lo", "Mark": "M", "Combining_Mark": "M", "Nonspacing_Mark": "Mn",
	"Spacing_Mark": "Mc", "Enclosing_Mark": "Me", "Number": "N", "Decimal_Number": "Nd", "digit": "Nd",
	"Letter_Number": "Nl", "Other_Number": "No", "Punctuation": "P", "punct": "P", "Connector_Punctuation": "Pc",
	"Dash_Punctuation": "Pd", "Open_Punctuation": "Ps", "Close_Punctuation": "Pe", "Initial_Punctuation": "Pi",
	"Final_Punctuation": "Pf", "Other_Punctuation": "Po", "Symbol": "S", "Math_Symbol": "Sm", "Currency_Symbol": "Sc",
	"Modifier_Symbol": "Sk", "Other_Symbol": "So", "Separator": "Z", "Space_Separator": "Zs", "Line_Separator": "Zl",
	"Paragraph_Separator": "Zp", "Other": "C", "Control": "Cc", "cntrl": "Cc", "Format": "Cf", "Surrogate": "Cs",
	"Private_Use": "Co", "Unassigned": "Cn",
}

func unicodePropertySet(name string) *charSet {
	if i := strings.IndexByte(name, '='); i >= 0 {
		k, v := name[:i], name[i+1:]
		switch k {
		case "General_Category", "gc":
			return gcSet(v)
		case "Script", "sc", "Script_Extensions", "scx":
			if t, ok := unicode.Scripts[v]; ok {
				return &charSet{tables: []*unicode.RangeTable{t}}
			}
			if full, ok := scriptAliases[v]; ok {
				return &charSet{tables: []*unicode.RangeTable{unicode.Scripts[full]}}
			}
			return nil
		}
		return nil
	}
	if cs := gcSet(name); cs != nil {
		return cs
	}
	switch name {
	case "Any":
		return &charSet{ranges: []runeRange{{0, 0x10FFFF}}}
	case "ASCII":
		return &charSet{ranges: []runeRange{{0, 0x7F}}}
	case "Assigned":
		cs := gcSet("Cn")
		return negSet(cs)
	case "Alphabetic", "Alpha":
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lt, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Other_Alphabetic}}
	case "Lowercase", "Lower":
		return &charSet{tables: []*unicode.RangeTable{unicode.Ll, unicode.Other_Lowercase}}
	case "Uppercase", "Upper":
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Other_Uppercase}}
	case "Math":
		return &charSet{tables: []*unicode.RangeTable{unicode.Sm, unicode.Other_Math}}
	case "ID_Start", "IDS":
		return &charSet{tables: []*unicode.RangeTable{unicode.L, unicode.Nl, unicode.Other_ID_Start}}
	case "ID_Continue", "IDC":
		return &charSet{tables: []*unicode.RangeTable{unicode.L, unicode.Nl, unicode.Other_ID_Start, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc, unicode.Other_ID_Continue}}
	case "Emoji", "Emoji_Presentation", "Extended_Pictographic", "ExtPict", "EPres":
		return emojiSet()
	case "Emoji_Modifier", "EMod":
		return &charSet{ranges: []runeRange{{0x1F3FB, 0x1F3FF}}}
	case "Emoji_Component", "EComp":
		return &charSet{ranges: []runeRange{{'#', '#'}, {'*', '*'}, {'0', '9'}, {0x200D, 0x200D}, {0x20E3, 0x20E3}, {0xFE0F, 0xFE0F}, {0x1F1E6, 0x1F1FF}, {0x1F3FB, 0x1F3FF}, {0x1F9B0, 0x1F9B3}, {0xE0020, 0xE007F}}}
	case "Regional_Indicator", "RI":
		return &charSet{ranges: []runeRange{{0x1F1E6, 0x1F1FF}}}
	}
	alias := map[string]string{"WSpace": "White_Space", "space": "White_Space", "Hex": "Hex_Digit", "AHex": "ASCII_Hex_Digit",
		"Ideo": "Ideographic", "QMark": "Quotation_Mark", "Dash": "Dash", "Dia": "Diacritic", "Ext": "Extender",
		"SD": "Soft_Dotted", "STerm": "Sentence_Terminal", "Term": "Terminal_Punctuation", "VS": "Variation_Selector",
		"Pat_Syn": "Pattern_Syntax", "Pat_WS": "Pattern_White_Space", "Join_C": "Join_Control", "UIdeo": "Unified_Ideograph",
		"Dep": "Deprecated", "Bidi_C": "Bidi_Control", "NChar": "Noncharacter_Code_Point", "Radical": "Radical",
		"LOE": "Logical_Order_Exception", "IDSB": "IDS_Binary_Operator", "IDST": "IDS_Trinary_Operator"}
	if a, ok := alias[name]; ok {
		name = a
	}
	if name == "Sentence_Terminal" {
		name = "STerm"
		if t, ok := unicode.Properties["Sentence_Terminal"]; ok {
			return &charSet{tables: []*unicode.RangeTable{t}}
		}
	}
	if t, ok := unicode.Properties[name]; ok {
		return &charSet{tables: []*unicode.RangeTable{t}}
	}
	return nil
}

var scriptAliases = map[string]string{
	"Latn": "Latin", "Grek": "Greek", "Cyrl": "Cyrillic", "Arab": "Arabic", "Hebr": "Hebrew", "Hani": "Han",
	"Hira": "Hiragana", "Kana": "Katakana", "Thai": "Thai", "Deva": "Devanagari", "Hang": "Hangul", "Zyyy": "Common",
	"Zinh": "Inherited", "Armn": "Armenian", "Geor": "Georgian", "Ethi": "Ethiopic", "Beng": "Bengali", "Taml": "Tamil",
}

func gcSet(v string) *charSet {
	if a, ok := gcAliases[v]; ok {
		v = a
	}
	if v == "LC" {
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lt}}
	}
	if v == "Cn" {
		// unassigned: complement of all categories
		all := []*unicode.RangeTable{}
		for _, t := range unicode.Categories {
			all = append(all, t)
		}
		cs := &charSet{tables: all}
		return &charSet{ranges: cs.complementRanges()}
	}
	if v == "C" {
		cs := gcSet("Cn")
		cs.tables = append(cs.tables, unicode.C)
		return cs
	}
	if t, ok := unicode.Categories[v]; ok {
		return &charSet{tables: []*unicode.RangeTable{t}}
	}
	return nil
}

func emojiSet() *charSet {
	return &charSet{ranges: []runeRange{{0x00A9, 0x00A9}, {0x00AE, 0x00AE}, {0x203C, 0x203C}, {0x2049, 0x2049},
		{0x2122, 0x2122}, {0x2139, 0x2139}, {0x2194, 0x2199}, {0x21A9, 0x21AA}, {0x231A, 0x231B}, {0x2328, 0x2328},
		{0x23CF, 0x23CF}, {0x23E9, 0x23F3}, {0x23F8, 0x23FA}, {0x24C2, 0x24C2}, {0x25AA, 0x25AB}, {0x25B6, 0x25B6},
		{0x25C0, 0x25C0}, {0x25FB, 0x25FE}, {0x2600, 0x27BF}, {0x2934, 0x2935}, {0x2B05, 0x2B07}, {0x2B1B, 0x2B1C},
		{0x2B50, 0x2B50}, {0x2B55, 0x2B55}, {0x3030, 0x3030}, {0x303D, 0x303D}, {0x3297, 0x3297}, {0x3299, 0x3299},
		{0x1F000, 0x1FAFF}}}
}

// ---------- compiled program ----------

const (
	opChar = iota
	opAny
	opClass
	opBOL
	opEOL
	opWordB
	opNotWordB
	opGroupStart
	opGroupEnd
	opBackref
	opAlt
	opRepeat
	opLoop
	opLook
	opLookEnd
	opMatch
	opSetFlags
)

type reNode struct {
	op       int
	next     *reNode
	c        rune
	cs       *charSet
	alts     []*reNode
	body     *reNode
	min, max int
	greedy   bool
	idx      int
	refs     []int
	neg      bool
	back     bool
	capStart int
	capEnd   int
	simple   bool
	icase    bool
	multi    bool
	dotall   bool
}

type compiledRegExp struct {
	start      *reNode
	ngroups    int
	groupNames []string
	unicode    bool
	icase      bool
	multi      bool
	dotall     bool
	sticky     bool
	global     bool
	hasIndices bool
	vmode      bool
}

type reFlags struct {
	icase, multi, dotall bool
}

func (re *compiledRegExp) emit(a *reAST, next *reNode, back bool, fl reFlags) *reNode {
	switch a.kind {
	case 0:
		c := a.c
		if fl.icase {
			c = re.canon(c)
		}
		return &reNode{op: opChar, c: c, next: next, back: back, icase: fl.icase}
	case 1:
		return &reNode{op: opAny, next: next, back: back, dotall: fl.dotall}
	case 2:
		return &reNode{op: opClass, cs: a.cs, next: next, back: back, icase: fl.icase}
	case 3:
		n := next
		if back {
			for _, it := range a.items {
				n = re.emit(it, n, back, fl)
			}
		} else {
			for i := len(a.items) - 1; i >= 0; i-- {
				n = re.emit(a.items[i], n, back, fl)
			}
		}
		return n
	case 4:
		alt := &reNode{op: opAlt, next: next}
		for _, it := range a.items {
			alt.alts = append(alt.alts, re.emit(it, next, back, fl))
		}
		return alt
	case 5:
		if a.idx < 0 {
			return re.emit(a.items[0], next, back, fl)
		}
		end := &reNode{op: opGroupEnd, idx: a.idx, next: next, back: back}
		body := re.emit(a.items[0], end, back, fl)
		return &reNode{op: opGroupStart, idx: a.idx, next: body, back: back}
	case 14:
		nfl := fl
		if a.icase >= 0 {
			nfl.icase = a.icase == 1
		}
		if a.multi >= 0 {
			nfl.multi = a.multi == 1
		}
		if a.dotall >= 0 {
			nfl.dotall = a.dotall == 1
		}
		return re.emit(a.items[0], next, back, nfl)
	case 6:
		max := a.max
		if max < 0 {
			max = 1 << 30
		}
		rep := &reNode{op: opRepeat, min: a.min, max: max, greedy: a.greedy, next: next, capStart: a.capStart, capEnd: a.capEnd}
		loop := &reNode{op: opLoop, body: rep}
		rep.body = re.emit(a.items[0], loop, back, fl)
		if b := rep.body; (b.op == opChar || b.op == opAny || b.op == opClass) && b.next == loop {
			rep.simple = true
		}
		return rep
	case 7:
		return &reNode{op: opBOL, next: next, multi: fl.multi}
	case 8:
		return &reNode{op: opEOL, next: next, multi: fl.multi}
	case 9:
		return &reNode{op: opWordB, next: next, icase: fl.icase}
	case 10:
		return &reNode{op: opNotWordB, next: next, icase: fl.icase}
	case 11:
		return &reNode{op: opBackref, refs: a.refs, next: next, back: back, icase: fl.icase}
	case 12:
		end := &reNode{op: opLookEnd}
		look := &reNode{op: opLook, neg: a.neg, back: a.behind, next: next}
		look.body = re.emit(a.items[0], end, a.behind, fl)
		return look
	case 13:
		return next
	}
	return next
}

func compileRegExp(pattern *JSString, flags string) (re *compiledRegExp, errMsg string) {
	re = &compiledRegExp{}
	for _, f := range flags {
		var p *bool
		switch f {
		case 'g':
			p = &re.global
		case 'i':
			p = &re.icase
		case 'm':
			p = &re.multi
		case 's':
			p = &re.dotall
		case 'u':
			p = &re.unicode
		case 'y':
			p = &re.sticky
		case 'd':
			p = &re.hasIndices
		case 'v':
			p = &re.vmode
		default:
			return nil, "invalid regular expression flags"
		}
		if *p {
			return nil, "invalid regular expression flags"
		}
		*p = true
	}
	if re.vmode && re.unicode {
		return nil, "invalid regular expression flags"
	}
	if re.vmode {
		re.unicode = true
	}
	u := pattern.UTF16()
	var src []rune
	if re.unicode {
		for i := 0; i < len(u); i++ {
			c := rune(u[i])
			if c >= 0xD800 && c < 0xDC00 && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] < 0xE000 {
				c = utf16.DecodeRune(c, rune(u[i+1]))
				i++
			}
			src = append(src, c)
		}
	} else {
		src = make([]rune, len(u))
		for i, c := range u {
			src[i] = rune(c)
		}
	}
	p := &reParser{src: src, unicode: re.unicode, vmode: re.vmode}
	// pre-scan for named groups
	for i := 0; i+2 < len(src); i++ {
		if src[i] == '\\' {
			i++
			continue
		}
		if src[i] == '(' && src[i+1] == '?' && src[i+2] == '<' && i+3 < len(src) && src[i+3] != '=' && src[i+3] != '!' {
			p.hasNamed = true
			break
		}
	}
	var ast *reAST
	func() {
		defer func() {
			if x := recover(); x != nil {
				if e, ok := x.(*reSyntaxError); ok {
					errMsg = e.msg
					return
				}
				if n, ok := x.(*reAST); ok {
					_ = n
					panic(x)
				}
				panic(x)
			}
		}()
		ast = p.parseDisjunctionTop()
	}()
	if errMsg != "" {
		return nil, errMsg
	}
	// resolve backrefs
	for _, br := range p.backrefs {
		if br.refName != "" {
			idxs, ok := p.names[br.refName]
			if !ok {
				return nil, "group name not defined"
			}
			br.refs = idxs
		} else if br.refs[0] > p.ngroups {
			if re.unicode {
				return nil, "back reference out of range in regular expression"
			}
			// annex B: treat as octal escape / identity
			br.kind = 0
			v := br.refs[0]
			s := strconv.Itoa(v)
			// convert to octal value if possible
			oct := 0
			n := 0
			for _, ch := range s {
				if ch > '7' || n >= 3 || oct*8+int(ch-'0') > 255 {
					break
				}
				oct = oct*8 + int(ch-'0')
				n++
			}
			if n == 0 {
				br.c = rune(s[0])
				// treat remaining digits as literals
				rest := s[1:]
				items := []*reAST{{kind: 0, c: rune(s[0])}}
				for _, ch := range rest {
					items = append(items, &reAST{kind: 0, c: ch})
				}
				br.kind = 3
				br.items = items
			} else {
				items := []*reAST{{kind: 0, c: rune(oct)}}
				for _, ch := range s[n:] {
					items = append(items, &reAST{kind: 0, c: ch})
				}
				br.kind = 3
				br.items = items
			}
		}
	}
	re.ngroups = p.ngroups
	re.groupNames = p.groupNames
	for len(re.groupNames) <= re.ngroups {
		re.groupNames = append(re.groupNames, "")
	}
	re.start = re.emit(ast, &reNode{op: opMatch}, false, reFlags{icase: re.icase, multi: re.multi, dotall: re.dotall})
	return re, ""
}

func (p *reParser) parseDisjunctionTop() (r *reAST) {
	defer func() {
		if x := recover(); x != nil {
			if n, ok := x.(*reAST); ok {
				// named backref signal from parseAtomEscape - should not happen at top
				_ = n
			}
			panic(x)
		}
	}()
	d := p.parseDisjunctionWithBackrefs()
	if !p.eof() {
		if p.peek() == ')' {
			p.fail("unexpected ')'")
		}
		p.fail("syntax error")
	}
	return d
}

// wrapper converting the panic(node) trick for \k<name> into a return value
func (p *reParser) parseDisjunctionWithBackrefs() *reAST {
	return p.parseDisjunction()
}

// canonicalize for case-insensitive matching
func (re *compiledRegExp) canon(c rune) rune {
	return canonChar(c, re.unicode)
}

func canonChar(c rune, uni bool) rune {
	if uni {
		// simple case folding approximation
		if c < 128 {
			if c >= 'A' && c <= 'Z' {
				return c + 32
			}
			return c
		}
		switch c {
		case 0x1E9E:
			return 0xDF
		case 0x2126:
			return 0x3C9
		case 0x212A:
			return 'k'
		case 0x212B:
			return 0xE5
		}
		l := unicode.ToLower(c)
		if l != c {
			return l
		}
		u := unicode.ToUpper(c)
		if u != c {
			l2 := unicode.ToLower(u)
			return l2
		}
		return c
	}
	if c < 128 {
		if c >= 'a' && c <= 'z' {
			return c - 32
		}
		return c
	}
	if c == 0xDF {
		return c
	}
	u := unicode.ToUpper(c)
	if u < 128 {
		return c
	}
	if u > 0xFFFF {
		return c
	}
	return u
}

// ---------- matcher ----------

type reMatcher struct {
	re      *compiledRegExp
	in      []uint16
	caps    []int
	pend    []int
	loops   []loopFrame
	steps   int
}

type loopFrame struct {
	rep   *reNode
	count int
	start int
}

func (m *reMatcher) charAt(pos int) (rune, int) {
	c := rune(m.in[pos])
	if m.re.unicode && c >= 0xD800 && c < 0xDC00 && pos+1 < len(m.in) {
		d := rune(m.in[pos+1])
		if d >= 0xDC00 && d < 0xE000 {
			return utf16.DecodeRune(c, d), 2
		}
	}
	return c, 1
}

func (m *reMatcher) charBefore(pos int) (rune, int) {
	c := rune(m.in[pos-1])
	if m.re.unicode && c >= 0xDC00 && c < 0xE000 && pos-2 >= 0 {
		h := rune(m.in[pos-2])
		if h >= 0xD800 && h < 0xDC00 {
			return utf16.DecodeRune(h, c), 2
		}
	}
	return c, 1
}

func isLineTermRune(c rune) bool {
	return c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029
}

func (m *reMatcher) isWordAt(pos int, icase bool) bool {
	if pos < 0 || pos >= len(m.in) {
		return false
	}
	c := rune(m.in[pos])
	if c < 128 {
		return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_'
	}
	if icase && m.re.unicode && (c == 0x17F || c == 0x212A) {
		return true
	}
	return false
}

func (m *reMatcher) classMatch(n *reNode, c rune) bool {
	if !n.icase {
		return n.cs.has(c)
	}
	if n.cs.has(c) {
		return true
	}
	cc := canonChar(c, m.re.unicode)
	// check orbit members with same canonical form
	for r := unicode.SimpleFold(c); r != c; r = unicode.SimpleFold(r) {
		if canonChar(r, m.re.unicode) == cc && n.cs.has(r) {
			return true
		}
	}
	if !m.re.unicode {
		// also check lowercase/uppercase forms
		for _, r := range []rune{unicode.ToLower(c), unicode.ToUpper(c)} {
			if r != c && canonChar(r, false) == cc && n.cs.has(r) {
				return true
			}
		}
	}
	return false
}

// match single-char node at pos; returns new pos or -1
func (m *reMatcher) matchOne(n *reNode, pos int) int {
	var c rune
	var l int
	if n.back {
		if pos <= 0 {
			return -1
		}
		c, l = m.charBefore(pos)
	} else {
		if pos >= len(m.in) {
			return -1
		}
		c, l = m.charAt(pos)
	}
	ok := false
	switch n.op {
	case opChar:
		if n.icase {
			ok = canonChar(c, m.re.unicode) == n.c
		} else {
			ok = c == n.c
		}
	case opAny:
		ok = n.dotall || !isLineTermRune(c)
	case opClass:
		ok = m.classMatch(n, c)
		if !ok && len(n.cs.strs) > 0 && !n.cs.neg {
			// try string alternatives (longest first)
			best := -1
			for _, s := range n.cs.strs {
				p := pos
				good := true
				for _, sc := range s {
					if p >= len(m.in) {
						good = false
						break
					}
					cc, ll := m.charAt(p)
					if cc != sc {
						good = false
						break
					}
					p += ll
				}
				if good && p > best {
					best = p
				}
			}
			return best
		}
	}
	if !ok {
		return -1
	}
	if n.back {
		return pos - l
	}
	return pos + l
}

func (m *reMatcher) run(n *reNode, pos int) bool {
	for {
		switch n.op {
		case opMatch:
			m.caps[1] = pos
			return true
		case opLookEnd:
			m.pend = append(m.pend, pos)
			return true
		case opChar, opAny, opClass:
			np := m.matchOne(n, pos)
			if np < 0 {
				return false
			}
			pos = np
			n = n.next
		case opBOL:
			if pos == 0 || (n.multi && isLineTermRune(rune(m.in[pos-1]))) {
				n = n.next
				continue
			}
			return false
		case opEOL:
			if pos == len(m.in) || (n.multi && isLineTermRune(rune(m.in[pos]))) {
				n = n.next
				continue
			}
			return false
		case opWordB, opNotWordB:
			a := m.isWordAt(pos-1, n.icase)
			b := m.isWordAt(pos, n.icase)
			if (a != b) == (n.op == opWordB) {
				n = n.next
				continue
			}
			return false
		case opGroupStart:
			i := n.idx
			old := m.pend[i]
			m.pend[i] = pos
			if m.run(n.next, pos) {
				return true
			}
			m.pend[i] = old
			return false
		case opGroupEnd:
			i := n.idx
			os, oe := m.caps[2*i], m.caps[2*i+1]
			if n.back {
				m.caps[2*i], m.caps[2*i+1] = pos, m.pend[i]
			} else {
				m.caps[2*i], m.caps[2*i+1] = m.pend[i], pos
			}
			if m.run(n.next, pos) {
				return true
			}
			m.caps[2*i], m.caps[2*i+1] = os, oe
			return false
		case opBackref:
			s, e := -1, -1
			for _, r := range n.refs {
				if r < len(m.caps)/2 && m.caps[2*r] >= 0 && m.caps[2*r+1] >= 0 {
					s, e = m.caps[2*r], m.caps[2*r+1]
					break
				}
			}
			if s < 0 {
				n = n.next
				continue
			}
			l := e - s
			if n.back {
				if pos-l < 0 {
					return false
				}
				for k := 0; k < l; k++ {
					if !m.eqChar(m.in[s+k], m.in[pos-l+k], n.icase) {
						return false
					}
				}
				pos -= l
			} else {
				if pos+l > len(m.in) {
					return false
				}
				for k := 0; k < l; k++ {
					if !m.eqChar(m.in[s+k], m.in[pos+k], n.icase) {
						return false
					}
				}
				pos += l
			}
			n = n.next
		case opAlt:
			last := len(n.alts) - 1
			for i := 0; i < last; i++ {
				if m.run(n.alts[i], pos) {
					return true
				}
			}
			n = n.alts[last]
		case opRepeat:
			if n.simple {
				return m.runSimpleRepeat(n, pos)
			}
			return m.repeatTry(n, 0, -1, pos)
		case opLoop:
			fr := m.loops[len(m.loops)-1]
			if pos == fr.start && fr.count > fr.rep.min {
				return false
			}
			m.loops = m.loops[:len(m.loops)-1]
			ok := m.repeatTry(fr.rep, fr.count, fr.start, pos)
			m.loops = append(m.loops, fr)
			return ok
		case opLook:
			saved := append([]int(nil), m.caps...)
			savedLoops := m.loops
			m.loops = nil
			pendLen := len(m.pend)
			matched := m.run(n.body, pos)
			m.pend = m.pend[:pendLen]
			m.loops = savedLoops
			if n.neg {
				copy(m.caps, saved)
				if matched {
					return false
				}
				n = n.next
				continue
			}
			if !matched {
				copy(m.caps, saved)
				return false
			}
			if m.run(n.next, pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		default:
			return false
		}
	}
}

func (m *reMatcher) eqChar(a, b uint16, icase bool) bool {
	if a == b {
		return true
	}
	if !icase {
		return false
	}
	return canonChar(rune(a), m.re.unicode) == canonChar(rune(b), m.re.unicode)
}

func (m *reMatcher) runSimpleRepeat(n *reNode, pos int) bool {
	body := n.body
	if n.greedy {
		positions := []int{pos}
		p := pos
		count := 0
		for count < n.max {
			np := m.matchOne(body, p)
			if np < 0 {
				break
			}
			p = np
			count++
			positions = append(positions, p)
		}
		for count >= n.min {
			if m.run(n.next, positions[count]) {
				return true
			}
			count--
		}
		return false
	}
	count := 0
	p := pos
	for count < n.min {
		np := m.matchOne(body, p)
		if np < 0 {
			return false
		}
		p = np
		count++
	}
	for {
		if m.run(n.next, p) {
			return true
		}
		if count >= n.max {
			return false
		}
		np := m.matchOne(body, p)
		if np < 0 {
			return false
		}
		p = np
		count++
	}
}

func (m *reMatcher) repeatTry(rep *reNode, count int, start int, pos int) bool {
	canIter := count < rep.max
	if rep.greedy {
		if canIter && m.iterate(rep, count, pos) {
			return true
		}
		if count >= rep.min {
			return m.run(rep.next, pos)
		}
		return false
	}
	if count >= rep.min && m.run(rep.next, pos) {
		return true
	}
	if canIter {
		return m.iterate(rep, count, pos)
	}
	return false
}

func (m *reMatcher) iterate(rep *reNode, count int, pos int) bool {
	var saved []int
	if rep.capEnd > rep.capStart {
		saved = append([]int(nil), m.caps[2*rep.capStart:2*rep.capEnd]...)
		for i := 2 * rep.capStart; i < 2*rep.capEnd; i++ {
			m.caps[i] = -1
		}
	}
	m.loops = append(m.loops, loopFrame{rep: rep, count: count + 1, start: pos})
	ok := m.run(rep.body, pos)
	m.loops = m.loops[:len(m.loops)-1]
	if !ok && saved != nil {
		copy(m.caps[2*rep.capStart:], saved)
	}
	return ok
}

// exec at position; returns captures or nil
func (re *compiledRegExp) execAt(in []uint16, pos int) []int {
	m := &reMatcher{re: re, in: in}
	m.caps = make([]int, 2*(re.ngroups+1))
	m.pend = make([]int, re.ngroups+1)
	for i := range m.caps {
		m.caps[i] = -1
	}
	if m.run(re.start, pos) {
		m.caps[0] = pos
		return m.caps
	}
	return nil
}

func (re *compiledRegExp) firstCharHint() (rune, bool) {
	n := re.start
	if n.op == opChar && !n.icase && !n.back {
		return n.c, true
	}
	return 0, false
}

// search from lastIndex; sticky -> only at pos
func (re *compiledRegExp) search(in []uint16, pos int, sticky bool) []int {
	if sticky {
		if pos > len(in) {
			return nil
		}
		return re.execAt(in, pos)
	}
	fc, hasFC := re.firstCharHint()
	if hasFC && fc > 0xFFFF {
		hasFC = false
	}
	for p := pos; p <= len(in); p++ {
		if hasFC {
			for p < len(in) && rune(in[p]) != fc {
				p++
			}
			if p >= len(in) {
				return nil
			}
		}
		if caps := re.execAt(in, p); caps != nil {
			return caps
		}
		if re.unicode && p < len(in) && in[p] >= 0xD800 && in[p] < 0xDC00 && p+1 < len(in) && in[p+1] >= 0xDC00 && in[p+1] < 0xE000 {
			p++
		}
	}
	return nil
}
