package main

import (
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf16"
)

// ---------- character sets ----------

type runeRange struct{ lo, hi rune }

type charSet struct {
	ranges []runeRange
	tables []*unicode.RangeTable
	ntables []*unicode.RangeTable // negated tables (\P)
	neg    bool
	// for v-flag string alternatives (\q{...})
	strs [][]rune
}

func (cs *charSet) addRange(lo, hi rune) { cs.ranges = append(cs.ranges, runeRange{lo, hi}) }

func (cs *charSet) addSet(o *charSet) {
	if o.neg {
		// add complement of o
		comp := o.complementRanges()
		cs.ranges = append(cs.ranges, comp...)
		return
	}
	cs.ranges = append(cs.ranges, o.ranges...)
	cs.tables = append(cs.tables, o.tables...)
	cs.ntables = append(cs.ntables, o.ntables...)
	cs.strs = append(cs.strs, o.strs...)
}

func (cs *charSet) normalize() {
	if len(cs.ranges) < 2 {
		return
	}
	sort.Slice(cs.ranges, func(i, j int) bool { return cs.ranges[i].lo < cs.ranges[j].lo })
	out := cs.ranges[:1]
	for _, r := range cs.ranges[1:] {
		last := &out[len(out)-1]
		if r.lo <= last.hi+1 {
			if r.hi > last.hi {
				last.hi = r.hi
			}
		} else {
			out = append(out, r)
		}
	}
	cs.ranges = out
}

func (cs *charSet) complementRanges() []runeRange {
	c := &charSet{ranges: append([]runeRange{}, cs.ranges...)}
	// materialize tables
	for _, t := range cs.tables {
		c.ranges = append(c.ranges, tableRanges(t)...)
	}
	c.normalize()
	var out []runeRange
	prev := rune(0)
	for _, r := range c.ranges {
		if r.lo > prev {
			out = append(out, runeRange{prev, r.lo - 1})
		}
		prev = r.hi + 1
	}
	if prev <= 0x10FFFF {
		out = append(out, runeRange{prev, 0x10FFFF})
	}
	return out
}

func tableRanges(t *unicode.RangeTable) []runeRange {
	var out []runeRange
	for _, r := range t.R16 {
		if r.Stride == 1 {
			out = append(out, runeRange{rune(r.Lo), rune(r.Hi)})
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				out = append(out, runeRange{c, c})
			}
		}
	}
	for _, r := range t.R32 {
		if r.Stride == 1 {
			out = append(out, runeRange{rune(r.Lo), rune(r.Hi)})
		} else {
			for c := rune(r.Lo); c <= rune(r.Hi); c += rune(r.Stride) {
				out = append(out, runeRange{c, c})
			}
		}
	}
	return out
}

func (cs *charSet) has(c rune) bool {
	r := cs.hasRaw(c)
	if cs.neg {
		return !r
	}
	return r
}

func (cs *charSet) hasRaw(c rune) bool {
	rs := cs.ranges
	lo, hi := 0, len(rs)
	for lo < hi {
		m := (lo + hi) / 2
		if c < rs[m].lo {
			hi = m
		} else if c > rs[m].hi {
			lo = m + 1
		} else {
			return true
		}
	}
	for _, t := range cs.tables {
		if unicode.Is(t, c) {
			return true
		}
	}
	for _, t := range cs.ntables {
		if !unicode.Is(t, c) {
			return true
		}
	}
	return false
}

// ---------- AST ----------

type reAST struct {
	kind     int // 0 char,1 any,2 class,3 seq,4 alt,5 group,6 repeat,7 bol,8 eol,9 wordb,10 notwordb,11 backref,12 look,13 empty, 14 modifiers group
	c        rune
	cs       *charSet
	items    []*reAST
	idx      int
	name     string
	min, max int
	greedy   bool
	neg      bool
	behind   bool
	refs     []int
	refName  string
	capStart int
	capEnd   int
	icase    int // -1 inherit, 0 off, 1 on (modifiers)
	multi    int
	dotall   int
}

// ---------- parser ----------

type reParser struct {
	src        []rune
	pos        int
	unicode    bool
	vmode      bool
	ngroups    int
	names      map[string][]int
	groupNames []string
	hasNamed   bool
	err        string
	backrefs   []*reAST
}

type reSyntaxError struct{ msg string }

func (p *reParser) fail(msg string) {
	panic(&reSyntaxError{msg})
}

func (p *reParser) eof() bool { return p.pos >= len(p.src) }
func (p *reParser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}
func (p *reParser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return -1
}

func (p *reParser) parseDisjunction() *reAST {
	alts := []*reAST{p.parseAlternative()}
	for p.peek() == '|' {
		p.pos++
		alts = append(alts, p.parseAlternative())
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &reAST{kind: 4, items: alts}
}

func (p *reParser) parseAlternative() *reAST {
	var items []*reAST
	for !p.eof() && p.peek() != '|' && p.peek() != ')' {
		t := p.parseTerm()
		if t != nil {
			items = append(items, t)
		}
	}
	return &reAST{kind: 3, items: items}
}

func (p *reParser) parseTerm() *reAST {
	c := p.peek()
	capBefore := p.ngroups
	var atom *reAST
	switch c {
	case '^':
		p.pos++
		return &reAST{kind: 7}
	case '$':
		p.pos++
		return &reAST{kind: 8}
	case '\\':
		if p.peekAt(1) == 'b' {
			p.pos += 2
			return &reAST{kind: 9}
		}
		if p.peekAt(1) == 'B' {
			p.pos += 2
			return &reAST{kind: 10}
		}
		p.pos++
		atom = p.parseAtomEscape()
	case '(':
		p.pos++
		if p.peek() == '?' {
			p.pos++
			switch p.peek() {
			case ':':
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 5, idx: -1, items: []*reAST{d}}
			case '=', '!':
				neg := p.peek() == '!'
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 12, neg: neg, items: []*reAST{d}}
				if p.unicode {
					return atom // lookaheads not quantifiable in unicode mode
				}
			case '<':
				if p.peekAt(1) == '=' || p.peekAt(1) == '!' {
					neg := p.peekAt(1) == '!'
					p.pos += 2
					d := p.parseDisjunction()
					p.expect(')')
					return &reAST{kind: 12, neg: neg, behind: true, items: []*reAST{d}}
				}
				p.pos++
				name := p.parseGroupName()
				p.ngroups++
				idx := p.ngroups
				if p.names == nil {
					p.names = map[string][]int{}
				}
				if len(p.names[name]) > 0 {
					p.fail("duplicate group name")
				}
				p.names[name] = append(p.names[name], idx)
				for len(p.groupNames) <= idx {
					p.groupNames = append(p.groupNames, "")
				}
				p.groupNames[idx] = name
				d := p.parseDisjunction()
				p.expect(')')
				atom = &reAST{kind: 5, idx: idx, name: name, items: []*reAST{d}}
			default:
				// modifiers (?ims-ims:...)
				start := p.pos
				add, rem := "", ""
				cur := &add
				for !p.eof() && p.peek() != ':' {
					ch := p.peek()
					if ch == '-' {
						if cur == &rem {
							p.fail("invalid group")
						}
						cur = &rem
						p.pos++
						continue
					}
					if ch != 'i' && ch != 'm' && ch != 's' {
						p.pos = start
						p.fail("invalid group")
					}
					if strings.ContainsRune(add, ch) || strings.ContainsRune(rem, ch) {
						p.fail("invalid group")
					}
					*cur += string(ch)
					p.pos++
				}
				if p.eof() || (add == "" && rem == "") {
					p.fail("invalid group")
				}
				p.pos++
				d := p.parseDisjunction()
				p.expect(')')
				g := &reAST{kind: 14, items: []*reAST{d}, icase: -1, multi: -1, dotall: -1}
				set := func(s string, v int) {
					for _, ch := range s {
						switch ch {
						case 'i':
							g.icase = v
						case 'm':
							g.multi = v
						case 's':
							g.dotall = v
						}
					}
				}
				set(add, 1)
				set(rem, 0)
				atom = g
			}
		} else {
			p.ngroups++
			idx := p.ngroups
			for len(p.groupNames) <= idx {
				p.groupNames = append(p.groupNames, "")
			}
			d := p.parseDisjunction()
			p.expect(')')
			atom = &reAST{kind: 5, idx: idx, items: []*reAST{d}}
		}
	case '.':
		p.pos++
		atom = &reAST{kind: 1}
	case '[':
		p.pos++
		atom = &reAST{kind: 2, cs: p.parseClass()}
	case '*', '+', '?':
		p.fail("nothing to repeat")
	case '{':
		if p.unicode {
			p.fail("nothing to repeat")
		}
		// annex B: literal if not a valid quantifier
		save := p.pos
		if _, _, ok := p.tryQuantifierBraces(); ok {
			p.fail("nothing to repeat")
		}
		p.pos = save + 1
		atom = &reAST{kind: 0, c: '{'}
	case ')':
		p.fail("unexpected ')'")
	case ']', '}':
		if p.unicode {
			p.fail("syntax error")
		}
		p.pos++
		atom = &reAST{kind: 0, c: c}
	default:
		p.pos++
		atom = &reAST{kind: 0, c: c}
	}
	return p.parseQuantifier(atom, capBefore)
}

func (p *reParser) expect(c rune) {
	if p.peek() != c {
		p.fail("expecting '" + string(c) + "'")
	}
	p.pos++
}

func (p *reParser) tryQuantifierBraces() (int, int, bool) {
	// at '{'
	save := p.pos
	p.pos++
	readInt := func() (int, bool) {
		start := p.pos
		v := 0
		for !p.eof() && p.peek() >= '0' && p.peek() <= '9' {
			if v < 1<<30 {
				v = v*10 + int(p.peek()-'0')
			}
			p.pos++
		}
		return v, p.pos > start
	}
	min, ok := readInt()
	if !ok {
		p.pos = save
		return 0, 0, false
	}
	max := min
	if p.peek() == ',' {
		p.pos++
		if p.peek() == '}' {
			max = -1
		} else {
			m, ok := readInt()
			if !ok {
				p.pos = save
				return 0, 0, false
			}
			max = m
		}
	}
	if p.peek() != '}' {
		p.pos = save
		return 0, 0, false
	}
	p.pos++
	return min, max, true
}

func (p *reParser) parseQuantifier(atom *reAST, capBefore int) *reAST {
	c := p.peek()
	min, max := -2, 0
	switch c {
	case '*':
		min, max = 0, -1
		p.pos++
	case '+':
		min, max = 1, -1
		p.pos++
	case '?':
		min, max = 0, 1
		p.pos++
	case '{':
		save := p.pos
		mn, mx, ok := p.tryQuantifierBraces()
		if !ok {
			if p.unicode {
				p.fail("invalid repetition count")
			}
			p.pos = save
			return atom
		}
		if mx >= 0 && mn > mx {
			p.fail("invalid repetition count")
		}
		min, max = mn, mx
	default:
		return atom
	}
	if atom.kind == 7 || atom.kind == 8 || atom.kind == 9 || atom.kind == 10 || (atom.kind == 12 && atom.behind) {
		p.fail("nothing to repeat")
	}
	greedy := true
	if p.peek() == '?' {
		greedy = false
		p.pos++
	}
	return &reAST{kind: 6, items: []*reAST{atom}, min: min, max: max, greedy: greedy, capStart: capBefore + 1, capEnd: p.ngroups + 1}
}

func (p *reParser) parseGroupName() string {
	var sb []rune
	for {
		if p.eof() {
			p.fail("invalid group name")
		}
		c := p.peek()
		if c == '>' {
			p.pos++
			break
		}
		if c == '\\' {
			p.pos++
			if p.peek() != 'u' {
				p.fail("invalid group name")
			}
			p.pos++
			cp := p.parseUnicodeEscapeAfterU(true)
			if cp < 0 {
				p.fail("invalid group name")
			}
			c = cp
		} else {
			p.pos++
			if c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 {
				c = utf16.DecodeRune(c, p.peek())
				p.pos++
			}
		}
		if len(sb) == 0 {
			if !isIDStart(c) {
				p.fail("invalid group name")
			}
		} else if !isIDPart(c) {
			p.fail("invalid group name")
		}
		sb = append(sb, c)
	}
	if len(sb) == 0 {
		p.fail("invalid group name")
	}
	return string(sb)
}

func (p *reParser) parseUnicodeEscapeAfterU(allowBrace bool) rune {
	if p.peek() == '{' && (p.unicode || allowBrace) {
		p.pos++
		var v rune
		n := 0
		for !p.eof() && p.peek() != '}' {
			h := hexVal(byte(p.peek()))
			if p.peek() > 127 || h < 0 {
				return -1
			}
			v = v*16 + rune(h)
			if v > 0x10FFFF {
				p.fail("invalid escape sequence in regular expression")
			}
			n++
			p.pos++
		}
		if p.eof() || n == 0 {
			return -1
		}
		p.pos++
		return v
	}
	v := rune(0)
	for i := 0; i < 4; i++ {
		c := p.peekAt(i)
		if c < 0 || c > 127 || hexVal(byte(c)) < 0 {
			return -1
		}
		v = v*16 + rune(hexVal(byte(c)))
	}
	p.pos += 4
	if (p.unicode || allowBrace) && v >= 0xD800 && v < 0xDC00 && p.peek() == '\\' && p.peekAt(1) == 'u' {
		save := p.pos
		p.pos += 2
		w := rune(0)
		ok := true
		for i := 0; i < 4; i++ {
			c := p.peekAt(i)
			if c < 0 || c > 127 || hexVal(byte(c)) < 0 {
				ok = false
				break
			}
			w = w*16 + rune(hexVal(byte(c)))
		}
		if ok && w >= 0xDC00 && w < 0xE000 {
			p.pos += 4
			return utf16.DecodeRune(v, w)
		}
		p.pos = save
	}
	return v
}

var (
	digitSet = &charSet{ranges: []runeRange{{'0', '9'}}}
	wordSet  = &charSet{ranges: []runeRange{{'0', '9'}, {'A', 'Z'}, {'_', '_'}, {'a', 'z'}}}
	spaceSet = &charSet{ranges: []runeRange{{9, 13}, {32, 32}, {0xA0, 0xA0}, {0x1680, 0x1680}, {0x2000, 0x200A}, {0x2028, 0x2029}, {0x202F, 0x202F}, {0x205F, 0x205F}, {0x3000, 0x3000}, {0xFEFF, 0xFEFF}}}
)

func negSet(s *charSet) *charSet {
	return &charSet{ranges: s.ranges, tables: s.tables, ntables: s.ntables, neg: !s.neg}
}

// parse escape after '\' in atom context
func (p *reParser) parseAtomEscape() *reAST {
	if p.eof() {
		p.fail("unexpected end")
	}
	c := p.peek()
	switch {
	case c >= '1' && c <= '9':
		save := p.pos
		v := 0
		for !p.eof() && p.peek() >= '0' && p.peek() <= '9' {
			v = v*10 + int(p.peek()-'0')
			p.pos++
			if v > 1<<20 {
				break
			}
		}
		node := &reAST{kind: 11, refs: []int{v}}
		node.idx = save
		p.backrefs = append(p.backrefs, node)
		return node
	case c == 'k':
		p.pos++
		if p.peek() != '<' {
			if p.unicode || p.hasNamed {
				p.fail("expecting group name")
			}
			return &reAST{kind: 0, c: 'k'}
		}
		save := p.pos
		p.pos++
		func() {
			defer func() {
				if x := recover(); x != nil {
					if !p.unicode && !p.hasNamed {
						p.pos = save
						return
					}
					panic(x)
				}
			}()
			name := p.parseGroupName()
			node := &reAST{kind: 11, refName: name}
			p.backrefs = append(p.backrefs, node)
			panic(node)
		}()
		return &reAST{kind: 0, c: 'k'}
	}
	cs := p.parseClassEscape(false)
	if cs != nil {
		return &reAST{kind: 2, cs: cs}
	}
	return &reAST{kind: 0, c: p.parseCharEscape(false)}
}

// returns non-nil for class escapes \d\D\w\W\s\S\p\P
func (p *reParser) parseClassEscape(inClass bool) *charSet {
	c := p.peek()
	switch c {
	case 'd':
		p.pos++
		return digitSet
	case 'D':
		p.pos++
		return negSet(digitSet)
	case 'w':
		p.pos++
		return wordSet
	case 'W':
		p.pos++
		return negSet(wordSet)
	case 's':
		p.pos++
		return spaceSet
	case 'S':
		p.pos++
		return negSet(spaceSet)
	case 'p', 'P':
		if !p.unicode {
			return nil
		}
		neg := c == 'P'
		p.pos++
		if p.peek() != '{' {
			p.fail("expecting '{' after \\p")
		}
		p.pos++
		start := p.pos
		for !p.eof() && p.peek() != '}' {
			p.pos++
		}
		if p.eof() {
			p.fail("expecting '}'")
		}
		name := string(p.src[start:p.pos])
		p.pos++
		cs := unicodePropertySet(name)
		if cs == nil {
			p.fail("unknown unicode property name")
		}
		if neg {
			return negSet(cs)
		}
		return cs
	}
	return nil
}

func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.peek()
	p.pos++
	switch c {
	case 't':
		return '\t'
	case 'n':
		return '\n'
	case 'v':
		return '\v'
	case 'f':
		return '\f'
	case 'r':
		return '\r'
	case 'c':
		n := p.peek()
		if n >= 'a' && n <= 'z' || n >= 'A' && n <= 'Z' || (inClass && !p.unicode && (n >= '0' && n <= '9' || n == '_')) {
			p.pos++
			return n % 32
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		p.pos--
		return '\\'
	case '0':
		if !(p.peek() >= '0' && p.peek() <= '9') {
			return 0
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		fallthrough
	case '1', '2', '3', '4', '5', '6', '7':
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		v := c - '0'
		if p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + p.peek() - '0'
			p.pos++
			if c <= '3' && p.peek() >= '0' && p.peek() <= '7' {
				v = v*8 + p.peek() - '0'
				p.pos++
			}
		}
		return v
	case 'x':
		h1, h2 := p.peek(), p.peekAt(1)
		if h1 >= 0 && h1 < 128 && h2 >= 0 && h2 < 128 && hexVal(byte(h1)) >= 0 && hexVal(byte(h2)) >= 0 {
			p.pos += 2
			return rune(hexVal(byte(h1))*16 + hexVal(byte(h2)))
		}
		if p.unicode {
			p.fail("invalid escape sequence in regular expression")
		}
		return 'x'
	case 'u':
		cp := p.parseUnicodeEscapeAfterU(false)
		if cp < 0 {
			if p.unicode {
				p.fail("invalid escape sequence in regular expression")
			}
			return 'u'
		}
		return cp
	case '-':
		if inClass || !p.unicode {
			return '-'
		}
		p.fail("invalid escape sequence in regular expression")
	case -1:
		p.fail("unexpected end")
	}
	if p.unicode {
		if strings.ContainsRune("^$\\.*+?()[]{}|/", c) {
			return c
		}
		p.fail("invalid escape sequence in regular expression")
	}
	if c == 'k' && p.hasNamed {
		p.fail("invalid escape sequence in regular expression")
	}
	if c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 && p.unicode {
		r := utf16.DecodeRune(c, p.peek())
		p.pos++
		return r
	}
	return c
}

func (p *reParser) parseClass() *charSet {
	cs := &charSet{}
	if p.peek() == '^' {
		cs.neg = true
		p.pos++
	}
	if p.vmode {
		p.parseClassV(cs)
		return cs
	}
	for {
		if p.eof() {
			p.fail("unexpected end")
		}
		if p.peek() == ']' {
			p.pos++
			break
		}
		a, aset := p.parseClassAtom()
		if p.peek() == '-' && p.peekAt(1) != ']' && p.peekAt(1) != -1 {
			p.pos++
			b, bset := p.parseClassAtom()
			if aset != nil || bset != nil {
				if p.unicode {
					p.fail("invalid class range")
				}
				if aset != nil {
					cs.addSet(aset)
				} else {
					cs.addRange(a, a)
				}
				cs.addRange('-', '-')
				if bset != nil {
					cs.addSet(bset)
				} else {
					cs.addRange(b, b)
				}
				continue
			}
			if a > b {
				p.fail("invalid class range")
			}
			cs.addRange(a, b)
			continue
		}
		if aset != nil {
			cs.addSet(aset)
		} else {
			cs.addRange(a, a)
		}
	}
	cs.normalize()
	return cs
}

func (p *reParser) parseClassAtom() (rune, *charSet) {
	c := p.peek()
	if c == '\\' {
		p.pos++
		if p.eof() {
			p.fail("unexpected end")
		}
		if cs := p.parseClassEscape(true); cs != nil {
			return 0, cs
		}
		if p.peek() == 'b' {
			p.pos++
			return '\b', nil
		}
		if p.peek() == '-' && p.unicode {
			p.pos++
			return '-', nil
		}
		if !p.unicode && p.peek() >= '1' && p.peek() <= '9' && p.peek() >= '8' {
			c := p.peek()
			p.pos++
			return c, nil
		}
		return p.parseCharEscape(true), nil
	}
	p.pos++
	if p.unicode && c >= 0xD800 && c < 0xDC00 && p.peek() >= 0xDC00 && p.peek() < 0xE000 {
		r := utf16.DecodeRune(c, p.peek())
		p.pos++
		return r, nil
	}
	return c, nil
}

// v-mode class (set notation) - simplified
func (p *reParser) parseClassV(cs *charSet) {
	var cur *charSet = &charSet{}
	op := 0 // 0 union, 1 intersection, 2 subtraction
	var acc *charSet
	first := true
	flush := func() {
		cur.normalize()
		if first {
			acc = cur
			first = false
		} else {
			switch op {
			case 1:
				acc = intersectSets(acc, cur)
			case 2:
				acc = subtractSets(acc, cur)
			default:
				acc.addSet(cur)
				acc.normalize()
			}
		}
		cur = &charSet{}
	}
	for {
		if p.eof() {
			p.fail("unexpected end")
		}
		c := p.peek()
		if c == ']' {
			p.pos++
			break
		}
		if c == '&' && p.peekAt(1) == '&' {
			p.pos += 2
			flush()
			op = 1
			continue
		}
		if c == '-' && p.peekAt(1) == '-' {
			p.pos += 2
			flush()
			op = 2
			continue
		}
		if c == '[' {
			p.pos++
			sub := &charSet{}
			if p.peek() == '^' {
				sub.neg = true
				p.pos++
			}
			p.parseClassV(sub)
			cur.addSet(sub)
			continue
		}
		if c == '\\' && p.peekAt(1) == 'q' && p.peekAt(2) == '{' {
			p.pos += 3
			var str []rune
			for !p.eof() && p.peek() != '}' {
				if p.peek() == '|' {
					p.pos++
					if len(str) == 1 {
						cur.addRange(str[0], str[0])
					} else {
						cur.strs = append(cur.strs, str)
					}
					str = nil
					continue
				}
				if p.peek() == '\\' {
					p.pos++
					str = append(str, p.parseCharEscape(true))
					continue
				}
				str = append(str, p.peek())
				p.pos++
			}
			p.pos++
			if len(str) == 1 {
				cur.addRange(str[0], str[0])
			} else {
				cur.strs = append(cur.strs, str)
			}
			continue
		}
		a, aset := p.parseClassAtom()
		if aset != nil {
			cur.addSet(aset)
			continue
		}
		if p.peek() == '-' && p.peekAt(1) != '-' && p.peekAt(1) != ']' {
			p.pos++
			b, _ := p.parseClassAtom()
			if a > b {
				p.fail("invalid class range")
			}
			cur.addRange(a, b)
			continue
		}
		cur.addRange(a, a)
	}
	flush()
	cs.ranges = acc.ranges
	cs.tables = acc.tables
	cs.ntables = acc.ntables
	cs.strs = acc.strs
	cs.normalize()
}

func materialize(s *charSet) []runeRange {
	if s.neg {
		return s.complementRanges()
	}
	c := &charSet{ranges: append([]runeRange{}, s.ranges...)}
	for _, t := range s.tables {
		c.ranges = append(c.ranges, tableRanges(t)...)
	}
	for _, t := range s.ntables {
		cc := &charSet{tables: []*unicode.RangeTable{t}}
		c.ranges = append(c.ranges, cc.complementRanges()...)
	}
	c.normalize()
	return c.ranges
}

func intersectSets(a, b *charSet) *charSet {
	ar, br := materialize(a), materialize(b)
	out := &charSet{}
	i, j := 0, 0
	for i < len(ar) && j < len(br) {
		lo := ar[i].lo
		if br[j].lo > lo {
			lo = br[j].lo
		}
		hi := ar[i].hi
		if br[j].hi < hi {
			hi = br[j].hi
		}
		if lo <= hi {
			out.addRange(lo, hi)
		}
		if ar[i].hi < br[j].hi {
			i++
		} else {
			j++
		}
	}
	return out
}

func subtractSets(a, b *charSet) *charSet {
	nb := &charSet{ranges: materialize(b), neg: true}
	return intersectSets(&charSet{ranges: materialize(a)}, nb)
}

