func unicodePropertySet(name string) *charSet {
	if i := strings.IndexByte(name, '='); i >= 0 {
		k, v := name[:i], name[i+1:]
		switch k {
		case "General_Category", "gc":
			return gcSet(v)
		case "Script", "sc", "Script_Extensions", "scx":
			if t, ok := unicode.Scripts[v]; ok {
				return &charSet{tables: []*unicode.RangeTable{t}}
			}
			if full, ok := scriptAliases[v]; ok {
				return &charSet{tables: []*unicode.RangeTable{unicode.Scripts[full]}}
			}
			return nil
		}
		return nil
	}
	if cs := gcSet(name); cs != nil {
		return cs
	}
	switch name {
	case "Any":
		return &charSet{ranges: []runeRange{{0, 0x10FFFF}}}
	case "ASCII":
		return &charSet{ranges: []runeRange{{0, 0x7F}}}
	case "Assigned":
		cs := gcSet("Cn")
		return negSet(cs)
	case "Alphabetic", "Alpha":
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lt, unicode.Lm, unicode.Lo, unicode.Nl, unicode.Other_Alphabetic}}
	case "Lowercase", "Lower":
		return &charSet{tables: []*unicode.RangeTable{unicode.Ll, unicode.Other_Lowercase}}
	case "Uppercase", "Upper":
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Other_Uppercase}}
	case "Math":
		return &charSet{tables: []*unicode.RangeTable{unicode.Sm, unicode.Other_Math}}
	case "ID_Start", "IDS":
		return &charSet{tables: []*unicode.RangeTable{unicode.L, unicode.Nl, unicode.Other_ID_Start}}
	case "ID_Continue", "IDC":
		return &charSet{tables: []*unicode.RangeTable{unicode.L, unicode.Nl, unicode.Other_ID_Start, unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc, unicode.Other_ID_Continue}}
	case "Emoji", "Emoji_Presentation", "Extended_Pictographic", "ExtPict", "EPres":
		return emojiSet()
	case "Emoji_Modifier", "EMod":
		return &charSet{ranges: []runeRange{{0x1F3FB, 0x1F3FF}}}
	case "Emoji_Component", "EComp":
		return &charSet{ranges: []runeRange{{'#', '#'}, {'*', '*'}, {'0', '9'}, {0x200D, 0x200D}, {0x20E3, 0x20E3}, {0xFE0F, 0xFE0F}, {0x1F1E6, 0x1F1FF}, {0x1F3FB, 0x1F3FF}, {0x1F9B0, 0x1F9B3}, {0xE0020, 0xE007F}}}
	case "Regional_Indicator", "RI":
		return &charSet{ranges: []runeRange{{0x1F1E6, 0x1F1FF}}}
	}
	alias := map[string]string{"WSpace": "White_Space", "space": "White_Space", "Hex": "Hex_Digit", "AHex": "ASCII_Hex_Digit",
		"Ideo": "Ideographic", "QMark": "Quotation_Mark", "Dash": "Dash", "Dia": "Diacritic", "Ext": "Extender",
		"SD": "Soft_Dotted", "STerm": "Sentence_Terminal", "Term": "Terminal_Punctuation", "VS": "Variation_Selector",
		"Pat_Syn": "Pattern_Syntax", "Pat_WS": "Pattern_White_Space", "Join_C": "Join_Control", "UIdeo": "Unified_Ideograph",
		"Dep": "Deprecated", "Bidi_C": "Bidi_Control", "NChar": "Noncharacter_Code_Point", "Radical": "Radical",
		"LOE": "Logical_Order_Exception", "IDSB": "IDS_Binary_Operator", "IDST": "IDS_Trinary_Operator"}
	if a, ok := alias[name]; ok {
		name = a
	}
	if name == "Sentence_Terminal" {
		name = "STerm"
		if t, ok := unicode.Properties["Sentence_Terminal"]; ok {
			return &charSet{tables: []*unicode.RangeTable{t}}
		}
	}
	if t, ok := unicode.Properties[name]; ok {
		return &charSet{tables: []*unicode.RangeTable{t}}
	}
	return nil
}

var scriptAliases = map[string]string{
	"Latn": "Latin", "Grek": "Greek", "Cyrl": "Cyrillic", "Arab": "Arabic", "Hebr": "Hebrew", "Hani": "Han",
	"Hira": "Hiragana", "Kana": "Katakana", "Thai": "Thai", "Deva": "Devanagari", "Hang": "Hangul", "Zyyy": "Common",
	"Zinh": "Inherited", "Armn": "Armenian", "Geor": "Georgian", "Ethi": "Ethiopic", "Beng": "Bengali", "Taml": "Tamil",
}

func gcSet(v string) *charSet {
	if a, ok := gcAliases[v]; ok {
		v = a
	}
	if v == "LC" {
		return &charSet{tables: []*unicode.RangeTable{unicode.Lu, unicode.Ll, unicode.Lt}}
	}
	if v == "Cn" {
		// unassigned: complement of all categories
		all := []*unicode.RangeTable{}
		for _, t := range unicode.Categories {
			all = append(all, t)
		}
		cs := &charSet{tables: all}
		return &charSet{ranges: cs.complementRanges()}
	}
	if v == "C" {
		cs := gcSet("Cn")
		cs.tables = append(cs.tables, unicode.C)
		return cs
	}
	if t, ok := unicode.Categories[v]; ok {
		return &charSet{tables: []*unicode.RangeTable{t}}
	}
	return nil
}

func emojiSet() *charSet {
	return &charSet{ranges: []runeRange{{0x00A9, 0x00A9}, {0x00AE, 0x00AE}, {0x203C, 0x203C}, {0x2049, 0x2049},
		{0x2122, 0x2122}, {0x2139, 0x2139}, {0x2194, 0x2199}, {0x21A9, 0x21AA}, {0x231A, 0x231B}, {0x2328, 0x2328},
		{0x23CF, 0x23CF}, {0x23E9, 0x23F3}, {0x23F8, 0x23FA}, {0x24C2, 0x24C2}, {0x25AA, 0x25AB}, {0x25B6, 0x25B6},
		{0x25C0, 0x25C0}, {0x25FB, 0x25FE}, {0x2600, 0x27BF}, {0x2934, 0x2935}, {0x2B05, 0x2B07}, {0x2B1B, 0x2B1C},
		{0x2B50, 0x2B50}, {0x2B55, 0x2B55}, {0x3030, 0x3030}, {0x303D, 0x303D}, {0x3297, 0x3297}, {0x3299, 0x3299},
		{0x1F000, 0x1FAFF}}}
}

// ---------- compiled program ----------

const (
	opChar = iota
	opAny
	opClass
	opBOL
	opEOL
	opWordB
	opNotWordB
	opGroupStart
	opGroupEnd
	opBackref
	opAlt
	opRepeat
	opLoop
	opLook
	opLookEnd
	opMatch
	opSetFlags
)

type reNode struct {
	op       int
	next     *reNode
	c        rune
	cs       *charSet
	alts     []*reNode
	body     *reNode
	min, max int
	greedy   bool
	idx      int
	refs     []int
	neg      bool
	back     bool
	capStart int
	capEnd   int
	simple   bool
	icase    bool
	multi    bool
	dotall   bool
}

type compiledRegExp struct {
	start      *reNode
	ngroups    int
	groupNames []string
	unicode    bool
	icase      bool
	multi      bool
	dotall     bool
	sticky     bool
	global     bool
	hasIndices bool
	vmode      bool
}

type reFlags struct {
	icase, multi, dotall bool
}

func (re *compiledRegExp) emit(a *reAST, next *reNode, back bool, fl reFlags) *reNode {
	switch a.kind {
	case 0:
		c := a.c
		if fl.icase {
			c = re.canon(c)
		}
		return &reNode{op: opChar, c: c, next: next, back: back, icase: fl.icase}
	case 1:
		return &reNode{op: opAny, next: next, back: back, dotall: fl.dotall}
	case 2:
		return &reNode{op: opClass, cs: a.cs, next: next, back: back, icase: fl.icase}
	case 3:
		n := next
		if back {
			for _, it := range a.items {
				n = re.emit(it, n, back, fl)
			}
		} else {
			for i := len(a.items) - 1; i >= 0; i-- {
				n = re.emit(a.items[i], n, back, fl)
			}
		}
		return n
	case 4:
		alt := &reNode{op: opAlt, next: next}
		for _, it := range a.items {
			alt.alts = append(alt.alts, re.emit(it, next, back, fl))
		}
		return alt
	case 5:
		if a.idx < 0 {
			return re.emit(a.items[0], next, back, fl)
		}
		end := &reNode{op: opGroupEnd, idx: a.idx, next: next, back: back}
		body := re.emit(a.items[0], end, back, fl)
		return &reNode{op: opGroupStart, idx: a.idx, next: body, back: back}
	case 14:
		nfl := fl
		if a.icase >= 0 {
			nfl.icase = a.icase == 1
		}
		if a.multi >= 0 {
			nfl.multi = a.multi == 1
		}
		if a.dotall >= 0 {
			nfl.dotall = a.dotall == 1
		}
		return re.emit(a.items[0], next, back, nfl)
	case 6:
		max := a.max
		if max < 0 {
			max = 1 << 30
		}
		rep := &reNode{op: opRepeat, min: a.min, max: max, greedy: a.greedy, next: next, capStart: a.capStart, capEnd: a.capEnd}
		loop := &reNode{op: opLoop, body: rep}
		rep.body = re.emit(a.items[0], loop, back, fl)
		if b := rep.body; (b.op == opChar || b.op == opAny || b.op == opClass) && b.next == loop {
			rep.simple = true
		}
		return rep
	case 7:
		return &reNode{op: opBOL, next: next, multi: fl.multi}
	case 8:
		return &reNode{op: opEOL, next: next, multi: fl.multi}
	case 9:
		return &reNode{op: opWordB, next: next, icase: fl.icase}
	case 10:
		return &reNode{op: opNotWordB, next: next, icase: fl.icase}
	case 11:
		return &reNode{op: opBackref, refs: a.refs, next: next, back: back, icase: fl.icase}
	case 12:
		end := &reNode{op: opLookEnd}
		look := &reNode{op: opLook, neg: a.neg, back: a.behind, next: next}
		look.body = re.emit(a.items[0], end, a.behind, fl)
		return look
	case 13:
		return next
	}
	return next
}

func compileRegExp(pattern *JSString, flags string) (re *compiledRegExp, errMsg string) {
	re = &compiledRegExp{}
	for _, f := range flags {
		var p *bool
		switch f {
		case 'g':
			p = &re.global
		case 'i':
			p = &re.icase
		case 'm':
			p = &re.multi
		case 's':
			p = &re.dotall
		case 'u':
			p = &re.unicode
		case 'y':
			p = &re.sticky
		case 'd':
			p = &re.hasIndices
		case 'v':
			p = &re.vmode
		default:
			return nil, "invalid regular expression flags"
		}
		if *p {
			return nil, "invalid regular expression flags"
		}
		*p = true
	}
	if re.vmode && re.unicode {
		return nil, "invalid regular expression flags"
	}
	if re.vmode {
		re.unicode = true
	}
	u := pattern.UTF16()
	var src []rune
	if re.unicode {
		for i := 0; i < len(u); i++ {
			c := rune(u[i])
			if c >= 0xD800 && c < 0xDC00 && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] < 0xE000 {
				c = utf16.DecodeRune(c, rune(u[i+1]))
				i++
			}
			src = append(src, c)
		}
	} else {
		src = make([]rune, len(u))
		for i, c := range u {
			src[i] = rune(c)
		}
	}
	p := &reParser{src: src, unicode: re.unicode, vmode: re.vmode}
	// pre-scan for named groups
	for i := 0; i+2 < len(src); i++ {
		if src[i] == '\\' {
			i++
			continue
		}
		if src[i] == '(' && src[i+1] == '?' && src[i+2] == '<' && i+3 < len(src) && src[i+3] != '=' && src[i+3] != '!' {
			p.hasNamed = true
			break
		}
	}
	var ast *reAST
	func() {
		defer func() {
			if x := recover(); x != nil {
				if e, ok := x.(*reSyntaxError); ok {
					errMsg = e.msg
					return
				}
				if n, ok := x.(*reAST); ok {
					_ = n
					panic(x)
				}
				panic(x)
			}
		}()
		ast = p.parseDisjunctionTop()
	}()
	if errMsg != "" {
		return nil, errMsg
	}
	// resolve backrefs
	for _, br := range p.backrefs {
		if br.refName != "" {
			idxs, ok := p.names[br.refName]
			if !ok {
				return nil, "group name not defined"
			}
			br.refs = idxs
		} else if br.refs[0] > p.ngroups {
			if re.unicode {
				return nil, "back reference out of range in regular expression"
			}
			// annex B: treat as octal escape / identity
			br.kind = 0
			v := br.refs[0]
			s := strconv.Itoa(v)
			// convert to octal value if possible
			oct := 0
			n := 0
			for _, ch := range s {
				if ch > '7' || n >= 3 || oct*8+int(ch-'0') > 255 {
					break
				}
				oct = oct*8 + int(ch-'0')
				n++
			}
			if n == 0 {
				br.c = rune(s[0])
				// treat remaining digits as literals
				rest := s[1:]
				items := []*reAST{{kind: 0, c: rune(s[0])}}
				for _, ch := range rest {
					items = append(items, &reAST{kind: 0, c: ch})
				}
				br.kind = 3
				br.items = items
			} else {
				items := []*reAST{{kind: 0, c: rune(oct)}}
				for _, ch := range s[n:] {
					items = append(items, &reAST{kind: 0, c: ch})
				}
				br.kind = 3
				br.items = items
			}
		}
	}
	re.ngroups = p.ngroups
	re.groupNames = p.groupNames
	for len(re.groupNames) <= re.ngroups {
		re.groupNames = append(re.groupNames, "")
	}
	re.start = re.emit(ast, &reNode{op: opMatch}, false, reFlags{icase: re.icase, multi: re.multi, dotall: re.dotall})
	return re, ""
}

func (p *reParser) parseDisjunctionTop() (r *reAST) {
	defer func() {
		if x := recover(); x != nil {
			if n, ok := x.(*reAST); ok {
				// named backref signal from parseAtomEscape - should not happen at top
				_ = n
			}
			panic(x)
		}
	}()
	d := p.parseDisjunctionWithBackrefs()
	if !p.eof() {
		if p.peek() == ')' {
			p.fail("unexpected ')'")
		}
		p.fail("syntax error")
	}
	return d
}

// wrapper converting the panic(node) trick for \k<name> into a return value
func (p *reParser) parseDisjunctionWithBackrefs() *reAST {
	return p.parseDisjunction()
}

// canonicalize for case-insensitive matching
func (re *compiledRegExp) canon(c rune) rune {
	return canonChar(c, re.unicode)
}

func canonChar(c rune, uni bool) rune {
	if uni {
		// simple case folding approximation
		if c < 128 {
			if c >= 'A' && c <= 'Z' {
				return c + 32
			}
			return c
		}
		switch c {
		case 0x1E9E:
			return 0xDF
		case 0x2126:
			return 0x3C9
		case 0x212A:
			return 'k'
		case 0x212B:
			return 0xE5
		}
		l := unicode.ToLower(c)
		if l != c {
			return l
		}
		u := unicode.ToUpper(c)
		if u != c {
			l2 := unicode.ToLower(u)
			return l2
		}
		return c
	}
	if c < 128 {
		if c >= 'a' && c <= 'z' {
			return c - 32
		}
		return c
	}
	if c == 0xDF {
		return c
	}
	u := unicode.ToUpper(c)
	if u < 128 {
		return c
	}
	if u > 0xFFFF {
		return c
	}
	return u
}

// ---------- matcher ----------

type reMatcher struct {
	re      *compiledRegExp
	in      []uint16
	caps    []int
	pend    []int
	loops   []loopFrame
	steps   int
}

type loopFrame struct {
	rep   *reNode
	count int
	start int
}

func (m *reMatcher) charAt(pos int) (rune, int) {
	c := rune(m.in[pos])
	if m.re.unicode && c >= 0xD800 && c < 0xDC00 && pos+1 < len(m.in) {
		d := rune(m.in[pos+1])
		if d >= 0xDC00 && d < 0xE000 {
			return utf16.DecodeRune(c, d), 2
		}
	}
	return c, 1
}

func (m *reMatcher) charBefore(pos int) (rune, int) {
	c := rune(m.in[pos-1])
	if m.re.unicode && c >= 0xDC00 && c < 0xE000 && pos-2 >= 0 {
		h := rune(m.in[pos-2])
		if h >= 0xD800 && h < 0xDC00 {
			return utf16.DecodeRune(h, c), 2
		}
	}
	return c, 1
}

func isLineTermRune(c rune) bool {
	return c == '\n' || c == '\r' || c == 0x2028 || c == 0x2029
}

func (m *reMatcher) isWordAt(pos int, icase bool) bool {
	if pos < 0 || pos >= len(m.in) {
		return false
	}
	c := rune(m.in[pos])
	if c < 128 {
		return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '_'
	}
	if icase && m.re.unicode && (c == 0x17F || c == 0x212A) {
		return true
	}
	return false
}

func (m *reMatcher) classMatch(n *reNode, c rune) bool {
	if !n.icase {
		return n.cs.has(c)
	}
	if n.cs.has(c) {
		return true
	}
	cc := canonChar(c, m.re.unicode)
	// check orbit members with same canonical form
	for r := unicode.SimpleFold(c); r != c; r = unicode.SimpleFold(r) {
		if canonChar(r, m.re.unicode) == cc && n.cs.has(r) {
			return true
		}
	}
	if !m.re.unicode {
		// also check lowercase/uppercase forms
		for _, r := range []rune{unicode.ToLower(c), unicode.ToUpper(c)} {
			if r != c && canonChar(r, false) == cc && n.cs.has(r) {
				return true
			}
		}
	}
	return false
}

// match single-char node at pos; returns new pos or -1
func (m *reMatcher) matchOne(n *reNode, pos int) int {
	var c rune
	var l int
	if n.back {
		if pos <= 0 {
			return -1
		}
		c, l = m.charBefore(pos)
	} else {
		if pos >= len(m.in) {
			return -1
		}
		c, l = m.charAt(pos)
	}
	ok := false
	switch n.op {
	case opChar:
		if n.icase {
			ok = canonChar(c, m.re.unicode) == n.c
		} else {
			ok = c == n.c
		}
	case opAny:
		ok = n.dotall || !isLineTermRune(c)
	case opClass:
		ok = m.classMatch(n, c)
		if !ok && len(n.cs.strs) > 0 && !n.cs.neg {
			// try string alternatives (longest first)
			best := -1
			for _, s := range n.cs.strs {
				p := pos
				good := true
				for _, sc := range s {
					if p >= len(m.in) {
						good = false
						break
					}
					cc, ll := m.charAt(p)
					if cc != sc {
						good = false
						break
					}
					p += ll
				}
				if good && p > best {
					best = p
				}
			}
			return best
		}
	}
	if !ok {
		return -1
	}
	if n.back {
		return pos - l
	}
	return pos + l
}

func (m *reMatcher) run(n *reNode, pos int) bool {
	for {
		switch n.op {
		case opMatch:
			m.caps[1] = pos
			return true
		case opLookEnd:
			m.pend = append(m.pend, pos)
			return true
		case opChar, opAny, opClass:
			np := m.matchOne(n, pos)
			if np < 0 {
				return false
			}
			pos = np
			n = n.next
		case opBOL:
			if pos == 0 || (n.multi && isLineTermRune(rune(m.in[pos-1]))) {
				n = n.next
				continue
			}
			return false
		case opEOL:
			if pos == len(m.in) || (n.multi && isLineTermRune(rune(m.in[pos]))) {
				n = n.next
				continue
			}
			return false
		case opWordB, opNotWordB:
			a := m.isWordAt(pos-1, n.icase)
			b := m.isWordAt(pos, n.icase)
			if (a != b) == (n.op == opWordB) {
				n = n.next
				continue
			}
			return false
		case opGroupStart:
			i := n.idx
			old := m.pend[i]
			m.pend[i] = pos
			if m.run(n.next, pos) {
				return true
			}
			m.pend[i] = old
			return false
		case opGroupEnd:
			i := n.idx
			os, oe := m.caps[2*i], m.caps[2*i+1]
			if n.back {
				m.caps[2*i], m.caps[2*i+1] = pos, m.pend[i]
			} else {
				m.caps[2*i], m.caps[2*i+1] = m.pend[i], pos
			}
			if m.run(n.next, pos) {
				return true
			}
			m.caps[2*i], m.caps[2*i+1] = os, oe
			return false
		case opBackref:
			s, e := -1, -1
			for _, r := range n.refs {
				if r < len(m.caps)/2 && m.caps[2*r] >= 0 && m.caps[2*r+1] >= 0 {
					s, e = m.caps[2*r], m.caps[2*r+1]
					break
				}
			}
			if s < 0 {
				n = n.next
				continue
			}
			l := e - s
			if n.back {
				if pos-l < 0 {
					return false
				}
				for k := 0; k < l; k++ {
					if !m.eqChar(m.in[s+k], m.in[pos-l+k], n.icase) {
						return false
					}
				}
				pos -= l
			} else {
				if pos+l > len(m.in) {
					return false
				}
				for k := 0; k < l; k++ {
					if !m.eqChar(m.in[s+k], m.in[pos+k], n.icase) {
						return false
					}
				}
				pos += l
			}
			n = n.next
		case opAlt:
			last := len(n.alts) - 1
			for i := 0; i < last; i++ {
				if m.run(n.alts[i], pos) {
					return true
				}
			}
			n = n.alts[last]
		case opRepeat:
			if n.simple {
				return m.runSimpleRepeat(n, pos)
			}
			return m.repeatTry(n, 0, -1, pos)
		case opLoop:
			fr := m.loops[len(m.loops)-1]
			if pos == fr.start && fr.count > fr.rep.min {
				return false
			}
			m.loops = m.loops[:len(m.loops)-1]
			ok := m.repeatTry(fr.rep, fr.count, fr.start, pos)
			m.loops = append(m.loops, fr)
			return ok
		case opLook:
			saved := append([]int(nil), m.caps...)
			savedLoops := m.loops
			m.loops = nil
			pendLen := len(m.pend)
			matched := m.run(n.body, pos)
			m.pend = m.pend[:pendLen]
			m.loops = savedLoops
			if n.neg {
				copy(m.caps, saved)
				if matched {
					return false
				}
				n = n.next
				continue
			}
			if !matched {
				copy(m.caps, saved)
				return false
			}
			if m.run(n.next, pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		default:
			return false
		}
	}
}

func (m *reMatcher) eqChar(a, b uint16, icase bool) bool {
	if a == b {
		return true
	}
	if !icase {
		return false
	}
	return canonChar(rune(a), m.re.unicode) == canonChar(rune(b), m.re.unicode)
}

func (m *reMatcher) runSimpleRepeat(n *reNode, pos int) bool {
	body := n.body
	if n.greedy {
		positions := []int{pos}
		p := pos
		count := 0
		for count < n.max {
			np := m.matchOne(body, p)
			if np < 0 {
				break
			}
			p = np
			count++
			positions = append(positions, p)
		}
		for count >= n.min {
			if m.run(n.next, positions[count]) {
				return true
			}
			count--
		}
		return false
	}
	count := 0
	p := pos
	for count < n.min {
		np := m.matchOne(body, p)
		if np < 0 {
			return false
		}
		p = np
		count++
	}
	for {
		if m.run(n.next, p) {
			return true
		}
		if count >= n.max {
			return false
		}
		np := m.matchOne(body, p)
		if np < 0 {
			return false
		}
		p = np
		count++
	}
}

func (m *reMatcher) repeatTry(rep *reNode, count int, start int, pos int) bool {
	canIter := count < rep.max
	if rep.greedy {
		if canIter && m.iterate(rep, count, pos) {
			return true
		}
		if count >= rep.min {
			return m.run(rep.next, pos)
		}
		return false
	}
	if count >= rep.min && m.run(rep.next, pos) {
		return true
	}
	if canIter {
		return m.iterate(rep, count, pos)
	}
	return false
}

func (m *reMatcher) iterate(rep *reNode, count int, pos int) bool {
	var saved []int
	if rep.capEnd > rep.capStart {
		saved = append([]int(nil), m.caps[2*rep.capStart:2*rep.capEnd]...)
		for i := 2 * rep.capStart; i < 2*rep.capEnd; i++ {
			m.caps[i] = -1
		}
	}
	m.loops = append(m.loops, loopFrame{rep: rep, count: count + 1, start: pos})
	ok := m.run(rep.body, pos)
	m.loops = m.loops[:len(m.loops)-1]
	if !ok && saved != nil {
		copy(m.caps[2*rep.capStart:], saved)
	}
	return ok
}

// exec at position; returns captures or nil
func (re *compiledRegExp) execAt(in []uint16, pos int) []int {
	m := &reMatcher{re: re, in: in}
	m.caps = make([]int, 2*(re.ngroups+1))
	m.pend = make([]int, re.ngroups+1)
	for i := range m.caps {
		m.caps[i] = -1
	}
	if m.run(re.start, pos) {
		m.caps[0] = pos
		return m.caps
	}
	return nil
}

func (re *compiledRegExp) firstCharHint() (rune, bool) {
	n := re.start
	if n.op == opChar && !n.icase && !n.back {
		return n.c, true
	}
	return 0, false
}

// search from lastIndex; sticky -> only at pos
func (re *compiledRegExp) search(in []uint16, pos int, sticky bool) []int {
	if sticky {
		if pos > len(in) {
			return nil
		}
		return re.execAt(in, pos)
	}
	fc, hasFC := re.firstCharHint()
	if hasFC && fc > 0xFFFF {
		hasFC = false
	}
	for p := pos; p <= len(in); p++ {
		if hasFC {
			for p < len(in) && rune(in[p]) != fc {
				p++
			}
			if p >= len(in) {
				return nil
			}
		}
		if caps := re.execAt(in, p); caps != nil {
			return caps
		}
		if re.unicode && p < len(in) && in[p] >= 0xD800 && in[p] < 0xDC00 && p+1 < len(in) && in[p+1] >= 0xDC00 && in[p+1] < 0xE000 {
			p++
		}
	}
	return nil
}
