func newRegExpObject(re *compiledRegExp, pattern *JSString, flags string, proto *Object) *Object {
	if proto == nil {
		proto = RegExpPrototype
	}
	o := newObjectProto(proto, ClassRegExp)
	o.internal = &RegExpData{re: re, source: pattern, flags: flags}
	o.addProp(strKey("lastIndex"), Int(0), pWritable)
