}

func escapeRegExpSource(s *JSString) *JSString {
	if s.n == 0 {
		return newStrASCII("(?:)")
	}
	var b strBuilder
	inClass := false
	for i := 0; i < s.n; i++ {
		c := s.At(i)
		switch {
		case c == '\\':
			b.WriteUnit(c)
			if i+1 < s.n {
				i++
				b.WriteUnit(s.At(i))
			}
			continue
		case c == '[':
			inClass = true
		case c == ']':
			inClass = false
		case c == '/' && !inClass:
			b.WriteASCII("\\/")
			continue
		case c == '\n':
			b.WriteASCII("\\n")
			continue
		case c == '\r':
			b.WriteASCII("\\r")
			continue
		case c == 0x2028:
			b.WriteASCII("\\u2028")
			continue
		case c == 0x2029:
			b.WriteASCII("\\u2029")
			continue
		}
		b.WriteUnit(c)
	}
	return b.String()
}

func regexpAlloc(proto *Object, pattern *JSString, flags string) *Object {
	re, err := compileRegExp(pattern, flags)
	if err != "" {
		throwSyntaxError("%s", err)
	}
	return newRegExpObject(re, escapeRegExpSource(pattern), flags, proto)
}

func regexpCreate(p Value, f Value) *Object {
	var ps *JSString
	if p.IsUndef() {
		ps = emptyStr
	} else {
		ps = toString(p)
	}
	fs := ""
	if !f.IsUndef() {
		fs = toString(f).String()
	}
	return regexpAlloc(RegExpPrototype, ps, fs)
}

func thisRegExp(this Value) (*Object, *RegExpData) {
	if this.t == TagObj && this.obj().class == ClassRegExp {
		return this.obj(), this.obj().internal.(*RegExpData)
	}
	throwTypeError("not a RegExp object")
	return nil, nil
}

func getLastIndex(o *Object) int64 {
	i := o.findOwn(strKey("lastIndex"))
	if i >= 0 && o.props[i].v.t == TagNum && o.class == ClassRegExp {
		f := o.props[i].v.n
		if f >= 0 && f < 1e15 && f == float64(int64(f)) {
			return int64(f)
		}
	}
	return toLength(o.Get(strKey("lastIndex"), Obj(o)))
}

func setLastIndex(o *Object, v int64) {
	o.Set(strKey("lastIndex"), Num(float64(v)), Obj(o), true)
}

// RegExpBuiltinExec
func regexpBuiltinExec(o *Object, rd *RegExpData, s *JSString) Value {
	caps, ok := regexpExecRaw(o, rd, s)
	if !ok {
		return Null
	}
	return buildMatchResult(rd, s, caps)
}

func regexpExecRaw(o *Object, rd *RegExpData, s *JSString) ([]int, bool) {
	re := rd.re
	li := getLastIndex(o)
	global, sticky := re.global, re.sticky
	if !global && !sticky {
		li = 0
	}
	in := s.UTF16()
	if li > int64(len(in)) {
		if global || sticky {
			setLastIndex(o, 0)
		}
		return nil, false
	}
	caps := re.search(in, int(li), sticky)
	if caps == nil {
		if global || sticky {
			setLastIndex(o, 0)
		}
		return nil, false
	}
	if global || sticky {
		setLastIndex(o, int64(caps[1]))
	}
	return caps, true
}

func buildMatchResult(rd *RegExpData, s *JSString, caps []int) Value {
	re := rd.re
	n := re.ngroups + 1
	vals := make([]Value, n)
	for i := 0; i < n; i++ {
		if caps[2*i] >= 0 && caps[2*i+1] >= 0 {
			vals[i] = Str(s.Substring(caps[2*i], caps[2*i+1]))
		} else {
			vals[i] = Undefined
		}
	}
	a := newArray(vals)
	a.addProp(strKey("index"), Int(caps[0]), pDefault)
	a.addProp(strKey("input"), Str(s), pDefault)
	groups := Undefined
	hasNames := false
	for _, nm := range re.groupNames {
		if nm != "" {
			hasNames = true
		}
	}
	if hasNames {
		g := newObjectProto(nil, ClassObject)
		for i := 1; i < n; i++ {
			if nm := re.groupNames[i]; nm != "" {
				if g.findOwn(strKey(nm)) >= 0 && vals[i].IsUndef() {
					continue
				}
				g.setOwn(strKey(nm), vals[i], pDefault)
			}
		}
		groups = Obj(g)
	}
	a.addProp(strKey("groups"), groups, pDefault)
	if re.hasIndices {
		ivals := make([]Value, n)
		for i := 0; i < n; i++ {
			if caps[2*i] >= 0 {
				ivals[i] = Obj(newArray([]Value{Int(caps[2*i]), Int(caps[2*i+1])}))
			} else {
				ivals[i] = Undefined
			}
		}
		ia := newArray(ivals)
		ig := Undefined
		if hasNames {
			g := newObjectProto(nil, ClassObject)
			for i := 1; i < n; i++ {
				if nm := re.groupNames[i]; nm != "" {
					g.setOwn(strKey(nm), ivals[i], pDefault)
				}
			}
			ig = Obj(g)
		}
		ia.addProp(strKey("groups"), ig, pDefault)
		a.addProp(strKey("indices"), Obj(ia), pDefault)
	}
	return Obj(a)
}

// RegExpExec (calls user exec if overridden)
func regexpExec(r *Object, s *JSString) Value {
	exec := r.Get(strKey("exec"), Obj(r))
	if exec.t == TagObj && exec.obj() == RegExpExecFunc && r.class == ClassRegExp {
		return regexpBuiltinExec(r, r.internal.(*RegExpData), s)
	}
	if exec.isCallable() {
		res := callValue(exec, Obj(r), []Value{Str(s)})
		if res.t != TagObj && res.t != TagNull {
			throwTypeError("exec result must be an object or null")
		}
		return res
	}
	if r.class != ClassRegExp {
		throwTypeError("not a RegExp object")
	}
	return regexpBuiltinExec(r, r.internal.(*RegExpData), s)
}

func advanceIndex(s *JSString, i int64, unicode bool) int64 {
	if !unicode || i+1 >= int64(s.n) {
		return i + 1
	}
	_, l := s.CodePointAt(int(i))
	return i + int64(l)
}

func isPristineRegExp(r *Object) bool {
	if r.class != ClassRegExp || r.proto != RegExpPrototype {
		return false
	}
	if len(r.keys) != 1 {
		return false
	}
	i := RegExpPrototype.findOwn(strKey("exec"))
	return i >= 0 && RegExpPrototype.props[i].v.p == RegExpExecFunc.toPtr()
}

func initRegExp() {
	RegExpPrototype = newObject()
	rp := RegExpPrototype
	ctorFn := func(args []Value, nt *Object) Value {
		pattern := arg(args, 0)
		flags := arg(args, 1)
		pIsRegExp := isRegExp(pattern)
		if nt == nil {
			nt = RegExpCtor
			if pIsRegExp && flags.IsUndef() {
				pc := getV(pattern, keyConstructor)
				if pc.t == TagObj && pc.obj() == RegExpCtor {
					return pattern
				}
			}
		}
		var P Value
		var F Value
		if pattern.t == TagObj && pattern.obj().class == ClassRegExp {
			rd := pattern.obj().internal.(*RegExpData)
			P = Str(rd.originalSource())
			if flags.IsUndef() {
				F = StrGo(rd.flags)
			} else {
				F = flags
			}
		} else if pIsRegExp {
			P = getV(pattern, strKey("source"))
			if flags.IsUndef() {
				F = getV(pattern, strKey("flags"))
			} else {
				F = flags
			}
		} else {
			P, F = pattern, flags
		}
		proto := getPrototypeFromCtor(nt, RegExpPrototype)
		var ps *JSString
		if P.IsUndef() {
			ps = emptyStr
		} else {
			ps = toString(P)
		}
		fs := ""
		if !F.IsUndef() {
			fs = toString(F).String()
		}
		return Obj(regexpAlloc(proto, ps, fs))
	}
	ctor := makeCtor("RegExp", 2, rp, func(this Value, args []Value) Value { return ctorFn(args, nil) }, ctorFn)
	RegExpCtor = ctor
	addGlobal("RegExp", Obj(ctor))
	defMethod(ctor, "escape", 1, func(this Value, args []Value) Value {
		v := arg(args, 0)
		if v.t != TagStr {
			throwTypeError("not a string")
		}
		s := v.str()
		var b strBuilder
		for i := 0; i < s.n; i++ {
			c := s.At(i)
			if i == 0 && (c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z') {
				b.WriteASCII("\\x")
				b.WriteUnit(uint16(digitChars[c>>4]))
				b.WriteUnit(uint16(digitChars[c&15]))
				continue
			}
			if c < 128 && strings.IndexByte("^$\\.*+?()[]{}|/", byte(c)) >= 0 {
				b.WriteUnit('\\')
				b.WriteUnit(c)
				continue
			}
			if c < 128 && strings.IndexByte(",-=<>#&!%:;@~'`\"", byte(c)) >= 0 {
				b.WriteASCII("\\x")
				b.WriteUnit(uint16(digitChars[c>>4]))
				b.WriteUnit(uint16(digitChars[c&15]))
				continue
			}
			switch c {
			case '\t':
				b.WriteASCII("\\t")
			case '\n':
				b.WriteASCII("\\n")
			case '\v':
				b.WriteASCII("\\v")
			case '\f':
				b.WriteASCII("\\f")
			case '\r':
				b.WriteASCII("\\r")
			case ' ':
				b.WriteASCII("\\x20")
			default:
				if isWSUnit(c) || (c >= 0xD800 && c < 0xE000) {
					b.WriteASCII("\\u")
					h := []byte("0000")
					hx := "0123456789abcdef"
					h[0], h[1], h[2], h[3] = hx[c>>12], hx[(c>>8)&15], hx[(c>>4)&15], hx[c&15]
					b.WriteASCII(string(h))
				} else {
					b.WriteUnit(c)
				}
			}
		}
		return Str(b.String())
	})
	finishCtor(ctor, rp)
	speciesGetter(ctor)
	ci := rp.findOwn(keyConstructor)
	rp.removePropAt(ci)
	rp.compact()

	defGetter(rp, "flags", func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		var sb strings.Builder
		for _, p := range []struct {
			n string
			c byte
		}{{"hasIndices", 'd'}, {"global", 'g'}, {"ignoreCase", 'i'}, {"multiline", 'm'}, {"dotAll", 's'}, {"unicode", 'u'}, {"unicodeSets", 'v'}, {"sticky", 'y'}} {
			if toBool(getV(this, strKey(p.n))) {
				sb.WriteByte(p.c)
			}
		}
		return StrGo(sb.String())
	})
	defGetter(rp, "source", func(this Value, args []Value) Value {
		if this.t == TagObj && this.obj() == RegExpPrototype {
			return StrGo("(?:)")
		}
		_, rd := thisRegExp(this)
		return Str(rd.source)
	})
	flagGetter := func(name string, c byte) {
		defGetter(rp, name, func(this Value, args []Value) Value {
			if this.t == TagObj && this.obj() == RegExpPrototype {
				return Undefined
			}
			_, rd := thisRegExp(this)
			return Bool(strings.IndexByte(rd.flags, c) >= 0)
		})
	}
	flagGetter("global", 'g')
	flagGetter("ignoreCase", 'i')
	flagGetter("multiline", 'm')
	flagGetter("dotAll", 's')
	flagGetter("unicode", 'u')
	flagGetter("unicodeSets", 'v')
	flagGetter("sticky", 'y')
	flagGetter("hasIndices", 'd')
	RegExpExecFunc = defMethod(rp, "exec", 1, func(this Value, args []Value) Value {
		o, rd := thisRegExp(this)
		s := toString(arg(args, 0))
		return regexpBuiltinExec(o, rd, s)
	})
	defMethod(rp, "compile", 2, func(this Value, args []Value) Value {
		o, rd := thisRegExp(this)
		pattern := arg(args, 0)
		flags := arg(args, 1)
		var ps *JSString
		fs := ""
		if pattern.t == TagObj && pattern.obj().class == ClassRegExp {
			if !flags.IsUndef() {
				throwTypeError("flags must be undefined")
			}
			prd := pattern.obj().internal.(*RegExpData)
			ps = prd.originalSource()
			fs = prd.flags
		} else {
			if pattern.IsUndef() {
				ps = emptyStr
			} else {
				ps = toString(pattern)
			}
			if !flags.IsUndef() {
				fs = toString(flags).String()
			}
		}
		re, err := compileRegExp(ps, fs)
		if err != "" {
			throwSyntaxError("%s", err)
		}
		rd.re = re
		rd.source = escapeRegExpSource(ps)
		rd.flags = fs
		setLastIndex(o, 0)
		return this
	})
	defMethod(rp, "test", 1, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		if isPristineRegExp(this.obj()) {
			_, ok := regexpExecRaw(this.obj(), this.obj().internal.(*RegExpData), s)
			return Bool(ok)
		}
		r := regexpExec(this.obj(), s)
		return Bool(!r.IsNull())
	})
	defMethod(rp, "toString", 0, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		src := toString(getV(this, strKey("source")))
		fl := toString(getV(this, strKey("flags")))
		return Str(concatStr(concatStr(concatStr(newStrASCII("/"), src), newStrASCII("/")), fl))
	})
	rp.setOwn(keyConstructor, Obj(ctor), pWritable|pConfigurable)

	defMethodSym(rp, SymMatch, "[Symbol.match]", 1, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		rx := this.obj()
		s := toString(arg(args, 0))
		flags := toString(getV(this, strKey("flags"))).String()
		if !strings.Contains(flags, "g") {
			return regexpExec(rx, s)
		}
		fullUnicode := strings.Contains(flags, "u") || strings.Contains(flags, "v")
		setLastIndex(rx, 0)
		var out []Value
		for {
			r := regexpExec(rx, s)
			if r.IsNull() {
				if len(out) == 0 {
					return Null
				}
				return Obj(newArray(out))
			}
			ms := toString(getMemberComputed(r, Num(0)))
			out = append(out, Str(ms))
			if ms.n == 0 {
				li := getLastIndex(rx)
				setLastIndex(rx, advanceIndex(s, li, fullUnicode))
			}
		}
	})
	defMethodSym(rp, SymMatchAll, "[Symbol.matchAll]", 1, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		s := toString(arg(args, 0))
		c := speciesConstructor(this.obj(), RegExpCtor)
		flags := toString(getV(this, strKey("flags")))
		matcher := constructValue(c, []Value{this, Str(flags)}, nil).obj()
		li := getLastIndex(this.obj())
		setLastIndex(matcher, li)
		fs := flags.String()
		it := newObjectProto(RegExpStringIteratorPrototype, ClassRegExpStringIterator)
		it.internal = &regexpStrIter{rx: matcher, s: s, global: strings.Contains(fs, "g"), unicode: strings.Contains(fs, "u") || strings.Contains(fs, "v")}
		return Obj(it)
	})
	defMethodSym(rp, SymReplace, "[Symbol.replace]", 2, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		return regexpReplace(this.obj(), toString(arg(args, 0)), arg(args, 1))
	})
	defMethodSym(rp, SymSearch, "[Symbol.search]", 1, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		rx := this.obj()
		s := toString(arg(args, 0))
		prev := rx.Get(strKey("lastIndex"), this)
		if !sameValue(prev, Num(0)) {
			rx.Set(strKey("lastIndex"), Num(0), this, true)
		}
		r := regexpExec(rx, s)
		cur := rx.Get(strKey("lastIndex"), this)
		if !sameValue(cur, prev) {
			rx.Set(strKey("lastIndex"), prev, this, true)
		}
		if r.IsNull() {
			return Int(-1)
		}
		return getV(r, strKey("index"))
	})
	defMethodSym(rp, SymSplit, "[Symbol.split]", 2, func(this Value, args []Value) Value {
		if this.t != TagObj {
			throwTypeError("not an object")
		}
		return regexpSplit(this.obj(), toString(arg(args, 0)), arg(args, 1))
	})

	RegExpStringIteratorPrototype = newObjectProto(IteratorPrototype, ClassObject)
	defMethod(RegExpStringIteratorPrototype, "next", 0, func(this Value, args []Value) Value {
		if this.t != TagObj || this.obj().class != ClassRegExpStringIterator {
			throwTypeError("not a RegExp String Iterator")
		}
		it := this.obj().internal.(*regexpStrIter)
		if it.done {
			return iterResult(Undefined, true)
		}
		r := regexpExec(it.rx, it.s)
		if r.IsNull() {
			it.done = true
			return iterResult(Undefined, true)
		}
		if !it.global {
			it.done = true
			return iterResult(r, false)
		}
		ms := toString(getMemberComputed(r, Num(0)))
		if ms.n == 0 {
			li := getLastIndex(it.rx)
			setLastIndex(it.rx, advanceIndex(it.s, li, it.unicode))
		}
		return iterResult(r, false)
	})
	RegExpStringIteratorPrototype.setOwn(PropKey{sym: SymToStringTag}, StrGo("RegExp String Iterator"), pConfigurable)
}

type regexpStrIter struct {
	rx      *Object
	s       *JSString
	global  bool
	unicode bool
	done    bool
}

func (rd *RegExpData) originalSource() *JSString {
	// source is escaped; unescaping '/' is harmless for recompilation
	return rd.source
}

func regexpReplace(rx *Object, s *JSString, replaceValue Value) Value {
	fnRepl := replaceValue.isCallable()
	var replStr *JSString
	if !fnRepl {
		replStr = toString(replaceValue)
	}
	flags := toString(getV(Obj(rx), strKey("flags"))).String()
	global := strings.Contains(flags, "g")
	fullUnicode := strings.Contains(flags, "u") || strings.Contains(flags, "v")
	if global {
		setLastIndex(rx, 0)
	}
	type result struct {
		matched  *JSString
		position int
		caps     []Value
		groups   Value
	}
	var results []result
	pristine := isPristineRegExp(rx)
	for {
		if pristine {
			rd := rx.internal.(*RegExpData)
			caps, ok := regexpExecRaw(rx, rd, s)
			if !ok {
				break
			}
			re := rd.re
			res := result{position: caps[0]}
			res.matched = s.Substring(caps[0], caps[1])
			for i := 1; i <= re.ngroups; i++ {
				if caps[2*i] >= 0 {
					res.caps = append(res.caps, Str(s.Substring(caps[2*i], caps[2*i+1])))
				} else {
					res.caps = append(res.caps, Undefined)
				}
			}
			res.groups = Undefined
			hasNames := false
			for _, nm := range re.groupNames {
				if nm != "" {
					hasNames = true
				}
			}
			if hasNames {
				g := newObjectProto(nil, ClassObject)
				for i := 1; i <= re.ngroups; i++ {
					if nm := re.groupNames[i]; nm != "" {
						if g.findOwn(strKey(nm)) >= 0 && res.caps[i-1].IsUndef() {
							continue
						}
						g.setOwn(strKey(nm), res.caps[i-1], pDefault)
					}
				}
				res.groups = Obj(g)
			}
			results = append(results, res)
			if !global {
				break
			}
			if caps[1] == caps[0] {
				li := getLastIndex(rx)
				setLastIndex(rx, advanceIndex(s, li, fullUnicode))
			}
			continue
		}
		r := regexpExec(rx, s)
		if r.IsNull() {
			break
		}
		ro := r.obj()
		ncaps := lengthOfArrayLike(ro) - 1
		if ncaps < 0 {
			ncaps = 0
		}
		matched := toString(objGetI(ro, 0))
		pos := toInteger(ro.Get(strKey("index"), r))
		if pos < 0 {
			pos = 0
		}
		if pos > float64(s.n) {
			pos = float64(s.n)
		}
		res := result{matched: matched, position: int(pos)}
		for i := int64(1); i <= ncaps; i++ {
			c := objGetI(ro, i)
			if !c.IsUndef() {
				c = Str(toString(c))
			}
			res.caps = append(res.caps, c)
		}
		res.groups = ro.Get(strKey("groups"), r)
		results = append(results, res)
		if !global {
			break
		}
		if matched.n == 0 {
			li := getLastIndex(rx)
			setLastIndex(rx, advanceIndex(s, li, fullUnicode))
		}
	}
	var b strBuilder
	nextPos := 0
	for _, res := range results {
		var rep *JSString
		if fnRepl {
			cargs := []Value{Str(res.matched)}
			cargs = append(cargs, res.caps...)
			cargs = append(cargs, Int(res.position), Str(s))
			if !res.groups.IsUndef() {
				cargs = append(cargs, res.groups)
			}
			rep = toString(callValue(replaceValue, Undefined, cargs))
		} else {
			groups := res.groups
			if !groups.IsUndef() {
				groups = Obj(toObject(groups))
			}
			rep = getSubstitution(res.matched, s, res.position, res.caps, groups, replStr)
		}
		if res.position >= nextPos {
			b.WriteStr(s.Substring(nextPos, res.position))
			b.WriteStr(rep)
			nextPos = res.position + res.matched.n
		}
	}
	if nextPos < s.n {
		b.WriteStr(s.Substring(nextPos, s.n))
	}
	return Str(b.String())
}

func regexpSplit(rx *Object, s *JSString, limit Value) Value {
	c := speciesConstructor(rx, RegExpCtor)
	flags := toString(getV(Obj(rx), strKey("flags"))).String()
	unicodeMatching := strings.Contains(flags, "u") || strings.Contains(flags, "v")
	newFlags := flags
	if !strings.Contains(flags, "y") {
		newFlags += "y"
	}
	splitter := constructValue(c, []Value{Obj(rx), StrGo(newFlags)}, nil).obj()
	lim := uint32(0xFFFFFFFF)
	if !limit.IsUndef() {
		lim = toUint32(limit)
	}
	var out []Value
	if lim == 0 {
		return Obj(newArray(nil))
	}
	size := s.n
	if size == 0 {
		z := regexpExec(splitter, s)
		if !z.IsNull() {
			return Obj(newArray(nil))
		}
		return Obj(newArray([]Value{Str(s)}))
	}
	p := 0
	q := p
	for q < size {
		setLastIndex(splitter, int64(q))
		z := regexpExec(splitter, s)
		if z.IsNull() {
			q = int(advanceIndex(s, int64(q), unicodeMatching))
			continue
		}
		e := int(getLastIndex(splitter))
		if e > size {
			e = size
		}
		if e == p {
			q = int(advanceIndex(s, int64(q), unicodeMatching))
			continue
		}
		out = append(out, Str(s.Substring(p, q)))
		if uint32(len(out)) == lim {
			return Obj(newArray(out))
		}
		p = e
		zo := z.obj()
		ncaps := lengthOfArrayLike(zo) - 1
		for i := int64(1); i <= ncaps; i++ {
			out = append(out, objGetI(zo, i))
			if uint32(len(out)) == lim {
				return Obj(newArray(out))
			}
		}
		q = p
	}
	out = append(out, Str(s.Substring(p, size)))
	return Obj(newArray(out))
}
