cat > module.go <<'EOF'
package main

import (
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const (
	modUnlinked = iota
	modLinking
	modLinked
	modEvaluating
	modEvaluated
	modError
)

type exportEntry struct {
	localB     *Binding
	fromMod    *ModuleRec
	importName string // for indirect; "*" for namespace re-export
}

type ModuleRec struct {
	name        string
	sf          *SourceFile
	prog        *Program
	code        *FuncCode
	env         *Env
	scope       *Scope
	status      int
	instantiated bool
	deps        map[string]*ModuleRec
	depOrder    []*ModuleRec
	importCells map[*Binding]*importCell
	exports     map[string]*exportEntry
	exportOrder []string
	starExports []*ModuleRec
	ns          *Object
	meta        *Object
	evalErr     *Value
	native      bool
	nativeVals  map[string]Value
	nativeOrder []string
	frame       *Frame
	isMain      bool
}

type importCell struct {
	env *Env
	idx int
	ns  *Object
	mod *ModuleRec
	nv  string
}

var moduleCache = map[string]*ModuleRec{}

func normalizeModuleName(base, name string) string {
	if !strings.HasPrefix(name, "./") && !strings.HasPrefix(name, "../") {
		return name
	}
	dir := ""
	if i := strings.LastIndexByte(base, '/'); i >= 0 {
		dir = base[:i]
	}
	parts := []string{}
	if dir != "" {
		parts = strings.Split(dir, "/")
	}
	for _, seg := range strings.Split(name, "/") {
		switch seg {
		case ".":
		case "..":
			if len(parts) > 0 && parts[len(parts)-1] != ".." && parts[len(parts)-1] != "" {
				parts = parts[:len(parts)-1]
			} else {
				parts = append(parts, "..")
			}
		default:
			parts = append(parts, seg)
		}
	}
	return strings.Join(parts, "/")
}

func (m *ModuleRec) importMeta() *Object {
	if m.meta == nil {
		o := newObjectProto(nil, ClassObject)
		url := m.name
		if !strings.Contains(url, "://") {
			if abs, err := filepath.Abs(m.name); err == nil {
				if rp, err := filepath.EvalSymlinks(abs); err == nil {
					abs = rp
				}
				url = "file://" + abs
			}
		}
		o.addProp(strKey("url"), StrGo(url), pDefault)
		o.addProp(strKey("main"), Bool(m.isMain), pDefault)
		m.meta = o
	}
	return m.meta
}

func throwModuleLoadError(name string) {
	e := newObjectProto(ReferenceErrorPrototype, ClassError)
	e.setOwn(strKey("message"), StrGo("could not load module filename '"+name+"'"), pWritable|pConfigurable)
	e.setOwn(strKey("stack"), Str(emptyStr), pWritable|pConfigurable)
	throwValue(Obj(e))
}

func throwModuleSyntaxError(msg string) {
	e := newObjectProto(SyntaxErrorPrototype, ClassError)
	e.setOwn(strKey("message"), StrGo(msg), pWritable|pConfigurable)
	e.setOwn(strKey("stack"), Str(emptyStr), pWritable|pConfigurable)
	throwValue(Obj(e))
}

// load (parse+resolve) a module and its dependencies
func loadModule(name string) *ModuleRec {
	if m, ok := moduleCache[name]; ok {
		return m
	}
	if nm := nativeModule(name); nm != nil {
		moduleCache[name] = nm
		return nm
	}
	data, err := os.ReadFile(name)
	if err != nil {
		throwModuleLoadError(name)
	}
	return loadModuleSource(name, string(data))
}

func loadModuleSource(name, src string) *ModuleRec {
	m := &ModuleRec{name: name, deps: map[string]*ModuleRec{}, importCells: map[*Binding]*importCell{}, exports: map[string]*exportEntry{}}
	moduleCache[name] = m
	sf := newSourceFile(name, src)
	m.sf = sf
	prog, se := parseProgram(sf, true, true, nil)
	if se != nil {
		delete(moduleCache, name)
		throwValue(Obj(makeSyntaxErrorAt(se, sf)))
	}
	m.prog = prog
	if se = resolveProgram(prog, pkModule, nil, m); se != nil {
		delete(moduleCache, name)
		throwValue(Obj(makeSyntaxErrorAt(se, sf)))
	}
	m.scope = prog.F.paramScope
	// requested modules in order
	var reqs []string
	for _, st := range prog.Body {
		switch x := st.(type) {
		case *ImportDecl:
			reqs = append(reqs, x.From)
		case *ExportDecl:
			if x.hasFrom {
				reqs = append(reqs, x.From)
			}
		}
	}
	for _, r := range reqs {
		rn := normalizeModuleName(name, r)
		if _, ok := m.deps[rn]; ok {
			continue
		}
		dm := loadModule(rn)
		m.deps[rn] = dm
		m.depOrder = append(m.depOrder, dm)
	}
	// export table
	for _, st := range prog.Body {
		x, ok := st.(*ExportDecl)
		if !ok {
			continue
		}
		addExp := func(exp string, e *exportEntry) {
			if _, dup := m.exports[exp]; dup {
				throwModuleSyntaxError("duplicate exported name '" + exp + "'")
			}
			m.exports[exp] = e
			m.exportOrder = append(m.exportOrder, exp)
		}
		switch {
		case x.Star && x.StarAs == "":
			m.starExports = append(m.starExports, m.deps[normalizeModuleName(name, x.From)])
		case x.Star:
			addExp(x.StarAs, &exportEntry{fromMod: m.deps[normalizeModuleName(name, x.From)], importName: "*"})
		case x.hasFrom:
			dm := m.deps[normalizeModuleName(name, x.From)]
			for _, sp := range x.Specs {
				addExp(sp.Exported, &exportEntry{fromMod: dm, importName: sp.Local})
			}
		case x.Default != nil:
			addExp("default", &exportEntry{localB: x.defaultB})
		case x.Decl != nil:
			if len(x.Specs) > 0 {
				for _, sp := range x.Specs {
					b := m.scope.lookupLocal(sp.Local)
					if sp.Local == "*default*" {
						b = x.defaultB
					}
					addExp(sp.Exported, &exportEntry{localB: b})
				}
				continue
			}
			var names []string
			switch d := x.Decl.(type) {
			case *VarDecl:
				for _, dd := range d.Decls {
					for _, id := range boundNames(dd.Target, nil) {
						names = append(names, id.Name)
					}
				}
			case *FuncDecl:
				names = append(names, d.F.Name)
			case *ClassDecl:
				names = append(names, d.C.Name)
			}
			for _, n := range names {
				addExp(n, &exportEntry{localB: m.scope.lookupLocal(n)})
			}
		default:
			for _, sp := range x.Specs {
				b := m.scope.lookupLocal(sp.Local)
				if b != nil && b.kind == bImport {
					// re-export of an import
					var imp *ImportSpec
					var from string
					for _, st2 := range prog.Body {
						if id, ok := st2.(*ImportDecl); ok {
							for _, isp := range id.Specs {
								if isp.b == b {
									imp = isp
									from = id.From
								}
							}
						}
					}
					if imp != nil {
						addExp(sp.Exported, &exportEntry{fromMod: m.deps[normalizeModuleName(name, from)], importName: imp.Imported})
						continue
					}
				}
				addExp(sp.Exported, &exportEntry{localB: b})
			}
		}
	}
	return m
}

type resolvedExport struct {
	mod *ModuleRec
	b   *Binding
	ns  bool
	nv  string // native value name
}

func (m *ModuleRec) resolveExport(name string, visited map[*ModuleRec]map[string]bool) (*resolvedExport, bool) {
	if visited[m] == nil {
		visited[m] = map[string]bool{}
	}
	if visited[m][name] {
		return nil, false
	}
	visited[m][name] = true
	if m.native {
		if _, ok := m.nativeVals[name]; ok {
			return &resolvedExport{mod: m, nv: name}, false
		}
		return nil, false
	}
	if e, ok := m.exports[name]; ok {
		if e.localB != nil {
			return &resolvedExport{mod: m, b: e.localB}, false
		}
		if e.importName == "*" {
			return &resolvedExport{mod: e.fromMod, ns: true}, false
		}
		return e.fromMod.resolveExport(e.importName, visited)
	}
	if name == "default" {
		return nil, false
	}
	var star *resolvedExport
	for _, sm := range m.starExports {
		r, amb := sm.resolveExport(name, visited)
		if amb {
			return nil, true
		}
		if r != nil {
			if star != nil && (star.mod != r.mod || star.b != r.b || star.nv != r.nv) {
				return nil, true
			}
			star = r
		}
	}
	return star, false
}

func (m *ModuleRec) exportedNames(visited map[*ModuleRec]bool) []string {
	if visited[m] {
		return nil
	}
	visited[m] = true
	if m.native {
		return append([]string{}, m.nativeOrder...)
	}
	names := append([]string{}, m.exportOrder...)
	for _, sm := range m.starExports {
		for _, n := range sm.exportedNames(visited) {
			if n == "default" {
				continue
			}
			dup := false
			for _, x := range names {
				if x == n {
					dup = true
				}
			}
			if !dup {
				names = append(names, n)
			}
		}
	}
	return names
}

func (m *ModuleRec) link() {
	if m.status != modUnlinked {
		return
	}
	m.status = modLinking
	for _, d := range m.depOrder {
		d.link()
	}
	if !m.native {
		for _, st := range m.prog.Body {
			imp, ok := st.(*ImportDecl)
			if !ok {
				continue
			}
			dm := m.deps[normalizeModuleName(m.name, imp.From)]
			for _, sp := range imp.Specs {
				if sp.Imported == "*" {
					m.importCells[sp.b] = &importCell{ns: dm.namespace()}
					continue
				}
				r, amb := dm.resolveExport(sp.Imported, map[*ModuleRec]map[string]bool{})
				if amb {
					throwModuleSyntaxError("ambiguous export '" + sp.Imported + "' in module '" + dm.name + "'")
				}
				if r == nil {
					throwModuleSyntaxError("Could not find export '" + sp.Imported + "' in module '" + dm.name + "'")
				}
				m.importCells[sp.b] = r.cell()
			}
		}
		// validate indirect exports
		for _, exp := range m.exportOrder {
			e := m.exports[exp]
			if e.localB == nil && e.importName != "*" {
				r, _ := e.fromMod.resolveExport(e.importName, map[*ModuleRec]map[string]bool{})
				if r == nil {
					throwModuleSyntaxError("Could not find export '" + e.importName + "' in module '" + e.fromMod.name + "'")
				}
			}
		}
	}
	m.status = modLinked
}

func (r *resolvedExport) cell() *importCell {
	if r.ns {
		return &importCell{ns: r.mod.namespace()}
	}
	if r.nv != "" {
		return &importCell{ns: nil, mod: r.mod, nv: r.nv}
	}
	return &importCell{mod: r.mod, idx: r.b.idx, env: nil, nv: "", ns: nil}
}

func (m *ModuleRec) compileAndInstantiate() {
	if m.instantiated || m.native {
		return
	}
	m.instantiated = true
	for _, d := range m.depOrder {
		d.compileAndInstantiate()
	}
	code, se := compileProgram(m.prog, pkModule, m.sf, nil, m)
	if se != nil {
		throwValue(Obj(makeSyntaxErrorAt(se, m.sf)))
	}
	m.code = code
	m.env = &Env{vals: make([]Value, m.scope.envSize)}
	for _, b := range m.scope.list {
		if b.tdz || b.kind == bClass {
			m.env.vals[b.idx] = Empty
		}
	}
	f := &Frame{code: code, thisInit: true, env: m.env}
	f.thisFrame = f
	if code.nlocals > 0 {
		f.locals = make([]Value, code.nlocals)
	}
	m.frame = f
	pushFrame(f, 1000)
	code.prologue(f)
	popStack()
}

// evaluate module; returns a promise if async (TLA), else nil
func (m *ModuleRec) evaluate() {
	if m.native || m.status == modEvaluated || m.status == modEvaluating {
		return
	}
	if m.status == modError {
		throwValue(*m.evalErr)
	}
	m.status = modEvaluating
	defer func() {
		if x := recover(); x != nil {
			if t, ok := x.(*JSThrow); ok {
				m.status = modError
				v := t.v
				m.evalErr = &v
			}
			panic(x)
		}
	}()
	for _, d := range m.depOrder {
		d.evaluate()
	}
	f := m.frame
	code := m.code
	if m.prog.F.usesAwait {
		pcap := newPromiseCap()
		co := newCoroutine(func(co *Coroutine, first coMsg) Value {
			pushFrame(f, 1000)
			code.body(f)
			popStack()
			return Undefined
		})
		f.co = co
		asyncStep(co, pcap, coMsg{kind: coNext})
		// drive event loop until settled
		pd := pcap.promise.internal.(*PromiseData)
		for pd.state == promPending {
			if !runEventLoopOnce() {
				break
			}
		}
		if pd.state == promRejected {
			// mark handled
			pd.isHandled = true
			promiseRejectionTracker(pcap.promise, true)
			throwValue(pd.result)
		}
	} else {
		pushFrame(f, 1000)
		code.body(f)
		popStack()
	}
	m.status = modEvaluated
}

func (m *ModuleRec) namespace() *Object {
	if m.ns == nil {
		o := &Object{proto: nil, class: ClassModuleNS, extensible: false, internal: m}
		m.ns = o
	}
	return m.ns
}

func (m *ModuleRec) nsNames() []string {
	names := m.exportedNames(map[*ModuleRec]bool{})
	var out []string
	for _, n := range names {
		r, amb := m.resolveExport(n, map[*ModuleRec]map[string]bool{})
		if r != nil && !amb {
			out = append(out, n)
		}
	}
	sort.Slice(out, func(i, j int) bool {
		return strCompare(newStr(out[i]), newStr(out[j])) < 0
	})
	return out
}

func (m *ModuleRec) nsGet(name string) (Value, bool) {
	r, amb := m.resolveExport(name, map[*ModuleRec]map[string]bool{})
	if r == nil || amb {
		return Undefined, false
	}
	if r.ns {
		return Obj(r.mod.namespace()), true
	}
	if r.nv != "" {
		return r.mod.nativeVals[r.nv], true
	}
	if r.mod.env == nil {
		throwReferenceError("%s is not initialized", name)
	}
	v := r.mod.env.vals[r.b.idx]
	if v.t == TagEmpty {
		throwReferenceError("%s is not initialized", name)
	}
	return v, true
}

func moduleNSGetOwnProperty(o *Object, k PropKey) *PropDesc {
	m := o.internal.(*ModuleRec)
	if k.sym != nil {
		if k.sym == SymToStringTag {
			return dataDesc(StrGo("Module"), 0)
		}
		return nil
	}
	found := false
	for _, n := range m.nsNames() {
		if n == k.s {
			found = true
			break
		}
	}
	if !found {
		return nil
	}
	v, _ := m.nsGet(k.s)
	return dataDesc(v, pWritable|pEnumerable)
}

func moduleNSOwnKeys(o *Object) []PropKey {
	m := o.internal.(*ModuleRec)
	var keys []PropKey
	for _, n := range m.nsNames() {
		keys = append(keys, strKey(n))
	}
	keys = append(keys, PropKey{sym: SymToStringTag})
	return keys
}

func (c *compiler) moduleInit(prog *Program, top *Scope) func(f *Frame) {
	return nil
}

func (c *compiler) exportDecl(x *ExportDecl) stmtFn {
	if x.Decl != nil {
		return c.stmt(x.Decl)
	}
	if x.Default != nil {
		e := c.exprNamed(x.Default, "default")
		set := c.bindingInit(x.defaultB)
		return func(f *Frame) ctrl {
			set(f, e(f))
			return cNormal
		}
	}
	return nil
}

func dynamicImport(m *ModuleRec, sf *SourceFile, spec Value) Value {
	cap := newPromiseCap()
	thr := catchJS(func() {
		s := toString(spec).String()
		base := ""
		if m != nil {
			base = m.name
		} else if sf != nil {
			base = sf.name
		}
		name := normalizeModuleName(base, s)
		mod := loadModule(name)
		mod.link()
		mod.compileAndInstantiate()
		mod.evaluate()
		cap.resolve(Obj(mod.namespace()))
	})
	if thr != nil {
		cap.reject(*thr)
	}
	return Obj(cap.promise)
}

func runModuleFile(name, src string) {
	m := loadModuleSource(name, src)
	m.isMain = true
	m.link()
	m.compileAndInstantiate()
	m.evaluate()
}

// detect whether source should be treated as a module
func detectModule(src string) bool {
	lx := &Lexer{src: src}
	if len(src) >= 2 && src[0] == '#' && src[1] == '!' {
		i := 0
		for i < len(src) && src[i] != '\n' {
			i++
		}
		lx.pos = i
	}
	ok := false
	func() {
		defer func() { recover() }()
		lx.next()
		t := lx.tok
		if t.kind == tIdent && t.str == "export" {
			ok = true
			return
		}
		if t.kind == tIdent && t.str == "import" {
			lx.next()
			if !(lx.tok.kind == tPunct && (lx.tok.str == "(" || lx.tok.str == ".")) {
				ok = true
			}
		}
	}()
	return ok
}
