			if err != nil {
				return Null
			}
			c.Stderr = os.Stderr
			if err := c.Start(); err != nil {
				return Null
			}
			jf.r = bufio.NewReader(out)
			jf.f = nil
		} else {
			in, err := c.StdinPipe()
			if err != nil {
				return Null
			}
			c.Stdout = os.Stdout
			c.Stderr = os.Stderr
			flushStdout()
			if err := c.Start(); err != nil {
				return Null
			}
			jf.w = bufio.NewWriter(in)
			pr := &pipeCloser{in}
			_ = pr
			jf.proc = c
			jf.f = nil
			jfw := jf
			_ = jfw
			jf.closer = in
		}
		return newFileObj(jf)
	})
