		f, err := os.CreateTemp("", "qjs")
		if err != nil {
			return Null
		}
		os.Remove(f.Name())
		return newFileObj(&jsFile{f: f})
	})
	m["parseExtJSON"] = nf("parseExtJSON", 1, func(this Value, args []Value) Value {
		return parseExtJSON(toString(arg(args, 0)))
	})
	m["evalScript"] = nf("evalScript", 2, func(this Value, args []Value) Value {
		return evalScriptSource(toString(arg(args, 0)).String(), "<evalScript>", false)
	})
	m["loadScript"] = nf("loadScript", 1, func(this Value, args []Value) Value {
		return loadScriptFile(toString(arg(args, 0)).String())
	})
	m["urlGet"] = nf("urlGet", 2, func(this Value, args []Value) Value {
		throwTypeError("urlGet not supported")
		return Undefined
	})
	m["__printObject"] = nf("__printObject", 1, func(this Value, args []Value) Value {
		writeStdout(printValueString(arg(args, 0)))
		return Undefined
	})
	return m
}

type pipeCloser struct{ w io.WriteCloser }

func parseExtJSON(s *JSString) Value {
	// accept JS-like object literal syntax: evaluate as an expression in a sandbox-ish way
	src := s.String()
	return evalScriptSource("("+src+"\n)", "<input>", false)
}

func loadScriptFile(name string) Value {
	data, err := os.ReadFile(name)
	if err != nil {
		throwReferenceError("could not load '%s'", name)
	}
	return evalScriptSource(string(data), name, false)
}

// ---------- timers / event loop ----------

type jsTimer struct {
	id       int
	when     time.Time
	fn       Value
	args     []Value
	seq      int
	interval time.Duration
}

var timers []*jsTimer
var timerSeq = 0
var timerNextID = 1

func addTimer(fn Value, delay float64, args []Value) int {
	if delay < 0 || delay != delay {
		delay = 0
	}
	t := &jsTimer{id: timerNextID, when: time.Now().Add(time.Duration(delay * float64(time.Millisecond))), fn: fn, args: args, seq: timerSeq}
	timerNextID++
	timerSeq++
	timers = append(timers, t)
	return t.id
}

func clearTimer(id int) {
	for i, t := range timers {
		if t.id == id {
			timers = append(timers[:i], timers[i+1:]...)
			return
		}
	}
}

var noUnhandledRejection = false

func checkRejections() {
	if noUnhandledRejection || len(pendingRejections) == 0 {
		return
	}
	for _, p := range pendingRejections {
		pd := p.internal.(*PromiseData)
		pp := &printer{}
		pp.value(pd.result, 0)
		flushStdout()
		fmt.Fprintf(os.Stderr, "Possibly unhandled promise rejection: %s\n", pp.sb.String())
	}
	flushStdout()
	os.Exit(1)
}

// run jobs then one timer; returns false if nothing left to do
func runEventLoopOnce() bool {
	runJobs()
	checkRejections()
	if len(timers) == 0 {
		return false
	}
	// earliest timer
	best := 0
	for i, t := range timers {
		if t.when.Before(timers[best].when) || (t.when.Equal(timers[best].when) && t.seq < timers[best].seq) {
			best = i
		}
	}
	t := timers[best]
	if d := time.Until(t.when); d > 0 {
		flushStdout()
		time.Sleep(d)
	}
	timers = append(timers[:best], timers[best+1:]...)
	callValue(t.fn, Undefined, t.args)
	return true
}

func runEventLoop() {
	for runEventLoopOnce() {
	}
}

