		if a := arg(args, 2); !a.IsUndef() {
			mode = int(toInt32(a))
		}
		fd, err := syscall.Open(toString(arg(args, 0)).String(), int(toInt32(arg(args, 1))), uint32(mode))
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(fd)
	})
	m["close"] = nf("close", 1, func(this Value, args []Value) Value {
		return Int(-errnoOf(syscall.Close(int(toInt32(arg(args, 0))))))
	})
	m["seek"] = nf("seek", 3, func(this Value, args []Value) Value {
		var off int64
		a := arg(args, 1)
		isBig := a.t == TagBigInt
		if isBig {
			off = a.big().Int64()
		} else {
			off = int64(toNumber(a))
		}
		r, err := syscall.Seek(int(toInt32(arg(args, 0))), off, int(toInt32(arg(args, 2))))
		if err != nil {
			r = int64(-errnoOf(err))
		}
		if isBig {
			return BigV(big.NewInt(r))
		}
		return Num(float64(r))
	})
	m["read"] = nf("read", 4, func(this Value, args []Value) Value {
		buf, pos, l := bufferArgs(args[1:])
		n, err := syscall.Read(int(toInt32(arg(args, 0))), buf[pos:pos+l])
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(n)
	})
	m["write"] = nf("write", 4, func(this Value, args []Value) Value {
		buf, pos, l := bufferArgs(args[1:])
		fd := int(toInt32(arg(args, 0)))
		if fd == 1 {
			flushStdout()
		}
		n, err := syscall.Write(fd, buf[pos:pos+l])
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(n)
	})
	m["isatty"] = nf("isatty", 1, func(this Value, args []Value) Value {
		fd := int(toInt32(arg(args, 0)))
		var st syscall.Stat_t
		if syscall.Fstat(fd, &st) != nil {
			return False
		}
		return Bool(st.Mode&syscall.S_IFMT == syscall.S_IFCHR)
	})
	m["ttyGetWinSize"] = nf("ttyGetWinSize", 1, func(this Value, args []Value) Value { return Null })
	m["ttySetRaw"] = nf("ttySetRaw", 1, func(this Value, args []Value) Value { return Undefined })
	m["getpid"] = nf("getpid", 0, func(this Value, args []Value) Value { return Int(os.Getpid()) })
	m["exec"] = nf("exec", 2, func(this Value, args []Value) Value {
		a := arg(args, 0)
		if a.t != TagObj {
			throwTypeError("not an object")
		}
		list := createListFromArrayLike(a)
		var argv []string
		for _, v := range list {
			argv = append(argv, toString(v).String())
		}
		if len(argv) == 0 {
			throwTypeError("invalid number of arguments")
		}
		opts := arg(args, 1)
		block := true
		usePath := true
		var cwd string
		var env []string
		if opts.t == TagObj {
			if b := getV(opts, strKey("block")); !b.IsUndef() {
				block = toBool(b)
			}
			if b := getV(opts, strKey("usePath")); !b.IsUndef() {
				usePath = toBool(b)
			}
			if c := getV(opts, strKey("cwd")); !c.IsUndef() {
				cwd = toString(c).String()
			}
			if e := getV(opts, strKey("env")); e.t == TagObj {
				for _, k := range ownEnumerableKeys(e.obj(), false) {
					env = append(env, k.s+"="+toString(e.obj().Get(k, e)).String())
				}
			}
		}
		path := argv[0]
		if usePath {
			if lp, err := exec.LookPath(path); err == nil {
				path = lp
			}
		}
		cmd := exec.Command(path, argv[1:]...)
		cmd.Args = argv
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Dir = cwd
		if env != nil {
			cmd.Env = env
		}
		flushStdout()
		if err := cmd.Start(); err != nil {
			return Int(-errnoOf(err))
		}
		if !block {
			pid := cmd.Process.Pid
			execProcs[pid] = cmd
			return Int(pid)
		}
		err := cmd.Wait()
		if err != nil {
			if ee, ok := err.(*exec.ExitError); ok {
				if ws, ok := ee.Sys().(syscall.WaitStatus); ok {
					if ws.Signaled() {
						return Int(-int(ws.Signal()))
					}
					return Int(ws.ExitStatus())
				}
			}
			return Int(-1)
		}
		return Int(0)
	})
	m["waitpid"] = nf("waitpid", 2, func(this Value, args []Value) Value {
		pid := int(toInt32(arg(args, 0)))
		var ws syscall.WaitStatus
		r, err := syscall.Wait4(pid, &ws, int(toInt32(arg(args, 1))), nil)
		if err != nil {
			return Obj(newArray([]Value{Int(-errnoOf(err)), Int(0)}))
		}
		return Obj(newArray([]Value{Int(r), Int(int(ws))}))
	})
	m["kill"] = nf("kill", 2, func(this Value, args []Value) Value {
		return Int(-errnoOf(syscall.Kill(int(toInt32(arg(args, 0))), syscall.Signal(toInt32(arg(args, 1))))))
	})
	m["pipe"] = nf("pipe", 0, func(this Value, args []Value) Value {
		var fds [2]int
		if err := syscall.Pipe(fds[:]); err != nil {
			return Null
		}
		return Obj(newArray([]Value{Int(fds[0]), Int(fds[1])}))
	})
	m["dup"] = nf("dup", 1, func(this Value, args []Value) Value {
		fd, err := syscall.Dup(int(toInt32(arg(args, 0))))
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(fd)
	})
	m["dup2"] = nf("dup2", 2, func(this Value, args []Value) Value {
		err := syscall.Dup2(int(toInt32(arg(args, 0))), int(toInt32(arg(args, 1))))
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(int(toInt32(arg(args, 1))))
	})
	m["signal"] = nf("signal", 2, func(this Value, args []Value) Value { return Undefined })
	m["setReadHandler"] = nf("setReadHandler", 2, func(this Value, args []Value) Value { return Undefined })
	m["setWriteHandler"] = nf("setWriteHandler", 2, func(this Value, args []Value) Value { return Undefined })
	m["Worker"] = Obj(makeCtor("Worker", 1, nil, func(this Value, args []Value) Value {
		throwTypeError("must be called with new")
		return Undefined
	}, func(args []Value, nt *Object) Value {
		throwTypeError("Worker not supported")
		return Undefined
	}))
	return m
}

