// ---------- printf ----------

func jsPrintf(format *JSString, args []Value) string {
	f := format.String()
	var sb strings.Builder
	ai := 0
	nextArg := func() Value {
		if ai >= len(args) {
			throwReferenceError("missing argument for conversion specifier")
		}
		v := args[ai]
		ai++
		return v
	}
	for i := 0; i < len(f); i++ {
		c := f[i]
		if c != '%' {
			sb.WriteByte(c)
			continue
		}
		j := i + 1
		flags := ""
		for j < len(f) && strings.IndexByte("-+ #0", f[j]) >= 0 {
			flags += string(f[j])
			j++
		}
		width := ""
		if j < len(f) && f[j] == '*' {
			width = strconv.Itoa(int(toInt32(nextArg())))
			j++
		} else {
			for j < len(f) && f[j] >= '0' && f[j] <= '9' {
				width += string(f[j])
				j++
			}
		}
		prec := ""
		hasPrec := false
		if j < len(f) && f[j] == '.' {
			hasPrec = true
			j++
			if j < len(f) && f[j] == '*' {
				prec = strconv.Itoa(int(toInt32(nextArg())))
				j++
			} else {
				for j < len(f) && f[j] >= '0' && f[j] <= '9' {
					prec += string(f[j])
					j++
				}
			}
		}
		if j < len(f) && f[j] == 'l' {
			j++
		}
		if j >= len(f) {
			throwTypeError("invalid conversion specifier in format string")
		}
		conv := f[j]
		spec := "%" + flags + width
		if hasPrec {
			if prec == "" {
				prec = "0"
			}
			spec += "." + prec
		}
		switch conv {
		case '%':
			sb.WriteByte('%')
		case 'd', 'i', 'u', 'x', 'X', 'o':
			v := nextArg()
			var bi *big.Int
			if v.t == TagBigInt {
				bi = v.big()
			} else {
				n := toNumber(v)
				var iv int64
				if conv == 'd' || conv == 'i' {
					if n != n {
						iv = 0
					} else {
						iv = int64(f64ToInt32(n))
						if math.Abs(n) > 2147483647 && !math.IsInf(n, 0) {
							iv = int64(math.Trunc(n))
						}
					}
				} else {
					iv = int64(uint32(f64ToInt32(n)))
				}
				bi = big.NewInt(iv)
			}
			gc := conv
			if conv == 'i' || conv == 'u' {
				gc = 'd'
			}
			s := fmt.Sprintf(spec+string(gc), bi)
			if conv == 'x' && strings.Contains(flags, "#") {
				// go prints 0xff already
			}
			sb.WriteString(s)
		case 'c':
			v := nextArg()
			var r rune
			if v.t == TagStr {
				s := v.str()
				if s.n > 0 {
					r, _ = s.CodePointAt(0)
				}
			} else {
				r = rune(toInt32(v))
			}
			sb.WriteString(fmt.Sprintf(strings.Replace(spec, "0", "", 1)+"c", r))
		case 's':
			v := nextArg()
			s := toString(v).ToUTF8()
			sb.WriteString(fmt.Sprintf(spec+"s", s))
		case 'f', 'F', 'e', 'E', 'g', 'G', 'a', 'A':
			v := nextArg()
			n := toNumber(v)
			gc := conv
			if conv == 'a' {
				gc = 'x'
			} else if conv == 'A' {
				gc = 'X'
			}
			if math.IsInf(n, 0) || n != n {
				s := "inf"
				if n != n {
					s = "nan"
				} else if n < 0 {
					s = "-inf"
				} else if strings.Contains(flags, "+") {
					s = "+inf"
				}
				if conv >= 'A' && conv <= 'Z' {
					s = strings.ToUpper(s)
				}
				sb.WriteString(fmt.Sprintf("%"+strings.Replace(flags, "0", "", -1)+width+"s", s))
				break
			}
			s := fmt.Sprintf(spec+string(gc), n)
			if conv == 'a' || conv == 'A' {
				s = cHexFloat(n, conv == 'A')
			}
			// Go uses e+06 like C (2 digits min) - matches
			sb.WriteString(s)
		default:
			throwTypeError("invalid conversion specifier in format string")
		}
		i = j
	}
	return sb.String()
}

func cHexFloat(f float64, upper bool) string {
	s := strconv.FormatFloat(f, 'x', -1, 64)
	// Go: 0x1.fep+07 ; C: 0x1.fep+7
	if i := strings.IndexAny(s, "pP"); i >= 0 {
		exp := s[i+1:]
		sign := ""
		if exp[0] == '+' || exp[0] == '-' {
			sign = exp[:1]
			exp = exp[1:]
		}
		exp = strings.TrimLeft(exp, "0")
		if exp == "" {
			exp = "0"
		}
		s = s[:i+1] + sign + exp
	}
	if upper {
		s = strings.ToUpper(s)
	}
	return s
}

// ---------- FILE ----------

type jsFile struct {
	f      *os.File
	r      *bufio.Reader
	w      *bufio.Writer
	isStd  int // 0 none, 1 stdin, 2 stdout, 3 stderr
	eof    bool
	err    bool
	proc   *exec.Cmd
	closed bool
}

var FilePrototype *Object

func newFileObj(jf *jsFile) Value {
	o := newObjectProto(FilePrototype, ClassFILE)
	o.internal = jf
	return Obj(o)
}

func thisFile(this Value) *jsFile {
	if this.t == TagObj && this.obj().class == ClassFILE {
		jf := this.obj().internal.(*jsFile)
		if jf.closed {
			throwTypeError("invalid file handle")
		}
		return jf
	}
	throwTypeError("not a FILE")
	return nil
}

func (jf *jsFile) write(s string) {
	switch jf.isStd {
	case 2:
		writeStdout(s)
		return
	case 3:
		flushStdout()
		os.Stderr.WriteString(s)
		return
	}
	if jf.w == nil {
		jf.w = bufio.NewWriter(jf.f)
	}
	jf.w.WriteString(s)
}

func (jf *jsFile) reader() *bufio.Reader {
	if jf.r == nil {
		jf.r = bufio.NewReader(jf.f)
	}
	return jf.r
}

func (jf *jsFile) flush() {
	if jf.isStd == 2 {
		flushStdout()
	}
	if jf.w != nil {
		jf.w.Flush()
	}
}

var stdinFile = &jsFile{f: os.Stdin, isStd: 1}
var stdoutFile = &jsFile{f: os.Stdout, isStd: 2}
var stderrFile = &jsFile{f: os.Stderr, isStd: 3}

func errnoOf(err error) int {
	if err == nil {
		return 0
	}
	if pe, ok := err.(*os.PathError); ok {
		err = pe.Err
	}
	if le, ok := err.(*os.LinkError); ok {
		err = le.Err
	}
	if se, ok := err.(*os.SyscallError); ok {
		err = se.Err
	}
	if en, ok := err.(syscall.Errno); ok {
		return int(en)
	}
	return int(syscall.EIO)
}

func openFlags(mode string) (int, bool) {
	m := strings.ReplaceAll(mode, "b", "")
	switch m {
	case "r":
		return os.O_RDONLY, true
	case "r+":
		return os.O_RDWR, true
	case "w":
		return os.O_WRONLY | os.O_CREATE | os.O_TRUNC, true
	case "w+":
		return os.O_RDWR | os.O_CREATE | os.O_TRUNC, true
	case "a":
		return os.O_WRONLY | os.O_CREATE | os.O_APPEND, true
	case "a+":
		return os.O_RDWR | os.O_CREATE | os.O_APPEND, true
	}
	return 0, false
}

func setErrObj(v Value, errno int) {
	if v.t == TagObj {
		v.obj().Set(strKey("errno"), Int(errno), v, false)
	}
}

func initFilePrototype() {
	fp := newObject()
	FilePrototype = fp
	defMethod(fp, "close", 0, func(this Value, args []Value) Value {
		jf := thisFile(this)
		jf.flush()
		if jf.isStd == 0 && jf.f != nil {
			jf.f.Close()
		}
		if jf.proc != nil {
			jf.proc.Wait()
		}
		jf.closed = true
		return Int(0)
	})
	defMethod(fp, "puts", 1, func(this Value, args []Value) Value {
		jf := thisFile(this)
		for _, a := range args {
			jf.write(toString(a).ToUTF8())
		}
		return Undefined
	})
	defMethod(fp, "printf", 1, func(this Value, args []Value) Value {
		jf := thisFile(this)
		var rest []Value
		if len(args) > 1 {
			rest = args[1:]
		}
		s := jsPrintf(toString(arg(args, 0)), rest)
		jf.write(s)
		return Int(len(s))
	})
	defMethod(fp, "flush", 0, func(this Value, args []Value) Value {
		thisFile(this).flush()
		return Int(0)
	})
	tell := func(this Value, args []Value) Value {
		jf := thisFile(this)
		jf.flush()
		pos, err := jf.f.Seek(0, io.SeekCurrent)
		if err != nil {
			return Int(-1)
		}
		if jf.r != nil {
			pos -= int64(jf.r.Buffered())
		}
		return Num(float64(pos))
	}
	defMethod(fp, "tell", 0, tell)
	defMethod(fp, "tello", 0, func(this Value, args []Value) Value {
		v := tell(this, args)
		return BigV(big.NewInt(int64(v.n)))
	})
	defMethod(fp, "seek", 2, func(this Value, args []Value) Value {
		jf := thisFile(this)
		jf.flush()
		var off int64
		if a := arg(args, 0); a.t == TagBigInt {
			off = a.big().Int64()
		} else {
			off = int64(toNumber(a))
		}
		whence := int(toInt32(arg(args, 1)))
		if jf.r != nil && whence == 1 {
			off -= int64(jf.r.Buffered())
		}
		_, err := jf.f.Seek(off, whence)
		jf.r = nil
		jf.eof = false
		if err != nil {
			return Int(-errnoOf(err))
		}
		return Int(0)
	})
	defMethod(fp, "eof", 0, func(this Value, args []Value) Value {
		jf := thisFile(this)
		if jf.eof {
			return True
		}
		return False
	})
	defMethod(fp, "fileno", 0, func(this Value, args []Value) Value {
		return Int(int(thisFile(this).f.Fd()))
	})
	defMethod(fp, "error", 0, func(this Value, args []Value) Value { return Bool(thisFile(this).err) })
	defMethod(fp, "clearerr", 0, func(this Value, args []Value) Value {
		jf := thisFile(this)
		jf.err = false
		jf.eof = false
		return Undefined
	})
	defMethod(fp, "read", 3, func(this Value, args []Value) Value {
		jf := thisFile(this)
		buf, pos, l := bufferArgs(args)
		n, err := io.ReadFull(jf.reader(), buf[pos:pos+l])
		if err != nil {
			jf.eof = true
		}
		return Int(n)
	})
	defMethod(fp, "write", 3, func(this Value, args []Value) Value {
		jf := thisFile(this)
		buf, pos, l := bufferArgs(args)
		jf.write(string(buf[pos : pos+l]))
		return Int(l)
	})
	defMethod(fp, "getline", 0, func(this Value, args []Value) Value {
		jf := thisFile(this)
		if jf.isStd == 1 {
			flushStdout()
		}
		line, err := jf.reader().ReadString('\n')
		if err != nil && line == "" {
			jf.eof = true
			return Null
		}
		if err != nil {
			jf.eof = true
		}
		line = strings.TrimSuffix(line, "\n")
		return StrGo(line)
	})
	defMethod(fp, "readAsString", 1, func(this Value, args []Value) Value {
		jf := thisFile(this)
		var data []byte
		if mx := arg(args, 0); !mx.IsUndef() {
			n := int(toInteger(mx))
			data = make([]byte, n)
			k, _ := io.ReadFull(jf.reader(), data)
			data = data[:k]
		} else {
			data, _ = io.ReadAll(jf.reader())
		}
		jf.eof = true
		return StrGo(string(data))
	})
	defMethod(fp, "getByte", 0, func(this Value, args []Value) Value {
		jf := thisFile(this)
		b, err := jf.reader().ReadByte()
		if err != nil {
			jf.eof = true
			return Int(-1)
		}
		return Int(int(b))
	})
	defMethod(fp, "putByte", 1, func(this Value, args []Value) Value {
		jf := thisFile(this)
		jf.write(string([]byte{byte(toInt32(arg(args, 0)))}))
		return Int(0)
	})
	fp.setOwn(PropKey{sym: SymToStringTag}, StrGo("FILE"), pConfigurable)
}

func bufferArgs(args []Value) ([]byte, int, int) {
	b := arg(args, 0)
	if b.t != TagObj || b.obj().class != ClassArrayBuffer {
		throwTypeError("not an ArrayBuffer")
	}
	data := b.obj().internal.(*ArrayBufferData).data
	pos := int(toInteger(arg(args, 1)))
	l := int(toInteger(arg(args, 2)))
	if pos < 0 || l < 0 || pos+l > len(data) {
		throwRangeError("read/write array buffer overflow")
	}
	return data, pos, l
}

// ---------- module construction ----------

func makeNativeModule(name string, vals map[string]Value) *ModuleRec {
	m := &ModuleRec{name: name, native: true, nativeVals: vals, status: modEvaluated, instantiated: true}
	for k := range vals {
		m.nativeOrder = append(m.nativeOrder, k)
	}
	sort.Strings(m.nativeOrder)
	return m
}

var stdModuleObj, osModuleObj *ModuleRec

func nativeModule(name string) *ModuleRec {
	switch name {
	case "std":
		if stdModuleObj == nil {
			stdModuleObj = makeNativeModule("std", stdExports())
		}
		return stdModuleObj
	case "os":
		if osModuleObj == nil {
