func numberToRadix(x float64, radix int) string {
	if x != x {
		return "NaN"
	}
	if math.IsInf(x, 1) {
		return "Infinity"
	}
	if math.IsInf(x, -1) {
		return "-Infinity"
	}
	if x == 0 {
		return "0"
	}
	neg := x < 0
	if neg {
		x = -x
	}
	if x == math.Trunc(x) && x < 9007199254740992 {
		s := strconv.FormatUint(uint64(x), radix)
		if neg {
			return "-" + s
		}
		return s
	}
	exact := new(big.Rat).SetFloat64(x)
	R := big.NewInt(int64(radix))
	// k: number of integer digits: smallest k with r^k > x
	k := int(math.Floor(math.Log(x)/math.Log(float64(radix)))) + 1
	pow := func(e int) *big.Rat {
		if e >= 0 {
			return new(big.Rat).SetInt(new(big.Int).Exp(R, big.NewInt(int64(e)), nil))
		}
		return new(big.Rat).SetFrac(big.NewInt(1), new(big.Int).Exp(R, big.NewInt(int64(-e)), nil))
	}
	// adjust k
	for exact.Cmp(pow(k)) >= 0 {
		k++
	}
	for k > -1100 && exact.Cmp(pow(k-1)) < 0 {
		k--
	}
	half := big.NewRat(1, 2)
	for n := 1; n <= 1200; n++ {
		scaled := new(big.Rat).Mul(exact, pow(n-k))
		// round half even
		num := scaled.Num()
		den := scaled.Denom()
		q, r := new(big.Int).QuoRem(num, den, new(big.Int))
		frac := new(big.Rat).SetFrac(r, den)
		c := frac.Cmp(half)
		if c > 0 || (c == 0 && q.Bit(0) == 1) {
			q.Add(q, big.NewInt(1))
		}
		kk := k
		limit := new(big.Int).Exp(R, big.NewInt(int64(n)), nil)
		if q.Cmp(limit) >= 0 {
			// rounding overflow: one more integer digit
			q.Quo(q, R)
			kk++
		}
		back := new(big.Rat).Mul(new(big.Rat).SetInt(q), pow(kk-n))
		f, _ := back.Float64()
		if f == x {
			digits := q.Text(radix)
			for len(digits) < n {
				digits = "0" + digits
			}
			var out string
			if kk >= n {
				out = digits + strings.Repeat("0", kk-n)
			} else if kk <= 0 {
				out = "0." + strings.Repeat("0", -kk) + strings.TrimRight(digits, "0")
			} else {
				ip := digits[:kk]
				fp := strings.TrimRight(digits[kk:], "0")
				out = ip
				if fp != "" {
					out += "." + fp
				}
			}
			if neg {
				out = "-" + out
			}
			return out
		}
