new='''func binPrec(t *Token, noIn bool) int {
	if t.kind == tPunct {
		switch t.str {
		case "|":
			return 4
		case "^":
			return 5
		case "&":
			return 6
		case "==", "!=", "===", "!==":
			return 7
		case "<", ">", "<=", ">=":
			return 8
		case "<<", ">>", ">>>":
			return 9
		case "+", "-":
			return 10
		case "*", "/", "%":
			return 11
		case "**":
			return 12
		}
	} else if t.kind == tIdent && !t.escaped {
		if t.str == "instanceof" {
			return 8
		}
		if t.str == "in" && !noIn {
			return 8
		}
	}
	return 0
}

// ShortCircuitExpression: LogicalOR or Coalesce
func (p *Parser) parseShortCircuit() Node {
	first := p.parseBinary(3)
	if _, ok := first.(*ArrowFunc); ok {
		return first
	}
	if p.is("??") {
		left := first
		for p.is("??") {
			opPos := p.lx.tok.pos
			p.checkCoverInit(left)
			p.next()
			right := p.parseBinary(3)
			left = &LogicalExpr{pos: opPos, Op: "??", L: left, R: right}
		}
		return left
	}
	// logical AND / OR
	left := p.parseAndTail(first)
	for p.is("||") {
		opPos := p.lx.tok.pos
		p.checkCoverInit(left)
		p.next()
		right := p.parseAndTail(p.parseBinary(3))
		left = &LogicalExpr{pos: opPos, Op: "||", L: left, R: right}
	}
	return left
}

func (p *Parser) parseAndTail(left Node) Node {
	for p.is("&&") {
		opPos := p.lx.tok.pos
		p.checkCoverInit(left)
		p.next()
		right := p.parseBinary(3)
		left = &LogicalExpr{pos: opPos, Op: "&&", L: left, R: right}
	}
	return left
}

func (p *Parser) parseBinary(minPrec int) Node {
	var left Node
	// private name 'in'
	if p.lx.tok.kind == tPrivate {
		t := p.lx.tok
		p.next()
		if !p.isKw("in") || p.noIn {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		if minPrec > 8 {
			p.errAt(t.pos, "unexpected token in expression: '%s'", t.str)
		}
		opPos := p.lx.tok.pos
		p.next()
		right := p.parseBinary(9)
		left = &PrivateIn{pos: opPos, Name: t.str, R: right}
	} else {
		left = p.parseUnary()
	}
	if _, ok := left.(*ArrowFunc); ok {
		return left
	}
	for {
		t := &p.lx.tok
		prec := binPrec(t, p.noIn)
		if prec == 0 || prec <= minPrec {
			break
		}
		op := t.str
		opPos := t.pos
		if op == "**" {
			if u, ok := left.(*UnaryExpr); ok {
				_ = u
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
			if _, ok := left.(*AwaitExpr); ok {
				p.err("unparenthesized unary expression can't appear on the left-hand side of '**'")
			}
		}
		p.checkCoverInit(left)
		p.next()
		var right Node
		if op == "**" {
			right = p.parseBinary(11) // right assoc
		} else {
			right = p.parseBinary(prec)
		}
		left = &BinaryExpr{pos: opPos, Op: op, L: left, R: right}
	}
	return left
}

