  parseTerm() { let left = this.parseFactor(); while (["*", "/"].includes(this.peek().value)) { const op = this.next().value; const right = this.parseFactor(); left = { op, left, right }; } return left; }
  parseFactor() { const base = this.parseUnary(); if (this.peek().value === "^") { this.next(); return { op: "^", left: base, right: this.parseFactor() }; } return base; }
  parseUnary() { if (this.peek().value === "-") { this.next(); return { op: "neg", arg: this.parseUnary() }; } return this.parsePrimary(); }
  parsePrimary() {
