    case "-": return evaluate(node.left) - evaluate(node.right);
    case "*": return evaluate(node.left) * evaluate(node.right);
    case "/": return evaluate(node.left) / evaluate(node.right);
    case "^": return evaluate(node.left) ** evaluate(node.right);
    case "neg": return -evaluate(node.arg);
