// localSlot returns the frame-local slot index for a simple local variable read (no TDZ, not captured)
func (c *compiler) localSlot(n Node) (int, bool) {
	id, ok := unparen(n).(*Ident)
	if !ok || id.ref == nil || id.ref.b == nil || len(id.ref.withs) > 0 {
		return 0, false
	}
	b := id.ref.b
	if b.inEnv || b.scope.kind == scScript || b.tdz || b.kind == bImport || b.kind == bClassInner {
		return 0, false
	}
	if !b.scope.compiledEnv {
		return 0, false
	}
	return b.idx, true
